// read_notes: up to so many bars a call, and the bars of up to so many notes (whole bars, one at least), so a song of
// 40-64 bars reads in one call and a busy part (a ripple of sixteenths) in two
const int MAX_READ_BARS = 64, MAX_READ_NOTES = 600;
const int MAX_PICTURE_BARS = 32;
const int MAX_LISTED = 15;
const char *const SOUNDTRACK_NOTES = "Soundtrack notes.txt";

// A tool's arguments or the song don't allow it: the reason goes back to Claude
struct Problem {
	std::string Text;
	explicit Problem(const std::string &Reason) : Text(Reason) {}
};

std::string Format(const char *pFormat, ...)
{
	char Buffer[1024];
	va_list Args;
	va_start(Args, pFormat);
	std::vsnprintf(Buffer, sizeof(Buffer), pFormat, Args);
	va_end(Args);
	return Buffer;
}

std::string Trim(const std::string &Text)
{
	size_t First = 0, Last = Text.size();
	while (First < Last && (Text[First] == ' ' || Text[First] == '\t'))
		++First;
	while (Last > First && (Text[Last - 1] == ' ' || Text[Last - 1] == '\t'))
		--Last;
	return Text.substr(First, Last - First);
}

// Lower case letters and digits only: "Hi-Hat" -> "hihat"
std::string Squeezed(const std::string &Text)
{
	std::string Out;
	for (size_t i = 0; i < Text.size(); ++i) {
		const unsigned char c = static_cast<unsigned char>(Text[i]);
		if (std::isalnum(c))
			Out += static_cast<char>(std::tolower(c));
	}
	return Out;
}

std::string Plural(int Count, const char *One, const char *Many)
{
	return Format("%d %s", Count, Count == 1 ? One : Many);
}

// A chip's name with its article, as it's said: "a VRC6", "an FDS"
std::string AChip(const std::string &Chip)
{
	return (Chip == "FDS" || Chip == "MMC5" || Chip == "N163" ? "an " : "a ") + Chip;
}

// Building tool schemas

Json Prop(const char *Type, const char *Description)
{
	Json P = Json::MakeObject();
	P.Set("type", Type);
	P.Set("description", Description);
	return P;
}

Json EnumProp(const char *Description, const std::vector<std::string> &Values)
{
	Json P = Prop("string", Description);
	Json List = Json::MakeArray();
	for (size_t i = 0; i < Values.size(); ++i)
		List.Push(Values[i]);
	P.Set("enum", List);
	return P;
}

Json ChannelProp(const char *Description)
{
	Json P = Json::MakeObject();
	Json Types = Json::MakeArray();
	Types.Push("string");
	Types.Push("integer");
	P.Set("type", Types);
	P.Set("description", Description);
	return P;
}

// One channel, several in a list, or "all"
// Words, as a list or as one text with commas
Json WordListProp(const char *Description)
{
	Json P = Prop("array", Description);
	Json Types = Json::MakeArray();
	Types.Push("array");
	Types.Push("string");
	P.Set("type", Types);
	Json Item = Json::MakeObject();
	Item.Set("type", "string");
	P.Set("items", Item);
	return P;
}

Json ChannelListProp(const char *Description)
{
	Json P = ChannelProp(Description);
	Json Types = Json::MakeArray();
	Types.Push("array");
	Types.Push("string");
	Types.Push("integer");
	P.Set("type", Types);
	Json Item = Json::MakeObject();
	Json ItemTypes = Json::MakeArray();
	ItemTypes.Push("string");
	ItemTypes.Push("integer");
	Item.Set("type", ItemTypes);
	P.Set("items", Item);
	return P;
}

// Words or a number, like vibrato's "slow" or 3
Json LevelProp(const char *Description)
{
	return ChannelProp(Description);
}

// A pan: a word or a number
Json PanChoice(const char *Description)
{
	Json P = Prop("string", Description);
	Json Types = Json::MakeArray();
	Types.Push("string");
	Types.Push("number");
	P.Set("type", Types);
	return P;
}

Json BarProp(const char *Description)
{
	Json P = Prop("integer", Description);
	P.Set("minimum", 1);
	return P;
}

// A section of the song (Sections.h) in place of from_bar and to_bar
Json SectionProp(const char *Description = "A section of the song by name, like \"Chorus\" (get_song lists them): its bars, in "
	"place of from_bar and to_bar.")
{
	return Prop("string", Description);
}

class Schema {
public:
	Schema() : m_Properties(Json::MakeObject()), m_Required(Json::MakeArray()) {}
	Schema &Add(const char *Name, const Json &Property, bool Required = false)
	{
		m_Properties.Set(Name, Property);
		if (Required)
			m_Required.Push(Name);
		return *this;
	}
	Schema &Range()
	{
		Add("from_bar", BarProp("First bar (from 1). Default: the start of the song."));
		Add("to_bar", BarProp("Last bar, included. Default: the end of the song."));
		Add("section", SectionProp());
		return *this;
	}
	// A section in place of bars, for tools with from_bar and to_bar of their own
	Schema &SectionChoice()
	{
		Add("section", SectionProp());
		return *this;
	}
	Schema &ClipChoice()
	{
		Add("as_clip", Prop("boolean", "Save the result as a clip even when direct changes are allowed (e.g. to offer an alternative)."));
		Add("clip_name", Prop("string", "Name for the clip, when the result becomes one."));
		return *this;
	}
	Json Get() const
	{
		Json S = Json::MakeObject();
		S.Set("type", "object");
		S.Set("properties", m_Properties);
		if (m_Required.Size() > 0)
			S.Set("required", m_Required);
		S.Set("additionalProperties", false);
		return S;
	}

private:
	Json m_Properties;
	Json m_Required;
};

std::vector<std::string> PresetNames()
{
	std::vector<std::string> Names;
	for (size_t i = 0; i < Presets().size(); ++i)
		Names.push_back(Presets()[i].Name);
	return Names;
}

std::vector<std::string> ModeNames()
{
	std::vector<std::string> Names;
	for (int m = 0; m < ModeCount(); ++m)
		Names.push_back(ModeName(m));
	return Names;
}

// The song as one tool call sees it

class Session {
	SongHost &m_Host;

public:
	explicit Session(SongHost &Host) : m_Host(Host), Time(64, 1, 4, 16)
	{
		Load();
	}

	void Load()
	{
		std::string Error;
		if (!m_Host.GetSong(Song, Error))
			throw Problem(Error.empty() ? "No song is open in FamiTracker." : Error);
		Time = Timing(Song.PatternLength, Song.Frames, Song.FirstHighlight, Song.SecondHighlight);
		Unhide();
		m_Cache.clear();
		m_Notes.clear();
	}

	// After instruments were added; the cells stay as they are
	void Refresh()
	{
		std::string Error;
		SongInfo Info;
		if (m_Host.GetSong(Info, Error)) {
			Song = Info;
			Unhide();
		}
	}

	// The effect columns a channel shows in FamiTracker, the ones that play. The tools use all
	// four (FamiTracker shows more where the effects written need them), so the effects of the
	// columns hidden now are left out of the cells they read
	int Shown(int Channel) const
	{
		return Channel >= 0 && static_cast<size_t>(Channel) < m_Shown.size() ? m_Shown[static_cast<size_t>(Channel)] : 1;
	}

	SongHost &Host() { return m_Host; }

	const std::vector<Cell> &Cells(int Channel)
	{
		std::map<int, std::vector<Cell> >::iterator it = m_Cache.find(Channel);
		if (it == m_Cache.end()) {
			std::vector<Cell> Read;
			m_Host.ReadCells(Channel, 0, Time.TotalRows(), Read);
			Read.resize(Time.TotalRows());
			for (size_t r = 0; r < Read.size(); ++r)
				for (int k = std::max(1, Shown(Channel)); k < EFFECT_COLUMNS; ++k) {
					Read[r].Effect[k] = EFF_NONE;
					Read[r].Param[k] = 0;
				}
			it = m_Cache.insert(std::make_pair(Channel, Read)).first;
		}
		return it->second;
	}

	const std::vector<NoteInfo> &Notes(int Channel)
	{
		std::map<int, std::vector<NoteInfo> >::iterator it = m_Notes.find(Channel);
		if (it == m_Notes.end())
			it = m_Notes.insert(std::make_pair(Channel, ReadNotes(Cells(Channel), Song.Channels[Channel].EffectColumns))).first;
		return it->second;
	}

	// A channel's cells as a change would leave them, in this session alone (write_notes' warnings hear the song as the part
	// it writes leaves it, in a copy of the session); the song stays as it is
	void Assume(int Channel, const std::vector<Cell> &Cells)
	{
		std::vector<Cell> Read(Cells);
		Read.resize(Time.TotalRows());
		m_Cache[Channel] = Read;
		m_Notes.erase(Channel);
	}

	int ChannelCount() const { return static_cast<int>(Song.Channels.size()); }
	const ChannelInfo &Channel(int Index) const { return Song.Channels[Index]; }
	int MaxRows() const { return Song.MaxFrames * Song.PatternLength; }
	int MaxBars() const { return Song.MaxFrames * Time.BarsPerFrame(); }

	SongInfo Song;
	Timing Time;
	std::vector<std::string> Remarks;	// told along with the result

private:
	void Unhide()
	{
		m_Shown.clear();
		for (size_t c = 0; c < Song.Channels.size(); ++c) {
			m_Shown.push_back(std::max(1, std::min(EFFECT_COLUMNS, Song.Channels[c].EffectColumns)));
			Song.Channels[c].EffectColumns = EFFECT_COLUMNS;
			// The channels of its chip (the N163's count sets how loud it plays: N163FullDb)
			int Same = 0;
			for (size_t d = 0; d < Song.Channels.size(); ++d)
				Same += Song.Channels[d].Chip == Song.Channels[c].Chip ? 1 : 0;
			Song.Channels[c].ChipChannels = Same;
		}
	}

	std::map<int, std::vector<Cell> > m_Cache;
	std::map<int, std::vector<NoteInfo> > m_Notes;
	std::vector<int> m_Shown;
};

bool IsMelodic(const ChannelInfo &Channel)
{
	return Channel.Kind != KIND_NOISE && Channel.Kind != KIND_DPCM;
}

bool IsBass(const ChannelInfo &Channel)
{
	return Channel.Kind == KIND_TRIANGLE || Channel.Kind == KIND_SAWTOOTH;
}

// The triangle, the VRC7 and the 5B sound an octave below what's written (the
// VRC7's A-3 is 220 Hz, a pulse's 440), and the FDS two in FamiTracker 0.4.6 (its
// A-5 sounds 440 Hz; see FdsSounds.h): a pitch that sounds as Sounding does on
// a pulse, as written on Channel
int Written(const ChannelInfo &Channel, int Sounding)
{
	if (Channel.Chip == "FDS")
		return Sounding + 12 * FDS_OCTAVES_DOWN;
	return Channel.Kind == KIND_TRIANGLE || Channel.Kind == KIND_FM || Channel.Kind == KIND_SQUARE ? Sounding + 12 : Sounding;
}

// The highest note a channel plays in tune: the FDS's pitch register tops out
// at G#7 (A-7 plays 13 cents flat, A#7 and B-7 no higher)
const int FDS_HIGHEST = 92;

int HighestWritten(const ChannelInfo &Channel)
{
	return Channel.Chip == "FDS" ? FDS_HIGHEST : PITCHES - 1;
}

// A note written on one channel, as written on another to sound the same
// (an octave further when that's outside the notes the other plays)
int WrittenOn(const ChannelInfo &From, const ChannelInfo &To, int Pitch)
{
	int Out = Pitch + Written(To, 0) - Written(From, 0);
	while (Out > HighestWritten(To))
		Out -= 12;
	while (Out < 0)
		Out += 12;
	return Out;
}

std::string InstrumentChip(const ChannelInfo &Channel)
{
	return Channel.Chip == "MMC5" ? "2A03" : Channel.Chip;
}

// The expansion chips the song has on ("VRC6", "N163", "5B"), as SongInfo::Expansion names them
std::vector<std::string> SongChips(const SongInfo &Song)
{
	std::vector<std::string> Out;
	size_t From = 0;
	while (From < Song.Expansion.size()) {
		size_t Comma = Song.Expansion.find(',', From);
		if (Comma == std::string::npos)
			Comma = Song.Expansion.size();
		const std::string Chip = Trim(Song.Expansion.substr(From, Comma - From));
		if (!Chip.empty())
			Out.push_back(Chip);
		From = Comma + 1;
	}
	return Out;
}

// The expansion chips as the user knows them, for get_song: "VRC6", "VRC6, N163, 5B", "VRC6 Plus (the VRC6 with a
// soft layer of four N163 wave channels), 5B"
std::string ExpansionText(const SongInfo &Song)
{
	if (!Song.Vrc6Plus)
		return Song.Expansion;
	std::string Text = std::string(VRC6_PLUS) + " (the VRC6 with a soft layer of four N163 wave channels)";
	const std::vector<std::string> Chips = SongChips(Song);
	for (size_t i = 0; i < Chips.size(); ++i)
		if (Chips[i] != "VRC6" && Chips[i] != "N163")
			Text += ", " + Chips[i];
	return Text;
}

bool HasChip(const SongInfo &Song, const std::string &Chip)
{
	const std::vector<std::string> Chips = SongChips(Song);
	return std::find(Chips.begin(), Chips.end(), Chip) != Chips.end();
}

// A chip as asked for ("vrc6", "Sunsoft 5B", "namco"), named as the tools name it ("VRC6", "5B", "N163")
std::string ChipWord(const std::string &Asked)
{
	std::string Chip;
	for (size_t i = 0; i < Asked.size(); ++i)
		if (std::isalnum(static_cast<unsigned char>(Asked[i])))
			Chip += static_cast<char>(std::toupper(static_cast<unsigned char>(Asked[i])));
	if (Chip == "S5B" || Chip == "SUNSOFT" || Chip == "SUNSOFT5B" || Chip == "FME7")
		return "5B";
	if (Chip == "NAMCO" || Chip == "NAMCO163" || Chip == "N106" || Chip == "NAMCO106")
		return "N163";
	if (Chip == "NES" || Chip == "RP2A03")
		return "2A03";
	return Chip;
}

// How loud a channel plays at a volume, in dB against a 2A03 pulse at 15, as FamiTracker renders
// it (measured): the VRC7's sounds about 5 dB louder at 15, each volume step 3 dB softer; the
// 5B's square as loud as a pulse at 15 (0.4 dB louder), each step 3 dB softer too; the N163's
// wave sounds by its channel count (N163FullDb); the FDS's sounds about 5 dB louder with their
// envelope at its top (31; FdsSounds.h's from 4 to 6.5); everything else in proportion to the volume
const double FM_FULL_DB = 5.0, FM_STEP_DB = 3.0, S5B_FULL_DB = 0.4, S5B_STEP_DB = 3.0, FDS_FULL_DB = 5.0;
// The N163, measured under Wine (A-3, volume 15 on a plain instrument, against a 2A03 pulse at 15 in the same
// rendering, October 2026): its one DAC plays its channels in turn, each a 1/n of the time, which FamiTracker's
// mixer makes up in part (CN163::Process: 1.3 for one channel, 1.5 + (n - 2) / 1.5 for more), so a square wave of
// 0-15 plays 0.6 dB under the pulse with 4 channels, 4.4 dB over it with 1 and 1.0 over with 8 (where the chip's
// switching whine, at 15 kHz, adds 1.8 dB of its own). Its level follows the wave's: the RMS of the ready-made
// waves, rounder than a square, is 4.1 dB under the square's on average (a sine 3.2, the soft flute 2.8, the
// choir 7.1, the sub bass 3.3), measured within 0.2 dB of that on every one.
const double N163_SQUARE_DB = -0.6, N163_WAVE_DB = -4.1;

// The N163's level at 15 against a pulse's with Channels of its channels in the song (0: not known, as 4)
double N163FullDb(int Channels)
{
	auto Share = [](int n) { return (n <= 1 ? 1.3 : 1.5 + (n - 2) / 1.5) / std::max(1, n); };
	const int n = Channels < 1 ? 4 : std::min(8, Channels);
	return N163_SQUARE_DB + N163_WAVE_DB + 20.0 * std::log10(Share(n) / Share(4));
}

// How loud a wave sound plays at volume 15 against a 2A03 pulse at 15 with Channels N163 channels (Struck: at its strike,
// for one that dies away): N163FullDb's square, its waves' level and its envelope's. Under Wine (October 2026, A-3, 4
// channels, against a 50% pulse) the soft layer's eight sounds measured within 0.5 dB of it: choir pad -8.3, string pad
// -7.3, soft flute -5.3, sub bass -5.1, breath -7.4, quick pad -7.7, pulsing pad -10.4 over its strikes, music box -4.8
// struck.
double WaveSoundDb(const WaveSound &Sound, int Channels, bool &Struck)
{
	const double Held = HeldVolume(Sound, Struck);
	return N163FullDb(Channels) - N163_WAVE_DB + WaveLevelDb(Sound, Struck) + 20.0 * std::log10(std::max(1.0, Held) / 15.0);
}

// The channels whose volume counts in steps of 3 dB, the VRC7's and the 5B's, not in proportion to it
bool StepVolume(const ChannelInfo &Channel)
{
	return Channel.Kind == KIND_FM || Channel.Kind == KIND_SQUARE;
}

// A chip's level at 15 against a pulse's, where it counts volume in proportion
double FullDb(const ChannelInfo &Channel)
{
	return Channel.Chip == "N163" ? N163FullDb(Channel.ChipChannels) : Channel.Chip == "FDS" ? FDS_FULL_DB : 0.0;
}

// A channel of the VRC6 Plus's soft layer (Vrc6Plus.h): an N163 channel shown as the VRC6 Plus's
bool IsSoftLayer(const ChannelInfo &Channel)
{
	return Channel.Chip == "N163" && Channel.Group == VRC6_PLUS;
}

// How far mix keeps the soft layer's parts under their roles' levels (but a melody of its own), so it sits under the VRC6
const double SOFT_LAYER_DB = 3.0;

// The mixer window's fader on a channel (View > Mixer, set_mixer), which FamiTracker's mixer adds to how loud it plays
double FaderDb(const ChannelInfo &Channel)
{
	return Channel.MixLevel / 10.0;
}

double LevelDb(const ChannelInfo &Channel, int Volume)
{
	if (Volume <= 0)
		return -60.0;
	if (Channel.Kind == KIND_FM)
		return FaderDb(Channel) + FM_FULL_DB - FM_STEP_DB * (15 - std::min(15, Volume));
	if (Channel.Kind == KIND_SQUARE)
		return FaderDb(Channel) + S5B_FULL_DB - S5B_STEP_DB * (15 - std::min(15, Volume));
	return FaderDb(Channel) + FullDb(Channel) + 20.0 * std::log10(std::min(15, Volume) / 15.0);
}

// The volume (1-15) at which a channel plays nearest a level in dB (its fader counted)
int VolumeForDb(const ChannelInfo &Channel, double Db)
{
	Db -= FaderDb(Channel);
	double Volume;
	if (Channel.Kind == KIND_FM)
		Volume = 15.0 - (FM_FULL_DB - Db) / FM_STEP_DB;
	else if (Channel.Kind == KIND_SQUARE)
		Volume = 15.0 - (S5B_FULL_DB - Db) / S5B_STEP_DB;
	else
		Volume = 15.0 * std::pow(10.0, (Db - FullDb(Channel)) / 20.0);
	return std::max(1, std::min(15, static_cast<int>(std::floor(Volume + 1e-9 + 0.5))));
}

// The volume on To that sounds like Volume on From made Ratio as loud, the way a pulse's volume
// scales (11.0 / 15: four steps under full): the same number between chips that count volume alike
int MatchVolume(const ChannelInfo &From, int Volume, double Ratio, const ChannelInfo &To)
{
	return VolumeForDb(To, LevelDb(From, Volume) + 20.0 * std::log10(std::max(0.01, Ratio)));
}

// A part's default volume on a channel, given as on a pulse: the same, but nearer 15 on the VRC7
// and the 5B, whose steps are 3 dB each
int PartVolume(const ChannelInfo &Channel, int Volume)
{
	return MatchVolume(Channel, 15, Volume / 15.0, Channel);
}

const InstrumentInfo *FindInstrument(const SongInfo &Song, int Index)
{
	for (size_t i = 0; i < Song.Instruments.size(); ++i)
		if (Song.Instruments[i].Index == Index)
			return &Song.Instruments[i];
	return 0;
}

// An instrument's volume envelope for a held note, a frame at a time, as
// CSequenceHandler runs it: from the start, back to the loop point at the
// sequence's end or past its release point (waiting there without a loop),
// its last value once it ends; 15 every frame when it has none
std::vector<int> HeldEnvelope(const InstrumentInfo *pInfo, int Frames)
{
	std::vector<int> Out(static_cast<size_t>(std::max(0, Frames)), 15);
	if (pInfo == 0 || pInfo->Volume.empty())
		return Out;
	const int Items = static_cast<int>(pInfo->Volume.size()), Loop = pInfo->VolumeLoop, Release = pInfo->VolumeRelease;
	int Pointer = 0, Value = 15;
	bool Ended = false;
	for (int f = 0; f < Frames; ++f) {
		if (!Ended) {
			Value = std::max(0, std::min(15, pInfo->Volume[static_cast<size_t>(std::max(0, std::min(Pointer, Items - 1)))]));
			++Pointer;
			if (Pointer == Release + 1 || Pointer >= Items) {
				if (Loop >= 0 && Loop < Items)
					Pointer = Loop;
				else if (Pointer >= Items)
					Ended = true;
				else
					--Pointer;
			}
		}
		Out[static_cast<size_t>(f)] = Value;
	}
	return Out;
}

// The loudest an instrument's envelope gets while a note holds (15 without one)
int EnvelopePeak(const InstrumentInfo *pInfo)
{
	if (pInfo == 0 || pInfo->Volume.empty())
		return 15;
	const std::vector<int> Held = HeldEnvelope(pInfo, static_cast<int>(pInfo->Volume.size()) + 1);
	return *std::max_element(Held.begin(), Held.end());
}

// The volume a channel plays at, as CChannelHandler::CalculateVolume works
// it out: the volume column's times the envelope's over 15, at least 1 while
// both sound
int PlayedVolume(int Column, int Envelope)
{
	if (Column <= 0 || Envelope <= 0)
		return 0;
	return std::max(1, Column * Envelope / 15);
}

// The same on a channel: on the 5B, as CChannelHandlerS5B works it out, the volume column's steps
// under 15 and the envelope's add up (each 3 dB), and it's silent at 0
int PlayedVolume(const ChannelInfo &Channel, int Column, int Envelope)
{
	if (Channel.Kind != KIND_SQUARE)
		return PlayedVolume(Column, Envelope);
	if (Column <= 0 || Envelope <= 0)
		return 0;
	return std::max(0, std::min(15, Column + Envelope - 15));
}

// How loud a note plays a frame, for comparing frames (HeardFrames, Vanishes): PlayedVolume's, and
// with a 5B instrument the 5B's as a pulse's volume (in proportion to how loud), at least 1 while
// it sounds
int HeardVolume(const InstrumentInfo *pInfo, int Column, int Envelope)
{
	if (pInfo == 0 || pInfo->Chip != "5B")
		return PlayedVolume(Column, Envelope);
	if (Column <= 0 || Envelope <= 0 || Column + Envelope - 15 <= 0)
		return 0;
	const int Steps = 15 - std::min(15, Column + Envelope - 15);
	return std::max(1, static_cast<int>(std::floor(15.0 * std::pow(10.0, -S5B_STEP_DB * Steps / 20.0) + 0.5)));
}

// Notes that vanish. A note heard for VANISH_FRAMES or fewer (what it plays falls under a sixth of the loudest it got, or
// to silence) and over two frames or more before the next comes out as a blip: beside notes of its line that hold
// (HOLD_FRAMES or more) it sounds like a missing note, a tick in its place. A user heard it at once in a tune that went
// from a held lead to a pluck whose envelope fell 15 10 5 2 1 0. A click pluck that holds low (2-3) carries its notes.
const int VANISH_FRAMES = 4, HOLD_FRAMES = 8;

// How many frames a note is heard for: until what it plays (its volume column times its instrument's envelope, as
// CalculateVolume works it out) falls under a sixth of the loudest it has got, or to silence; Limit when it's heard that
// long (or never sounds)
int HeardFramesOf(const InstrumentInfo *pInfo, int Volume, int Limit)
{
	const std::vector<int> Envelope = HeldEnvelope(pInfo, Limit);
	int Peak = 0;
	for (int f = 0; f < Limit; ++f) {
		const int Level = HeardVolume(pInfo, Volume, Envelope[static_cast<size_t>(f)]);
		if (Level > Peak)
			Peak = Level;
		else if (Peak > 0 && (Level == 0 || Level * 6 < Peak))
			return f;
	}
	return Limit;
}

int HeardFrames(const SongInfo &Song, const NoteInfo &N, int Limit)
{
	return HeardFramesOf(FindInstrument(Song, N.Instrument), N.Volume, Limit);
}

// What the tools and the sound browser say of a sound whose notes are gone within Heard frames
std::string VanishText(int Heard, bool ForTools)
{
	return Format(" Its notes are gone within %s: right for echoes, stabs and drums, but a tune's notes on it come out as "
		"blips, which sound like missing notes beside held ones (for a tune, %s).", Plural(Heard, "frame", "frames").c_str(),
		ForTools ? "a sound that settles to a level: design_instrument kind pluck with sustain half" :
		"pick a sound that settles to a level");
}

// What design_instrument and reference_sound say of a sound whose notes vanish (nothing for one that lasts)
std::string VanishRemark(const SongInfo &Song, int Instrument)
{
	NoteInfo N = NoteInfo();
	N.Instrument = Instrument;
	N.Volume = 15;
	const int Heard = HeardFrames(Song, N, 60);
	if (Heard > VANISH_FRAMES)
		return std::string();
	return VanishText(Heard, true);
}

std::string InstrumentLabel(const SongInfo &Song, int Index)
{
	const InstrumentInfo *pInfo = FindInstrument(Song, Index);
	if (pInfo == 0)
		return Format("instrument %02X", Index);
	return Format("\"%s\" (%02X)", pInfo->Name.c_str(), Index);
}

// The notes an instrument's looping arpeggio adds above each note it plays ({4, 7, 11}); empty for none
const std::vector<int> &InstrumentChord(const Session &S, int Instrument)
{
	static const std::vector<int> NONE;
	const InstrumentInfo *pInfo = FindInstrument(S.Song, Instrument);
	return pInfo != 0 ? pInfo->Arpeggio : NONE;
}

// The semitones above a note that sound with it: its 0xy arpeggio's (Arpeggio, 0 for none), else its instrument's
std::vector<int> ChordAbove(const Session &S, const NoteInfo &N, int Arpeggio)
{
	if (Arpeggio == 0)
		return InstrumentChord(S, N.Instrument);
	std::vector<int> Out(1, Arpeggio >> 4);
	if ((Arpeggio & 15) != 0)
		Out.push_back(Arpeggio & 15);
	return Out;
}

// Whether a note sounds a chord: an 0xy arpeggio on its rows, or its instrument's own
bool SoundsChord(const Session &S, const NoteInfo &N)
{
	for (size_t e = 0; e < N.Effects.size(); ++e)
		if (N.Effects[e].second.first == EFF_ARPEGGIO && N.Effects[e].second.second != 0)
			return true;
	return !InstrumentChord(S, N.Instrument).empty();
}

std::vector<bool> ReleasingInstruments(const SongInfo &Song)
{
	std::vector<bool> Releases(NO_INSTRUMENT, false);
	for (size_t i = 0; i < Song.Instruments.size(); ++i)
		if (Song.Instruments[i].Index >= 0 && Song.Instruments[i].Index < NO_INSTRUMENT)
			Releases[Song.Instruments[i].Index] = Song.Instruments[i].Releases;
	return Releases;
}

std::string ChannelList(const Session &S)
{
	std::string List;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (c > 0)
			List += ", ";
		List += Format("%d %s", c + 1, S.Channel(c).FullName().c_str());
	}
	return List;
}

// "2A03 Pulse 2 and VRC6 Sawtooth", "" when the user hears every channel
std::string MutedChannels(const Session &S)
{
	std::vector<std::string> Names;
	for (int c = 0; c < S.ChannelCount(); ++c)
		if (S.Channel(c).Muted)
			Names.push_back(S.Channel(c).FullName());
	std::string List;
	for (size_t i = 0; i < Names.size(); ++i)
		List += (i == 0 ? "" : (i + 1 == Names.size() ? " and " : ", ")) + Names[i];
	return List;
}

std::string PositionText(const Session &S, int Row)
{
	return Format("%s (frame %02X, row %02X)", S.Time.Position(Row).c_str(), Row / S.Time.PatternLength,
		Row % S.Time.PatternLength);
}

std::string PitchText(const ChannelInfo &Channel, int Pitch)
{
	return Channel.Kind == KIND_NOISE ? NoisePitchName(Pitch & 15) : PitchName(Pitch);
}

// Stereo (this FamiTracker's own: the pan effect, 8xx; the NES, FamiTracker
// 0.4.6 and NSF files are mono, the game's OGG files are stereo)

// A pan as the tools take it: "left", "right", "center" (or "middle"), "half left", "a little right", "40% left", a
// number from -1 (left) to 1 (right), or the effect itself ("840"); false otherwise
bool ParsePanValue(const Json &Value, int &Param)
{
	if (Value.IsNumber()) {
		const double Position = Value.Number();
		if (!(Position >= -1.0 && Position <= 1.0))
			return false;
		Param = PanParam(Position);
		return true;
	}
	if (!Value.IsString())
		return false;
	std::string Text = Lowercase(Trim(Value.String()));
	if (Text.size() == 3 && Text[0] == '8' && std::isxdigit(static_cast<unsigned char>(Text[1])) &&
		std::isxdigit(static_cast<unsigned char>(Text[2]))) {
		Param = static_cast<int>(std::strtol(Text.c_str() + 1, 0, 16));	// the effect, as FamiTracker shows it
		return true;
	}
	if (Text == "center" || Text == "centre" || Text == "middle" || Text == "mid" || Text == "centered" || Text == "the middle") {
		Param = PAN_CENTER;
		return true;
	}
	int Side = 0;
	if (Text.size() >= 4 && Text.compare(Text.size() - 4, 4, "left") == 0) {
		Side = -1;
		Text = Trim(Text.substr(0, Text.size() - 4));
	}
	else if (Text.size() >= 5 && Text.compare(Text.size() - 5, 5, "right") == 0) {
		Side = 1;
		Text = Trim(Text.substr(0, Text.size() - 5));
	}
	if (Side == 0) {
		char *pEnd = 0;
		const double Position = std::strtod(Text.c_str(), &pEnd);
		if (Text.empty() || pEnd == 0 || *pEnd != 0 || !(Position >= -1.0 && Position <= 1.0))
			return false;
		Param = PanParam(Position);
		return true;
	}
	if (Text.size() >= 3 && Text.compare(Text.size() - 3, 3, " to") == 0)
		Text = Trim(Text.substr(0, Text.size() - 3));	// "halfway to the left"
	if (Text.size() >= 7 && Text.compare(Text.size() - 7, 7, " to the") == 0)
		Text = Trim(Text.substr(0, Text.size() - 7));
	if (Text == "the")
		Text.clear();
	double Share = -1.0;
	if (Text.empty() || Text == "hard" || Text == "full" || Text == "fully" || Text == "all the way" || Text == "far")
		Share = 1.0;
	else if (Text == "half" || Text == "halfway" || Text == "half way")
		Share = 0.5;
	else if (Text == "a little" || Text == "slightly" || Text == "a bit" || Text == "a touch" || Text == "a little to the")
		Share = 0.25;
	else if (!Text.empty() && Text[Text.size() - 1] == '%') {
		char *pEnd = 0;
		const double Percent = std::strtod(Text.c_str(), &pEnd);
		if (pEnd != 0 && Trim(std::string(pEnd)) == "%" && Percent >= 0.0 && Percent <= 100.0)
			Share = Percent / 100.0;
	}
	if (Share < 0.0)
		return false;
	Param = PanParam(Side * Share);
	return true;
}

// Where notes play between the speakers: "in the middle", "panned left", "panned 40% right", or "panning between
// left and right"
std::string PanText(const std::vector<NoteInfo> &Notes)
{
	int Lowest = -1, Highest = -1, Changes = 0;
	for (size_t i = 0; i < Notes.size(); ++i) {
		const int Pan = Notes[i].Pan;
		if (i > 0 && Pan != Notes[i - 1].Pan)
			++Changes;
		if (Lowest < 0 || Pan < Lowest)
			Lowest = Pan;
		if (Highest < 0 || Pan > Highest)
			Highest = Pan;
	}
	if (Lowest < 0 || (Lowest == PAN_CENTER && Highest == PAN_CENTER))
		return "in the middle";
	if (Lowest == Highest)
		return "panned " + PanName(Lowest);
	return "panning between " + PanName(Lowest) + " and " + PanName(Highest) + (Changes >= 3 ? " (" + Plural(Changes, "change",
		"changes") + ")" : "");
}

// Where notes play most of their time, from -1 (left) to 1 (right)
double PanPositionOf(const std::vector<NoteInfo> &Notes)
{
	double Sum = 0.0, Rows = 0.0;
	for (size_t i = 0; i < Notes.size(); ++i) {
		Sum += PanPosition(Notes[i].Pan) * std::max(1, Notes[i].Rows);
		Rows += std::max(1, Notes[i].Rows);
	}
	return Rows > 0.0 ? Sum / Rows : 0.0;
}

// A channel's notes with the pan each starts at as it plays: the ones before the channel's first 8xx where
// FamiTracker's mixer starts the channel (ChannelInfo::MixPan), not in the middle
std::vector<NoteInfo> PannedNotes(Session &S, int Channel)
{
	std::vector<NoteInfo> Notes = S.Notes(Channel);
	const int Start = S.Channel(Channel).MixPan;
	if (Start == PAN_CENTER)
		return Notes;
	const std::vector<Cell> &Cells = S.Cells(Channel);
	int First = static_cast<int>(Cells.size());
	for (int r = 0; r < First; ++r)
		if (HasEffect(Cells[static_cast<size_t>(r)], EFF_PAN, S.Channel(Channel).EffectColumns))
			First = r;
	for (size_t i = 0; i < Notes.size() && Notes[i].Row < First; ++i)
		Notes[i].Pan = Start;
	return Notes;
}

// Whether any of the song's notes play anywhere but the middle (the mixer's starting pans counted)
bool SongPans(Session &S)
{
	for (int c = 0; c < S.ChannelCount(); ++c) {
		const std::vector<NoteInfo> Notes = PannedNotes(S, c);
		for (size_t i = 0; i < Notes.size(); ++i)
			if (Notes[i].Pan != PAN_CENTER)
				return true;
	}
	return false;
}

// Puts the pans Want (one per note, by where each starts) on a channel's notes in [First, End): the 8xx there go,
// and a note gets one where the pan coming into it isn't its own. The notes after the range keep theirs when the
// change is collected (KeepFollowing). False when a note had no free effect column for it.
bool PutPans(std::vector<Cell> &Cells, int First, int End, int Columns, const std::vector<std::pair<int, int> > &Want)
{
	Columns = std::max(1, std::min(EFFECT_COLUMNS, Columns));
	End = std::min(End, static_cast<int>(Cells.size()));
	for (int r = std::max(0, First); r < End; ++r)
		for (int k = 0; k < EFFECT_COLUMNS; ++k)
			if (Cells[static_cast<size_t>(r)].Effect[k] == EFF_PAN) {
				Cells[static_cast<size_t>(r)].Effect[k] = EFF_NONE;
				Cells[static_cast<size_t>(r)].Param[k] = 0;
			}
	int Now = StateAt(Cells, std::max(0, First), Columns).Sticky[EFF_PAN];
	bool Fits = true;
	for (size_t i = 0; i < Want.size(); ++i) {
		const int Row = Want[i].first;
		if (Row < First || Row >= End || Want[i].second == Now)
			continue;
		if (AddEffect(Cells[static_cast<size_t>(Row)], EFF_PAN, Want[i].second, Columns))
			Now = Want[i].second;
		else
			Fits = false;
	}
	return Fits;
}

// Arguments

const Json *Arg(const Json &Args, const char *Name)
{
	const Json *pValue = Args.Get(Name);
	return (pValue == 0 || pValue->IsNull()) ? 0 : pValue;
}

std::string StringArg(const Json &Args, const char *Name, const std::string &Default = std::string())
{
	const Json *pValue = Arg(Args, Name);
	if (pValue == 0)
		return Default;
	if (pValue->IsString())
		return Trim(pValue->String());
	if (pValue->IsNumber())
		return FormatNumber(pValue->Number());
	throw Problem(Format("%s should be text.", Name));
}

bool BoolArg(const Json &Args, const char *Name, bool Default)
{
	const Json *pValue = Arg(Args, Name);
	if (pValue == 0)
		return Default;
	if (pValue->IsBool())
		return pValue->Bool();
	if (pValue->IsString()) {
		const std::string Text = Lowercase(pValue->String());
		if (Text == "true" || Text == "yes")
			return true;
		if (Text == "false" || Text == "no")
			return false;
	}
	throw Problem(Format("%s should be true or false.", Name));
}

double NumberArg(const Json &Args, const char *Name, double Default, double Min, double Max)
{
	const Json *pValue = Arg(Args, Name);
	if (pValue == 0)
		return Default;
	double Value;
	if (pValue->IsNumber())
		Value = pValue->Number();
	else if (pValue->IsString()) {
		char *pEnd = 0;
		Value = std::strtod(pValue->String().c_str(), &pEnd);
		if (pEnd == pValue->String().c_str() || *pEnd != 0)
			throw Problem(Format("%s should be a number.", Name));
	}
	else
		throw Problem(Format("%s should be a number.", Name));
	if (!(Value >= Min && Value <= Max))
		throw Problem(Format("%s should be from %s to %s.", Name, FormatNumber(Min).c_str(), FormatNumber(Max).c_str()));
	return Value;
}

int IntArg(const Json &Args, const char *Name, int Default, int Min, int Max)
{
	const double Value = NumberArg(Args, Name, Default, Min, Max);
	if (Value != std::floor(Value))
		throw Problem(Format("%s should be a whole number.", Name));
	return static_cast<int>(Value);
}

int ParseChannel(const Session &S, const Json &Value, const char *Name)
{
	int Number = 0;
	if (Value.IsNumber()) {
		if (Value.Number() != std::floor(Value.Number()))
			throw Problem(Format("%s: channels are numbered 1-%d.", Name, S.ChannelCount()));
		Number = static_cast<int>(Value.Number());
	}
	else if (Value.IsString()) {
		std::string Text;
		const std::string Raw = Lowercase(Trim(Value.String()));
		for (size_t i = 0; i < Raw.size(); ++i)	// "VRC6  Pulse-1" -> "vrc6 pulse 1"
			if (Raw[i] != ' ' && Raw[i] != '-' && Raw[i] != '_')
				Text += Raw[i];
		if (!Text.empty() && Text.find_first_not_of("0123456789") == std::string::npos)
			Number = std::atoi(Text.c_str());
		else {
			std::string Alias = Text;
			const char *const ALIASES[][2] = {
				{ "square1", "pulse1" }, { "square2", "pulse2" }, { "tri", "triangle" }, { "saw", "sawtooth" },
				{ "vrc6saw", "vrc6sawtooth" }, { "drums", "noise" }, { "samples", "dpcm" }, { "dmc", "dpcm" }, { "fdsfds", "fds" },
			};
			for (size_t a = 0; a < sizeof(ALIASES) / sizeof(ALIASES[0]); ++a)
				if (Text == ALIASES[a][0])
					Alias = ALIASES[a][1];
			// A channel's own name before a word for one: "Square 1" is the 5B's in a 5B song, else the first pulse
			// and a VRC6 Plus's channels by their names on the VRC6 and the N163 ("VRC6 Pulse 1", "N163 Namco 1", "Namco 1")
			for (int Try = 0; Try < 2 && Number == 0; ++Try) {
				const std::string &Wanted = Try == 0 ? Text : Alias;
				for (int Pass = 0; Pass < 4 && Number == 0; ++Pass) {
					for (int c = 0; c < S.ChannelCount(); ++c) {
						const ChannelInfo &Info = S.Channel(c);
						if (Pass >= 2 && Info.Group.empty())
							continue;
						const std::string &Old = Info.OldName.empty() ? Info.Name : Info.OldName;
						std::string Full = Lowercase(Pass == 0 ? Info.FullName() : Pass == 1 ? Info.Name : Pass == 2 ? Info.Chip + " " + Old :
							Old), Squeezed;
						for (size_t i = 0; i < Full.size(); ++i)
							if (Full[i] != ' ' && Full[i] != '-' && Full[i] != '_')
								Squeezed += Full[i];
						if (Squeezed == Wanted) {
							Number = c + 1;
							break;
						}
					}
				}
			}
		}
	}
	if (Number < 1 || Number > S.ChannelCount())
		throw Problem(Format("Unknown channel for %s. The song's channels: %s.", Name, ChannelList(S).c_str()));
	return Number - 1;
}

int ChannelArg(const Session &S, const Json &Args, const char *Name, int Default = -1)
{
	const Json *pValue = Arg(Args, Name);
	if (pValue == 0) {
		if (Default >= 0)
			return Default;
		throw Problem(Format("Say which channel with %s. The song's channels: %s.", Name, ChannelList(S).c_str()));
	}
	return ParseChannel(S, *pValue, Name);
}

std::string RangeText(int From, int To);

// Sections (Sections.h): named runs of the track's frames, so whole frames of bars

int SectionFirstBar(const Session &S, const Section &Part)
{
	return Part.First * S.Time.BarsPerFrame() + 1;
}

int SectionLastBar(const Session &S, const Section &Part)
{
	return std::min(S.Time.BarCount(), (Part.Last + 1) * S.Time.BarsPerFrame());
}

// "\"Chorus\" (bars 9-16)"
std::string SectionText(const Session &S, const Section &Part)
{
	return "\"" + Part.Name + "\" (" + RangeText(SectionFirstBar(S, Part), SectionLastBar(S, Part)) + ")";
}

// A track's sections in words, with the bars no section has: "\"Intro\" bars 1-4, \"A\" bars 5-12; bars 13-16 aren't in one"
std::string SectionsText(const Session &S, const SectionList &List)
{
	std::string Text;
	std::vector<std::string> Gaps;
	bool Many = false;	// bars, not a bar
	int Bar = 1;
	auto Gap = [&](int From, int To) {
		if (To < From)
			return;
		Gaps.push_back(RangeText(From, To));
		Many = Many || To > From || Gaps.size() > 1;
	};
	for (size_t i = 0; i < List.size(); ++i) {
		const int From = SectionFirstBar(S, List[i]), To = SectionLastBar(S, List[i]);
		Gap(Bar, From - 1);
		Text += (i == 0 ? "" : ", ") + Format("\"%s\" %s", List[i].Name.c_str(), RangeText(From, To).c_str());
		Bar = To + 1;
	}
	Gap(Bar, S.Time.BarCount());
	for (size_t i = 0; i < Gaps.size(); ++i)
		Text += (i == 0 ? "; " : i + 1 == Gaps.size() ? " and " : ", ") + Gaps[i];
	if (!Gaps.empty())
		Text += Many ? " aren't in one" : " isn't in one";
	return Text;
}

// A version of the track, added as a track of its own laid out frame by
// frame like this one (Channels its cells), keeps the sections; when it
// can't, the version is there all the same
void SectionsToVersion(Session &S, const std::vector<std::vector<Cell> > &Channels)
{
	if (S.Song.Sections.empty())
		return;
	const size_t Length = static_cast<size_t>(std::max(1, S.Song.PatternLength));
	size_t Rows = Length;
	for (size_t c = 0; c < Channels.size(); ++c)
		Rows = std::max(Rows, Channels[c].size());
	SectionList List = S.Song.Sections;
	SectionsFrameCount(List, std::min(S.Song.MaxFrames, static_cast<int>((Rows + Length - 1) / Length)));
	std::string Ignored;
	if (!List.empty())
		S.Host().SetSections(List, Ignored);
}

// The section an argument names; a Problem saying which there are when there's none of that name
const Section &SectionArg(const Session &S, const Json &Args, const char *Name)
{
	const std::string Wanted = StringArg(Args, Name);
	const int Index = FindSection(S.Song.Sections, Wanted);
	if (Index >= 0)
		return S.Song.Sections[static_cast<size_t>(Index)];
	if (S.Song.Sections.empty())
		throw Problem(Format("This track has no sections yet, so none is called \"%s\". Give bars with from_bar and to_bar, or name "
			"the song's parts with name_section first.", Wanted.c_str()));
	throw Problem(Format("No section is called \"%s\". The track's sections: %s.", Wanted.c_str(),
		SectionsText(S, S.Song.Sections).c_str()));
}

// A section given in place of bars: its bars in From and To; false when there's none
bool SectionBars(const Session &S, const Json &Args, int &From, int &To)
{
	if (Arg(Args, "section") == 0)
		return false;
	if (Arg(Args, "from_bar") != 0 || Arg(Args, "to_bar") != 0)
		throw Problem("Give a section or bars (from_bar and to_bar), not both.");
	const Section &Part = SectionArg(S, Args, "section");
	From = SectionFirstBar(S, Part);
	To = SectionLastBar(S, Part);
	return true;
}

// Bars asked for, or a section
bool RangeGiven(const Json &Args)
{
	return Arg(Args, "from_bar") != 0 || Arg(Args, "to_bar") != 0 || Arg(Args, "section") != 0;
}

// The bars to work on: from_bar and to_bar (or a section), defaulting to the whole song
void BarRange(const Session &S, const Json &Args, int &From, int &To, bool PastEnd = false)
{
	if (SectionBars(S, Args, From, To))
		return;
	const int Last = PastEnd ? S.MaxBars() : S.Time.BarCount();
	From = IntArg(Args, "from_bar", 1, 1, Last);
	To = IntArg(Args, "to_bar", std::max(From, S.Time.BarCount()), 1, Last);
	if (To < From)
		throw Problem("to_bar comes before from_bar.");
}

// The sampled drum kit's instrument (DpcmKit.h), added with its samples when
// the song has none
// What a kit made by an older version gets: its samples brought up to date
const char *const KIT_REFRESHED = "The song's sampled drums were brought up to date: their old samples (the toms, mostly) slid "
	"to silence where they ended when the DPCM level started them higher, which clicked and made the bass jump.";

int SampleDrumsInstrument(Session &S)
{
	const DpcmKit &Kit = SampleDrums();
	for (size_t i = 0; i < S.Song.Instruments.size(); ++i)
		if (Lowercase(S.Song.Instruments[i].Name) == Lowercase(Kit.Name) && S.Song.Instruments[i].Chip == "2A03") {
			std::string Error;
			if (S.Host().RefreshDpcmKit(Kit, Error) > 0)
				S.Remarks.push_back(KIT_REFRESHED);
			return S.Song.Instruments[i].Index;
		}
	std::string Error;
	const int Index = S.Host().AddDpcmKit(Kit, Error);
	if (Index < 0)
		throw Problem("The sampled drums couldn't be added: " + (Error.empty() ? std::string("FamiTracker refused.") : Error));
	S.Refresh();
	S.Remarks.push_back(Format("Added the instrument %s: sampled drums for the DPCM channel (kick on C-3, snare on D-3, low tom on "
		"F-3, high tom on A-3).", InstrumentLabel(S.Song, Index).c_str()));
	return Index;
}

// What the tools say of a wave sound's level in the song (its N163 channels counted, WaveSoundDb)
std::string WaveSoundLevel(Session &S, const WaveSound &Sound)
{
	int Channels = 0;
	for (int c = 0; c < S.ChannelCount(); ++c)
		Channels += S.Channel(c).Chip == "N163" ? 1 : 0;
	bool Struck = false;
	const double Db = WaveSoundDb(Sound, Channels, Struck);
	return Format(" At volume 15 it %s about %.1f dB %s a 2A03 pulse at 15.", Struck ? "strikes" : "holds", std::fabs(Db),
		Db <= 0.0 ? "under" : "over");
}

// An N163 sound as an instrument, or the N163 one of its name already there:
// its wave goes where no other N163 instrument's is. Where says where (empty
// when it was there already).
int AddWaveInstrument(Session &S, const WaveSound &Sound, std::string &Where)
{
	const std::string Name = Lowercase(Sound.InstrumentName());
	std::vector<std::pair<int, int> > Used;
	for (size_t i = 0; i < S.Song.Instruments.size(); ++i) {
		const InstrumentInfo &I = S.Song.Instruments[i];
		if (I.Chip != "N163")
			continue;
		if (Lowercase(I.Name) == Name) {
			Where.clear();
			return I.Index;
		}
		if (I.WaveSize > 0)
			Used.push_back(std::make_pair(I.WavePos, I.WaveSize));
	}
	int Channels = 0;
	for (int c = 0; c < S.ChannelCount(); ++c)
		Channels += S.Channel(c).Chip == "N163" ? 1 : 0;
	// FamiTracker 0.4.6 loads an N163 instrument's wave only from the memory's first 128 samples: a wave placed at 128 or
	// later makes its loader stop short, and the module loads out of step. So the waves go there, whatever the chip holds.
	const int Memory = std::min(N163WaveMemory(Channels), N163_LOADABLE);
	const int Place = FindWavePlace(N163_WAVE_SIZE, Memory, Used);
	if (Place < 0)
		throw Problem(Format("The N163's wave memory is full: FamiTracker loads N163 waves only from its first %d samples (%d sounds "
			"of %d samples), and the song's N163 instruments take them all. Use one of the song's N163 instruments.", Memory,
			Memory / N163_WAVE_SIZE, N163_WAVE_SIZE));
	std::string Error;
	const int Index = S.Host().AddN163Instrument(Sound, Place, Error);
	if (Index < 0)
		throw Problem(Error.empty() ? "The instrument couldn't be added." : Error);
	S.Refresh();
	Used.push_back(std::make_pair(Place, N163_WAVE_SIZE));
	int Room = 0;
	for (std::vector<std::pair<int, int> > More(Used); FindWavePlace(N163_WAVE_SIZE, Memory, More) >= 0; ++Room)
		More.push_back(std::make_pair(FindWavePlace(N163_WAVE_SIZE, Memory, More), N163_WAVE_SIZE));
	Where = Format("its wave takes samples %d-%d of the %d FamiTracker loads N163 waves from, which have room for %d more %s", Place,
		Place + N163_WAVE_SIZE - 1, Memory, Room, Room == 1 ? "sound" : "sounds");
	return Index;
}

// An FDS sound as an instrument, or the FDS one of its name already there;
// Added says whether it's new
int AddFdsSound(Session &S, const FdsSound &Sound, bool &Added)
{
	const size_t Before = S.Song.Instruments.size();
	std::string Error;
	const int Index = S.Host().AddFdsInstrument(Sound, Error);
	if (Index < 0)
		throw Problem(Error.empty() ? "The instrument couldn't be added." : Error);
	S.Refresh();
	Added = S.Song.Instruments.size() > Before;
	return Index;
}

// A pulse sound on the sawtooth: the odd values of its duty sequence add 32
// to the sawtooth's volume, so it overdrives. Said once.
void OddDutyRemark(Session &S, const InstrumentInfo &I, const ChannelInfo &Info)
{
	const std::string Text = Format("%s is a pulse sound: the odd values of its duty sequence add 32 to the sawtooth's volume, so "
		"on %s it overdrives (louder, and distorted). For the sawtooth, name a preset (it adds a sawtooth version) or make a "
		"sound with design_instrument for that channel.", InstrumentLabel(S.Song, I.Index).c_str(), Info.FullName().c_str());
	if (std::find(S.Remarks.begin(), S.Remarks.end(), Text) == S.Remarks.end())
		S.Remarks.push_back(Text);
}

// An instrument for notes on a channel: one in the song (by name, or by its
// number as FamiTracker shows it), or a preset, which is added
int ResolveInstrument(Session &S, const std::string &Wanted, int Channel)
{
	const ChannelInfo &Info = S.Channel(Channel);
	const std::string Chip = InstrumentChip(Info);
	const std::string Lower = Lowercase(Trim(Wanted));
	if (Lower.empty())
		throw Problem("The instrument name is empty.");
	const InstrumentInfo *pWrongChip = 0;
	for (size_t i = 0; i < S.Song.Instruments.size(); ++i) {
		const InstrumentInfo &I = S.Song.Instruments[i];
		if (Lowercase(I.Name) == Lower) {
			if (I.Chip == Chip) {
				if (Info.Kind == KIND_SAWTOOTH && I.OddDuty) {
					// A pulse sound would overdrive the sawtooth: its sawtooth version, when the song has one
					for (size_t k = 0; k < S.Song.Instruments.size(); ++k)
						if (S.Song.Instruments[k].Chip == Chip && Lowercase(S.Song.Instruments[k].Name) == Lower + " (saw)")
							return S.Song.Instruments[k].Index;
					OddDutyRemark(S, I, Info);
				}
				return I.Index;
			}
			pWrongChip = &I;
		}
	}
	// The sawtooth's sounds carry " (saw)" after the name they were made under
	if (Info.Kind == KIND_SAWTOOTH)
		for (size_t i = 0; i < S.Song.Instruments.size(); ++i)
			if (S.Song.Instruments[i].Chip == Chip && Lowercase(S.Song.Instruments[i].Name) == Lower + " (saw)")
				return S.Song.Instruments[i].Index;
	// VRC7 channels play the chip's own patches (a preset's name picks the one most like it), or a
	// custom patch of this connection's design
	if (Chip == "VRC7") {
		const Vrc7Custom *pCustom = FindVrc7Custom(Wanted);
		if (pCustom != 0 && pWrongChip != 0 && Squeezed(pCustom->Name) != Squeezed(Wanted))
			pCustom = 0;	// the song's instrument of that name was meant
		if (pCustom != 0) {
			// Other custom patches the song plays already: the chip holds one at a time
			std::string Others;
			for (size_t i = 0; i < S.Song.Instruments.size(); ++i) {
				const InstrumentInfo &I = S.Song.Instruments[i];
				const Vrc7Custom *pOther = I.Chip == "VRC7" ? FindVrc7Custom(I.Name) : 0;
				if (pOther != 0 && pOther != pCustom)
					Others += (Others.empty() ? "" : ", ") + InstrumentLabel(S.Song, I.Index);
			}
			const size_t Before = S.Song.Instruments.size();
			std::string Error;
			const std::vector<int> Regs(pCustom->Regs, pCustom->Regs + 8);
			const int Index = S.Host().AddVrc7CustomInstrument(Regs, pCustom->InstrumentName(), Error);
			if (Index < 0)
				throw Problem(Error.empty() ? "The instrument couldn't be added." : Error);
			S.Refresh();
			if (S.Song.Instruments.size() > Before) {
				S.Remarks.push_back(Format("Added the instrument %s (a VRC7 custom patch: %s).", InstrumentLabel(S.Song, Index).c_str(),
					pCustom->Description.c_str()));
				if (!Others.empty())
					S.Remarks.push_back("The VRC7 holds one custom patch at a time, and " + Others + " plays another: where two "
						"channels play both at once, both sound like the one struck last. Keep custom patches to different "
						"sections, or give one part a built-in sound.");
			}
			return Index;
		}
		const Vrc7Patch *pPatch = FindVrc7Patch(Wanted);
		if (pPatch != 0 && pWrongChip != 0 && Squeezed(pPatch->Name) != Squeezed(Wanted)) {
			// The song's instrument of that name was meant, unless that's a preset's own name (a 2A03 "Soft lead"
			// from the preset): then it's the preset's VRC7 sound
			const Preset *pNamed = FindPreset(Wanted);
			if (pNamed == 0 || Squeezed(pNamed->Name) != Squeezed(Wanted))
				pPatch = 0;
		}
		if (pPatch != 0) {
			const size_t Before = S.Song.Instruments.size();
			std::string Error;
			const int Index = S.Host().AddVrc7Instrument(pPatch->Number, pPatch->InstrumentName(), Error);
			if (Index < 0)
				throw Problem(Error.empty() ? "The instrument couldn't be added." : Error);
			S.Refresh();
			if (S.Song.Instruments.size() > Before)
				S.Remarks.push_back(Format("Added the instrument %s (VRC7 patch %d, %s).", InstrumentLabel(S.Song, Index).c_str(),
					pPatch->Number, pPatch->Description.c_str()));
			return Index;
		}
	}
	// 5B channels play the chip's own sounds (a buzz bass, a noise hat) and the presets, made for it
	if (Chip == "5B") {
		const Preset *pSound = FindSoundFor5B(Wanted);
		if (pSound != 0 && pWrongChip != 0 && Squeezed(pSound->Name) != Squeezed(Wanted))
			pSound = 0;	// the song's instrument of that name was meant
		if (pSound != 0) {
			const size_t Before = S.Song.Instruments.size();
			std::string Error;
			const int Index = S.Host().AddInstrument(*pSound, Chip, false, Error);
			if (Index < 0)
				throw Problem(Error.empty() ? "The instrument couldn't be added." : Error);
			S.Refresh();
			if (S.Song.Instruments.size() > Before)
				S.Remarks.push_back(Format("Added the instrument %s (5B: %s).", InstrumentLabel(S.Song, Index).c_str(),
					pSound->Description.c_str()));
			return Index;
		}
	}
	// N163 channels play wave sounds drawn for them (a preset's name picks the one most like it)
	if (Chip == "N163") {
		const WaveSound *pSound = FindWaveSound(Wanted);
		if (pSound != 0) {
			const size_t Before = S.Song.Instruments.size();
			std::string Where;
			const int Index = AddWaveInstrument(S, *pSound, Where);
			if (S.Song.Instruments.size() > Before)
				S.Remarks.push_back(Format("Added the instrument %s (N163: %s; %s).", InstrumentLabel(S.Song, Index).c_str(),
					pSound->Description.c_str(), Where.c_str()));
			return Index;
		}
	}
	// The FDS plays sounds drawn for it: a wave and its modulator (a preset's name picks the one most like it)
	if (Chip == "FDS") {
		const FdsSound *pSound = FindFdsSound(Wanted);
		const Preset *pLike = pSound == 0 ? FindPreset(Wanted) : 0;
		if (pLike != 0 && !pLike->Drum)
			pSound = FindFdsSound(pLike->Name);	// a preset's word ("keys" is the organ): the FDS sound most like that preset
		if (pSound != 0) {
			bool Added = false;
			const int Index = AddFdsSound(S, *pSound, Added);
			if (Added)
				S.Remarks.push_back(Format("Added the instrument %s (FDS: %s).", InstrumentLabel(S.Song, Index).c_str(),
					pSound->Description.c_str()));
			return Index;
		}
	}
	const Preset *pPreset = FindPreset(Wanted);
	if (pPreset != 0 && pWrongChip != 0 && Squeezed(pPreset->Name) != Squeezed(Wanted))
		pPreset = 0;	// the song's instrument of that name was meant, not a preset it's a nickname of
	if (pPreset != 0) {
		if (pPreset->Drum && Info.Kind != KIND_NOISE)
			throw Problem(Format("The preset \"%s\" is a drum for the noise channel.", pPreset->Name.c_str()));
		if (!pPreset->Drum && Info.Kind == KIND_NOISE)
			throw Problem(Format("The noise channel needs a drum preset (kick, snare, hi-hat, open hi-hat), not \"%s\".", pPreset->Name.c_str()));
		if (Chip == "FDS")
			throw Problem(Format("The FDS channel plays the FDS's own sounds: %s. \"%s\" isn't one of them.", FdsSoundList().c_str(),
				pPreset->Name.c_str()));
		if (Chip != "2A03" && Chip != "VRC6")
			throw Problem(Format("Presets are for 2A03, MMC5, VRC6, VRC7 and 5B channels; %s needs one of the song's %s instruments.",
				Info.FullName().c_str(), Chip.c_str()));
		const size_t Before = S.Song.Instruments.size();
		std::string Error;
		const int Index = S.Host().AddInstrument(*pPreset, Chip, Info.Kind == KIND_SAWTOOTH, Error);
		if (Index < 0)
			throw Problem(Error.empty() ? "The instrument couldn't be added." : Error);
		S.Refresh();
		if (S.Song.Instruments.size() > Before)
			S.Remarks.push_back(Format("Added the instrument %s (%s) from the preset \"%s\".", InstrumentLabel(S.Song, Index).c_str(),
				Chip.c_str(), pPreset->Name.c_str()));
		return Index;
	}
	int Number = -1;
	if (Lower.size() <= 2 && Lower.find_first_not_of("0123456789abcdef") == std::string::npos)
		Number = static_cast<int>(std::strtol(Lower.c_str(), 0, 16));	// as FamiTracker shows it: "0A"
	if (Number >= 0) {
		const InstrumentInfo *pInfo = FindInstrument(S.Song, Number);
		if (pInfo != 0) {
			if (pInfo->Chip != Chip)
				throw Problem(Format("Instrument %02X \"%s\" is %s instrument; %s needs %s one. A preset name (like \"soft lead\") adds one.",
					Number, pInfo->Name.c_str(), AChip(pInfo->Chip).c_str(), Info.FullName().c_str(), AChip(Chip).c_str()));
			if (Info.Kind == KIND_SAWTOOTH && pInfo->OddDuty)
				OddDutyRemark(S, *pInfo, Info);
			return Number;
		}
	}
	if (pWrongChip != 0)
		throw Problem(Format("\"%s\" is %s instrument; %s needs %s one. A preset name (like \"soft lead\") adds one.",
			pWrongChip->Name.c_str(), AChip(pWrongChip->Chip).c_str(), Info.FullName().c_str(), AChip(Chip).c_str()));
	std::string Names;
	for (size_t i = 0; i < S.Song.Instruments.size(); ++i) {
		if (S.Song.Instruments[i].Chip != Chip)
			continue;
		if (!Names.empty())
			Names += ", ";
		Names += "\"" + S.Song.Instruments[i].Name + "\"";
	}
	if (Chip == "VRC7")
		throw Problem(Format("No instrument or VRC7 sound called \"%s\". VRC7 instruments in the song: %s. VRC7 sounds: %s (or a preset's "
			"name, like \"soft lead\"); custom ones: %s.", Wanted.c_str(), Names.empty() ? "none" : Names.c_str(), Vrc7PatchList().c_str(),
			Vrc7CustomList().c_str()));
	if (Chip == "N163")
		throw Problem(Format("No instrument or N163 sound called \"%s\". N163 instruments in the song: %s. N163 sounds: %s.",
			Wanted.c_str(), Names.empty() ? "none" : Names.c_str(), WaveSoundList().c_str()));
	if (Chip == "5B")
		throw Problem(Format("No instrument, 5B sound or preset called \"%s\". 5B instruments in the song: %s. 5B sounds: %s; "
			"presets: %s.", Wanted.c_str(), Names.empty() ? "none" : Names.c_str(), Sound5BList().c_str(), PresetList().c_str()));
	if (Chip == "FDS")
		throw Problem(Format("No instrument or FDS sound called \"%s\". FDS instruments in the song: %s. FDS sounds: %s.",
			Wanted.c_str(), Names.empty() ? "none" : Names.c_str(), FdsSoundList().c_str()));
	throw Problem(Format("No instrument or preset called \"%s\". %s instruments in the song: %s. Presets: %s.", Wanted.c_str(),
		Chip.c_str(), Names.empty() ? "none" : Names.c_str(), PresetList().c_str()));
}

int InstrumentArg(Session &S, const Json &Args, const char *Name, int Channel, int Default)
{
	const Json *pValue = Arg(Args, Name);
	if (pValue == 0)
		return Default;
	if (pValue->IsNumber())
		return ResolveInstrument(S, Format("%02X", static_cast<int>(pValue->Number())), Channel);
	return ResolveInstrument(S, StringArg(Args, Name), Channel);
}

// The instrument a channel plays with at Row, if it fits the channel
int InstrumentAt(Session &S, int Channel, int Row)
{
	const ChannelState State = StateAt(S.Cells(Channel), Row, S.Channel(Channel).EffectColumns);
	int Index = State.Instrument;
	if (Index == NO_INSTRUMENT) {
		// Or the first one of the channel's notes after it
		const std::vector<NoteInfo> &Notes = S.Notes(Channel);
		for (size_t i = 0; i < Notes.size() && Index == NO_INSTRUMENT; ++i)
			if (Notes[i].Row >= Row)
				Index = Notes[i].Instrument;
	}
	const InstrumentInfo *pInfo = FindInstrument(S.Song, Index);
	return (pInfo != 0 && pInfo->Chip == InstrumentChip(S.Channel(Channel))) ? Index : NO_INSTRUMENT;
}

// Keys and melodies for the harmony code

// The pitch a note lands on: a slide as it starts (a scoop, written a
// semitone or two low and sliding up at once) counts where it lands
int LandedPitch(const NoteInfo &N)
{
	int Pitch = N.Pitch;
	for (size_t e = 0; e < N.Effects.size(); ++e) {
		if (N.Effects[e].first != 0)
			continue;
		if (N.Effects[e].second.first == EFF_SLIDE_UP)
			Pitch += N.Effects[e].second.second & 0x0F;
		else if (N.Effects[e].second.first == EFF_SLIDE_DOWN)
			Pitch -= N.Effects[e].second.second & 0x0F;
	}
	return Pitch;
}

std::vector<transcribe::MelodyNote> MelodyOf(const std::vector<NoteInfo> &Notes, int First, int End)
{
	std::vector<transcribe::MelodyNote> Melody;
	for (size_t i = 0; i < Notes.size(); ++i) {
		const NoteInfo &N = Notes[i];
		if (N.Row < First || N.Row >= End)
			continue;
		transcribe::MelodyNote M;
		M.row = N.Row;
		M.length = std::max(1, N.Rows);
		M.midi = LandedPitch(N) + 24;	// C-0 is MIDI note 24
		M.weight = std::max(0.3, N.Volume / 15.0);
		Melody.push_back(M);
	}
	return Melody;
}

transcribe::Key HarmonyKey(const Key &K)
{
	transcribe::Key Out;
	Out.tonic = K.Tonic;
	Out.minor = K.Mode == MODE_MINOR || K.Mode == 1 || K.Mode == 2 || K.Mode == 6 || K.Mode == 7;	// dorian, phrygian, locrian, harmonic minor
	return Out;
}

std::vector<int> StickyAt(const std::vector<Cell> &Cells, const std::vector<NoteInfo> &Notes, int Columns, int Effect);

// The key from the notes of every melodic channel in [First, End), or the
// whole song when that's too few. False when there are no notes.
bool FindKey(Session &S, int First, int End, Key &Out)
{
	for (int Pass = 0; Pass < 2; ++Pass) {
		std::vector<transcribe::MelodyNote> All;
		for (int c = 0; c < S.ChannelCount(); ++c) {
			if (!IsMelodic(S.Channel(c)))
				continue;
			const int From = Pass == 0 ? First : 0, To = Pass == 0 ? End : S.Time.TotalRows();
			const std::vector<transcribe::MelodyNote> Part = MelodyOf(S.Notes(c), From, To);
			All.insert(All.end(), Part.begin(), Part.end());
			// The chords arpeggios sound (0xy, or the instrument's own) count too, a little less; a 0xy lasts until a 000,
			// wherever that is (on a release's row too)
			const std::vector<NoteInfo> &Notes = S.Notes(c);
			const std::vector<int> Arpeggios = StickyAt(S.Cells(c), Notes, S.Channel(c).EffectColumns, EFF_ARPEGGIO);
			for (size_t i = 0; i < Notes.size(); ++i) {
				const NoteInfo &N = Notes[i];
				if (N.Row < From || N.Row >= To)
					continue;
				const std::vector<int> Above = ChordAbove(S, N, Arpeggios[i]);
				for (size_t a = 0; a < Above.size(); ++a) {
					transcribe::MelodyNote M;
					M.row = N.Row;
					M.length = std::max(1, N.Rows);
					M.midi = N.Pitch + Above[a] + 24;
					M.weight = 0.7 * std::max(0.3, N.Volume / 15.0);
					All.push_back(M);
				}
			}
		}
		if (All.size() >= 4 || (Pass == 1 && !All.empty())) {
			std::sort(All.begin(), All.end(), [](const transcribe::MelodyNote &a, const transcribe::MelodyNote &b) { return a.row < b.row; });
			const transcribe::Key K = transcribe::FindKey(All);
			Out = Key(K.tonic, K.minor ? MODE_MINOR : MODE_MAJOR);
			// A key the notes keep leaving (the G naturals of a song heard as F# minor) gives way to one they
			// fit, the one whose tonic chord sounds most: progressions that circle the tonic without
			// landing on it (IVmaj7 V7 iii7 vi7) fool the profile of the notes alone
			double Weight[12] = { 0 }, Total = 0.0;
			for (size_t i = 0; i < All.size(); ++i) {
				const double w = All[i].length * All[i].weight;
				Weight[(All[i].midi % 12 + 12) % 12] += w;
				Total += w;
			}
			auto Outside = [&](const Key &Candidate) {
				double Off = 0.0;
				const int *pSteps = ModeSteps(Candidate.Mode);
				for (int pc = 0; pc < 12; ++pc) {
					bool In = false;	// the scale itself (a minor key's raised seventh would favour it over its relative major)
					for (int s = 0; s < 7; ++s)
						In = In || (Candidate.Tonic + pSteps[s]) % 12 == pc;
					if (!In)
						Off += Weight[pc];
				}
				return Off / std::max(Total, 1e-9);
			};
			const double Own = Outside(Out);
			double Least = Own;
			for (int t = 0; t < 12; ++t)
				for (int m = 0; m < 2; ++m)
					Least = std::min(Least, Outside(Key(t, m ? MODE_MINOR : MODE_MAJOR)));
			if (Own > Least + 0.04 && Own > 1.5 * Least) {
				double BestTriad = -1.0;
				for (int t = 0; t < 12; ++t)
					for (int m = 0; m < 2; ++m) {
						const Key Candidate(t, m ? MODE_MINOR : MODE_MAJOR);
						if (Outside(Candidate) > Least + 1e-9)
							continue;
						const double Triad = 1.5 * Weight[t] + Weight[(t + (m ? 3 : 4)) % 12] + Weight[(t + 7) % 12];
						if (Triad > BestTriad) {
							BestTriad = Triad;
							Out = Candidate;
						}
					}
			}
			return true;
		}
	}
	return false;
}

// The key the tools use where they're given none: the one chosen for the
// track (Keys.h: in FamiTracker's piano roll, or with set_key), else the one
// the notes in [First, End) fit. False when none is chosen and there are no
// notes.
bool TrackKey(Session &S, int First, int End, Key &Out)
{
	if (S.Song.KeyChosen) {
		Out = S.Song.ChosenKey.K;
		return true;
	}
	return FindKey(S, First, End, Out);
}

// Where a key the tools used came from, for their replies: "" when the call gave it
std::string KeySource(const Session &S, const Json &Args, const char *Name = "key")
{
	if (!StringArg(Args, Name).empty())
		return std::string();
	return S.Song.KeyChosen ? " (the track's key, chosen for it)" : " (found from the notes)";
}

Key KeyArg(Session &S, const Json &Args, const char *Name, int First, int End, bool &Found)
{
	const std::string Text = StringArg(Args, Name);
	Key K;
	Found = true;
	if (!Text.empty()) {
		if (!ParseKey(Text, K))
			throw Problem(Format("%s: \"%s\" isn't a key. Write it like \"C major\", \"A minor\", \"F# dorian\" or \"Bbm\".", Name, Text.c_str()));
		return K;
	}
	Found = TrackKey(S, First, End, K);
	return K;
}

// The track's chosen key once every melodic note of the song moved from
// FromKey to ToKey (transpose, change_mood, a version): the choice goes
// along, so the piano roll and the tools follow the notes. False when it
// stays: none is chosen, or it isn't the key the notes moved from.
bool KeyAfterMove(const Session &S, const Key &FromKey, const Key &ToKey, KeyChoice &Out)
{
	if (!S.Song.KeyChosen || S.Song.ChosenKey.K.Tonic != FromKey.Tonic || S.Song.ChosenKey.K.Mode != FromKey.Mode)
		return false;
	Out = KeyChoice(ToKey, S.Song.ChosenKey.Pentatonic && CanBePentatonic(ToKey));
	return Out != S.Song.ChosenKey;
}

// A version (keep_version, make_version, the selected track now) keeps the
// track's chosen key, moved along when the version moved the whole song from
// it to another key (pFrom, pTo)
void KeyToVersion(Session &S, const Key *pFrom, const Key *pTo)
{
	if (!S.Song.KeyChosen)
		return;
	KeyChoice Kept = S.Song.ChosenKey, Moved;
	if (pFrom != 0 && pTo != 0 && KeyAfterMove(S, *pFrom, *pTo, Moved))
		Kept = Moved;
	std::string Ignored;
	S.Host().SetKey(true, Kept, Ignored);
}

// "| C | F C | G | C |", up to 32 bars
std::string ChordsText(const std::vector<transcribe::ChordSpan> &Chords, const std::vector<transcribe::Bar> &Bars,
	const transcribe::Key &K)
{
	std::string Text;
	for (size_t b = 0; b < Bars.size(); ++b) {
		if (b == 32) {
			Text += "| ...";
			return Text;
		}
		Text += "|";
		const int BarEnd = Bars[b].row + Bars[b].length;
		for (size_t c = 0; c < Chords.size(); ++c) {
			const transcribe::ChordSpan &Span = Chords[c];
			const int From = std::max(Span.row, Bars[b].row);
			if (From < std::min(Span.row + Span.length, BarEnd) && (From == Bars[b].row || From == Span.row)) {
				Text += " ";
				Text += transcribe::ChordName(Span.chord, K);
			}
		}
		Text += " ";
	}
	Text += "|";
	return Text;
}

// A channel's notes that start in [First, End)
std::vector<NoteInfo> NotesIn(const std::vector<NoteInfo> &Notes, int First, int End)
{
	std::vector<NoteInfo> Out;
	for (size_t i = 0; i < Notes.size(); ++i)
		if (Notes[i].Row >= First && Notes[i].Row < End)
			Out.push_back(Notes[i]);
	return Out;
}

// The pitch half of the notes' time is spent below, or Default
int MiddleOf(const std::vector<NoteInfo> &Notes, int Default)
{
	std::vector<std::pair<int, int> > Pitches;
	int Total = 0;
	for (size_t i = 0; i < Notes.size(); ++i) {
		Pitches.push_back(std::make_pair(Notes[i].Pitch, std::max(1, Notes[i].Rows)));
		Total += std::max(1, Notes[i].Rows);
	}
	if (Pitches.empty())
		return Default;
	std::sort(Pitches.begin(), Pitches.end());
	int Sum = 0;
	for (size_t i = 0; i < Pitches.size(); ++i) {
		Sum += Pitches[i].second;
		if (Sum * 2 >= Total)
			return Pitches[i].first;
	}
	return Pitches.back().first;
}

// The channel most likely to play the melody in [First, End): of the
// melodic channels that aren't bass channels or mostly 0xy chords (any of
// them when only those play), the one with the most notes, notes higher up
// counting for more: a melody is usually the top line, and an accompaniment
// of many quick notes sits under it
// Whether a channel mostly repeats another's notes a little later (an echo of it)
bool EchoesAnother(Session &S, int Channel, const std::vector<NoteInfo> &Notes, int First, int End)
{
	if (Notes.size() < 4)
		return false;
	for (int o = 0; o < S.ChannelCount(); ++o) {
		if (o == Channel || !IsMelodic(S.Channel(o)))
			continue;
		const std::vector<NoteInfo> Theirs = NotesIn(S.Notes(o), First, End);
		if (Theirs.size() < 4)
			continue;
		std::map<int, int> PitchAt;
		for (size_t i = 0; i < Theirs.size(); ++i)
			PitchAt[Theirs[i].Row] = Theirs[i].Pitch;
		for (int Delay = 1; Delay <= std::max(1, S.Time.RowsPerBar); ++Delay) {
			size_t Same = 0;
			for (size_t i = 0; i < Notes.size(); ++i) {
				std::map<int, int>::const_iterator it = PitchAt.find(Notes[i].Row - Delay);
				if (it != PitchAt.end() && (it->second - Notes[i].Pitch) % 12 == 0)
					++Same;
			}
			if (Same * 10 >= Notes.size() * 7)
				return true;
		}
	}
	return false;
}

// A steady run of quick notes of one length (an arpeggio, broken chords, an
// ostinato): accompaniment, however busy
bool RunsSteadily(const Session &S, const std::vector<NoteInfo> &Notes)
{
	if (Notes.size() < 16)
		return false;
	std::map<int, int> Lengths;
	int Most = 0;
	for (size_t i = 0; i + 1 < Notes.size(); ++i)
		Most = std::max(Most, ++Lengths[Notes[i].Rows]);
	const int Span = Notes.back().Row - Notes.front().Row;
	const double PerBeat = Span > 0 ? (Notes.size() - 1) * static_cast<double>(std::max(1, S.Time.RowsPerBeat)) / Span : 0.0;
	return Most * 20 >= static_cast<int>(Notes.size() - 1) * 17 && PerBeat >= 2.0;
}

int GuessMelodyChannel(Session &S, int First, int End)
{
	for (int Pass = 0; Pass < 3; ++Pass) {
		std::vector<int> Channels, Counts, Middles, Loudness;
		int Lowest = 1000;
		for (int c = 0; c < S.ChannelCount(); ++c) {
			const ChannelInfo &Info = S.Channel(c);
			if (!IsMelodic(Info) || (Pass < 2 && IsBass(Info)))
				continue;
			const std::vector<NoteInfo> Notes = NotesIn(S.Notes(c), First, End);
			if (Notes.empty())
				continue;
			int Chords = 0;
			for (size_t i = 0; i < Notes.size(); ++i)
				if (SoundsChord(S, Notes[i]))
					++Chords;
			if (Pass == 0 && Chords * 3 >= static_cast<int>(Notes.size()))
				continue;
			// An echo of another part isn't the melody
			if (Pass < 2 && EchoesAnother(S, c, Notes, First, End))
				continue;
			const int Middle = MiddleOf(Notes, 48) - Written(Info, 0);	// as it sounds
			// How loud it usually plays (the triangle has no volume)
			std::vector<int> Volumes;
			for (size_t i = 0; i < Notes.size(); ++i)
				Volumes.push_back(Info.Kind == KIND_TRIANGLE ? 15 : Notes[i].Volume);
			std::sort(Volumes.begin(), Volumes.end());
			Channels.push_back(c);
			// A steady run counts as a part of a few notes, so a melody over it wins
			Counts.push_back(RunsSteadily(S, Notes) ? static_cast<int>(Notes.size()) / 8 : static_cast<int>(Notes.size()));
			Middles.push_back(Middle);
			Loudness.push_back(std::max(1, Volumes[Volumes.size() / 2]));
			Lowest = std::min(Lowest, Middle);
		}
		int Best = -1;
		double BestScore = 0.0;
		for (size_t i = 0; i < Channels.size(); ++i) {
			// Busy and high, and loud: a quiet part is seldom the melody
			const double Score = Counts[i] * std::pow(2.0, (Middles[i] - Lowest) / 8.0) * std::pow(Loudness[i] / 15.0, 2.0);
			if (Score > BestScore) {
				Best = Channels[i];
				BestScore = Score;
			}
		}
		if (Best >= 0)
			return Best;
	}
	return -1;
}

bool NoteStartsIn(Session &S, int Channel, int First, int End)
{
	const std::vector<NoteInfo> &Notes = S.Notes(Channel);
	for (size_t i = 0; i < Notes.size(); ++i)
		if (Notes[i].Row >= First && Notes[i].Row < End)
			return true;
	return false;
}

bool HasNotesIn(Session &S, int Channel, int First, int End)
{
	const std::vector<NoteInfo> &Notes = S.Notes(Channel);
	for (size_t i = 0; i < Notes.size(); ++i)
		if (Notes[i].Row < End && Notes[i].Row + Notes[i].Rows > First)
			return true;
	return false;
}

// Calm and lively tracks. mix, polish, check_song and review_arrangement take a style: calm (a night or ambient track:
// the melody only a little over the chords, no accents, a lead whose sound never holds a high, steady level, which
// sounds aggressive) or lively (a stage that bounces without pressing: the melody 3-4 dB
// over the parts, notes that fade). Calm applies only when asked, or when the track's name says so ("Town (night)"),
// a label the user gave it; a track that only looks calm (slow, no drums) gets a line suggesting it, and nothing changes
enum track_style { STYLE_ANY, STYLE_CALM, STYLE_LIVELY };

struct TrackStyle {
	int Style;			// track_style
	std::string Note;	// for the reply: why the tool chose calm by itself, or that the track looks calm; empty for neither
	TrackStyle() : Style(STYLE_ANY) {}
};

bool NameSaysCalm(const std::string &TrackName);	// VersionMood's calm (with the depth review)
double FramesPerRow(const Session &S);

// A hit of a drum kit on the noise channel: a sound that strikes (at its peak within three frames) and is gone within
// half a second, or cut as short (Frames: how long the note lasts); a swell of wind or waves, or a held hiss, isn't one
bool IsDrumHit(Session &S, const NoteInfo &N, int Frames)
{
	const InstrumentInfo *pInfo = FindInstrument(S.Song, N.Instrument);
	const std::vector<int> Envelope = HeldEnvelope(pInfo, 64);
	const int Peak = *std::max_element(Envelope.begin(), Envelope.end());
	int Attack = 0;
	while (Attack < 63 && Envelope[static_cast<size_t>(Attack)] * 10 < Peak * 9)
		++Attack;
	return Peak > 0 && N.Volume > 0 && Attack <= 3 && std::min(Frames, HeardFramesOf(pInfo, N.Volume, 64)) <= 30;
}

// A track that sounds calm by its numbers: slow (about 90 BPM or under, at its tempo) with no drum kit (no drum hits on
// the noise channel and no samples on the DPCM channel); Bpm its tempo
bool LooksCalm(Session &S, double &Bpm)
{
	Bpm = BeatsPerMinute(S.Song.Speed, S.Song.Tempo, S.Song.FrameRate, S.Time.RowsPerBeat);
	if (Bpm >= 90.5)
		return false;
	const double RowFrames = FramesPerRow(S);
	bool Any = false;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		const int Kind = S.Channel(c).Kind;
		const std::vector<NoteInfo> &Notes = S.Notes(c);
		Any = Any || !Notes.empty();
		for (size_t i = 0; i < Notes.size() && (Kind == KIND_NOISE || Kind == KIND_DPCM); ++i)
			if (Kind == KIND_DPCM || IsDrumHit(S, Notes[i], static_cast<int>(std::floor(Notes[i].Rows * RowFrames + 0.5))))
				return false;
	}
	return Any;
}

// The style a tool works in: Given (track_style; -1 when the call gave none). Without one, calm when the track's name
// says so; otherwise none, and when the track looks calm a line suggests it (CalmDoes: what style calm does there;
// Usual: the style that keeps a calm-named track out of calm)
TrackStyle ChooseStyle(Session &S, int Given, const char *CalmDoes, const char *Usual)
{
	TrackStyle Out;
	if (Given >= 0) {
		Out.Style = Given;
		return Out;
	}
	if (NameSaysCalm(S.Song.TrackName)) {
		Out.Style = STYLE_CALM;
		Out.Note = Format("Calm: the track's name says so (style %s to change).", Usual);
		return Out;
	}
	double Bpm = 0.0;
	if (LooksCalm(S, Bpm))
		Out.Note = Format("This looks calm (%s BPM, no drums): style calm %s.", FormatNumber(std::floor(Bpm + 0.5)).c_str(), CalmDoes);
	return Out;
}

// polish's, check_song's and review_arrangement's style argument: any, calm (or ambient), lively; -1 when not given
int StyleArg(const Json &Args)
{
	if (Arg(Args, "style") == 0)
		return -1;
	const std::string Word = Squeezed(StringArg(Args, "style"));
	if (Word == "calm" || Word == "ambient" || Word == "night" || Word == "peaceful")
		return STYLE_CALM;
	if (Word == "lively")
		return STYLE_LIVELY;
	if (Word == "any" || Word == "none" || Word == "normal")
		return STYLE_ANY;
	throw Problem("style should be any or calm (also \"ambient\"), or lively.");
}

// Changes go into the song, or become a clip

struct Change {
	int Channel;
	std::vector<Cell> Cells;	// from the first row on
};

bool Direct(const Session &S, bool AsClip)
{
	return S.Song.DirectChanges && !AsClip;
}

PartOptions OptionsFor(const Session &S, int Channel, bool DirectChange)
{
	PartOptions Options;
	Options.EffectColumns = S.Channel(Channel).EffectColumns;
	Options.Releases = ReleasingInstruments(S.Song);
	// The triangle can't fade: a release plays on at full volume until the instrument's release reaches 0 (a row or
	// more), so a staccato note would sound held. Its notes end with a halt.
	if (S.Channel(Channel).Kind == KIND_TRIANGLE)
		Options.Releases.assign(Options.Releases.size(), false);
	Options.KeepFollowing = DirectChange;
	Options.StopAtEnd = !DirectChange;
	Options.RingOut = S.Channel(Channel).Kind == KIND_DPCM;
	return Options;
}

// Clicks on the 2A03's and MMC5's pulses (PulseClicks.h)

// The multiple of 256 a note's vibrato crosses: the one nearest its period
int ClickBoundary(const SongInfo &Song, const ClickFix &F)
{
	const int Period = PulsePeriod(F.Pitch, Song.Pal) + 0x80 - (F.Fine + F.Shift);
	return std::max(256, (Period + 128) / 256 * 256);
}

// A nudge in words: "P81, 7 cents sharp", or "P84 from bar 5 beat 2 as its vibrato starts, 21 cents sharp"
std::string NudgeText(Session &S, const ClickFix &F)
{
	const int Period = PulsePeriod(F.Pitch, S.Song.Pal) + 0x80 - (F.Fine + F.Shift);
	return Format("P%02X%s, %.0f cents %s", F.Fine, F.At != F.Row ? (" from " + S.Time.Position(F.At) + " as its vibrato starts").c_str() :
		"", NudgeCents(Period, F.Shift), F.Shift < 0 ? "sharp" : "flat");
}

// What smoothing a channel's clicks did, for a tool's answer ("" when no note clicked)
std::string SmoothedText(Session &S, int Channel, const std::vector<ClickFix> &Fixes)
{
	const int LISTED = 4;
	std::string Nudged, Stuck;
	int NudgedCount = 0, StuckCount = 0;
	for (size_t i = 0; i < Fixes.size(); ++i) {
		const ClickFix &F = Fixes[i];
		const std::string Where = Format("%s at %s", PitchName(F.Pitch).c_str(), S.Time.Position(F.Row).c_str());
		if (F.Shift != 0 && F.Left == 0) {
			if (++NudgedCount <= LISTED)
				Nudged += (Nudged.empty() ? "" : ", ") + Where + " (" + NudgeText(S, F) + ")";
		}
		else if (++StuckCount <= LISTED)
			Stuck += (Stuck.empty() ? "" : ", ") + Where;
	}
	const std::string Name = S.Channel(Channel).FullName();
	std::string Text;
	if (NudgedCount > 0)
		Text = Format("%s on %s nudged a hair so %s vibrato doesn't click (the 2A03's pulses restart their wave when a "
			"vibrato takes the period across a multiple of 256): %s%s.", Plural(NudgedCount, "note", "notes").c_str(), Name.c_str(),
			NudgedCount == 1 ? "its" : "their", Nudged.c_str(), NudgedCount > LISTED ? ", ..." : "");
	if (StuckCount > 0)
		Text += (Text.empty() ? "" : " ") + Format("%s on %s still click%s: %s, %s vibrato too deep to nudge clear (a gentler "
			"vibrato, or another channel, stops it).", Plural(StuckCount, "note", "notes").c_str(), Name.c_str(),
			StuckCount == 1 ? "s" : "", (Stuck + (StuckCount > LISTED ? ", ..." : "")).c_str(), StuckCount == 1 ? "its" : "their");
	return Text;
}

// The song's notes that click on the 2A03's and MMC5's pulses, those that sound in [First, End): each with its channel
std::vector<std::pair<int, ClickFix> > SongClicks(Session &S, int First, int End)
{
	std::vector<std::pair<int, ClickFix> > Out;
	std::vector<std::vector<Cell> > Channels;
	std::vector<int> Columns;
	bool Any = false;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		Channels.push_back(S.Cells(c));
		Columns.push_back(S.Channel(c).EffectColumns);
		Any = Any || ClicksOnPeriods(S.Channel(c));
	}
	if (!Any)
		return Out;
	int LoopRow = -1;
	const std::vector<std::pair<int, int> > Played = PlayedFrames(S.Song, Channels, Columns, LoopRow);
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (!ClicksOnPeriods(S.Channel(c)))
			continue;
		int Shown = Columns[static_cast<size_t>(c)];
		bool Lost = false;
		const std::vector<ClickFix> Fixes = SmoothClicks(S.Song, Channels[static_cast<size_t>(c)], Shown, First, End, Played,
			LoopRow, false, Lost);
		for (size_t i = 0; i < Fixes.size(); ++i)
			Out.push_back(std::make_pair(c, Fixes[i]));
	}
	return Out;
}

// A direct change's notes on the 2A03's and MMC5's pulses that would click are nudged: those that sound in the rows it
// writes. The changes grow to the rows the nudges touch (the fine pitch back on the next note, or on the loop's first
// note), First moving back when that's before them; Notes says what was done. Without Fix (a clip, whose neighbours
// are the song's once it's placed), Notes only says which would click.
void SmoothChanges(Session &S, std::vector<Change> &Changes, int &First, std::vector<std::string> &Notes, bool Fix = true)
{
	bool Any = false;
	for (size_t i = 0; i < Changes.size(); ++i)
		Any = Any || ClicksOnPeriods(S.Channel(Changes[i].Channel));
	if (!Any)
		return;
	// The song as the change leaves it
	std::vector<std::vector<Cell> > Channels;
	std::vector<int> Columns;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		Channels.push_back(S.Cells(c));
		Columns.push_back(S.Channel(c).EffectColumns);
	}
	int End = First;
	for (size_t i = 0; i < Changes.size(); ++i) {
		std::vector<Cell> &Cells = Channels[static_cast<size_t>(Changes[i].Channel)];
		const size_t Need = static_cast<size_t>(First) + Changes[i].Cells.size();
		if (Cells.size() < Need)
			Cells.resize(Need);
		std::copy(Changes[i].Cells.begin(), Changes[i].Cells.end(), Cells.begin() + First);
		End = std::max(End, static_cast<int>(Need));
	}
	int LoopRow = -1;
	const std::vector<std::pair<int, int> > Played = PlayedFrames(S.Song, Channels, Columns, LoopRow);
	bool Lost = false;
	std::set<int> Touched;	// channels the nudges changed
	int Low = First, High = End;
	for (size_t i = 0; i < Changes.size(); ++i) {
		const int c = Changes[i].Channel;
		if (!ClicksOnPeriods(S.Channel(c)))
			continue;
		std::vector<Cell> Work = Channels[static_cast<size_t>(c)];
		int Shown = Columns[static_cast<size_t>(c)];
		const std::vector<ClickFix> Fixes = SmoothClicks(S.Song, Work, Shown, First,
			First + static_cast<int>(Changes[i].Cells.size()), Played, LoopRow, Fix, Lost);
		if (!Fix) {
			if (!Fixes.empty())
				Notes.push_back(Format("%s on %s click%s as written (the 2A03's pulses restart their wave when a vibrato takes "
					"the period across a multiple of 256): once it's in the song, polish with touches [\"clicks\"] nudges %s.",
					Plural(static_cast<int>(Fixes.size()), "note", "notes").c_str(), S.Channel(c).FullName().c_str(),
					Fixes.size() == 1 ? "s" : "", Fixes.size() == 1 ? "it" : "them"));
			continue;
		}
		const std::string Text = SmoothedText(S, c, Fixes);
		if (!Text.empty())
			Notes.push_back(Text);
		const std::vector<Cell> &Was = Channels[static_cast<size_t>(c)];
		for (size_t r = 0; r < Work.size(); ++r) {
			if (r >= Was.size() || Work[r] != Was[r]) {
				Low = std::min(Low, static_cast<int>(r));
				High = std::max(High, static_cast<int>(r) + 1);
				Touched.insert(c);
			}
		}
		Channels[static_cast<size_t>(c)] = Work;
	}
	if (Lost)
		Notes.push_back("A note that clicks had no free effect column for its nudge (Pxx), so it still clicks.");
	if (Touched.empty())
		return;
	// A nudged channel's change runs over every row the nudges touched; the others start there too (the rows before
	// theirs as they are), since every part starts on the same row
	for (size_t i = 0; i < Changes.size(); ++i) {
		const int c = Changes[i].Channel;
		const std::vector<Cell> &Cells = Channels[static_cast<size_t>(c)];
		const int Stop = Touched.count(c) ? High : First + static_cast<int>(Changes[i].Cells.size());
		Changes[i].Cells.clear();
		for (int r = Low; r < Stop; ++r)
			Changes[i].Cells.push_back(r < static_cast<int>(Cells.size()) ? Cells[static_cast<size_t>(r)] : Cell());
	}
	First = Low;
}

// When the song loops, its end leads back into its loop: a channel the change leaves panned at the end otherwise than
// the loop's first note plays the first time through would move that note elsewhere every time round. The note gets
// that pan written on its row then (it changes nothing the first time through), and the change grows to it, First
// moving back when it's before; Notes says so. A song that doesn't pan has nothing to keep.
void KeepLoopPans(Session &S, std::vector<Change> &Changes, int &First, std::vector<std::string> &Notes)
{
	// The song as the change leaves it
	std::vector<std::vector<Cell> > Channels;
	std::vector<int> Columns;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		Channels.push_back(S.Cells(c));
		Columns.push_back(std::max(1, std::min(EFFECT_COLUMNS, S.Channel(c).EffectColumns)));
	}
	int End = First;
	bool Pans = false;
	for (size_t i = 0; i < Changes.size(); ++i) {
		const int c = Changes[i].Channel;
		std::vector<Cell> &Cells = Channels[static_cast<size_t>(c)];
		const size_t Need = static_cast<size_t>(First) + Changes[i].Cells.size();
		if (Cells.size() < Need)
			Cells.resize(Need);
		std::copy(Changes[i].Cells.begin(), Changes[i].Cells.end(), Cells.begin() + First);
		End = std::max(End, static_cast<int>(Need));
		for (size_t r = 0; r < Cells.size() && !Pans; ++r)
			Pans = HasEffect(Cells[r], EFF_PAN, Columns[static_cast<size_t>(c)]);
	}
	if (!Pans)
		return;
	int LoopRow = -1;
	const std::vector<std::pair<int, int> > Played = PlayedFrames(S.Song, Channels, Columns, LoopRow);
	size_t Once = Played.size(), Again = Played.size();	// where the loop starts in Played, the first time and the next
	for (size_t p = 0; p < Played.size() && LoopRow >= 0; ++p) {
		if (Played[p].first != LoopRow)
			continue;
		if (Once == Played.size())
			Once = p;
		else {
			Again = p;
			break;
		}
	}
	if (Again == Played.size())
		return;
	std::set<int> Touched;
	int Low = First, High = End;
	for (size_t i = 0; i < Changes.size(); ++i) {
		const int c = Changes[i].Channel;
		std::vector<Cell> &Cells = Channels[static_cast<size_t>(c)];
		const int Shown = Columns[static_cast<size_t>(c)];
		// The loop's first note, and the pans coming into it the first time and the next
		size_t Note = Again;
		for (size_t p = Once; p < Again && Note == Again; ++p)
			if (Played[p].first < static_cast<int>(Cells.size()) && Cells[static_cast<size_t>(Played[p].first)].HasNote())
				Note = p;
		if (Note == Again || Again + (Note - Once) >= Played.size())
			continue;
		int Pan = PAN_CENTER, FirstTime = PAN_CENTER;
		for (size_t p = 0; p < Again + (Note - Once); ++p) {
			if (p == Note)
				FirstTime = Pan;
			const int Row = Played[p].first;
			if (Row < static_cast<int>(Cells.size()))
				for (int k = 0; k < Shown; ++k)
					if (Cells[static_cast<size_t>(Row)].Effect[k] == EFF_PAN)
						Pan = Cells[static_cast<size_t>(Row)].Param[k];
		}
		const int Row = Played[Note].first;
		if (Pan == FirstTime || HasEffect(Cells[static_cast<size_t>(Row)], EFF_PAN, Shown))
			continue;
		if (!AddEffect(Cells[static_cast<size_t>(Row)], EFF_PAN, FirstTime, Shown)) {
			Notes.push_back(Format("%s ends panned %s, so when the song loops its note at %s plays there too (it has no free "
				"effect column for its own pan, %s).", S.Channel(c).FullName().c_str(), PanName(Pan).c_str(), S.Time.Position(Row).c_str(),
				PanName(FirstTime).c_str()));
			continue;
		}
		Notes.push_back(Format("%s's note at %s, where the song loops, gets 8%02X: the song's end leaves the channel panned %s, "
			"and this keeps the note %s every time round, as the first time.", S.Channel(c).FullName().c_str(),
			S.Time.Position(Row).c_str(), FirstTime, PanName(Pan).c_str(), FirstTime == PAN_CENTER ? "in the middle" :
			("panned " + PanName(FirstTime)).c_str()));
		Touched.insert(c);
		Low = std::min(Low, Row);
		High = std::max(High, Row + 1);
	}
	if (Touched.empty())
		return;
	for (size_t i = 0; i < Changes.size(); ++i) {
		const int c = Changes[i].Channel;
		const std::vector<Cell> &Cells = Channels[static_cast<size_t>(c)];
		const int Stop = Touched.count(c) ? High : First + static_cast<int>(Changes[i].Cells.size());
		Changes[i].Cells.clear();
		for (int r = Low; r < Stop; ++r)
			Changes[i].Cells.push_back(r < static_cast<int>(Cells.size()) ? Cells[static_cast<size_t>(r)] : Cell());
	}
	First = Low;
}

std::string Commit(Session &S, std::vector<Change> &Changes, int First, bool AsClip, const std::string &ClipName,
	const std::string &What, const SectionList *pSections = 0, const KeyChoice *pKey = 0)
{
	if (Changes.empty())
		throw Problem("There was nothing to change.");
	std::string Result;
	std::vector<std::string> Smoothed;	// what was done about notes that would click
	if (Direct(S, AsClip)) {
		std::string Why;
		if (!S.Host().CanChange(Why))
			throw Problem(Why);
		std::vector<Change> Writing = Changes;
		int Start = First;
		SmoothChanges(S, Writing, Start, Smoothed);
		KeepLoopPans(S, Writing, Start, Smoothed);
		std::vector<ChannelCells> Parts;
		for (size_t i = 0; i < Writing.size(); ++i) {
			ChannelCells Part;
			Part.Channel = Writing[i].Channel;
			Part.Cells = Writing[i].Cells;
			Part.Exact = true;	// worked out from the song's cells, its speed, jumps and halts among them
			Parts.push_back(Part);
		}
		SongWrite Write;
		Write.First = Start;
		if (Start != First)
			Write.Cursor = First;
		if (pSections != 0) {	// the track's sections afterwards, in the same change
			Write.SetSections = true;
			Write.Sections = *pSections;
		}
		if (pKey != 0) {	// the track's chosen key afterwards (the whole song in another key), in the same change
			Write.SetKey = true;
			Write.KeyChosen = true;
			Write.Key = *pKey;
		}
		// Effects past the columns a channel shows: FamiTracker shows more there
		std::string Wider;
		for (size_t i = 0; i < Parts.size(); ++i) {
			int Needed = 0;
			for (size_t r = 0; r < Parts[i].Cells.size(); ++r)
				for (int k = EFFECT_COLUMNS - 1; k >= Needed; --k)
					if (Parts[i].Cells[r].Effect[k] != EFF_NONE) {
						Needed = k + 1;
						break;
					}
			if (Needed > S.Shown(Parts[i].Channel))
				Wider += Format("%s%s (%d)", Wider.empty() ? "" : ", ", S.Channel(Parts[i].Channel).FullName().c_str(), Needed);
		}
		std::string Error;
		if (!S.Host().WriteSong(Parts, Write, Error))
			throw Problem(Error.empty() ? "The song couldn't be changed." : Error);
		Result = "Changed the song: " + What + ". One Ctrl+Z in FamiTracker undoes it.";
		if (!Wider.empty())
			Result += " More effect columns show for the effects on " + Wider + ".";
		for (size_t i = 0; i < Smoothed.size(); ++i)
			Result += "\nNote: " + Smoothed[i];
	}
	else {
		// One clip over the channels from the first changed one to the last;
		// channels in between come along as they are
		int Low = Changes[0].Channel, High = Changes[0].Channel;
		size_t Rows = 0;
		for (size_t i = 0; i < Changes.size(); ++i) {
			Low = std::min(Low, Changes[i].Channel);
			High = std::max(High, Changes[i].Channel);
			Rows = std::max(Rows, Changes[i].Cells.size());
		}
		std::vector<std::vector<Cell> > Columns;
		std::vector<int> Sources;
		for (int c = Low; c <= High; ++c) {
			std::vector<Cell> Column;
			for (size_t i = 0; i < Changes.size(); ++i)
				if (Changes[i].Channel == c)
					Column = Changes[i].Cells;
			const std::vector<Cell> &Song = S.Cells(c);
			while (Column.size() < Rows) {
				const size_t Row = First + Column.size();
				Column.push_back(Row < Song.size() ? Song[Row] : Cell());
			}
			Columns.push_back(Column);
			Sources.push_back(S.Channel(c).ChanId);
		}
		std::string Name = ClipName.empty() ? "Claude: " + What : ClipName;
		if (Name.size() > 80)
			Name = Name.substr(0, 77) + "...";
		std::string Error;
		if (!S.Host().AddClip(Name, Sources, Columns, Error))
			throw Problem(Error.empty() ? "The clip couldn't be saved." : Error);
		Result = Format("Saved as the clip \"%s\" (%s). It shows in the clips panel beside the song: the play button on its "
			"card plays it, and dragging the card to %s at %s puts it there; Ctrl+Z takes it out again.", Name.c_str(), What.c_str(),
			S.Channel(Low).FullName().c_str(), PositionText(S, First).c_str());
		if (!S.Song.DirectChanges)
			Result += " (Changes arrive as clips: the user hasn't allowed direct changes in File > Connect Claude Code.)";
		std::vector<Change> Placed = Changes;
		int Start = First;
		SmoothChanges(S, Placed, Start, Smoothed, false);
		for (size_t i = 0; i < Smoothed.size(); ++i)
			Result += "\nNote: " + Smoothed[i];
	}
	return Result;
}

std::string WithRemarks(const Session &S, const std::string &Text, const std::vector<std::string> &Warnings = std::vector<std::string>())
{
	std::string Out = Text;
	for (size_t i = 0; i < S.Remarks.size(); ++i)
		Out += "\n" + S.Remarks[i];
	for (size_t i = 0; i < Warnings.size(); ++i)
		Out += "\nNote: " + Warnings[i];
	return Out;
}

std::string RangeText(int From, int To)
{
	return From == To ? Format("bar %d", From) : Format("bars %d-%d", From, To);
}

// The song

std::vector<BarSpan> SongBarSpans(const Session &S, int First, int End);
std::vector<ChordAt> SongChords(Session &S, int First, int End, const Key &K, int Melody = -2);

// The channels whose fader, starting pan, Soft or Space in FamiTracker's mixer is off its default: "Pulse 1
// -3.0 dB, Triangle starting 30% left, VRC6 Pulse 1 Soft 30 Space 25"
std::string MixerText(const ChannelInfo &Channel)
{
	std::string Text = Channel.FullName();
	if (Channel.MixLevel != 0)
		Text += Format(" %+.1f dB", Channel.MixLevel / 10.0);
	if (Channel.MixPan != PAN_CENTER)
		Text += " starting " + PanName(Channel.MixPan);
	if (Channel.MixSoft > 0)
		Text += Format(" Soft %d", Channel.MixSoft);
	if (Channel.MixSpace > 0)
		Text += Format(" Space %d", Channel.MixSpace);
	return Text;
}

bool MixerDefault(const ChannelInfo &Channel)
{
	return Channel.MixLevel == 0 && Channel.MixPan == PAN_CENTER && Channel.MixSoft == 0 && Channel.MixSpace == 0;
}

// The echo's time, from 48ths of a beat: "1/2 beat", "1 1/2 beats"
std::string EchoText(int Echo)
{
	if (Echo <= 0)
		return "no echo";
	const int Whole = Echo / ECHO_STEPS, Rest = Echo % ECHO_STEPS;
	int x = Rest, y = ECHO_STEPS;
	while (y != 0) {
		const int t = x % y;
		x = y;
		y = t;
	}
	const int a = x > 0 ? Rest / x : 0, b = x > 0 ? ECHO_STEPS / x : 1;
	if (Rest == 0)
		return Format("%d %s", Whole, Whole == 1 ? "beat" : "beats");
	if (Whole == 0)
		return Format("%d/%d beat", a, b);
	return Format("%d %d/%d beats", Whole, a, b);
}

// The space channels' Space sends to: "a hall, an echo of 1/2 beat repeating 3 times"
std::string SpaceText(const SongInfo &Song)
{
	const int Room = std::max(0, std::min(SPACE_ROOMS - 1, Song.SpaceRoom));
	std::string Text = Room == SPACE_ROOM_NONE ? "no room" : std::string("a ") + SPACE_ROOM_NAMES[Room];
	if (Song.SpaceEcho > 0)
		Text += Format(", an echo of %s repeating %s", EchoText(Song.SpaceEcho).c_str(), Song.SpaceRepeats == 1 ? "once" :
			Format("%d times", Song.SpaceRepeats).c_str());
	else
		Text += ", no echo";
	return Text;
}

// A channel sends to the space and the space sounds: its sound rings on after the notes
bool SpaceRings(const Session &S)
{
	if (S.Song.SpaceRoom == SPACE_ROOM_NONE && S.Song.SpaceEcho <= 0)
		return false;
	for (int c = 0; c < S.ChannelCount(); ++c)
		if (S.Channel(c).MixSpace > 0)
			return true;
	return false;
}

std::string MixerList(const Session &S)
{
	std::string Text;
	bool Space = false;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (!MixerDefault(S.Channel(c)))
			Text += (Text.empty() ? "" : ", ") + MixerText(S.Channel(c));
		Space = Space || S.Channel(c).MixSpace > 0;
	}
	if (Space)
		Text += "; the space they send to: " + SpaceText(S.Song);
	return Text;
}

// The mixer as it is, for SongHost::SetMixer
MixerSettings CurrentMixer(const Session &S)
{
	MixerSettings M;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		M.Levels.push_back(S.Channel(c).MixLevel);
		M.Pans.push_back(S.Channel(c).MixPan);
		M.Softs.push_back(S.Channel(c).MixSoft);
		M.Spaces.push_back(S.Channel(c).MixSpace);
	}
	M.Room = S.Song.SpaceRoom;
	M.Echo = S.Song.SpaceEcho;
	M.Repeats = S.Song.SpaceRepeats;
	return M;
}

std::string SongOverview(Session &S, const Json &Args)
{
	const SongInfo &Song = S.Song;
	const Timing &T = S.Time;
	std::string Text;
	Text += Format("\"%s\"", Song.Title.empty() ? "(untitled)" : Song.Title.c_str());
	if (!Song.Author.empty())
		Text += " by " + Song.Author;
	Text += Song.FileName.empty() ? ", not saved yet" : ", file " + Song.FileName;
	if (Song.Modified)
		Text += " (unsaved changes)";
	if (Song.Tracks > 1)
		Text += Format("; track %d of %d \"%s\"", Song.Track + 1, Song.Tracks, Song.TrackName.c_str());
	Text += "\n";
	if (Song.TrackNames.size() > 1) {
		Text += "Tracks:";
		for (size_t t = 0; t < Song.TrackNames.size(); ++t)
			Text += Format(" %d \"%s\"%s%s", static_cast<int>(t) + 1, Song.TrackNames[t].c_str(),
				static_cast<int>(t) == Song.Track ? " (selected)" : "", t + 1 < Song.TrackNames.size() ? "," : "");
		Text += "\n";
	}
	Text += Format("Tempo: %s BPM (speed %d, tempo %d, %s %d Hz); %d rows a beat, %d beats a bar (%d rows)\n",
		FormatNumber(std::floor(BeatsPerMinute(Song.Speed, Song.Tempo, Song.FrameRate, T.RowsPerBeat) * 10 + 0.5) / 10).c_str(),
		Song.Speed, Song.Tempo, Song.FrameRate == 50 ? "PAL" : (Song.FrameRate == 60 ? "NTSC" : "engine"), Song.FrameRate,
		T.RowsPerBeat, T.RowsPerBar / T.RowsPerBeat, T.RowsPerBar);
	Text += Format("Length: %s (%s of %d rows)\n", Plural(T.BarCount(), "bar", "bars").c_str(),
		Plural(T.Frames, "frame", "frames").c_str(), T.PatternLength);
	if (Song.Sections.empty())
		Text += "Sections: none named yet (name_section names the song's parts, like Intro, A, B, Bridge, Outro)\n";
	else
		Text += "Sections: " + SectionsText(S, Song.Sections) + "\n";

	Text += Format("Channels%s:\n", Song.Expansion.empty() ? "" : (" (expansion: " + ExpansionText(Song) + ")").c_str());
	const bool Stereo = SongPans(S);
	for (int c = 0; c < S.ChannelCount(); ++c) {
		const ChannelInfo &Channel = S.Channel(c);
		const std::vector<NoteInfo> &Notes = S.Notes(c);
		Text += Format("  %d %s%s: ", c + 1, Channel.FullName().c_str(), Channel.Muted ? " (muted, the user doesn't hear it)" : "");
		if (Notes.empty()) {
			Text += "empty\n";
			continue;
		}
		int Low = 999, High = -1;
		std::set<int> Instruments;
		for (size_t i = 0; i < Notes.size(); ++i) {
			Low = std::min(Low, Notes[i].Pitch);
			High = std::max(High, Notes[i].Pitch);
			if (Notes[i].Instrument != NO_INSTRUMENT)
				Instruments.insert(Notes[i].Instrument);
		}
		Text += Format("%s in %s", Plural(static_cast<int>(Notes.size()), Channel.Kind == KIND_NOISE ? "hit" : "note",
			Channel.Kind == KIND_NOISE ? "hits" : "notes").c_str(),
			RangeText(T.BarOf(Notes.front().Row), T.BarOf(Notes.back().Row)).c_str());
		if (Channel.Kind != KIND_DPCM)
			Text += Format(", %s to %s", PitchText(Channel, Low).c_str(), PitchText(Channel, High).c_str());
		if (Channel.Chip == "FDS")	// FamiTracker 0.4.6 plays the FDS two octaves under the note written
			Text += Format(" (sounding %s to %s)", PitchName(std::max(0, Low - Written(Channel, 0))).c_str(),
				PitchName(std::max(0, High - Written(Channel, 0))).c_str());
		if (!Instruments.empty()) {
			Text += ", instruments";
			for (std::set<int>::const_iterator it = Instruments.begin(); it != Instruments.end(); ++it)
				Text += " " + InstrumentLabel(Song, *it);
		}
		if (Stereo)
			Text += ", " + PanText(PannedNotes(S, c));
		Text += "\n";
	}
	Text += Stereo ? "Stereo: the parts pan (8xx, this FamiTracker's own: its playback and the game's OGG files have it; NSF "
		"files and FamiTracker 0.4.6 play mono).\n" : "Stereo: every part in the middle (set_pan, or write_notes' pan, moves "
		"parts left or right for the game's stereo OGG files).\n";
	const std::string Mixer = MixerList(S);
	if (!Mixer.empty())
		Text += "Mixer (FamiTracker's View > Mixer, saved with the song, the same in every track; its playback, WAV files and "
			"export_for_game play it, NSF files don't): " + Mixer + ". The tools count the faders in how loud parts sound (a "
			"channel's level before its Soft and Space); set_mixer changes them, or writes the faders and pans into the notes "
			"for NSF files.\n";

	// Key and chords
	Key K, Found;
	const bool HasFound = FindKey(S, 0, T.TotalRows(), Found);
	const bool HasKey = Song.KeyChosen || HasFound;
	if (HasKey) {
		K = Song.KeyChosen ? Song.ChosenKey.K : Found;
		if (Song.KeyChosen) {
			Text += "Key: " + KeyChoiceName(Song.ChosenKey) + " (chosen for this track: the tools use it when not given a key";
			if (Song.ChosenKey.Pentatonic)
				Text += ", and FamiTracker's piano roll keeps to its five notes";
			if (HasFound && (Found.Tonic != K.Tonic || Found.Mode != K.Mode))
				Text += "; the notes alone fit " + KeyName(Found);
			Text += ")";
		}
		else
			Text += "Key: " + KeyName(K) + " (found from the notes; set_key chooses one for the track)";
		int Melody = -1;
		if (Arg(Args, "melody_channel") != 0)
			Melody = ChannelArg(S, Args, "melody_channel");
		else
			Melody = GuessMelodyChannel(S, 0, T.TotalRows());
		if (Melody >= 0) {
			const std::vector<transcribe::MelodyNote> Line = MelodyOf(S.Notes(Melody), 0, T.TotalRows());
			const std::vector<transcribe::Bar> Bars = transcribe::MelodyBars(Line, T.PatternLength, T.RowsPerBar);
			transcribe::HarmonyOptions Options;
			Options.rowsPerBeat = T.RowsPerBeat;
			const transcribe::Key HK = HarmonyKey(K);
			const std::vector<transcribe::ChordSpan> Chords = transcribe::ChooseChords(Line, Bars, HK, Options);
			if (!Bars.empty() && !Chords.empty())
				Text += Format("; chords that fit the melody on %s, from bar %d: %s", S.Channel(Melody).FullName().c_str(),
					T.BarOf(Bars.front().row), ChordsText(Chords, Bars, HK).c_str());
		}
		Text += "\n";
	}
	else
		Text += "Key: none yet (no notes; set_key chooses one for the track)\n";
	{
		if (HasKey) {
			const Key Played = K;
			const int Melody = GuessMelodyChannel(S, 0, T.TotalRows());
			bool Backing = false;
			for (int c = 0; c < S.ChannelCount() && !Backing; ++c)
				Backing = c != Melody && IsMelodic(S.Channel(c)) && !S.Notes(c).empty();
			if (Backing) {
				const std::vector<ChordAt> Heard = SongChords(S, 0, T.TotalRows(), Played);
				if (!Heard.empty())
					Text += "Chords the parts play: " + ProgressionText(Heard, SongBarSpans(S, 0, T.TotalRows()), Played) + "\n";
			}
		}
	}
	{
		std::string Notes, Error;
		if (S.Host().ReadFile(SOUNDTRACK_NOTES, Notes, Error) && !Trim(Notes).empty())
			Text += std::string("Soundtrack notes: \"") + SOUNDTRACK_NOTES + "\" next to the song holds the user's taste and the decisions "
				"about this game's music; read it with soundtrack_notes before writing.\n";
	}

	Text += "Instruments:";
	if (Song.Instruments.empty())
		Text += " none";
	for (size_t i = 0; i < Song.Instruments.size(); ++i)
		Text += Format(" %02X \"%s\" (%s)%s", Song.Instruments[i].Index, Song.Instruments[i].Name.c_str(),
			Song.Instruments[i].Chip.c_str(), i + 1 < Song.Instruments.size() ? "," : "");
	Text += "\n";
	if (!Song.Clips.empty()) {
		Text += "Clips:";
		for (size_t i = 0; i < Song.Clips.size(); ++i)
			Text += Format(" %d \"%s\" (%s, %s%s)%s", Song.Clips[i].Index + 1, Song.Clips[i].Name.c_str(),
				Plural(Song.Clips[i].Columns, "channel", "channels").c_str(), T.Length(Song.Clips[i].Rows).c_str(),
				Song.Clips[i].Links > 0 ? Format(", %s in the song", Plural(Song.Clips[i].Links, "linked copy", "linked copies").c_str()).c_str() : "",
				i + 1 < Song.Clips.size() ? "," : "");
		Text += "\n";
	}
	Text += Song.DirectChanges ?
		"Changes: direct. Your edits change the song, each one undoable with Ctrl+Z.\n" :
		"Changes: as clips. Your edits are saved as clips for the user to listen to and place from the clips panel "
		"beside the song; they can allow direct changes in File > Connect Claude Code.\n";
	if (Song.Playing && Song.PlayRow >= 0)
		Text += "Playing, now at " + T.Position(Song.PlayRow) + ".\n";
	Text += "Instrument presets: " + PresetList() + ".";
	if (HasChip(Song, "N163"))
		Text += " N163 sounds (for the Namco channels): " + WaveSoundList() + ".";
	if (HasChip(Song, "5B"))
		Text += " 5B sounds (the presets play there too; its notes sound an octave under the note written): " + Sound5BList() + ".";
	if (Song.Expansion.find("FDS") != std::string::npos)
		Text += " FDS sounds (for the FDS channel, which sounds two octaves under the note written: its A-5 is a pulse's A-3): " +
			FdsSoundList() + ".";
	return Text;
}

// "Q31", "431 at beat 3.5"; the pan on the note's first row is told apart, a later one as "pan right (8FF)"
std::string EffectsText(const Session &S, const NoteInfo &Note)
{
	std::string Text;
	for (size_t e = 0; e < Note.Effects.size(); ++e) {
		const bool Pan = Note.Effects[e].second.first == EFF_PAN;
		if (Pan && Note.Effects[e].first == 0)
			continue;
		if (!Text.empty())
			Text += ", ";
		if (Pan)
			Text += "pan " + PanName(Note.Effects[e].second.second) + " (";
		Text += EffectText(Note.Effects[e].second.first, Note.Effects[e].second.second);
		if (Pan)
			Text += ")";
		if (Note.Effects[e].first > 0)
			Text += " at beat " + FormatNumber(S.Time.BeatOf(Note.Row + Note.Effects[e].first));
	}
	return Text;
}

std::string BarList(const std::vector<int> &Bars);	// "3, 5-8, 12"

// Notes in steps (StepNotes.h): write_notes takes a melody as text, a token a step of a grid, and read_notes with
// format steps gives a part back that way

// A grid's step. An eighth is half a beat, or a third of one where a beat's rows divide by three, as set_meter makes
// 6/8, 9/8 and 12/8 (a beat of three eighths); a sixteenth is half an eighth, a quarter two
struct StepGrid {
	int Sixteenths;		// 1, 2 or 4
	int Rows;			// a step's rows; 0 where that isn't a whole number
};

StepGrid GridOf(const Timing &T, int Sixteenths)
{
	StepGrid G;
	G.Sixteenths = Sixteenths;
	const int Beat = std::max(1, T.RowsPerBeat);
	const int PerBeat = Beat % 3 == 0 ? 6 : 4;	// sixteenths to a beat
	G.Rows = Beat * Sixteenths % PerBeat == 0 ? Beat * Sixteenths / PerBeat : 0;
	return G;
}

const char *StepName(int Sixteenths, bool Many = false)
{
	return Sixteenths == 1 ? (Many ? "sixteenths" : "sixteenth") : Sixteenths == 4 ? (Many ? "quarters" : "quarter") :
		(Many ? "eighths" : "eighth");
}

// step: eighth (the default), sixteenth or quarter
int StepArg(const Json &Args)
{
	const std::string Text = Squeezed(StringArg(Args, "step"));
	if (Text.empty() || Text == "eighth" || Text == "eighths" || Text == "8th" || Text == "8ths" || Text == "18")
		return 2;
	if (Text == "sixteenth" || Text == "sixteenths" || Text == "16th" || Text == "16ths" || Text == "116")
		return 1;
	if (Text == "quarter" || Text == "quarters" || Text == "4th" || Text == "4ths" || Text == "14")
		return 4;
	throw Problem("step is eighth (the default), sixteenth or quarter.");
}

// "eighths of 2 rows, 2 to a beat and 8 to a bar of 4 beats"
std::string GridText(const Session &S, const StepGrid &G, int Bar)
{
	std::string Text = Format("%s of %s, ", StepName(G.Sixteenths, true), Plural(G.Rows, "row", "rows").c_str());
	if (S.Time.RowsPerBeat % G.Rows == 0)
		Text += Format("%d to a beat and ", S.Time.RowsPerBeat / G.Rows);
	return Text + Format("%d to a bar of %s", S.Time.BarLength(Bar) / G.Rows, Plural(S.Time.BeatsPerBar(Bar), "beat", "beats").c_str());
}

// The steps that make a grid of whole rows here: "eighth or sixteenth"
std::string GridsThatFit(const Timing &T)
{
	std::string Out;
	for (int k = 4; k >= 1; k /= 2)
		if (GridOf(T, k).Rows > 0)
			Out += std::string(Out.empty() ? "" : " or ") + StepName(k);
	return Out;
}

// A pitch as the steps write it: "D4", "C#4"; the noise's "D-#"
std::string StepPitch(const ChannelInfo &Info, int Pitch)
{
	std::string Text = PitchText(Info, Pitch);
	if (Info.Kind != KIND_NOISE && Text.size() == 3 && Text[1] == '-')
		Text.erase(1, 1);
	return Text;
}

const char *const STEP_HELP = " In steps, every token is a step: a pitch (D4, C#4, Bb3) starts a note, - holds it a step more "
	"(across | too), . is a step of rest, and | or a new line ends a bar: \"D4 G4 A4 B4 - A4 G4 - | B4 - - - . . D5 -\".";

// read_notes with format steps: the part as a line of steps, a bar to a line, with what the line doesn't show (the
// instruments, effects, a note held into it or ringing on past it). Empty, with Why, when its notes don't sit on any
// grid the song's rows make, so they're read as notes.
std::string ReadNotesInSteps(Session &S, const Json &Args, std::string &Why)
{
	const int Channel = ChannelArg(S, Args, "channel");
	int From, To;
	BarRange(S, Args, From, To);
	const int Asked = To;
	To = std::min(To, From + MAX_READ_BARS - 1);
	const ChannelInfo &Info = S.Channel(Channel);
	const std::vector<NoteInfo> &Notes = S.Notes(Channel);
	const int First = S.Time.BarStart(From), End = S.Time.BarEnd(To);
	const int Wanted = StepArg(Args);

	// The grid asked for, else a finer one the notes sit on
	StepGrid Grid = GridOf(S.Time, Wanted);
	Grid.Rows = 0;
	int OffAt = -1;		// the first row off the grid asked for
	for (int k = Wanted; k >= 1 && Grid.Rows == 0; k /= 2) {
		const StepGrid G = GridOf(S.Time, k);
		if (G.Rows == 0)
			continue;
		int Off = -1;
		for (int Bar = From; Bar <= To && Off < 0; ++Bar)
			if (S.Time.BarLength(Bar) % G.Rows != 0)
				Off = S.Time.BarEnd(Bar);
		for (size_t i = 0; i < Notes.size() && Off < 0; ++i) {
			const NoteInfo &N = Notes[i];
			const int Z = N.Row + N.Rows;
			if (Z <= First || N.Row >= End)
				continue;
			if (N.Row >= First && (N.Row - First) % G.Rows != 0)
				Off = N.Row;
			else if (Z < End && (Z - First) % G.Rows != 0)
				Off = Z;
		}
		if (Off < 0)
			Grid = G;
		else if (OffAt < 0)
			OffAt = Off;
	}
	if (Grid.Rows == 0) {
		Why = Format("(Not in steps: %s isn't on a grid of %s%s, so these are the notes.)\n", OffAt >= 0 ?
			("what plays at " + S.Time.Position(OffAt)).c_str() : "the part", StepName(Wanted, true),
			Wanted > 1 ? " or finer" : "");
		return std::string();
	}

	StepLine Line;
	Line.FirstBar = From;
	for (int Bar = From; Bar <= To; ++Bar) {
		StepLineBar B;
		B.First = (S.Time.BarStart(Bar) - First) / Grid.Rows;
		B.Steps = S.Time.BarLength(Bar) / Grid.Rows;
		B.Number = Bar;
		Line.Bars.push_back(B);
	}
	const NoteInfo *pHeld = 0, *pOn = 0;
	std::vector<const NoteInfo *> Shown;
	for (size_t i = 0; i < Notes.size(); ++i) {
		const NoteInfo &N = Notes[i];
		const int Z = std::min(End, N.Row + N.Rows);
		if (Z <= First || N.Row >= End)
			continue;
		if (N.Row < First) {
			Line.Held = (Z - First) / Grid.Rows;
			pHeld = &N;
		}
		else {
			StepLineNote L;
			L.Step = (N.Row - First) / Grid.Rows;
			L.Steps = std::max(1, (Z - N.Row) / Grid.Rows);
			L.Pitch = StepPitch(Info, N.Pitch);
			L.Volume = N.VolumeSet ? N.Volume : -1;
			Line.Notes.push_back(L);
			Shown.push_back(&N);
		}
		if (N.Row + N.Rows > End)
			pOn = &N;
	}

	bool Volumes = false;
	for (size_t n = 0; n < Line.Notes.size(); ++n)
		Volumes = Volumes || Line.Notes[n].Volume >= 0;
	std::string Text = Format("%s, %s in %s", Info.FullName().c_str(), RangeText(From, To).c_str(), GridText(S, Grid, From).c_str());
	if (Grid.Sixteenths != Wanted && OffAt >= 0)
		Text += Format(" (not %s: notes fall between them, the first at %s)", StepName(Wanted, true), S.Time.Position(OffAt).c_str());
	Text += std::string(". A pitch starts a note, - holds it a step more, . is a step of rest") + (Volumes ? ", and v after a "
		"pitch is its volume (the notes after it keep it)" : "") + ":";
	if (pHeld != 0)
		Text += Format("\nIt starts by holding %s from %s (the - at its start).", PitchText(Info, pHeld->Pitch).c_str(),
			S.Time.Position(pHeld->Row).c_str());
	// The instruments, where they change
	{
		std::vector<const NoteInfo *> Playing(Shown);
		if (pHeld != 0)
			Playing.insert(Playing.begin(), pHeld);
		std::string List;
		int Instrument = NO_INSTRUMENT, Count = 0;
		for (size_t i = 0; i < Playing.size(); ++i) {
			if (Playing[i]->Instrument == Instrument || Playing[i]->Instrument == NO_INSTRUMENT)
				continue;
			List += (Count == 0 ? std::string() : Format(", from %s ", S.Time.Position(Playing[i]->Row).c_str())) +
				InstrumentLabel(S.Song, Playing[i]->Instrument);
			Instrument = Playing[i]->Instrument;
			++Count;
		}
		if (Count > 0)
			Text += Format("\n%s %s.", Count > 1 ? "Instruments:" : "Instrument", List.c_str());
	}
	if (!Shown.empty() && pHeld == 0 && !Shown[0]->VolumeSet && Shown[0]->Volume != 15)
		Text += Format("\nVolume %d until a note gives another.", Shown[0]->Volume);
	if (!Shown.empty() && pHeld == 0 && !Shown[0]->PanSet && Shown[0]->Pan != PAN_CENTER)
		Text += Format("\nPan: %s (8%02X).", PanName(Shown[0]->Pan).c_str(), Shown[0]->Pan);
	Text += "\n" + FormatStepLine(Line);

	if (pOn != 0)
		Text += Format("\n%s rings on into bar %d: left as it is, it goes on ringing; a . at the line's end stops it there.",
			PitchText(Info, pOn->Pitch).c_str(), To + 1);
	{
		std::string List;
		int Count = 0;
		for (size_t i = 0; i < Shown.size(); ++i) {
			if (Shown[i]->Effects.empty())
				continue;
			if (++Count > MAX_LISTED)
				continue;
			std::string Effects;
			for (size_t e = 0; e < Shown[i]->Effects.size(); ++e)
				Effects += (e == 0 ? "" : " ") + EffectText(Shown[i]->Effects[e].second.first, Shown[i]->Effects[e].second.second);
			List += Format("%s%s %s %s", List.empty() ? "" : ", ", S.Time.Position(Shown[i]->Row).c_str(),
				StepPitch(Info, Shown[i]->Pitch).c_str(), Effects.c_str());
		}
		if (Count > MAX_LISTED)
			List += Format(" and %d more", Count - MAX_LISTED);
		if (Count > 0)
			Text += "\nEffects (not in the line; they stay on the notes left where they are): " + List + ".";
	}
	Text += Format("\nTo change it, edit the line and give it back to write_notes as notes, with from_bar %d%s. Notes left at "
		"the same step with the same pitch keep their instrument and effects.", From, Grid.Sixteenths == 2 ? "" :
		(std::string(" and step ") + StepName(Grid.Sixteenths)).c_str());
	if (To < Asked)
		Text += Format("\n(Not read: %s, from from_bar %d on.)", RangeText(To + 1, Asked).c_str(), To + 1);
	return Text;
}

// A note of the song kept by a line in steps starts with the effects that were on as it played before (a vibrato set
// on a note before it, one turned off on a release): where the new cells leave another on after its row, its row
// says so
void KeepEffectsOn(const std::vector<Cell> &Old, std::vector<Cell> &Work, int Row, int Columns, bool &Lost)
{
	const ChannelState Was = StateAt(Old, Row + 1, Columns), Now = StateAt(Work, Row + 1, Columns);
	const ChannelState Entering = StateAt(Work, Row, Columns);
	Cell &C = Work[static_cast<size_t>(Row)];
	for (int e = 0; e < EFF_COUNT; ++e) {
		if (!IsStickyEffect(e) || Was.Sticky[e] == Now.Sticky[e])
			continue;
		for (int k = 0; k < Columns; ++k)
			if (C.Effect[k] == e) {
				C.Effect[k] = EFF_NONE;
				C.Param[k] = 0;
			}
		if (Entering.Sticky[e] != Was.Sticky[e] && !AddEffect(C, e, Was.Sticky[e], Columns))
			Lost = true;
	}
}

// The same effects on two rows, whichever columns they're in
bool SameEffects(const Cell &A, const Cell &B)
{
	std::vector<std::pair<int, int> > X, Y;
	for (int k = 0; k < EFFECT_COLUMNS; ++k) {
		if (A.Effect[k] != EFF_NONE)
			X.push_back(std::make_pair(int(A.Effect[k]), int(A.Param[k])));
		if (B.Effect[k] != EFF_NONE)
			Y.push_back(std::make_pair(int(B.Effect[k]), int(B.Param[k])));
	}
	std::sort(X.begin(), X.end());
	std::sort(Y.begin(), Y.end());
	return X == Y;
}

// write_notes' warnings as it writes a part, and how its reply ends with them (defined with finish_song, after
// export_for_game)
std::vector<std::string> WritingWarnings(Session &S, int Channel, const std::vector<Cell> &Cells,
	const std::vector<std::pair<int, int> > &Spans, bool Direct, bool Core, const StepLine *pLine);
std::string WarningLines(const std::vector<std::string> &Warnings);

// write_notes with notes as text: a melody in steps, from from_bar (or the bar number the text starts with). Every bar
// holds the meter's steps. A note at the same step with the same pitch as the song's there is kept as it was (its
// instrument, its effects within its length, the release or halt that ends it where it ends as before); a - at the
// line's start holds the note sounding into it, and a kept last note that rang on past the line rings on.
std::string WriteNotesInSteps(Session &S, const Json &Args, bool Core = false)
{
	const int Channel = ChannelArg(S, Args, "channel");
	const ChannelInfo &Info = S.Channel(Channel);
	const bool Dpcm = Info.Kind == KIND_DPCM, Noise = Info.Kind == KIND_NOISE;
	const bool AsClip = BoolArg(Args, "as_clip", false);
	const bool DirectChange = Direct(S, AsClip);
	const int Sixteenths = StepArg(Args);
	const StepGrid Grid = GridOf(S.Time, Sixteenths);
	if (Grid.Rows == 0)
		throw Problem(Format("At %s a beat, %s %s isn't a whole number of rows: give step %s.", Plural(S.Time.RowsPerBeat, "row",
			"rows").c_str(), Sixteenths == 2 ? "an" : "a", StepName(Sixteenths), GridsThatFit(S.Time).c_str()));

	// The line, its bars from from_bar (or the bar number it starts with)
	int FirstBar = 0;
	if (Arg(Args, "from_bar") != 0)
		FirstBar = IntArg(Args, "from_bar", 1, 1, S.MaxBars());
	StepLine Line;
	std::string Error;
	if (!ParseStepLine(Arg(Args, "notes")->String(), FirstBar, Line, Error))
		throw Problem(Error + STEP_HELP);
	if (Line.FirstBar < 1)
		throw Problem("Say where the line starts: from_bar 5, or begin it with the bar's number (\"5: D4 G4 A4 B4 - A4 G4 -\").");
	FirstBar = Line.FirstBar;
	const int Bars = static_cast<int>(Line.Bars.size()), LastBar = FirstBar + Bars - 1;
	if (LastBar > S.MaxBars())
		throw Problem(Format("The line runs to bar %d, past the longest a song can be (%d bars).", LastBar, S.MaxBars()));
	if (Arg(Args, "to_bar") != 0) {
		const int Said = IntArg(Args, "to_bar", LastBar, 1, S.MaxBars());
		if (Said != LastBar)
			throw Problem(Format("The line covers %s, but to_bar says %d. In steps the line's bars are the ones it replaces: leave "
				"to_bar out (a bar of rests is . . . . . . . ., a . for each step).", RangeText(FirstBar, LastBar).c_str(), Said));
	}
	// Every bar holds the meter's steps; the bars that don't are named with their counts, so all of them can be fixed
	{
		std::vector<std::string> Wrong;
		const int Usual = S.Time.BarLength(FirstBar) / Grid.Rows;
		bool Same = true;
		for (int b = 0; b < Bars; ++b) {
			const int Bar = FirstBar + b, Length = S.Time.BarLength(Bar);
			if (Length % Grid.Rows != 0)
				throw Problem(Format("Bar %d is %s long (the last of its frame), which steps of %s don't fill: write it with step %s, "
					"or as a list of notes.", Bar, Plural(Length, "row", "rows").c_str(), Plural(Grid.Rows, "row", "rows").c_str(),
					Grid.Sixteenths > 1 && GridOf(S.Time, Grid.Sixteenths / 2).Rows > 0 ? StepName(Grid.Sixteenths / 2) : "sixteenth"));
			Same = Same && Length / Grid.Rows == Usual;
		}
		for (int b = 0; b < Bars; ++b) {
			const int Bar = FirstBar + b, Want = S.Time.BarLength(Bar) / Grid.Rows;
			if (Line.Bars[static_cast<size_t>(b)].Steps != Want)
				Wrong.push_back(Format("bar %d has %d", Bar, Line.Bars[static_cast<size_t>(b)].Steps) + (Same ? std::string() :
					Format(" of %d", Want)));
		}
		if (!Wrong.empty()) {
			std::string List;
			for (size_t i = 0; i < Wrong.size() && i < 8; ++i)
				List += (i == 0 ? "" : i + 1 == Wrong.size() ? " and " : ", ") + Wrong[i];
			if (Wrong.size() > 8)
				List += Format(" and %d more", static_cast<int>(Wrong.size()) - 8);
			List[0] = 'B';
			throw Problem(Format("A bar here holds %s: %s. %s: make %s (- holds a note a step more, . is a step of rest), then "
				"write the line again.", Same ? Plural(Usual, "step", "steps").c_str() : "the steps of its length",
				GridText(S, Grid, FirstBar).c_str(), List.c_str(), Same ? Format("%s %d steps", Wrong.size() == 1 ? "it" : "each",
				Usual).c_str() : "each that long"));
		}
	}
	const int First = S.Time.BarStart(FirstBar), End = S.Time.BarEnd(LastBar);
	if (End > S.MaxRows())
		throw Problem(Format("The line runs past the longest a song can be (%d bars).", S.MaxBars()));

	// The notes: the song's own where they stay, new ones from the line
	const std::vector<NoteInfo> &Old = S.Notes(Channel);
	const std::vector<Cell> &OldCells = S.Cells(Channel);
	const bool InstrumentGiven = Arg(Args, "instrument") != 0;
	const int Given = InstrumentGiven ? InstrumentArg(S, Args, "instrument", Channel, NO_INSTRUMENT) : NO_INSTRUMENT;
	auto Keep = [&](size_t i, int Rows, bool OnLine) {
		const NoteInfo &O = Old[i];
		PartNote N;
		N.Row = O.Row;
		N.Rows = Rows;
		N.Pitch = O.Pitch;
		N.Instrument = InstrumentGiven && OnLine ? Given : O.InstrumentSet ? O.Instrument : NO_INSTRUMENT;
		for (size_t e = 0; e < O.Effects.size(); ++e) {
			if (O.Effects[e].first == 0)
				N.Effects.push_back(O.Effects[e].second);
			else if (O.Effects[e].first < Rows)
				N.LaterEffects.push_back(O.Effects[e]);
		}
		return N;
	};
	std::vector<PartNote> Notes;
	std::vector<int> Kept;		// per note, the song's note it is (the same start and pitch), -1 for a new one
	int Held = -1;				// the song's note the line's - at its start holds
	if (Line.Held > 0) {
		// The note sounding into the line, or up to its start (a note, release or halt there, which the line rewrites, ended
		// it: a tie onto a line written before)
		for (size_t i = 0; i < Old.size(); ++i)
			if (Old[i].Row < First && Old[i].Row + Old[i].Rows >= First)
				Held = static_cast<int>(i);
		if (Held < 0)
			throw Problem(Format("The line starts with -, which holds the note sounding into bar %d, but none does: start it with a "
				"pitch, or with . for a rest.", FirstBar));
		PartNote N = Keep(static_cast<size_t>(Held), First + Line.Held * Grid.Rows - Old[static_cast<size_t>(Held)].Row, false);
		N.Volume = Old[static_cast<size_t>(Held)].VolumeSet ? Old[static_cast<size_t>(Held)].Volume : -1;
		Notes.push_back(N);
		Kept.push_back(Held);
	}
	int KeptEffects = 0;
	for (size_t n = 0; n < Line.Notes.size(); ++n) {
		const StepLineNote &L = Line.Notes[n];
		int InBar = 0;
		const int b = StepLineBarOf(Line, L.Step, &InBar);
		const std::string Which = Format("Bar %d, step %d", FirstBar + b, InBar + 1);
		const int Row = First + L.Step * Grid.Rows, Rows = L.Steps * Grid.Rows;
		int Pitch = 0;
		std::string Drum;
		if (Dpcm) {
			const DpcmKey *pKey = FindSampleDrum(L.Pitch);
			if (pKey != 0) {
				Pitch = pKey->Pitch;
				Drum = "sample drums";
			}
			else if (!ParsePitch(L.Pitch, Pitch))
				throw Problem(Format("%s: \"%s\" isn't a drum or a key. On the DPCM channel: kick, snare, low tom or high tom (the "
					"sampled drums of add_sample_drums), or the key a sample is on, like C-3.", Which.c_str(), L.Pitch.c_str()));
		}
		else if (Noise) {
			if (!ParseNoisePitch(L.Pitch, Pitch, Drum))
				throw Problem(Format("%s: \"%s\" isn't a noise sound. Use kick, snare, hihat, open hihat or a noise pitch 0-# to F-#.",
					Which.c_str(), L.Pitch.c_str()));
		}
		else if (!ParsePitch(L.Pitch, Pitch))
			throw Problem(Format("%s: \"%s\" isn't a note, a hold (-) or a rest (.). Write a note like D4, C#4, Bb3 or D-4 "
				"(FamiTracker octaves: C-3 is middle C, from C-0 to B-7).", Which.c_str(), L.Pitch.c_str()));
		int Same = -1;
		for (size_t i = 0; i < Old.size() && Same < 0 && Old[i].Row <= Row; ++i)
			if (Old[i].Row == Row && (Noise ? (Old[i].Pitch & 15) == (Pitch & 15) : Old[i].Pitch == Pitch))
				Same = static_cast<int>(i);
		PartNote N;
		if (Same >= 0) {
			N = Keep(static_cast<size_t>(Same), Rows, true);
			KeptEffects += Old[static_cast<size_t>(Same)].Effects.empty() ? 0 : 1;
		}
		else {
			N.Row = Row;
			N.Rows = Rows;
			N.Pitch = Pitch;
			if (InstrumentGiven)
				N.Instrument = Given;
			else if (Drum == "sample drums")
				N.Instrument = SampleDrumsInstrument(S);
			else if (!Drum.empty())
				N.Instrument = ResolveInstrument(S, Drum, Channel);
		}
		N.Volume = L.Volume;
		Notes.push_back(N);
		Kept.push_back(Same);
	}

	// A kept last note that rang on past the line rings on as it did (a change in place only: a clip ends with its bars)
	int RangeEnd = End;
	std::string RingsOn;
	if (DirectChange && !Notes.empty() && Kept.back() >= 0 && Notes.back().Row + Notes.back().Rows == End) {
		const NoteInfo &O = Old[static_cast<size_t>(Kept.back())];
		if (O.Row + O.Rows > End) {
			const int Volume = Notes.back().Volume;
			Notes.back() = Keep(static_cast<size_t>(Kept.back()), O.Rows, !(Held >= 0 && Notes.size() == 1));
			Notes.back().Volume = Volume;
			RangeEnd = O.Row + O.Rows;
			RingsOn = Format("%s rings on into bar %d as it did; a . at the line's end stops it there.", PitchText(Info, O.Pitch).c_str(),
				LastBar + 1);
		}
	}
	const int RangeFirst = Held >= 0 ? Old[static_cast<size_t>(Held)].Row : First;
	// A sample plays to its end: hits ring until the next one
	if (Dpcm)
		for (size_t i = 0; i < Notes.size(); ++i)
			Notes[i].Rows = (i + 1 < Notes.size() ? Notes[i + 1].Row : RangeEnd) - Notes[i].Row;

	// The instrument when none was named: what the channel played with
	{
		const int Playing = InstrumentAt(S, Channel, RangeFirst);
		int Current = Playing;
		bool NeedInstrument = false;
		for (size_t i = 0; i < Notes.size(); ++i) {
			if (Notes[i].Instrument != NO_INSTRUMENT)
				Current = Notes[i].Instrument;
			else if (Current == NO_INSTRUMENT)
				NeedInstrument = NeedInstrument || Kept[i] < 0;
			else if (i == 0 && (Kept[i] < 0 || !DirectChange))
				Notes[i].Instrument = Current;
		}
		if (NeedInstrument)
			throw Problem(Format("%s has no instrument to play these notes with yet: give an instrument (one of the song's, or %s: %s).",
				Info.FullName().c_str(), Info.Chip == "N163" ? "an N163 sound" : "a preset", Info.Chip == "N163" ?
				(IsSoftLayer(Info) ? "the soft layer's choir pad, string pad, soft flute and sub bass, or " + WaveSoundList() :
				WaveSoundList()).c_str() : PresetList().c_str()));
	}
	PartOptions Options = OptionsFor(S, Channel, DirectChange);
	Options.KeepDetune = true;
	Options.KeepVolume = NoteStartsIn(S, Channel, RangeFirst, RangeEnd);
	if (!Options.KeepVolume && !Notes.empty() && Notes.front().Volume < 0)
		Notes.front().Volume = 15;
	// The note after the line plays as it did once the kept notes have their effects (below), not before
	const bool Following = Options.KeepFollowing;
	Options.KeepFollowing = false;
	std::vector<std::string> Warnings;
	std::vector<Cell> Piece;
	BuildPart(OldCells, RangeFirst, RangeEnd, Notes, Options, Piece, Warnings);
	std::vector<Cell> Work(OldCells);
	if (Work.size() < RangeFirst + Piece.size())
		Work.resize(RangeFirst + Piece.size());
	std::copy(Piece.begin(), Piece.end(), Work.begin() + RangeFirst);
	const int Written = RangeFirst + static_cast<int>(Piece.size());
	const int OldRows = static_cast<int>(OldCells.size());

	// The song's notes kept: each ends as it did where it ends as before (a release or a halt), as does the note sounding
	// into the line that a rest at its start stops; each starts with the effects that were on as it played; and rows
	// with the effects they had keep them in their columns
	for (size_t i = 0; i < Notes.size(); ++i) {
		const int Z = Notes[i].Row + Notes[i].Rows;
		if (Kept[i] >= 0 && Z == Old[static_cast<size_t>(Kept[i])].Row + Old[static_cast<size_t>(Kept[i])].Rows && Z < Written &&
			Z < OldRows && Work[Z].IsEnd() && OldCells[Z].IsEnd())
			Work[Z].Note = OldCells[Z].Note;
	}
	if (Held < 0 && First < Written && First < OldRows && Work[First].IsEnd() && OldCells[First].IsEnd())
		Work[First].Note = OldCells[First].Note;
	bool Lost = false;
	for (size_t i = 0; i < Notes.size(); ++i)
		if (Kept[i] >= 0)
			KeepEffectsOn(OldCells, Work, Notes[i].Row, Options.EffectColumns, Lost);
	for (int r = RangeFirst; r < Written && r < OldRows; ++r)
		if (SameEffects(OldCells[r], Work[r]))
			for (int k = 0; k < EFFECT_COLUMNS; ++k) {
				Work[r].Effect[k] = OldCells[r].Effect[k];
				Work[r].Param[k] = OldCells[r].Param[k];
			}
	std::vector<Change> Changes(1);
	Changes[0].Channel = Channel;
	Changes[0].Cells.assign(Work.begin() + RangeFirst, Work.begin() + Written);
	if (Following && !KeepFollowing(OldCells, RangeFirst, RangeEnd, Changes[0].Cells, Options.EffectColumns))
		Lost = true;
	if (Lost)
		Warnings.push_back("Some effects didn't fit in the channel's visible effect columns and were left out.");
	const std::string What = Format("%s on %s, %s in %s", Plural(static_cast<int>(Line.Notes.size()), "note", "notes").c_str(),
		Info.FullName().c_str(), RangeText(FirstBar, LastBar).c_str(), StepName(Sixteenths, true));
	if (Held >= 0)
		Warnings.push_back(Format("The line starts by holding %s from %s.", PitchText(Info, Old[static_cast<size_t>(Held)].Pitch).c_str(),
			S.Time.Position(Old[static_cast<size_t>(Held)].Row).c_str()));
	if (!RingsOn.empty())
		Warnings.push_back(RingsOn);
	if (KeptEffects > 0)
		Warnings.push_back(Format("The song's notes left where they were keep their effects (%s with some).",
			Plural(KeptEffects, "note", "notes").c_str()));
	// A rest before most bar lines: a melody that stops at every bar
	{
		int Breaks = 0;
		for (int b = 0; b + 1 < Bars; ++b) {
			const int Last = Line.Bars[static_cast<size_t>(b)].First + Line.Bars[static_cast<size_t>(b)].Steps - 1;
			bool Rest = Last >= Line.Held;
			for (size_t n = 0; n < Line.Notes.size() && Rest; ++n)
				Rest = !(Line.Notes[n].Step <= Last && Line.Notes[n].Step + Line.Notes[n].Steps > Last);
			Breaks += Rest ? 1 : 0;
		}
		if (Bars >= 4 && Breaks >= 3 && Breaks * 4 >= (Bars - 1) * 3 && IsMelodic(Info) && Info.Kind != KIND_TRIANGLE)
			Warnings.push_back(Format("%d of the line's %d bar lines come after a rest, so the line stops at every bar. A phrase of "
				"2 or 4 bars breathes at its end; inside it, let the notes run up to the bar line or hold one across it (- after the |).",
				Breaks, Bars - 1));
	}
	// What a composer would want to hear of at once: notes out of range or out of the key, a bass that leaves its channel
	// nearly silent, a sound the channel doesn't play as it's meant
	const std::vector<std::string> Guard = WritingWarnings(S, Channel, Work, std::vector<std::pair<int, int> >(1, std::make_pair(First,
		End)), DirectChange, Core, &Line);
	return WithRemarks(S, Commit(S, Changes, RangeFirst, AsClip, StringArg(Args, "clip_name"), What), Warnings) + WarningLines(Guard);
}

std::string ReadChannel(Session &S, const Json &Args)
{
	// In steps (format steps), when the notes sit on a grid of them
	std::string NotSteps;
	const std::string Form = Lowercase(StringArg(Args, "format"));
	if (Form == "steps" || Form == "step") {
		const std::string Steps = ReadNotesInSteps(S, Args, NotSteps);
		if (!Steps.empty())
			return Steps;
	}
	else if (!Form.empty() && Form != "notes" && Form != "list")
		throw Problem("format is notes (the default) or steps.");
	const int Channel = ChannelArg(S, Args, "channel");
	int From, To;
	BarRange(S, Args, From, To);
	const int Asked = To;
	const ChannelInfo &Info = S.Channel(Channel);
	const std::vector<NoteInfo> &Notes = S.Notes(Channel);
	// Up to MAX_READ_BARS bars, and the whole bars of up to MAX_READ_NOTES notes
	To = std::min(To, From + MAX_READ_BARS - 1);
	for (int Bar = From, Count = 0; Bar <= To; ++Bar) {
		const int A = S.Time.BarStart(Bar), Z = S.Time.BarEnd(Bar);
		int InBar = 0;
		for (size_t i = 0; i < Notes.size(); ++i)
			InBar += Notes[i].Row >= A && Notes[i].Row < Z ? 1 : 0;
		if (Bar > From && Count + InBar > MAX_READ_NOTES) {
			To = Bar - 1;
			break;
		}
		Count += InBar;
	}
	const int First = S.Time.BarStart(From), End = S.Time.BarEnd(To);
	std::string Text, More;
	if (To < Asked) {
		// Said first and last, so a part rewritten from this reply isn't rewritten from part of it
		const std::string Rest = RangeText(To + 1, Asked);
		Text = Format("%s, %s only, not %s (a call reads up to %d bars or %d notes): read %s with from_bar %d before rewriting "
			"the part, or the rewrite clears them (%d beats a bar, %d rows a beat):", Info.FullName().c_str(), RangeText(From, To).c_str(),
			Rest.c_str(), MAX_READ_BARS, MAX_READ_NOTES, Rest.c_str(), To + 1, S.Time.RowsPerBar / S.Time.RowsPerBeat, S.Time.RowsPerBeat);
		More = Format("\n(Not read: %s, from from_bar %d on.)", Rest.c_str(), To + 1);
	}
	else
		Text = Format("%s, %s (%d beats a bar, %d rows a beat):", Info.FullName().c_str(), RangeText(From, To).c_str(),
			S.Time.RowsPerBar / S.Time.RowsPerBeat, S.Time.RowsPerBeat);
	int Instrument = -1, Volume = -1, Pan = -1;
	size_t Shown = 0;
	for (int Bar = From; Bar <= To; ++Bar) {
		const int BarFirst = S.Time.BarStart(Bar), BarEnd = S.Time.BarEnd(Bar);
		bool Any = false;
		for (size_t i = 0; i < Notes.size(); ++i) {
			const NoteInfo &N = Notes[i];
			const bool Held = Bar == From && N.Row < First && N.Row + N.Rows > First;
			if (!Held && (N.Row < BarFirst || N.Row >= BarEnd))
				continue;
			Any = true;
			++Shown;
			std::string Line;
			if (Held)
				Line = Format("\n(held from %s: %s, %s more)", S.Time.Position(N.Row).c_str(), PitchText(Info, N.Pitch).c_str(),
					S.Time.Length(N.Row + N.Rows - First).c_str());
			else {
				Line = Format("\nbar %d beat %s: %s, %s", Bar, FormatNumber(S.Time.BeatOf(N.Row)).c_str(),
					PitchText(Info, N.Pitch).c_str(), S.Time.Length(N.Rows).c_str());
				if (N.Instrument != Instrument && N.Instrument != NO_INSTRUMENT)
					Line += ", " + InstrumentLabel(S.Song, N.Instrument);
				if (N.VolumeSet || (Volume < 0 && N.Volume != 15))
					Line += Format(", volume %d", N.Volume);
				// Where it plays between the speakers, where that changes (or the bars start off the middle)
				if (N.PanSet || (Pan < 0 ? N.Pan != PAN_CENTER : N.Pan != Pan))
					Line += ", pan " + PanName(N.Pan) + Format(" (8%02X)", N.Pan);
				const std::string Effects = EffectsText(S, N);
				if (!Effects.empty())
					Line += ", effects " + Effects;
				if (N.EndNote == NOTE_RELEASE)
					Line += ", released";
			}
			Instrument = N.Instrument;
			Volume = N.Volume;
			Pan = N.Pan;
			Text += Line;
		}
		if (!Any)
			Text += Format("\nbar %d: rest", Bar);
	}
	if (Shown == 0)
		Text += "\n(No notes in these bars.)";
	if (End > S.Time.TotalRows())
		Text += "\n(The song ends before that.)";
	return NotSteps + Text + More;
}

// Writing a part

std::string WriteNotes(Session &S, const Json &Args, bool Core)
{
	const int Channel = ChannelArg(S, Args, "channel");
	const ChannelInfo &Info = S.Channel(Channel);
	const bool Dpcm = Info.Kind == KIND_DPCM;
	const Json *pNotes = Arg(Args, "notes");
	if (pNotes != 0 && pNotes->IsString())
		return WriteNotesInSteps(S, Args, Core);
	if (pNotes == 0 || !pNotes->IsArray())
		throw Problem("notes should be a list of notes like {\"bar\": 1, \"beat\": 1, \"pitch\": \"C-4\", \"beats\": 1}, or a melody "
			"in steps as text, like \"D4 G4 A4 B4 - A4 G4 - | B4 - - - . . D5 -\" from from_bar.");
	const bool AsClip = BoolArg(Args, "as_clip", false);
	const bool DirectChange = Direct(S, AsClip);
	const bool Noise = Info.Kind == KIND_NOISE;
	const int MaxRows = S.MaxRows();

	// The default instrument: as asked, or what the channel plays with
	int DefaultInstrument = NO_INSTRUMENT;
	if (Arg(Args, "instrument") != 0)
		DefaultInstrument = InstrumentArg(S, Args, "instrument", Channel, NO_INSTRUMENT);

	std::vector<PartNote> Notes;
	std::vector<std::string> Warnings;
	bool Rounded = false;
	int FirstBar = S.MaxBars() + 1, LastRow = 0;
	for (size_t i = 0; i < pNotes->Size(); ++i) {
		const Json &Item = pNotes->At(i);
		if (!Item.IsObject())
			throw Problem(Format("Note %d should be an object like {\"bar\": 1, \"beat\": 1, \"pitch\": \"C-4\", \"beats\": 1}.", int(i + 1)));
		const std::string Which = Format("Note %d", int(i + 1));
		const int Bar = IntArg(Item, "bar", 0, 0, S.MaxBars());
		if (Bar < 1)
			throw Problem(Which + " needs a bar (from 1).");
		const double Beat = NumberArg(Item, "beat", 1.0, 1.0, 64.0);
		int Row;
		bool Exact;
		if (!S.Time.PositionToRow(Bar, Beat, Row, Exact))
			throw Problem(Format("%s: beat %s is past the end of bar %d (%d beats).", Which.c_str(), FormatNumber(Beat).c_str(), Bar,
				S.Time.BeatsPerBar(Bar)));
		if (!Exact)
			Rounded = true;
		if (Arg(Item, "beats") == 0)
			throw Problem(Which + " needs its length in beats (\"beats\": 1).");
		const int Rows = S.Time.BeatsToRows(NumberArg(Item, "beats", 1.0, 0.001, 1024.0), Exact);
		if (!Exact)
			Rounded = true;
		if (Row + Rows > MaxRows)
			throw Problem(Format("%s runs past the longest a song can be (%d bars).", Which.c_str(), S.MaxBars()));

		PartNote Note;
		Note.Row = Row;
		Note.Rows = Rows;
		const std::string Pitch = StringArg(Item, "pitch");
		if (Pitch.empty())
			throw Problem(Which + " needs a pitch, like \"C-4\" or \"F#3\"" + (Noise ? " (on the noise channel: kick, snare, hihat or 0-# to F-#)." :
				(Dpcm ? " (on the DPCM channel: kick, snare, low tom or high tom, from add_sample_drums)." : ".")));
		std::string Drum;
		if (Dpcm) {
			const DpcmKey *pKey = FindSampleDrum(Pitch);
			if (pKey != 0) {
				Note.Pitch = pKey->Pitch;
				Drum = "sample drums";
			}
			else if (!ParsePitch(Pitch, Note.Pitch))
				throw Problem(Format("%s: \"%s\" isn't a drum or a key. On the DPCM channel: kick, snare, low tom or high tom (the "
					"sampled drums of add_sample_drums), or the key a sample is on, like C-3.", Which.c_str(), Pitch.c_str()));
		}
		else if (Noise) {
			if (!ParseNoisePitch(Pitch, Note.Pitch, Drum))
				throw Problem(Format("%s: \"%s\" isn't a noise sound. Use kick, snare, hihat, open hihat or a noise pitch 0-# to F-#.",
					Which.c_str(), Pitch.c_str()));
		}
		else if (!ParsePitch(Pitch, Note.Pitch))
			throw Problem(Format("%s: \"%s\" isn't a note. Write it like C-4, C#4, Db4 (FamiTracker octaves: C-3 is middle C, "
				"from C-0 to B-7).", Which.c_str(), Pitch.c_str()));
		if (Arg(Item, "instrument") != 0)
			Note.Instrument = InstrumentArg(S, Item, "instrument", Channel, NO_INSTRUMENT);
		else if (DefaultInstrument != NO_INSTRUMENT)
			Note.Instrument = DefaultInstrument;
		else if (Drum == "sample drums")
			Note.Instrument = SampleDrumsInstrument(S);
		else if (!Drum.empty())
			Note.Instrument = ResolveInstrument(S, Drum, Channel);
		if (Arg(Item, "volume") != 0)
			Note.Volume = IntArg(Item, "volume", 15, 0, 15);
		const Json *pEffects = Arg(Item, "effects");
		if (pEffects != 0) {
			if (!pEffects->IsArray())
				throw Problem(Which + ": effects should be a list like [\"Q31\"].");
			for (size_t e = 0; e < pEffects->Size(); ++e) {
				int Effect = EFF_NONE, Param = 0;
				std::string Why;
				if (!pEffects->At(e).IsString())
					throw Problem(Which + ": effects are written as in FamiTracker, like \"Q31\" or \"047\".");
				// Only what FamiTracker 0.4.6 has, and what this channel plays
				if (!ParseChannelEffect(pEffects->At(e).String(), Info, S.Song.Speed, Effect, Param, Why))
					throw Problem(Which + ": " + Why + " (the effects tool explains them all.)");
				Note.Effects.push_back(std::make_pair(Effect, Param));
			}
		}
		// Effects later in the note (a fade into its tail, a slide, a vibrato coming in), and where it ends
		auto ReadEffects = [&](const Json &List, const std::string &Where, std::vector<std::pair<int, int> > &Into) {
			if (!List.IsArray() || List.Size() == 0)
				throw Problem(Which + ": " + Where + " should be a list of effects like [\"A02\"].");
			for (size_t e = 0; e < List.Size(); ++e) {
				int Effect = EFF_NONE, Param = 0;
				std::string Why;
				if (!List.At(e).IsString())
					throw Problem(Which + ": effects are written as in FamiTracker, like \"A02\" or \"P80\".");
				if (!ParseChannelEffect(List.At(e).String(), Info, S.Song.Speed, Effect, Param, Why))
					throw Problem(Which + ": " + Why + " (the effects tool explains them all.)");
				Into.push_back(std::make_pair(Effect, Param));
			}
		};
		const Json *pLater = Arg(Item, "later_effects");
		if (pLater != 0) {
			if (!pLater->IsArray())
				throw Problem(Which + ": later_effects should be a list like [{\"beats\": 1, \"effects\": [\"A02\"]}].");
			for (size_t k = 0; k < pLater->Size(); ++k) {
				const Json &Later = pLater->At(k);
				if (!Later.IsObject() || Arg(Later, "beats") == 0 || Arg(Later, "effects") == 0)
					throw Problem(Which + ": each of later_effects is {\"beats\": how far into the note, \"effects\": [\"A02\"]}.");
				bool ExactLater;
				const double Beats = NumberArg(Later, "beats", 1.0, 0.001, 1024.0);
				const int After = S.Time.BeatsToRows(Beats, ExactLater);
				if (!ExactLater)
					Rounded = true;
				if (After >= Rows)
					throw Problem(Format("%s: later_effects %s beats in is past the note's end (it lasts %s); end_effects go where it "
						"ends.", Which.c_str(), FormatNumber(Beats).c_str(), S.Time.Length(Rows).c_str()));
				std::vector<std::pair<int, int> > Effects;
				ReadEffects(*Arg(Later, "effects"), "later_effects' effects", Effects);
				for (size_t e = 0; e < Effects.size(); ++e)
					Note.LaterEffects.push_back(std::make_pair(After, Effects[e]));
			}
		}
		if (Arg(Item, "end_effects") != 0)
			ReadEffects(*Arg(Item, "end_effects"), "end_effects", Note.EndEffects);
		// Where it plays between the speakers (8xx); the notes after it keep that until one says otherwise
		if (Arg(Item, "pan") != 0) {
			int Pan = PAN_CENTER;
			if (!ParsePanValue(*Arg(Item, "pan"), Pan))
				throw Problem(Which + ": pan is \"left\", \"right\", \"center\", a place between like \"half left\" or \"30% right\", "
					"or a number from -1 (left) to 1 (right).");
			Note.Effects.push_back(std::make_pair(static_cast<int>(EFF_PAN), Pan));
		}
		Notes.push_back(Note);
		FirstBar = std::min(FirstBar, Bar);
		LastRow = std::max(LastRow, Row + Rows);
	}
	if (Notes.empty() && Arg(Args, "from_bar") == 0)
		throw Problem("No notes to write. To clear bars, give from_bar and to_bar with an empty list.");

	// In time order, one note at a time
	std::stable_sort(Notes.begin(), Notes.end(), [](const PartNote &a, const PartNote &b) { return a.Row < b.Row; });
	for (size_t i = 0; i + 1 < Notes.size(); ++i) {
		if (Notes[i + 1].Row == Notes[i].Row)
			throw Problem(Format("Two notes start at %s; a channel plays one note at a time.", S.Time.Position(Notes[i].Row).c_str()));
		if (Notes[i].Row + Notes[i].Rows > Notes[i + 1].Row) {
			Notes[i].Rows = Notes[i + 1].Row - Notes[i].Row;
			Warnings.push_back(Format("The note at %s overlapped the next one and was shortened; a channel plays one note at a time.",
				S.Time.Position(Notes[i].Row).c_str()));
		}
	}

	// The bars it covers
	const int From = IntArg(Args, "from_bar", Notes.empty() ? 1 : FirstBar, 1, S.MaxBars());
	const int LastBar = Notes.empty() ? From : S.Time.BarOf(LastRow - 1);
	const int To = IntArg(Args, "to_bar", std::max(From, LastBar), 1, S.MaxBars());
	if (To < From)
		throw Problem("to_bar comes before from_bar.");
	const int First = S.Time.BarStart(From);
	int End = S.Time.BarEnd(To);
	if (!Notes.empty() && Notes.front().Row < First)
		throw Problem(Format("A note starts before from_bar %d.", From));
	if (LastRow > End)
		End = LastRow;
	// Whole bars the notes leave empty between them, where the channel has notes, stay as they are: an intro and a break
	// written in one call would otherwise clear the drums between them. from_bar and to_bar together give the range to
	// replace, every bar of it. The rest is written a piece at a time
	std::vector<int> Kept;
	if (!(Arg(Args, "from_bar") != 0 && Arg(Args, "to_bar") != 0))
		for (int Bar = FirstBar + 1; !Notes.empty() && Bar < LastBar; ++Bar) {
			const int A = S.Time.BarStart(Bar), Z = S.Time.BarEnd(Bar);
			bool Covered = false;
			for (size_t i = 0; i < Notes.size() && !Covered; ++i)
				Covered = Notes[i].Row < Z && Notes[i].Row + std::max(1, Notes[i].Rows) > A;
			if (!Covered && NoteStartsIn(S, Channel, A, Z))
				Kept.push_back(Bar);
		}
	std::vector<std::pair<int, int> > Pieces;
	{
		int Piece = First;
		for (size_t k = 0; k < Kept.size(); ++k) {
			if (S.Time.BarStart(Kept[k]) > Piece)
				Pieces.push_back(std::make_pair(Piece, S.Time.BarStart(Kept[k])));
			Piece = S.Time.BarEnd(Kept[k]);
		}
		if (End > Piece || Pieces.empty())
			Pieces.push_back(std::make_pair(Piece, std::max(Piece, End)));
	}
	// A sample plays to its end: hits ring until the next one (in their piece), rather than being cut
	if (Dpcm)
		for (size_t i = 0; i < Notes.size(); ++i) {
			int Stop = End;
			for (size_t p = 0; p < Pieces.size(); ++p)
				if (Notes[i].Row >= Pieces[p].first && Notes[i].Row < Pieces[p].second)
					Stop = Pieces[p].second;
			Notes[i].Rows = (i + 1 < Notes.size() && Notes[i + 1].Row < Stop ? Notes[i + 1].Row : Stop) - Notes[i].Row;
		}

	// The instrument when none was named: what the channel played with
	const int Playing = InstrumentAt(S, Channel, First);
	bool NeedInstrument = false;
	for (size_t i = 0; i < Notes.size(); ++i) {
		if (Notes[i].Instrument == NO_INSTRUMENT) {
			if (Playing == NO_INSTRUMENT)
				NeedInstrument = true;
			else if (i == 0)
				Notes[i].Instrument = Playing;
		}
	}
	if (NeedInstrument)
		throw Problem(Format("%s has no instrument to play these notes with yet: give an instrument (one of the song's, or %s: %s).",
			Info.FullName().c_str(), Info.Chip == "N163" ? "an N163 sound" : "a preset", Info.Chip == "N163" ?
			(IsSoftLayer(Info) ? "the soft layer's choir pad, string pad, soft flute and sub bass, or " + WaveSoundList() :
			WaveSoundList()).c_str() : PresetList().c_str()));
	PartOptions Options = OptionsFor(S, Channel, DirectChange);
	Options.KeepDetune = true;	// notes rewritten over an echo play as far out of tune as the ones they replace (its P81, then P80)
	std::vector<Cell> Work(S.Cells(Channel));
	int Written = First, PartVolume = 15;	// where the pieces' cells end; the volume the part's notes give, so far
	std::string Where;
	for (size_t p = 0; p < Pieces.size(); ++p) {
		std::vector<PartNote> Mine;
		for (size_t i = 0; i < Notes.size(); ++i)
			if (Notes[i].Row >= Pieces[p].first && Notes[i].Row < Pieces[p].second)
				Mine.push_back(Notes[i]);
		// Notes that give no volume: rewriting a part, as loud as the notes they replace (a soft part stays soft); in bars
		// that had none, at the part's volume (full to start with), unless they say otherwise
		Options.KeepVolume = NoteStartsIn(S, Channel, Pieces[p].first, Pieces[p].second);
		if (!Options.KeepVolume && !Mine.empty() && Mine.front().Volume < 0)
			Mine.front().Volume = PartVolume;
		for (size_t i = 0; i < Mine.size(); ++i)
			if (Mine[i].Volume >= 0)
				PartVolume = Mine[i].Volume;
		std::vector<Cell> Piece;
		BuildPart(Work, Pieces[p].first, Pieces[p].second, Mine, Options, Piece, Warnings);
		if (Work.size() < Pieces[p].first + Piece.size())
			Work.resize(Pieces[p].first + Piece.size());
		std::copy(Piece.begin(), Piece.end(), Work.begin() + Pieces[p].first);
		Written = std::max(Written, Pieces[p].first + static_cast<int>(Piece.size()));
		const int A = S.Time.BarOf(Pieces[p].first), Z = S.Time.BarOf(std::max(Pieces[p].first, Pieces[p].second - 1));
		Where += p == 0 ? RangeText(A, Z) : (p + 1 == Pieces.size() ? " and " : ", ") + (Z > A ? Format("%d-%d", A, Z) : Format("%d", A));
	}
	const std::vector<Cell> Out(Work.begin() + First, Work.begin() + std::max(First, Written));
	if (!Kept.empty())
		Warnings.push_back((Kept.size() == 1 ? Format("Bar %d keeps its notes", Kept[0]) : "Bars " + BarList(Kept) + " keep their notes") +
			": the part has none there, and write_notes replaces only the bars its notes cover (from_bar and to_bar together "
			"clear a range, every bar of it).");
	if (Rounded)
		Warnings.push_back(Format("Some beats fell between rows and were rounded to the nearest row (%d rows a beat).", S.Time.RowsPerBeat));
	std::vector<Change> Changes(1);
	Changes[0].Channel = Channel;
	Changes[0].Cells = Out;
	std::string What = Format("%s on %s, %s", Plural(static_cast<int>(Notes.size()), "note", "notes").c_str(),
		Info.FullName().c_str(), Pieces.size() == 1 ? RangeText(From, S.Time.BarOf(End - 1)).c_str() : Where.c_str());
	// What got panned: where the part's notes play now, as written
	{
		std::vector<Cell> Song(S.Cells(Channel));
		for (size_t i = 0; i < Out.size(); ++i) {
			if (First + i >= Song.size())
				Song.resize(First + i + 1);
			Song[First + i] = Out[i];
		}
		const std::vector<NoteInfo> Written = NotesIn(ReadNotes(Song, Info.EffectColumns), First, End);
		std::string Panned;
		int Count = 0;
		for (size_t i = 0; i < Notes.size(); ++i)
			for (size_t e = 0; e < Notes[i].Effects.size(); ++e)
				if (Notes[i].Effects[e].first == EFF_PAN && Count++ < 6)
					Panned += (Panned.empty() ? "" : ", ") + S.Time.Position(Notes[i].Row) + " " + PanName(Notes[i].Effects[e].second);
		if (Count > 0)
			What += Format(", panned: %s%s (the notes after each keep its place)", Panned.c_str(), Count > 6 ? ", ..." : "");
		else if (PanText(Written) != "in the middle")
			What += ", " + PanText(Written) + " where the channel played before";
	}
	// What a composer would want to hear of at once (in the pieces written; the bars kept between them aside)
	std::vector<Cell> After(S.Cells(Channel));
	if (After.size() < First + Out.size())
		After.resize(First + Out.size());
	std::copy(Out.begin(), Out.end(), After.begin() + First);
	const std::vector<std::string> Guard = WritingWarnings(S, Channel, After, Pieces, DirectChange, Core, 0);
	return WithRemarks(S, Commit(S, Changes, First, AsClip, StringArg(Args, "clip_name"), What), Warnings) + WarningLines(Guard);
}

std::string PlaceClipTool(Session &S, const Json &Args)
{
	if (!S.Song.DirectChanges)
		throw Problem("Placing clips changes the song, and the user hasn't allowed direct changes. Ask them to drag it from "
			"the clips panel into the song, or to allow direct changes in File > Connect Claude Code.");
	const Json *pClip = Arg(Args, "clip");
	if (pClip == 0)
		throw Problem("Say which clip (its name or number).");
	int Index = -1;
	if (pClip->IsNumber())
		Index = static_cast<int>(pClip->Number()) - 1;
	else {
		const std::string Wanted = Lowercase(StringArg(Args, "clip"));
		for (size_t i = 0; i < S.Song.Clips.size() && Index < 0; ++i)
			if (Lowercase(S.Song.Clips[i].Name) == Wanted)
				Index = S.Song.Clips[i].Index;
		if (Index < 0 && !Wanted.empty() && Wanted.find_first_not_of("0123456789") == std::string::npos)
			Index = std::atoi(Wanted.c_str()) - 1;
	}
	const ClipInfo *pInfo = 0;
	for (size_t i = 0; i < S.Song.Clips.size(); ++i)
		if (S.Song.Clips[i].Index == Index)
			pInfo = &S.Song.Clips[i];
	if (pInfo == 0)
		throw Problem("No such clip. get_song lists the song's clips.");
	const int Channel = ChannelArg(S, Args, "channel");
	const int Bar = IntArg(Args, "bar", 0, 1, S.MaxBars());
	const double Beat = NumberArg(Args, "beat", 1.0, 1.0, 64.0);
	int Row;
	bool Exact;
	if (!S.Time.PositionToRow(Bar, Beat, Row, Exact))
		throw Problem(Format("Beat %s is past the end of bar %d.", FormatNumber(Beat).c_str(), Bar));
	const bool Linked = BoolArg(Args, "linked", false);

	std::vector<std::vector<Cell> > Columns;
	if (!S.Host().ReadClip(Index, Columns) || Columns.empty())
		throw Problem("The clip couldn't be read.");
	std::vector<ChannelCells> Parts;
	std::vector<std::string> Warnings;
	for (size_t c = 0; c < Columns.size(); ++c) {
		if (Channel + static_cast<int>(c) >= S.ChannelCount()) {
			Warnings.push_back("Its last channels didn't fit to the right of that channel.");
			break;
		}
		ChannelCells Part;
		Part.Channel = Channel + static_cast<int>(c);
		Part.Cells = Columns[c];
		if (Row + static_cast<int>(Part.Cells.size()) > S.MaxRows())
			Part.Cells.resize(static_cast<size_t>(std::max(0, S.MaxRows() - Row)));
		Parts.push_back(Part);
	}
	if (Parts.empty() || Parts[0].Cells.empty())
		throw Problem("The clip doesn't fit there.");
	std::string Why, Error;
	if (!S.Host().CanChange(Why))
		throw Problem(Why);
	SongWrite Write;
	Write.First = Row;
	Write.LinkClipId = Linked ? pInfo->Id : -1;
	if (!S.Host().WriteSong(Parts, Write, Error))
		throw Problem(Error.empty() ? "The clip couldn't be placed." : Error);
	return WithRemarks(S, Format("Placed the clip \"%s\" %s on %s at %s. One Ctrl+Z undoes it.", pInfo->Name.c_str(),
		Linked ? "linked" : "as a copy", S.Channel(Channel).FullName().c_str(), PositionText(S, Row).c_str()), Warnings);
}

std::string AddInstrumentTool(Session &S, const Json &Args)
{
	const std::string Name = StringArg(Args, "preset");
	std::string Chip = "2A03";
	bool Sawtooth = false;
	int Channel = -1;
	if (Arg(Args, "channel") != 0) {
		Channel = ChannelArg(S, Args, "channel");
		Chip = InstrumentChip(S.Channel(Channel));
		Sawtooth = S.Channel(Channel).Kind == KIND_SAWTOOTH;
	}
	else if (Arg(Args, "chip") != 0) {
		Chip = ChipWord(StringArg(Args, "chip"));
		if (Chip == "MMC5")
			Chip = "2A03";
	}

	// The VRC7 plays its own patches
	if (Chip == "VRC7") {
		if (S.Song.Expansion.find("VRC7") == std::string::npos)
			throw Problem("This song has no VRC7 channels; set_expansion switches it to the VRC7.");
		const Vrc7Patch *pPatch = FindVrc7Patch(Name);
		if (pPatch == 0)
			throw Problem(Format("No VRC7 sound called \"%s\". VRC7 sounds: %s (or a preset's name, like \"soft lead\").", Name.c_str(),
				Vrc7PatchList().c_str()));
		const size_t Before = S.Song.Instruments.size();
		std::string Error;
		const int Index = S.Host().AddVrc7Instrument(pPatch->Number, pPatch->InstrumentName(), Error);
		if (Index < 0)
			throw Problem(Error.empty() ? "The instrument couldn't be added." : Error);
		S.Refresh();
		return Format("%s %s (VRC7 instrument, patch %d: %s). Use it by that name in write_notes or set_instrument.",
			S.Song.Instruments.size() > Before ? "Added" : "The song already has", InstrumentLabel(S.Song, Index).c_str(), pPatch->Number,
			pPatch->Description.c_str());
	}

	// The 5B plays its own sounds and the presets, made for it
	if (Chip == "5B") {
		if (!HasChip(S.Song, "5B"))
			throw Problem("This song has no 5B channels; set_expansion turns the Sunsoft 5B on.");
		const Preset *pSound = FindSoundFor5B(Name);
		if (pSound == 0)
			throw Problem(Format("No 5B sound or preset called \"%s\". 5B sounds: %s; presets: %s (not the drums, which are the "
				"noise channel's: the 5B has its own).", Name.c_str(), Sound5BList().c_str(), PresetList().c_str()));
		const size_t Before = S.Song.Instruments.size();
		std::string Error;
		const int Index = S.Host().AddInstrument(*pSound, Chip, false, Error);
		if (Index < 0)
			throw Problem(Error.empty() ? "The instrument couldn't be added." : Error);
		S.Refresh();
		return Format("%s %s (5B instrument: %s). Use it by that name in write_notes or set_instrument; its notes sound an octave "
			"under the note written.", S.Song.Instruments.size() > Before ? "Added" : "The song already has",
			InstrumentLabel(S.Song, Index).c_str(), pSound->Description.c_str());
	}

	// The N163 plays wave sounds drawn for it
	if (Chip == "N163") {
		if (!HasChip(S.Song, "N163"))
			throw Problem("This song has no N163 channels; set_expansion switches it to the N163.");
		const WaveSound *pSound = FindWaveSound(Name);
		if (pSound == 0)
			throw Problem(Format("No N163 sound called \"%s\". N163 sounds: %s.", Name.c_str(), WaveSoundList().c_str()));
		const size_t Before = S.Song.Instruments.size();
		std::string Where;
		const int Index = AddWaveInstrument(S, *pSound, Where);
		return Format("%s %s (N163 instrument: %s%s).%s Use it by that name in write_notes or set_instrument.",
			S.Song.Instruments.size() > Before ? "Added" : "The song already has", InstrumentLabel(S.Song, Index).c_str(),
			pSound->Description.c_str(), Where.empty() ? "" : ("; " + Where).c_str(), WaveSoundLevel(S, *pSound).c_str());
	}

	// The FDS plays sounds drawn for it
	if (Chip == "FDS") {
		if (S.Song.Expansion.find("FDS") == std::string::npos)
			throw Problem("This song has no FDS channel; set_expansion switches it to the FDS.");
		const FdsSound *pSound = FindFdsSound(Name);
		if (pSound == 0)
			throw Problem(Format("No FDS sound called \"%s\". FDS sounds: %s.", Name.c_str(), FdsSoundList().c_str()));
		bool Added = false;
		const int Index = AddFdsSound(S, *pSound, Added);
		return Format("%s %s (FDS instrument: %s). Use it by that name in write_notes or set_instrument. The FDS sounds two "
			"octaves under the note written, so its notes go two octaves above where a pulse would play them (A-5 there is a "
			"pulse's A-3, 440 Hz).", Added ? "Added" : "The song already has", InstrumentLabel(S.Song, Index).c_str(),
			pSound->Description.c_str());
	}

	const Preset *pPreset = FindPreset(Name);
	if (pPreset == 0)
		throw Problem(Format("No preset called \"%s\". Presets: %s; on VRC7 channels also: %s.", Name.c_str(), PresetList().c_str(),
			Vrc7PatchList().c_str()));
	if (Channel >= 0 && pPreset->Drum && S.Channel(Channel).Kind != KIND_NOISE)
		throw Problem(Format("\"%s\" is a drum for the noise channel.", pPreset->Name.c_str()));
	if (Chip != "2A03" && Chip != "VRC6")
		throw Problem("Presets are made for the 2A03 (also used by MMC5 channels), the VRC6, the VRC7 and the 5B; the N163 and "
			"the FDS have sounds of their own.");
	if (pPreset->Drum)
		Chip = "2A03";
	if (Chip == "VRC6" && S.Song.Expansion.find("VRC6") == std::string::npos)
		throw Problem("This song has no VRC6 channels.");
	const size_t Before = S.Song.Instruments.size();
	std::string Error;
	const int Index = S.Host().AddInstrument(*pPreset, Chip, Sawtooth, Error);
	if (Index < 0)
		throw Problem(Error.empty() ? "The instrument couldn't be added." : Error);
	S.Refresh();
	return Format("%s %s (%s instrument, %s). Use it by that name in write_notes or set_instrument.",
		S.Song.Instruments.size() > Before ? "Added" : "The song already has", InstrumentLabel(S.Song, Index).c_str(), Chip.c_str(),
		pPreset->Description.c_str());
}

// Changing notes that are there

// A working copy of the channels a change touches, from the song's first row
// on. Steps change it one after the other; at the end it is compared with the
// song, and what differs becomes one clip or one undoable change.
class Draft {
public:
	explicit Draft(Session &S) : m_S(S) {}

	std::vector<Cell> &Cells(int Channel)
	{
		std::map<int, std::vector<Cell> >::iterator it = m_Work.find(Channel);
		if (it == m_Work.end())
			it = m_Work.insert(std::make_pair(Channel, m_S.Cells(Channel))).first;
		return it->second;
	}

	// Cells from Row on; the channel grows past the song's end when needed
	void Put(int Channel, int Row, const std::vector<Cell> &Part)
	{
		std::vector<Cell> &Work = Cells(Channel);
		if (Work.size() < Row + Part.size())
			Work.resize(Row + Part.size());
		std::copy(Part.begin(), Part.end(), Work.begin() + Row);
	}

	std::vector<NoteInfo> Notes(int Channel)
	{
		return ReadNotes(Cells(Channel), m_S.Channel(Channel).EffectColumns);
	}

	// A channel as the draft has it, without taking it into the draft
	const std::vector<Cell> &View(int Channel)
	{
		std::map<int, std::vector<Cell> >::const_iterator it = m_Work.find(Channel);
		return it != m_Work.end() ? it->second : m_S.Cells(Channel);
	}

	// How the song plays with the draft in (jumps, skips and halts), and
	// the rows it then has
	SongFlow Flow(int &TotalRows)
	{
		std::vector<std::vector<Cell> > Channels;
		std::vector<int> Columns;
		size_t Rows = 0;
		for (int c = 0; c < m_S.ChannelCount(); ++c) {
			Channels.push_back(View(c));
			Columns.push_back(m_S.Channel(c).EffectColumns);
			Rows = std::max(Rows, Channels.back().size());
		}
		const int Length = std::max(1, m_S.Time.PatternLength);
		const int Frames = static_cast<int>((Rows + Length - 1) / Length);
		TotalRows = Frames * Length;
		return FollowSong(Channels, Columns, Length, Frames);
	}

	// What changed: the rows from the first changed one (or RangeFirst, when
	// that's earlier) to the last, in every channel that changed. Direct
	// changes also keep the notes after it playing as before. False when
	// nothing changed.
	// The changed rows from RangeFirst (or the first changed one) to the last changed one, or to RangeEnd when that's
	// later: the notes after them play as they did before (direct changes)
	bool Collect(int RangeFirst, bool DirectChange, std::vector<Change> &Changes, int &First, std::vector<std::string> &Warnings,
		int RangeEnd = -1)
	{
		int Low = -1, High = -1;
		std::vector<int> Changed;
		for (std::map<int, std::vector<Cell> >::const_iterator it = m_Work.begin(); it != m_Work.end(); ++it) {
			const std::vector<Cell> &Old = m_S.Cells(it->first), &New = it->second;
			const size_t Rows = std::max(Old.size(), New.size());
			bool Any = false;
			for (size_t r = 0; r < Rows; ++r) {
				const Cell a = r < Old.size() ? Old[r] : Cell();
				const Cell b = r < New.size() ? New[r] : Cell();
				if (a != b) {
					if (Low < 0 || static_cast<int>(r) < Low)
						Low = static_cast<int>(r);
					High = std::max(High, static_cast<int>(r));
					Any = true;
				}
			}
			if (Any)
				Changed.push_back(it->first);
		}
		if (High < 0)
			return false;
		First = std::min(Low, std::max(0, RangeFirst));
		const int End = std::max(High + 1, RangeEnd);
		bool Lost = false;
		for (size_t i = 0; i < Changed.size(); ++i) {
			const std::vector<Cell> &New = m_Work[Changed[i]];
			Change C;
			C.Channel = Changed[i];
			for (int r = First; r < End; ++r)
				C.Cells.push_back(r < static_cast<int>(New.size()) ? New[r] : Cell());
			if (DirectChange && !KeepFollowing(m_S.Cells(C.Channel), First, End, C.Cells, m_S.Channel(C.Channel).EffectColumns))
				Lost = true;
			Changes.push_back(C);
		}
		if (Lost)
			Warnings.push_back("Some effects didn't fit in the channels' four effect columns and were left out.");
		return true;
	}

private:
	Session &m_S;
	std::map<int, std::vector<Cell> > m_Work;
};

// Moves the notes that start in Cells[First, End) to Map(pitch, row); arpeggios
// (0xy) on their rows follow when MoveChords. True if anything moved. Moves
// counts how far each pitch class moved (where it did)
template <class MapFunction>
bool MapPitches(std::vector<Cell> &Cells, int First, int End, int Columns, MapFunction Map, bool MoveChords, int &Count,
	int &Skipped, std::map<int, int> *pMoves)
{
	int Original = -1;	// the playing note's pitch before
	bool Changed = false;
	for (int r = std::max(0, First); r < End && r < static_cast<int>(Cells.size()); ++r) {
		Cell &C = Cells[r];
		if (C.HasNote()) {
			Original = C.Pitch();
			const int Moved = Map(Original, r);
			if (Moved < 0 || Moved >= PITCHES) {
				++Skipped;
				Original = -1;
				continue;
			}
			if (pMoves != 0 && Moved != Original)
				(*pMoves)[Original % 12] = Moved - Original;
			Changed = Changed || Moved != Original;
			C.SetPitch(Moved);
			++Count;
		}
		else if (C.IsEnd())
			Original = -1;
		if (!MoveChords || Original < 0)
			continue;
		for (int k = 0; k < Columns && k < EFFECT_COLUMNS; ++k) {
			if (C.Effect[k] != EFF_ARPEGGIO || C.Param[k] == 0)
				continue;
			const int Root = Map(Original, r);
			const int x = Map(Original + (C.Param[k] >> 4), r) - Root, y = Map(Original + (C.Param[k] & 15), r) - Root;
			if (x >= 0 && x <= 15 && y >= 0 && y <= 15 && C.Param[k] != ((x << 4) | y)) {
				C.Param[k] = static_cast<unsigned char>((x << 4) | y);
				Changed = true;
			}
		}
	}
	return Changed;
}

// The notes that start in Cells[First, End) get Instrument; how many there are
int SetInstruments(std::vector<Cell> &Cells, int First, int End, int Instrument)
{
	int Count = 0;
	for (int r = std::max(0, First); r < End && r < static_cast<int>(Cells.size()); ++r) {
		if (Cells[r].HasNote()) {
			Cells[r].Instrument = static_cast<unsigned char>(Instrument);
			++Count;
		}
	}
	return Count;
}

// Vibrato 4xy on the notes that start in [First, End) and last MinRows or
// more, Delay rows in, with 400 on the note's last row; the vibrato a note
// had goes first. Depth 0 only takes it off. How many notes it changed.
int ApplyVibrato(std::vector<Cell> &Cells, const std::vector<NoteInfo> &Notes, int First, int End, int Speed, int Depth,
	int MinRows, int Delay, int Columns, bool &Lost)
{
	int Count = 0;
	for (size_t i = 0; i < Notes.size(); ++i) {
		const NoteInfo &N = Notes[i];
		if (N.Row < First || N.Row >= End)
			continue;
		const int Last = std::min(N.Row + N.Rows, static_cast<int>(Cells.size())) - 1;
		for (int r = N.Row; r <= Last; ++r) {
			for (int k = 0; k < EFFECT_COLUMNS; ++k) {
				if (Cells[r].Effect[k] == EFF_VIBRATO) {
					Cells[r].Effect[k] = EFF_NONE;
					Cells[r].Param[k] = 0;
				}
			}
		}
		if (Depth == 0) {
			++Count;
			continue;
		}
		if (N.Rows < MinRows || N.Row + Delay >= Last)
			continue;
		if (!AddEffect(Cells[N.Row + Delay], EFF_VIBRATO, (Speed << 4) | Depth, Columns) ||
			!AddEffect(Cells[Last], EFF_VIBRATO, 0, Columns))
			Lost = true;
		++Count;
	}
	return Count;
}

std::vector<int> ChannelsArg(Session &S, const Json &Args, const char *Name)
{
	std::vector<int> Channels;
	const Json *pValue = Arg(Args, Name);
	if (pValue == 0 || (pValue->IsString() && Lowercase(pValue->String()) == "all")) {
		for (int c = 0; c < S.ChannelCount(); ++c)
			if (IsMelodic(S.Channel(c)))
				Channels.push_back(c);
		return Channels;
	}
	if (pValue->IsArray()) {
		for (size_t i = 0; i < pValue->Size(); ++i)
			Channels.push_back(ParseChannel(S, pValue->At(i), Name));
	}
	else
		Channels.push_back(ParseChannel(S, *pValue, Name));
	std::sort(Channels.begin(), Channels.end());
	Channels.erase(std::unique(Channels.begin(), Channels.end()), Channels.end());
	return Channels;
}

// Sounds described in words

// A word from Words (as Values), or a number from 0 to Max
int WordArg(const Json &Args, const char *Name, int Default, const char *const *Words, const int *Values, int Count, int Max)
{
	const Json *pValue = Arg(Args, Name);
	if (pValue == 0)
		return Default;
	if (pValue->IsString()) {
		const std::string Text = Squeezed(pValue->String());
		// "darker" for dark, "longer" for long, as the descriptions put it
		const std::string Plain = Text.size() > 3 && Text.compare(Text.size() - 2, 2, "er") == 0 ? Text.substr(0, Text.size() - 2) :
			std::string();
		for (int i = 0; i < Count; ++i)
			if (Text == Squeezed(Words[i]) || (!Plain.empty() && Plain == Squeezed(Words[i])))
				return Values[i];
		if (Text.empty() || Text.find_first_not_of("0123456789") != std::string::npos) {
			std::string List;
			for (int i = 0; i < Count; ++i)
				List += (i == 0 ? "" : ", ") + std::string(Words[i]);
			throw Problem(std::string(Name) + ": " + List + (Max > 0 ? Format(", or a number up to %d.", Max) : std::string(".")));
		}
	}
	return IntArg(Args, Name, Default, 0, Max);
}

// A share of a beat in words: "a beat", "half a beat", "0.9 of a beat", "1.5 beats"
std::string BeatShare(double Beats)
{
	if (std::fabs(Beats - 1.0) < 0.05)
		return "a beat";
	if (std::fabs(Beats - 0.5) < 0.03)
		return "half a beat";
	return Format(Beats < 1.0 ? "%.2g of a beat" : "%.2g beats", Beats);
}

// An instrument's volume sequence a frame at a time, as FamiTracker reports it, and what it means in time at the song's
// tempo (Bpm, FramesPerBeat): when it peaks, is down to half, holds or falls silent, is struck again, and how a release
// fades it (design_instrument's answer, so the shape is known before a tune is written on it)
std::string VolumeTimeline(const InstrumentInfo &Info, double FramesPerBeat, double Bpm)
{
	const std::vector<int> &V = Info.Volume;
	const int Items = static_cast<int>(V.size());
	if (Items == 0)
		return std::string();
	const int Release = Info.VolumeRelease >= 0 && Info.VolumeRelease < Items ? Info.VolumeRelease : -1;
	const int Loop = Info.VolumeLoop >= 0 && Info.VolumeLoop < Items ? Info.VolumeLoop : -1;
	const int Held = Release >= 0 ? Release : Items - 1;	// the last frame before a release
	auto Join = [&V](int From, int To) {
		std::string Out;
		for (int i = From; i <= To; ++i)
			Out += (i == From ? "" : " ") + std::to_string(V[static_cast<size_t>(i)]);
		return Out;
	};
	// Frames, and in beats when that's a quarter of a beat or more
	const double Beat = std::max(1.0, FramesPerBeat);
	auto Frames = [Beat](const std::string &Before, int Count, const char *After) {
		return Before + " " + std::to_string(Count) + After + (Count >= Beat / 4 ? " (" + BeatShare(Count / Beat) + ")" : std::string());
	};
	int PeakAt = 0;
	for (int i = 1; i <= Held; ++i)
		if (V[static_cast<size_t>(i)] > V[static_cast<size_t>(PeakAt)])
			PeakAt = i;
	const int Peak = V[static_cast<size_t>(PeakAt)];
	int HalfAt = -1;
	for (int i = PeakAt + 1; i <= Held && HalfAt < 0; ++i)
		if (V[static_cast<size_t>(i)] * 2 <= Peak)
			HalfAt = i;
	std::vector<std::string> When;
	if (PeakAt >= 4)	// a swell
		When.push_back(Frames("peaks on frame", PeakAt, ""));
	std::string Out = " Volume a frame at a time: " + Join(0, Held);
	if (Loop >= 0 && Loop <= Held) {
		Out += Format(", again from frame %d while the note lasts", Loop);
		When.push_back(Frames("is struck again every", Held - Loop + 1, " frames"));
	}
	else if (Release >= 0) {
		const int Hold = V[static_cast<size_t>(Release)];
		int HoldAt = Release;
		while (HoldAt > PeakAt && V[static_cast<size_t>(HoldAt - 1)] == Hold)
			--HoldAt;
		Out += Format(", holding %d while the note lasts", Hold);
		if (HalfAt >= 0 && HalfAt < HoldAt)
			When.push_back(Format("is down to half (%d) on frame %d", V[static_cast<size_t>(HalfAt)], HalfAt));
		if (Hold < Peak)
			When.push_back(Frames(Format("holds %d from frame", Hold), HoldAt, ""));
	}
	else {
		int Silent = Items;	// silent for good from here
		while (Silent > 0 && V[static_cast<size_t>(Silent - 1)] == 0)
			--Silent;
		if (HalfAt >= 0)
			When.push_back(Format("is down to half (%d) on frame %d", V[static_cast<size_t>(HalfAt)], HalfAt));
		When.push_back(Silent < Items ? Frames("is silent from frame", Silent, "") : Format("then holds %d until the next note", V.back()));
	}
	if (Release >= 0 && Release + 1 < Items) {
		Out += "; after a release (===): " + Join(Release + 1, Items - 1);
		int Fade = Release + 1;
		while (Fade < Items && V[static_cast<size_t>(Fade)] > 0)
			++Fade;
		When.push_back(Frames("fades out in", Fade - Release, " frames after a release"));
	}
	Out += ".";
	if (When.empty())
		return Out;
	Out += " At " + FormatNumber(std::floor(Bpm * 10 + 0.5) / 10) + " BPM it ";
	for (size_t i = 0; i < When.size(); ++i)
		Out += (i == 0 ? "" : i + 1 == When.size() ? " and " : ", ") + When[i];
	return Out + ".";
}

// design_instrument's duty: a word (thin, bright, round, square, hollow, nasal), a share ("37.5%", 37.5) or a step of the
// chip's pulse (0-3 on the 2A03; 0-7 on the VRC6, (n + 1) / 16). The VRC6's pulses play every 6.25% up to 50% (Vrc6Duty its
// step, Duty the nearest on the 2A03), the 2A03's 12.5%, 25%, 50% and 75%.
void DutyArg(const Json &Args, bool Vrc6, int &Duty, int &Vrc6Duty)
{
	const Json *pValue = Arg(Args, "duty");
	if (pValue == 0)
		return;
	static const char *const WORDS[] = { "thin", "bright", "round", "square", "hollow", "nasal" };
	static const int WORD_VALUES[] = { 0, 1, 2, 2, 2, 0 };
	static const int NEAREST[8] = { 0, 0, 1, 1, 1, 2, 2, 2 };	// a VRC6 step's on the 2A03
	const std::string Help = Vrc6 ? "duty on the VRC6's pulses: 6.25% to 50% in steps of 6.25% (6.25%, 12.5%, 18.75%, 25%, 31.25%, "
		"37.5%, 43.75%, 50%), a step 0-7, or thin, bright, round, hollow, nasal." : "duty on the 2A03's pulses: 12.5%, 25%, 50% or "
		"75%, a step 0-3, or thin, bright, round, hollow, nasal (the VRC6's pulses also play 6.25% to 50% in steps of 6.25%).";
	double Share = -1.0;
	bool Step = false;
	if (pValue->IsNumber()) {
		Share = pValue->Number();
		Step = Share == std::floor(Share) && Share >= 0 && Share <= (Vrc6 ? 7 : 3);
	}
	else if (pValue->IsString()) {
		std::string Text = Lowercase(Trim(pValue->String()));
		const bool Percent = !Text.empty() && Text[Text.size() - 1] == '%';
		if (Percent)
			Text = Trim(Text.substr(0, Text.size() - 1));
		for (size_t w = 0; w < sizeof(WORDS) / sizeof(WORDS[0]); ++w) {
			if (Text == WORDS[w]) {
				Duty = WORD_VALUES[w];
				Vrc6Duty = -1;
				return;
			}
		}
		char *pEnd = 0;
		Share = Text.empty() ? -1.0 : std::strtod(Text.c_str(), &pEnd);
		if (Text.empty() || pEnd == 0 || *pEnd != 0)
			throw Problem(Help);
		Step = !Percent && Share == std::floor(Share) && Share >= 0 && Share <= (Vrc6 ? 7 : 3);
	}
	else
		throw Problem(Help);
	if (Step) {
		Vrc6Duty = Vrc6 ? static_cast<int>(Share) : -1;
		Duty = Vrc6 ? NEAREST[static_cast<int>(Share)] : static_cast<int>(Share);
		return;
	}
	if (std::fabs(Share - 75.0) < 0.01) {	// a 75% pulse sounds like a 25% one; the VRC6 plays it as before, at its nearest
		Duty = 3;
		Vrc6Duty = -1;
		return;
	}
	if (Vrc6 && Share >= 6.0 && Share <= 50.5) {
		Vrc6Duty = std::max(0, std::min(7, static_cast<int>(std::floor(Share / 6.25 + 0.5)) - 1));
		Duty = NEAREST[Vrc6Duty];
		return;
	}
	static const double SHARES[] = { 12.5, 25.0, 50.0 };
	for (int d = 0; d < 3 && !Vrc6; ++d) {
		if (std::fabs(Share - SHARES[d]) < 0.01) {
			Duty = d;
			Vrc6Duty = -1;
			return;
		}
	}
	throw Problem(Help);
}

std::string DesignInstrumentTool(Session &S, const Json &Args)
{
	const std::string Name = StringArg(Args, "name");
	if (Name.empty())
		throw Problem("Give the instrument a name.");
	if (Name.size() > 60)
		throw Problem("name: up to 60 characters.");
	std::string Chip = "2A03";
	bool Sawtooth = false, Triangle = false, Noise = false, Low = false;
	if (Arg(Args, "channel") != 0) {
		const int Channel = ChannelArg(S, Args, "channel");
		Chip = InstrumentChip(S.Channel(Channel));
		Sawtooth = S.Channel(Channel).Kind == KIND_SAWTOOTH;
		Triangle = S.Channel(Channel).Kind == KIND_TRIANGLE;
		Noise = S.Channel(Channel).Kind == KIND_NOISE;
		Low = IsBass(S.Channel(Channel));
		if (S.Channel(Channel).Kind == KIND_DPCM)
			throw Problem("The DPCM channel plays samples; design_instrument makes sounds for the other channels.");
	}
	else if (Arg(Args, "chip") != 0) {
		Chip = ChipWord(StringArg(Args, "chip"));
		if (Chip == "MMC5")
			Chip = "2A03";
	}
	if (Chip == "VRC7")
		throw Problem("VRC7 channels play the chip's own built-in sounds: add_instrument picks one by name (" + Vrc7PatchList() + ").");
	if (Chip != "2A03" && Chip != "VRC6" && Chip != "FDS" && Chip != "5B" && Chip != "N163")
		throw Problem("design_instrument makes sounds for 2A03 (and MMC5), VRC6, FDS, 5B and N163 channels.");
	if (Chip == "N163" && !HasChip(S.Song, "N163"))
		throw Problem("This song has no N163 channels; set_expansion switches it to the VRC6 Plus (a soft layer of four) or the N163.");
	if (Chip == "FDS" && !HasChip(S.Song, "FDS"))
		throw Problem("This song has no FDS channel; set_expansion switches it to the FDS.");
	if (Chip == "VRC6" && !HasChip(S.Song, "VRC6"))
		throw Problem("This song has no VRC6 channels.");
	if (Chip == "5B" && !HasChip(S.Song, "5B"))
		throw Problem("This song has no 5B channels.");

	SoundDesign D;
	const std::string Kind = StringArg(Args, "kind");
	if (!Kind.empty()) {
		if (!DesignOfKind(Kind, D))
			throw Problem("kind: " + DesignKinds() + ".");
	}
	else if (Noise)
		throw Problem("For the noise channel, say which drum with kind (kick, snare, hihat, open hihat, crash or tom), or swell for "
			"waves and wind.");
	else
		DesignOfKind(Low ? "bass" : "lead", D);
	if (D.Drum && Arg(Args, "channel") != 0 && !Noise)
		throw Problem(Chip == "5B" ? "A drum is for the noise channel; on the 5B, add_instrument has the chip's own: " + Sound5BList() +
			"." : std::string("A drum is for the noise channel."));
	if (D.Drum) {
		Chip = "2A03";
		Sawtooth = false;
	}
	D.Name = Name;
	// The song's beat, which the arguments in beats go by, and the calm kinds' times (a music box gone within a beat)
	const double RowsAMinute = RowsPerMinute(S.Song.Speed, S.Song.Tempo, S.Song.FrameRate);
	const double FramesPerBeat = RowsAMinute > 0 ? S.Time.RowsPerBeat * 60.0 * S.Song.FrameRate / RowsAMinute : 24.0;
	FitCalmTempo(Kind, FramesPerBeat, D);

	static const char *const ATTACKS[] = { "instant", "fast", "medium", "slow", "swell" };
	static const int ATTACK_FRAMES[] = { 0, 2, 5, 10, 20 };
	static const char *const DECAYS[] = { "none", "short", "medium", "long" };
	// The decay words go by the kind's own decay, so a bell's "long" rings longer than its usual 40 frames, not 24
	const int Natural = D.Decay;
	const int DECAY_FRAMES[] = { 0, Natural > 0 ? std::max(4, Natural / 3) : 4, Natural > 0 ? std::max(10, Natural) : 10,
		Natural > 0 ? std::min(120, std::max(24, Natural * 2)) : 24 };
	static const char *const SUSTAINS[] = { "none", "low", "half", "high", "full" };
	static const int SUSTAIN_LEVELS[] = { 0, 4, 8, 12, 15 };
	static const char *const RELEASES[] = { "short", "medium", "long" };
	static const int RELEASE_FRAMES[] = { 3, 8, 20 };
	static const char *const MOTIONS[] = { "still", "none", "sweep", "open", "wobble", "chorus", "fade" };
	static const int MOTION_VALUES[] = { DUTY_STILL, DUTY_STILL, DUTY_SWEEP, DUTY_SWEEP, DUTY_WOBBLE, DUTY_WOBBLE, DUTY_FADE };
	static const char *const VIBRATOS[] = { "none", "faint", "gentle", "medium", "strong" };
	static const int VIBRATO_DEPTHS[] = { 0, VIBRATO_FAINT, 1, 2, 3 };
	static const char *const PITCHES_WORDS[] = { "none", "blip", "scoop", "drop", "flick", "thump" };
	static const int PITCH_VALUES[] = { PITCH_PLAIN, PITCH_BLIP, PITCH_SCOOP, PITCH_DROP, PITCH_FLICK, PITCH_THUMP };
	static const char *const DECAY_STYLES[] = { "smooth", "steps", "stepped" };
	static const int DECAY_STYLE_VALUES[] = { DECAY_SMOOTH, DECAY_STEPS, DECAY_STEPS };
	static const char *const TONES[] = { "dark", "normal", "bright" };
	static const int TONE_VALUES[] = { -1, 0, 1 };
	static const char *const LENGTHS[] = { "short", "normal", "long" };
	static const int LENGTH_VALUES[] = { -1, 0, 1 };
	if (Lowercase(StringArg(Args, "attack")) == "bloom") {	// from about two thirds of the peak, in two frames
		D.Attack = 2;
		D.AttackFrom = std::max(1, (IntArg(Args, "volume", D.Peak, 1, 15) * 2 + 1) / 3);
	}
	else
		D.Attack = WordArg(Args, "attack", D.Attack, ATTACKS, ATTACK_FRAMES, 5, 60);
	D.AttackFrom = IntArg(Args, "attack_from", D.AttackFrom, 0, 15);
	D.DecayStyle = WordArg(Args, "decay_style", D.DecayStyle, DECAY_STYLES, DECAY_STYLE_VALUES, 3, 0);
	D.Click = BoolArg(Args, "click", D.Click);
	D.Echo = BoolArg(Args, "echo", D.Echo);
	D.Decay = WordArg(Args, "decay", D.Decay, DECAYS, DECAY_FRAMES, 4, 120);
	D.Peak = IntArg(Args, "volume", D.Peak, 1, 15);
	if (Arg(Args, "volume") != 0 && IsCalmKind(Kind)) {
		// Where its swell starts and what it holds, in proportion to the peak given (unless given too)
		SoundDesign Fit = D;
		FitCalmPeak(Kind, Fit);
		if (Arg(Args, "attack_from") == 0 && Lowercase(StringArg(Args, "attack")) != "bloom")
			D.AttackFrom = Fit.AttackFrom;
		if (Arg(Args, "sustain") == 0)
			D.Sustain = Fit.Sustain;
	}
	if (Arg(Args, "decay") != 0 && D.Decay == 0 && Arg(Args, "sustain") == 0)
		D.Sustain = D.Peak;	// no decay: it holds at its peak
	D.Sustain = std::min(D.Peak, WordArg(Args, "sustain", D.Sustain, SUSTAINS, SUSTAIN_LEVELS, 5, 15));
	// A sound that holds (no decay) asked to hold under its peak would drop straight down after its attack: it swells to
	// the level it holds instead, or with a volume given, settles to it over as long as its attack took
	if (!D.Drum && D.Decay == 0 && D.Sustain > 0 && D.Sustain < D.Peak && Arg(Args, "decay") == 0) {
		if (Arg(Args, "volume") == 0)
			D.Peak = D.Sustain;
		else
			D.Decay = std::max(8, D.Attack);
	}
	D.Release = WordArg(Args, "release", D.Release, RELEASES, RELEASE_FRAMES, 3, 60);
	if (Chip != "FDS")	// on the FDS a duty's word picks its wave
		DutyArg(Args, Chip == "VRC6", D.Duty, D.Vrc6Duty);
	D.Motion = WordArg(Args, "duty_motion", D.Motion, MOTIONS, MOTION_VALUES, 7, 0);
	D.Vibrato = WordArg(Args, "vibrato", D.Vibrato, VIBRATOS, VIBRATO_DEPTHS, 5, 0);
	if (Arg(Args, "vibrato_delay_beats") != 0) {
		const double Beats = NumberArg(Args, "vibrato_delay_beats", 0.5, 0.0, 8.0);
		D.VibratoDelay = std::max(0, std::min(200, static_cast<int>(std::floor(Beats * FramesPerBeat + 0.5))));
	}
	else if (D.Vibrato == VIBRATO_FAINT && Arg(Args, "vibrato") != 0 && !IsCalmKind(Kind))
		D.VibratoDelay = std::max(D.VibratoDelay, 24);	// as late as the calm references' comes in
	D.AttackPitch = WordArg(Args, "attack_pitch", D.AttackPitch, PITCHES_WORDS, PITCH_VALUES, 6, 0);
	if (Arg(Args, "restrike_beats") != 0) {
		const double Beats = NumberArg(Args, "restrike_beats", 0.5, 0.0, 4.0);
		D.Restrike = Beats <= 0 ? 0 : std::max(4, std::min(120, static_cast<int>(std::floor(Beats * FramesPerBeat + 0.5))));
	}
	// A drum is struck once a note, and the triangle has no volume to dip: a restrike would do nothing there
	std::string NoRestrike;
	if (D.Restrike > 0 && (D.Drum || Triangle)) {
		if (Arg(Args, "restrike_beats") != 0)
			NoRestrike = D.Drum ? " restrike_beats doesn't work on drums, which sound once a note: write the hits as notes." :
				" restrike_beats doesn't work on the triangle, which has no volume to dip: write the notes again instead.";
		D.Restrike = 0;
	}
	const std::string Chord = Squeezed(StringArg(Args, "arpeggio"));
	if (!Chord.empty()) {
		static const struct { const char *Word; std::initializer_list<int> Tones; } CHORDS[] = {
			{ "none", {} }, { "octave", { 0, 12 } }, { "major", { 0, 4, 7 } }, { "minor", { 0, 3, 7 } }, { "fifth", { 0, 7 } },
			{ "power", { 0, 7, 12 } }, { "sus2", { 0, 2, 7 } }, { "sus4", { 0, 5, 7 } }, { "major6", { 0, 4, 7, 9 } },
			{ "minor6", { 0, 3, 7, 9 } }, { "major7", { 0, 4, 7, 11 } }, { "minor7", { 0, 3, 7, 10 } }, { "dominant7", { 0, 4, 7, 10 } },
			{ "add9", { 0, 4, 7, 14 } }, { "minoradd9", { 0, 3, 7, 14 } }, { "diminished", { 0, 3, 6 } }, { "halfdiminished", { 0, 3, 6, 10 } },
			{ "diminished7", { 0, 3, 6, 9 } }, { "augmented", { 0, 4, 8 } },
			// The usual short names
			{ "maj", { 0, 4, 7 } }, { "m", { 0, 3, 7 } }, { "min", { 0, 3, 7 } }, { "5", { 0, 7 } }, { "6", { 0, 4, 7, 9 } }, { "m6", { 0, 3, 7, 9 } },
			{ "maj7", { 0, 4, 7, 11 } }, { "m7", { 0, 3, 7, 10 } }, { "7", { 0, 4, 7, 10 } }, { "dom7", { 0, 4, 7, 10 } },
			{ "madd9", { 0, 3, 7, 14 } }, { "dim", { 0, 3, 6 } }, { "m7b5", { 0, 3, 6, 10 } }, { "dim7", { 0, 3, 6, 9 } },
			{ "aug", { 0, 4, 8 } },
		};
		bool Known = false;
		for (size_t i = 0; i < sizeof(CHORDS) / sizeof(CHORDS[0]) && !Known; ++i) {
			if (Chord == CHORDS[i].Word) {
				D.Arpeggio.assign(CHORDS[i].Tones.begin(), CHORDS[i].Tones.end());
				Known = true;
			}
		}
		if (!Known)
			throw Problem("arpeggio: none, octave, major, minor, fifth, power, sus2, sus4, major6, minor6, major7, minor7, dominant7, "
				"add9, minoradd9, diminished, halfdiminished, diminished7 or augmented (or a short name: 6, m6, maj7, m7, 7, madd9, "
				"dim, m7b5, dim7, aug).");
	}
	D.ArpeggioFrames = IntArg(Args, "arpeggio_frames", D.ArpeggioFrames, 1, 8);
	D.Tone = WordArg(Args, "tone", D.Tone, TONES, TONE_VALUES, 3, 0);
	D.Length = WordArg(Args, "length", D.Length, LENGTHS, LENGTH_VALUES, 3, 0);
	std::vector<std::string> Dropped;
	if (Noise && !D.Drum) {
		// A volume envelope on the noise (a wave, a gust): an odd duty would make it metallic, and anything that moves the
		// pitch makes it warble
		if (Arg(Args, "vibrato") != 0 && D.Vibrato > 0)
			Dropped.push_back("vibrato");
		if (Arg(Args, "attack_pitch") != 0 && D.AttackPitch != PITCH_PLAIN)
			Dropped.push_back("attack_pitch");
		if (Arg(Args, "arpeggio") != 0 && !D.Arpeggio.empty())
			Dropped.push_back("arpeggio");
		if ((Arg(Args, "duty_motion") != 0 && D.Motion != DUTY_STILL) || (Arg(Args, "click") != 0 && D.Click) ||
			(Arg(Args, "duty") != 0 && D.Duty % 2 != 0))
			Dropped.push_back("duty");
		D.Duty = 0;
		D.Motion = DUTY_STILL;
		D.Click = false;
		D.Vibrato = 0;
		D.AttackPitch = PITCH_PLAIN;
		D.Arpeggio.clear();
		Chip = "2A03";
		Sawtooth = false;
	}

	// The FDS: its wave by word (or the kind's), its modulator, the design's envelope, pitch and arpeggio
	if (Chip == "FDS") {
		std::string Wave = StringArg(Args, "wave");
		if (Wave.empty() && Arg(Args, "duty") != 0 && IsFdsWave(StringArg(Args, "duty")))
			Wave = StringArg(Args, "duty");	// "bright", "hollow", "nasal", "round", "square": the wave of that name
		int ModDelay = 0;
		if (Arg(Args, "modulation_delay_beats") != 0) {
			const double Beats = NumberArg(Args, "modulation_delay_beats", 0.5, 0.0, 8.0);
			ModDelay = std::max(0, std::min(255, static_cast<int>(std::floor(Beats * FramesPerBeat + 0.5))));
		}
		FdsSound F;
		std::string Why;
		if (!DesignFdsSound(D, Kind.empty() ? "lead" : Kind, Wave, StringArg(Args, "modulation"), ModDelay, S.Song.FrameRate, F, Why))
			throw Problem(Why);
		for (size_t i = 0; i < S.Song.Instruments.size(); ++i)
			if (Lowercase(S.Song.Instruments[i].Name) == Lowercase(F.InstrumentName()) && S.Song.Instruments[i].Chip == Chip)
				throw Problem(Format("The song already has an FDS instrument called \"%s\"; give the new sound another name.",
					S.Song.Instruments[i].Name.c_str()));
		bool Added = false;
		const int Index = AddFdsSound(S, F, Added);
		return "Added " + InstrumentLabel(S.Song, Index) + " (FDS instrument): " + F.Description + "." + VanishRemark(S.Song, Index) +
			" Use it by name in write_notes, set_instrument or a part tool's instrument; the FDS sounds two octaves under the note "
			"written. Play a few notes so the user hears it.";
	}

	// N163 channels (the VRC6 Plus's soft layer): a wave sound's waves, following each other as in it, with the design's
	// volume, arpeggio and pitch
	if (Chip == "N163") {
		const std::string WaveName = StringArg(Args, "wave");
		const WaveSound *pBase = WaveName.empty() ? WaveSoundForKind(Kind.empty() ? "lead" : Kind) : FindWaveSound(WaveName);
		if (pBase == 0)
			throw Problem("wave: on N163 channels, the wave sound whose waves it plays: " + WaveSoundList() + ".");
		for (size_t i = 0; i < S.Song.Instruments.size(); ++i)
			if (Lowercase(S.Song.Instruments[i].Name) == Lowercase(Name) && S.Song.Instruments[i].Chip == "N163")
				throw Problem(Format("The song already has an N163 instrument called \"%s\"; give the new sound another name.",
					S.Song.Instruments[i].Name.c_str()));
		const WaveSound Sound = DesignedWaveSound(*pBase, D, Name);
		std::string Where;
		const int Index = AddWaveInstrument(S, Sound, Where);
		const std::string Unused = Arg(Args, "duty") != 0 || Arg(Args, "duty_motion") != 0 || Arg(Args, "click") != 0 ?
			" (without the duty asked for: its timbre is the waves')" : "";
		return "Added " + InstrumentLabel(S.Song, Index) + " (N163 instrument, the " + pBase->Name + "'s waves): " +
			DescribeDesign(D, S.Song.FrameRate, "N163") + Unused + (Where.empty() ? std::string() : "; " + Where) + "." +
			VolumeTimeline(SequencesInfo(Sound.Sequences, "N163"), FramesPerBeat, BeatsPerMinute(S.Song.Speed, S.Song.Tempo,
			S.Song.FrameRate, S.Time.RowsPerBeat)) + WaveSoundLevel(S, Sound) + NoRestrike + VanishRemark(S.Song, Index) +
			" Use it by name in write_notes, "
			"set_instrument or a part tool's instrument; play a few notes so the user hears it.";
	}

	// A new name, so an instrument the song uses doesn't change under it
	const Preset Sound = DesignPreset(D);
	const std::string Final = Lowercase(Sound.InstrumentName(Sawtooth));
	for (size_t i = 0; i < S.Song.Instruments.size(); ++i)
		if (Lowercase(S.Song.Instruments[i].Name) == Final && S.Song.Instruments[i].Chip == Chip)
			throw Problem(Format("The song already has %s instrument called \"%s\"; give the new sound another name.", AChip(Chip).c_str(),
				S.Song.Instruments[i].Name.c_str()));
	std::string Error;
	const int Index = S.Host().AddInstrument(Sound, Chip, Sawtooth, Error);
	if (Index < 0)
		throw Problem(Error.empty() ? "The instrument couldn't be added." : Error);
	S.Refresh();
	std::string Without;
	for (size_t i = 0; i < Dropped.size(); ++i)
		Without += (i == 0 ? "" : i + 1 == Dropped.size() ? " or " : ", ") + Dropped[i];
	const bool Square = Chip == "5B";
	const InstrumentInfo *pMade = FindInstrument(S.Song, Index);
	std::string Timeline, Clicks;
	if (pMade != 0 && !D.Drum && !Triangle && (Chip == "2A03" || Chip == "VRC6"))
		Timeline = VolumeTimeline(*pMade, FramesPerBeat, BeatsPerMinute(S.Song.Speed, S.Song.Tempo, S.Song.FrameRate,
			S.Time.RowsPerBeat));
	if (pMade != 0 && Chip == "2A03" && !D.Drum && !Triangle && !Noise && D.Vibrato > 0) {
		// On the 2A03's (and the MMC5's) pulses a vibrato that takes a held note's period across a multiple of 256 clicks
		const std::vector<int> Pitches = VibratoClickPitches(*pMade);
		const size_t Shown = std::min<size_t>(Pitches.size(), 4);
		for (size_t p = 0; p < Shown; ++p)
			Clicks += (p == 0 ? "" : p + 1 == Shown && Shown == Pitches.size() ? " and " : ", ") + PitchName(Pitches[p]);
		if (!Clicks.empty())
			Clicks = " Held on a 2A03 or MMC5 pulse its vibrato clicks on " + Clicks + (Pitches.size() > Shown ?
				Format(" and %d more", static_cast<int>(Pitches.size() - Shown)) : std::string()) + ": the tools nudge such notes "
				"with a fine pitch (Pxx) as they write them, and check_song lists any left.";
	}
	return "Added " + InstrumentLabel(S.Song, Index) + " (" + Chip + " instrument): " + DescribeDesign(D, S.Song.FrameRate,
		Sawtooth ? "sawtooth" : Triangle ? "triangle" : Noise && !D.Drum ? "noise" : Square ? "square" : "pulse") +
		(Without.empty() ? std::string() : " (without the " + Without + " asked for: on the noise they'd make it warble or ring "
			"metallic)") + "." + (Square && (Arg(Args, "duty") != 0 || Arg(Args, "duty_motion") != 0 || D.Click) ?
			" The 5B's square is always 50%, so it plays without the duty." : "") + Timeline + Clicks + NoRestrike +
		(D.Drum || Triangle || Noise ? std::string() : VanishRemark(S.Song, Index)) +
		" Use it by name in write_notes, set_instrument or a part tool's instrument; play a few notes so the user hears it.";
}

std::string SetInstrumentTool(Session &S, const Json &Args)
{
	const int Channel = ChannelArg(S, Args, "channel");
	if (Arg(Args, "instrument") == 0)
		throw Problem("Say which instrument (one of the song's, or a preset).");
	const int Instrument = InstrumentArg(S, Args, "instrument", Channel, NO_INSTRUMENT);
	int From, To;
	BarRange(S, Args, From, To);
	const int First = S.Time.BarStart(From), End = S.Time.BarEnd(To);
	const bool AsClip = BoolArg(Args, "as_clip", false);
	Draft D(S);
	const int Count = SetInstruments(D.Cells(Channel), First, End, Instrument);
	if (Count == 0)
		throw Problem(Format("%s has no notes in %s.", S.Channel(Channel).FullName().c_str(), RangeText(From, To).c_str()));
	std::vector<Change> Changes;
	std::vector<std::string> Warnings;
	int Start;
	if (!D.Collect(First, Direct(S, AsClip), Changes, Start, Warnings))
		throw Problem(Format("Those notes already play %s.", InstrumentLabel(S.Song, Instrument).c_str()));
	const std::string What = Format("%s on %s, %s", InstrumentLabel(S.Song, Instrument).c_str(), S.Channel(Channel).FullName().c_str(),
		RangeText(From, To).c_str());
	return WithRemarks(S, Commit(S, Changes, Start, AsClip, StringArg(Args, "clip_name"), What) +
		Format(" (%s)", Plural(Count, "note", "notes").c_str()), Warnings);
}

// to_key and to_mode, from the key the notes are in (key, or found)
bool KeyChangeArgs(Session &S, const Json &Args, int First, int End, Key &FromKey, Key &ToKey)
{
	if (Arg(Args, "to_key") == 0 && Arg(Args, "to_mode") == 0)
		return false;
	bool Found;
	FromKey = KeyArg(S, Args, "key", First, End, Found);
	if (!Found)
		throw Problem("There are no notes to find the key from; give key.");
	ToKey = FromKey;
	if (Arg(Args, "to_key") != 0) {
		const std::string Text = StringArg(Args, "to_key");
		if (!ParseKey(Text, ToKey))
			throw Problem(Format("to_key: \"%s\" isn't a key. Write it like \"A minor\" or \"F# dorian\".", Text.c_str()));
	}
	if (Arg(Args, "to_mode") != 0) {
		const std::string Text = StringArg(Args, "to_mode");
		if (!ParseMode(Text, ToKey.Mode))
			throw Problem(Format("to_mode: \"%s\" isn't a mode. Modes: major, dorian, phrygian, lydian, mixolydian, minor, locrian, "
				"harmonic minor.", Text.c_str()));
	}
	if (ToKey.Tonic == FromKey.Tonic && ToKey.Mode == FromKey.Mode)
		throw Problem("The notes are already in " + KeyName(FromKey) + (Arg(Args, "key") != 0 ? "" : S.Song.KeyChosen ?
			" (the track's key, chosen for it; give key if they're in another)" : " (found from the notes; give key if that's wrong)") +
			". Pick another to_mode or to_key.");
	return true;
}

// A key change (MapToKey) that keeps a dominant's ninth natural when the mode changes: E add9's F# in A major would become
// F in A minor (each scale degree to the new key's), a flat nine, a semitone over the chord's root an octave up. The
// source's chords on its fifth degree that sound a ninth (or a suspended second) are heard before anything moves
// (SongChords); a note on that ninth while one sounds goes to the new key's dominant's natural ninth
class KeyMove {
public:
	KeyMove(Session &S, const Key &From, const Key &To, int First, int End) : m_S(S), m_From(From), m_To(To)
	{
		if (From.Mode == To.Mode)
			return;
		const std::vector<ChordAt> Chords = SongChords(S, First, End, From);
		for (size_t i = 0; i < Chords.size(); ++i)
			if (Chords[i].C.Root == (From.Tonic + 7) % 12 && Chords[i].C.Has(2))
				m_Dominants.push_back(Chords[i]);
	}

	int operator()(int Pitch, int Row) const
	{
		for (size_t i = 0; i < m_Dominants.size(); ++i) {
			const ChordAt &D = m_Dominants[i];
			if (Row >= D.Row && Row < D.Row + D.Rows && ((Pitch - D.C.Root) % 12 + 12) % 12 == 2) {
				const int Kept = MapToKey(Pitch - 2, m_From, m_To) + 2;
				if (Kept != MapToKey(Pitch, m_From, m_To))
					m_Kept.insert(i);
				return Kept;
			}
		}
		return MapToKey(Pitch, m_From, m_To);
	}

	// What it kept, in words: "Eadd9's F# in bars 4 and 8 (A minor's F would be a flat nine)"; empty for nothing
	std::string KeptText() const
	{
		if (m_Kept.empty())
			return std::string();
		std::map<std::string, std::vector<int> > Bars;	// by chord, then its bars
		std::vector<std::string> Order;
		for (std::set<size_t>::const_iterator it = m_Kept.begin(); it != m_Kept.end(); ++it) {
			const ChordAt &D = m_Dominants[*it];
			const std::string Name = ChordName(D.C, m_From) + "'s " + NoteClassName(D.C.Root + 2, m_From);
			if (Bars.find(Name) == Bars.end())
				Order.push_back(Name);
			std::vector<int> &List = Bars[Name];
			const int Bar = m_S.Time.BarOf(D.Row);
			if (std::find(List.begin(), List.end(), Bar) == List.end())
				List.push_back(Bar);
		}
		std::string Text;
		for (size_t i = 0; i < Order.size(); ++i) {
			const std::vector<int> &List = Bars[Order[i]];
			Text += (i == 0 ? "" : "; ") + Order[i] + (List.size() == 1 ? Format(" in bar %d", List[0]) : " in bars " + BarList(List));
		}
		const ChordAt &D = m_Dominants[*m_Kept.begin()];
		return Text + " stays natural (" + KeyName(m_To) + "'s " + NoteClassName(MapToKey(D.C.Root + 2, m_From, m_To), m_To) +
			" would be a flat nine, a semitone over the chord's root)";
	}

private:
	Session &m_S;
	Key m_From, m_To;
	std::vector<ChordAt> m_Dominants;
	mutable std::set<size_t> m_Kept;
};

std::string MovesText(const std::map<int, int> &Moves, const Key &FromKey, const Key &ToKey)
{
	std::string Summary;
	for (std::map<int, int>::const_iterator it = Moves.begin(); it != Moves.end(); ++it) {
		if (it->second == 0)
			continue;
		if (!Summary.empty())
			Summary += ", ";
		Summary += NoteClassName(it->first, FromKey) + " to " + NoteClassName(it->first + it->second, ToKey);
	}
	return Summary;
}

int RevoiceLushChords(Session &S, Draft &D, int Channel, int First, int End, const Key &FromKey, const Key &ToKey, int &Unknown,
	const KeyMove *pMove = 0);

// Instruments no note in the module plays (its tracks, its clips): the
// template's starters, sounds tried and replaced. They're listed first and
// go with confirm, since FamiTracker can't undo it.
std::string RemoveUnusedInstrumentsTool(Session &S, const Json &Args)
{
	std::vector<int> InTracks, InClips;
	S.Host().CountInstrumentUses(InTracks, InClips);
	InTracks.resize(NO_INSTRUMENT, 0);
	InClips.resize(NO_INSTRUMENT, 0);
	// The ones to keep anyway, by name or number
	std::set<int> Keep;
	const Json *pKeep = Arg(Args, "keep");
	if (pKeep != 0) {
		std::vector<Json> Items;
		if (pKeep->IsArray())
			for (size_t i = 0; i < pKeep->Size(); ++i)
				Items.push_back(pKeep->At(i));
		else
			Items.push_back(*pKeep);
		for (size_t i = 0; i < Items.size(); ++i) {
			int Found = -1;
			const std::string Text = Items[i].IsString() ? Lowercase(Trim(Items[i].String())) : std::string();
			for (size_t k = 0; k < S.Song.Instruments.size() && Found < 0; ++k)
				if (Items[i].IsNumber() ? S.Song.Instruments[k].Index == static_cast<int>(Items[i].Number()) :
					Lowercase(S.Song.Instruments[k].Name) == Text)
					Found = S.Song.Instruments[k].Index;
			if (Found < 0 && Text.size() <= 2 && !Text.empty() && Text.find_first_not_of("0123456789abcdef") == std::string::npos) {
				const int Index = static_cast<int>(std::strtol(Text.c_str(), 0, 16));	// as FamiTracker numbers them
				if (FindInstrument(S.Song, Index) != 0)
					Found = Index;
			}
			if (Found < 0)
				throw Problem("keep: the song has no instrument " + (Items[i].IsNumber() ? FormatNumber(Items[i].Number()) :
					"\"" + (Items[i].IsString() ? Items[i].String() : std::string("?")) + "\"") + "; get_song lists them.");
			Keep.insert(Found);
		}
	}
	std::vector<int> Unused;
	std::string Names, InClipsOnly;
	for (size_t i = 0; i < S.Song.Instruments.size(); ++i) {
		const InstrumentInfo &I = S.Song.Instruments[i];
		if (I.Index < 0 || I.Index >= NO_INSTRUMENT || Keep.count(I.Index) > 0)
			continue;
		if (InTracks[static_cast<size_t>(I.Index)] > 0)
			continue;
		if (InClips[static_cast<size_t>(I.Index)] > 0) {
			InClipsOnly += (InClipsOnly.empty() ? "" : ", ") + Format("%02X %s", I.Index, I.Name.c_str());
			continue;
		}
		Unused.push_back(I.Index);
		Names += (Names.empty() ? "" : ", ") + Format("%02X %s", I.Index, I.Name.c_str());
	}
	const std::string Clips = InClipsOnly.empty() ? std::string() : " Only clips play " + InClipsOnly + ", so they stay.";
	if (Unused.empty())
		return "Every instrument plays somewhere, in a track or a clip: nothing to remove." + Clips;
	const std::string Count = Plural(static_cast<int>(Unused.size()), "instrument", "instruments");
	if (!BoolArg(Args, "confirm", false))
		return Format("No track or clip plays %s: %s.%s FamiTracker can't undo removing them, so ask the user, then call again "
			"with confirm: true (keep names any to keep).", Count.c_str(), Names.c_str(), Clips.c_str());
	if (!S.Song.DirectChanges)
		throw Problem("Removing instruments changes the song, which needs direct changes; the user can allow them in File > Connect "
			"Claude Code, or remove them with Edit > Clean up > Remove unused instruments in FamiTracker.");
	std::string Error;
	if (!S.Host().RemoveInstruments(Unused, Error))
		throw Problem(Error.empty() ? "The instruments couldn't be removed." : Error);
	S.Refresh();
	return Format("Removed %s no track or clip played: %s, and the sequences only they used. FamiTracker can't undo it; the "
		"song's notes play as before.%s", Count.c_str(), Names.c_str(), Clips.c_str());
}

std::string TransposeTool(Session &S, const Json &Args)
{
	std::vector<int> Channels = ChannelsArg(S, Args, "channels");
	int From, To;
	BarRange(S, Args, From, To);
	const int First = S.Time.BarStart(From), End = S.Time.BarEnd(To);
	const bool BySemitones = Arg(Args, "semitones") != 0;
	Key FromKey, ToKey;
	const bool ByKey = KeyChangeArgs(S, Args, First, End, FromKey, ToKey);
	if (BySemitones == ByKey)
		throw Problem("Give either semitones, or to_key or to_mode.");
	const int Semitones = IntArg(Args, "semitones", 0, -48, 48);
	const std::string How = ByKey ? "from " + KeyName(FromKey) + " to " + KeyName(ToKey) :
		Format("%s %s", Semitones >= 0 ? "up" : "down", Plural(std::abs(Semitones), "semitone", "semitones").c_str());

	std::vector<int> Melodic;
	for (size_t i = 0; i < Channels.size(); ++i)
		if (IsMelodic(S.Channel(Channels[i])) && NoteStartsIn(S, Channels[i], First, End))
			Melodic.push_back(Channels[i]);
	if (Melodic.empty()) {
		for (size_t i = 0; i < Channels.size(); ++i)
			if (IsMelodic(S.Channel(Channels[i])))
				throw Problem(Format("No notes to transpose in %s.", RangeText(From, To).c_str()));
		throw Problem("Noise and DPCM have no notes to transpose; pick melodic channels.");
	}

	const bool AsClip = BoolArg(Args, "as_clip", false);
	int Count = 0, Skipped = 0;
	std::map<int, int> Moves;	// pitch class -> semitones moved, for the summary
	Draft D(S);
	int Revoiced = 0, Unknown = 0;
	const KeyMove Move(S, FromKey, ToKey, First, End);
	for (size_t i = 0; i < Melodic.size(); ++i) {
		const int Columns = S.Channel(Melodic[i]).EffectColumns;
		if (ByKey) {
			MapPitches(D.Cells(Melodic[i]), First, End, Columns, [&](int Pitch, int Row) { return Move(Pitch, Row); }, true, Count,
				Skipped, &Moves);
			Revoiced += RevoiceLushChords(S, D, Melodic[i], First, End, FromKey, ToKey, Unknown, &Move);
		}
		else
			MapPitches(D.Cells(Melodic[i]), First, End, Columns, [&](int Pitch, int) { return Pitch + Semitones; }, false, Count, Skipped, 0);
	}
	std::vector<std::string> Warnings;
	if (ByKey && !Move.KeptText().empty())
		S.Remarks.push_back("A dominant's ninth kept: " + Move.KeptText() + ".");
	if (Revoiced > 0)
		S.Remarks.push_back(Format("%s now play%s the instrument for the chord's new shape.",
			Plural(Revoiced, "lush chord", "lush chords").c_str(), Revoiced == 1 ? "s" : ""));
	if (Unknown > 0)
		Warnings.push_back(Format("%s played by arpeggio instruments of the song's own keep their shapes, which may not fit %s.",
			Plural(Unknown, "chord", "chords").c_str(), KeyName(ToKey).c_str()));
	if (Skipped > 0)
		Warnings.push_back(Format("%s would have left FamiTracker's range (C-0 to B-7) and stayed as they were.",
			Plural(Skipped, "note", "notes").c_str()));
	std::vector<Change> Changes;
	int Start;
	if (!D.Collect(First, Direct(S, AsClip), Changes, Start, Warnings))
		throw Problem(Skipped > 0 ? "Every note would have left FamiTracker's range (C-0 to B-7); nothing moved." :
			ByKey ? "Nothing moved: those notes are the same in both keys." : "Nothing moved: give semitones other than 0.");
	const std::string What = Format("%s, %s, %s", How.c_str(), Plural(static_cast<int>(Changes.size()), "channel", "channels").c_str(),
		RangeText(From, To).c_str());
	// Every melodic note of the song in another key: the track's chosen key goes along
	KeyChoice NewKey;
	bool KeyMoves = false;
	if (S.Song.KeyChosen && Direct(S, AsClip) && First <= 0 && End >= S.Time.TotalRows()) {
		bool Every = true;
		for (int c = 0; c < S.ChannelCount() && Every; ++c)
			if (IsMelodic(S.Channel(c)) && NoteStartsIn(S, c, First, End) && std::find(Melodic.begin(), Melodic.end(), c) == Melodic.end())
				Every = false;
		const Key Now = S.Song.ChosenKey.K;
		KeyMoves = Every && KeyAfterMove(S, ByKey ? FromKey : Now, ByKey ? ToKey : Key(((Now.Tonic + Semitones) % 12 + 12) % 12, Now.Mode),
			NewKey);
	}
	std::string Result = Commit(S, Changes, Start, AsClip, StringArg(Args, "clip_name"), What, 0, KeyMoves ? &NewKey : 0) +
		Format(" (%s)", Plural(Count, "note", "notes").c_str());
	if (KeyMoves)
		Result += " The track's chosen key went along: " + KeyChoiceName(NewKey) + " now.";
	const std::string Summary = ByKey ? MovesText(Moves, FromKey, ToKey) : std::string();
	if (!Summary.empty())
		Result += " Notes moved: " + Summary + ".";
	return WithRemarks(S, Result, Warnings);
}

// The song's speed and tempo commands (Fxx) in the effect columns that play:
// speeds below the split point, tempos from it on
void SpeedCommands(Session &S, bool &Speeds, bool &Tempos)
{
	Speeds = Tempos = false;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		const std::vector<Cell> &Cells = S.Cells(c);
		for (size_t r = 0; r < Cells.size(); ++r) {
			for (int k = 0; k < S.Channel(c).EffectColumns && k < EFFECT_COLUMNS; ++k) {
				if (Cells[r].Effect[k] != EFF_SPEED)
					continue;
				if (std::max(1, static_cast<int>(Cells[r].Param[k])) >= S.Song.SplitPoint)
					Tempos = true;
				else
					Speeds = true;
			}
		}
	}
}

// The speed and tempo for a BPM (ChooseSpeedTempo). Speed commands in the
// song would set another speed back, so then the speed stays and the tempo
// changes.
void SpeedTempoFor(Session &S, double Bpm, int RowsPerBeat, int &Speed, int &Tempo)
{
	bool Speeds = false, Tempos = false;
	SpeedCommands(S, Speeds, Tempos);
	ChooseSpeedTempo(Bpm, RowsPerBeat, S.Song.FrameRate, S.Song.Speed, S.Song.SplitPoint, Speed, Tempo, Speeds ? S.Song.Speed : 0);
}

// "120 BPM (speed 6, tempo 120)"
std::string TempoText(const Session &S, int Speed, int Tempo)
{
	const double Bpm = BeatsPerMinute(Speed, Tempo, S.Song.FrameRate, S.Time.RowsPerBeat);
	return Format("%s BPM (speed %d, tempo %d)", FormatNumber(std::floor(Bpm * 10 + 0.5) / 10).c_str(), Speed, Tempo);
}

// When rows don't all last the same number of ticks: how long they last, and
// (Nearby) the speeds at the default tempo that would be even around there
std::string UnevenText(const Session &S, int Speed, int Tempo, bool Nearby)
{
	const double Rows = RowsPerMinute(Speed, Tempo, S.Song.FrameRate);
	if (EvenRows(Speed, Tempo, S.Song.FrameRate) || Rows <= 0.0)
		return std::string();
	const double Ticks = 60.0 * S.Song.FrameRate / Rows;
	const int Shorter = std::max(1, static_cast<int>(std::floor(Ticks))), Longer = Shorter + 1;
	std::string Text = Format(" Its rows last %d or %d ticks, so the rhythm isn't quite even.", Shorter, Longer);
	const int Default = DefaultTempo(S.Song.FrameRate);
	if (!Nearby || Default < std::max(32, S.Song.SplitPoint) || Default > 255)
		return Text;
	std::vector<std::string> Even;
	const int Speeds[] = { Shorter, Longer };
	for (int i = 0; i < 2; ++i) {
		if (Speeds[i] < S.Song.SplitPoint && Speeds[i] <= 31)
			Even.push_back(TempoText(S, Speeds[i], Default));
	}
	if (!Even.empty())
		Text += " Even rows nearby: " + Even[0] + (Even.size() > 1 ? " or " + Even[1] : std::string()) + ".";
	return Text;
}

// How many characters UTF-8 text holds
size_t Characters(const std::string &Text)
{
	size_t Count = 0;
	for (size_t i = 0; i < Text.size(); ++i)
		if ((static_cast<unsigned char>(Text[i]) & 0xC0) != 0x80)
			++Count;
	return Count;
}

std::string NameSongTool(Session &S, const Json &Args)
{
	if (!S.Song.DirectChanges)
		throw Problem("Naming the song changes it, and the user hasn't allowed direct changes. Suggest the user types the names in "
			"FamiTracker's song information boxes (title, author, copyright) or renames the track in Module > Module properties, "
			"or allows direct changes in File > Connect Claude Code.");
	SongNames Names;
	auto Take = [&](const char *Name, bool &Has, std::string &Text, size_t Most) {
		if (Arg(Args, Name) == 0)
			return;
		Text = Trim(StringArg(Args, Name));
		if (Characters(Text) > Most)
			throw Problem(Format("%s: at most %d characters, as FamiTracker keeps them.", Name, static_cast<int>(Most)));
		Has = true;
	};
	Take("title", Names.HasTitle, Names.Title, 31);
	Take("author", Names.HasAuthor, Names.Author, 31);
	Take("copyright", Names.HasCopyright, Names.Copyright, 31);
	Take("track", Names.HasTrack, Names.Track, 60);
	if (!Names.HasTitle && !Names.HasAuthor && !Names.HasCopyright && !Names.HasTrack)
		throw Problem("Give the names to set: title, author or copyright (the module's) or track (the selected track's), like "
			"{\"title\": \"Skylight\", \"track\": \"Title screen\"}.");
	if (Names.HasTrack && Names.Track.empty())
		throw Problem("A track's name can't be empty.");
	std::string Error;
	if (!S.Host().SetNames(Names, Error))
		throw Problem(Error.empty() ? "The names couldn't be set." : Error);
	S.Refresh();
	std::vector<std::string> Done;
	if (Names.HasTitle)
		Done.push_back("the title \"" + S.Song.Title + "\"");
	if (Names.HasAuthor)
		Done.push_back("the author \"" + S.Song.Author + "\"");
	if (Names.HasCopyright)
		Done.push_back("the copyright \"" + S.Song.Copyright + "\"");
	if (Names.HasTrack)
		Done.push_back(Format("track %d's name \"%s\" (export_for_game names its file and GameMaker sound after it)", S.Song.Track + 1,
			S.Song.TrackName.c_str()));
	std::string Text = "Set ";
	for (size_t i = 0; i < Done.size(); ++i)
		Text += (i == 0 ? "" : (i + 1 == Done.size() ? " and " : ", ")) + Done[i];
	return Text + ". Ctrl+Z doesn't undo names; name_song again changes them.";
}

// Speed and tempo commands (Fxx) inside the song

// A row's speed and tempo commands applied to Speed and Tempo, as
// CSoundGen::EvaluateGlobalEffects reads them: 0 counts as 1, and from the
// split point up a value is a tempo
void ApplySpeedCommands(const Cell &C, int Columns, int Split, int &Speed, int &Tempo)
{
	for (int k = 0; k < std::min(EFFECT_COLUMNS, Columns); ++k) {
		if (C.Effect[k] != EFF_SPEED)
			continue;
		const int Value = std::max(1, static_cast<int>(C.Param[k]));
		if (Value >= Split)
			Tempo = Value;
		else
			Speed = Value;
	}
}

// The speed and tempo as Row starts, the rows before it played in order: the
// track's, then their commands (a later channel's wins on a row). Rows gives
// a channel's cells, the song's or a draft's.
template <class RowsOf>
void SpeedTempoAt(Session &S, RowsOf Rows, int Row, int &Speed, int &Tempo)
{
	Speed = S.Song.Speed;
	Tempo = S.Song.Tempo;
	for (int r = 0; r < Row; ++r)
		for (int c = 0; c < S.ChannelCount(); ++c) {
			const std::vector<Cell> &Cells = Rows(c);
			if (r < static_cast<int>(Cells.size()))
				ApplySpeedCommands(Cells[static_cast<size_t>(r)], S.Channel(c).EffectColumns, S.Song.SplitPoint, Speed, Tempo);
		}
}

// The BPM a beat from Row plays at: its rows at their speed and tempo, on
// average (a swing's middle)
double BpmAt(Session &S, int Row)
{
	const int R = std::max(1, S.Time.RowsPerBeat), Total = S.Time.TotalRows();
	int Speed, Tempo;
	SpeedTempoAt(S, [&](int c) -> const std::vector<Cell> & { return S.Cells(c); }, Row, Speed, Tempo);
	double Frames = 0.0;
	int Rows = 0;
	for (int r = std::max(0, Row); r < Row + R && r < Total; ++r, ++Rows) {
		for (int c = 0; c < S.ChannelCount(); ++c)
			ApplySpeedCommands(S.Cells(c)[static_cast<size_t>(r)], S.Channel(c).EffectColumns, S.Song.SplitPoint, Speed, Tempo);
		Frames += 60.0 * S.Song.FrameRate / std::max(1e-9, RowsPerMinute(Speed, Tempo, S.Song.FrameRate));
	}
	if (Rows == 0 || Frames <= 0.0)
		return BeatsPerMinute(Speed, Tempo, S.Song.FrameRate, R);
	return 60.0 * S.Song.FrameRate * Rows / Frames / R;
}

// The channel the song's speed and tempo commands go on: the one that has
// some already, else the last
int SpeedHome(Session &S)
{
	for (int c = S.ChannelCount() - 1; c >= 0; --c) {
		const std::vector<Cell> &Cells = S.Cells(c);
		for (size_t r = 0; r < Cells.size(); ++r)
			if (HasEffect(Cells[r], EFF_SPEED, S.Channel(c).EffectColumns))
				return c;
	}
	return S.ChannelCount() - 1;
}

// An effect in a cell (AddEffect), where a speed command (Fxx under the split
// point) and a tempo command (from it up) are two kinds: a new one takes the
// place of one of its own kind, beside one of the other
bool AddSongEffect(Cell &Target, int Effect, int Param, int EffectColumns, int Split)
{
	if (Effect != EFF_SPEED)
		return AddEffect(Target, Effect, Param, EffectColumns);
	const int Columns = std::max(1, std::min(EFFECT_COLUMNS, EffectColumns));
	const bool Tempo = std::max(1, Param) >= Split;
	for (int k = 0; k < Columns; ++k)
		if (Target.Effect[k] == EFF_SPEED && (std::max(1, static_cast<int>(Target.Param[k])) >= Split) == Tempo) {
			Target.Param[k] = static_cast<unsigned char>(Param);
			return true;
		}
	for (int k = 0; k < Columns; ++k)
		if (Target.Effect[k] == EFF_NONE) {
			Target.Effect[k] = static_cast<unsigned char>(Effect);
			Target.Param[k] = static_cast<unsigned char>(Param);
			return true;
		}
	return false;
}

// An effect that steers the song (Fxx, Cxx) on Row in the draft: on Home, or
// the last channel with a free effect column there; false when none has one
bool PutSongEffect(Session &S, Draft &D, int Home, int Row, int Effect, int Param)
{
	if (Row < 0 || Row >= S.Time.TotalRows())
		return false;
	const int Split = S.Song.SplitPoint;
	if (AddSongEffect(D.Cells(Home)[static_cast<size_t>(Row)], Effect, Param, S.Channel(Home).EffectColumns, Split))
		return true;
	for (int c = S.ChannelCount() - 1; c >= 0; --c)
		if (c != Home && AddSongEffect(D.Cells(c)[static_cast<size_t>(Row)], Effect, Param, S.Channel(c).EffectColumns, Split))
			return true;
	return false;
}

SongFlow Flow(Session &S);
std::string StartPosition(const Session &S, int Row);

// A new tempo inside the song: from row First on, at Bpm (Speed and Tempo,
// when given, are its own; 0 works them out with even rows first), reached
// at once or in Ramp steps a beat apart, until End, where the speed and
// tempo the song had there come back (End at the song's end: none).
// SpeedGiven: the user named the speed, so the song's own go.
struct TempoChange {
	int First, End;
	double Bpm;
	int Speed, Tempo;
	int Ramp;
	bool SpeedGiven;
};

// The tempo whose BPM at Speed comes nearest Bpm, within FamiTracker's
// tempos
int NearestTempo(Session &S, double Bpm, int Speed)
{
	const int R = std::max(1, S.Time.RowsPerBeat), MinTempo = std::max(32, S.Song.SplitPoint);
	const int Guess = static_cast<int>(std::floor(Bpm * Speed * R / 24.0 + 0.5));
	int Best = std::max(MinTempo, std::min(255, Guess));
	for (int t = std::max(MinTempo, Guess - 2); t <= std::min(255, Guess + 2); ++t)
		if (std::fabs(BeatsPerMinute(Speed, t, S.Song.FrameRate, R) - Bpm) <
			std::fabs(BeatsPerMinute(Speed, Best, S.Song.FrameRate, R) - Bpm) - 1e-9)
			Best = t;
	return Best;
}

// The speed and tempo commands for a change, in the draft: the song's own
// there go, but for speed commands that keep changing inside it, one a beat or
// more (a swing): those stay and the tempo moves instead, so they keep their
// proportions. Where the song loops back into or past the change, the loop's
// start gets the speed and tempo it plays at the first time. What it did, in
// words ("" when nothing changed); a Problem when it can't be done.
std::string WriteTempoChange(Session &S, Draft &D, const TempoChange &Plan, std::vector<std::string> &Warnings,
	bool *pKeptSpeeds = 0)
{
	const int Split = S.Song.SplitPoint, R = std::max(1, S.Time.RowsPerBeat), Total = S.Time.TotalRows();
	const int MinTempo = std::max(32, Split), MaxSpeed = std::max(1, std::min(31, Split - 1));
	const int First = std::max(0, Plan.First), End = std::min(Total, std::max(First + 1, Plan.End));
	const auto Song = [&](int c) -> const std::vector<Cell> & { return S.Cells(c); };
	const auto Drafted = [&](int c) -> const std::vector<Cell> & { return D.View(c); };
	int Speed0, Tempo0;	// entering the range (its first row's commands go)
	SpeedTempoAt(S, Drafted, First, Speed0, Tempo0);
	int SpeedAt = Speed0, TempoAt = Tempo0;	// what it starts at now, with them
	for (int c = 0; c < S.ChannelCount(); ++c)
		if (First < static_cast<int>(D.View(c).size()))
			ApplySpeedCommands(D.View(c)[static_cast<size_t>(First)], S.Channel(c).EffectColumns, Split, SpeedAt, TempoAt);
	int SpeedAfter = 0, TempoAfter = 0;	// as the song plays on from End (with End's own commands)
	if (End < Total)
		SpeedTempoAt(S, Song, End + 1, SpeedAfter, TempoAfter);

	// Speed commands that keep changing inside the range (a swing) stay; a few (a ritardando, a section's
	// speed) go with the rest, as do all when the user named the speed
	int Changing = 0;	// rows inside with a speed command
	for (int r = First + 1; r < End; ++r) {
		bool Has = false;
		for (int c = 0; c < S.ChannelCount() && !Has; ++c) {
			const std::vector<Cell> &Cells = D.View(c);
			if (r < static_cast<int>(Cells.size()))
				for (int k = 0; k < std::min(EFFECT_COLUMNS, S.Channel(c).EffectColumns); ++k)
					Has = Has || (Cells[static_cast<size_t>(r)].Effect[k] == EFF_SPEED &&
						std::max(1, static_cast<int>(Cells[static_cast<size_t>(r)].Param[k])) < Split);
		}
		Changing += Has ? 1 : 0;
	}
	const bool KeepSpeeds = !Plan.SpeedGiven && Changing >= std::max(4, (End - First) / R);
	if (pKeptSpeeds != 0)
		*pKeptSpeeds = KeepSpeeds;
	// The speed the range's first beat plays at on average (a swing's middle)
	double Base = SpeedAt;
	if (KeepSpeeds) {
		int Speed = Speed0, Tempo = Tempo0, Sum = 0, Rows = 0;
		for (int r = First; r < std::min(End, First + R); ++r, ++Rows) {
			for (int c = 0; c < S.ChannelCount(); ++c)
				if (r < static_cast<int>(D.View(c).size()))
					ApplySpeedCommands(D.View(c)[static_cast<size_t>(r)], S.Channel(c).EffectColumns, Split, Speed, Tempo);
			Sum += Speed;
		}
		Base = Rows > 0 ? static_cast<double>(Sum) / Rows : SpeedAt;
	}
	const double Bpm0 = KeepSpeeds ? 24.0 * TempoAt / (Base * R) : BeatsPerMinute(SpeedAt, TempoAt, S.Song.FrameRate, R);
	if (Bpm0 <= 0.0 || Plan.Bpm <= 0.0)
		throw Problem("The tempo there can't be worked out.");
	auto ScaledTempo = [&](double Bpm) {
		const int Tempo = static_cast<int>(std::floor(TempoAt * Bpm / Bpm0 + 0.5));
		if (Tempo < MinTempo || Tempo > 255)
			throw Problem(Format("The song changes its speed inside those bars (a swing, say), which stays, so the tempo has to "
				"carry the change: from %d it would go to %d, outside FamiTracker's tempos (%d-255).", TempoAt, Tempo, MinTempo));
		return Tempo;
	};
	int Speed1 = Plan.Speed, Tempo1 = Plan.Tempo;
	if (KeepSpeeds) {
		Speed1 = -1;
		Tempo1 = ScaledTempo(Plan.Bpm);
	}
	else if (Speed1 <= 0 || Tempo1 <= 0)
		ChooseSpeedTempo(Plan.Bpm, R, S.Song.FrameRate, Speed0, Split, Speed1, Tempo1);

	// The song's commands there go
	for (int c = 0; c < S.ChannelCount(); ++c)
		for (int r = First; r < End && r < static_cast<int>(D.View(c).size()); ++r)
			for (int k = 0; k < EFFECT_COLUMNS; ++k) {
				const Cell &Old = D.View(c)[static_cast<size_t>(r)];
				if (Old.Effect[k] != EFF_SPEED || (KeepSpeeds && std::max(1, static_cast<int>(Old.Param[k])) < Split))
					continue;
				Cell &C = D.Cells(c)[static_cast<size_t>(r)];
				C.Effect[k] = EFF_NONE;
				C.Param[k] = 0;
			}

	// The steps: one, or a beat apart, the last on the new speed and tempo. A
	// ramp keeps one speed on its way, one every step's tempo fits at
	struct Step { int Row, Speed, Tempo; };
	std::vector<Step> Steps;
	const int Ramp = std::max(0, Plan.Ramp);
	if (Ramp > 1 && First + (Ramp - 1) * R >= End)
		throw Problem(Format("The change is %s long, too short for %s of it a beat apart.", S.Time.Length(End - First).c_str(),
			Plural(Ramp, "step", "steps").c_str()));
	int Along = Speed0;
	if (Ramp > 1 && !KeepSpeeds) {
		const double Low = std::min(Bpm0, Plan.Bpm), High = std::max(Bpm0, Plan.Bpm);
		int Best = -1;
		for (int s = 1; s <= MaxSpeed; ++s) {
			if (Low * s * R / 24.0 < MinTempo - 0.5 || High * s * R / 24.0 > 255.5)
				continue;
			if (Best < 0 || std::abs(s - Speed0) < std::abs(Best - Speed0))
				Best = s;
		}
		if (Best < 0)
			throw Problem(Format("FamiTracker can't slide from %s to %s BPM in even steps; try fewer bars or a nearer tempo.",
				FormatNumber(std::floor(Bpm0 * 10 + 0.5) / 10).c_str(), FormatNumber(std::floor(Plan.Bpm * 10 + 0.5) / 10).c_str()));
		Along = Best;
	}
	if (Ramp <= 1) {
		const Step Only = { First, Speed1, Tempo1 };
		Steps.push_back(Only);
	}
	else
		for (int k = 1; k <= Ramp; ++k) {
			const double Bpm = Bpm0 + (Plan.Bpm - Bpm0) * k / Ramp;
			Step St = { First + (k - 1) * R, Speed1, Tempo1 };
			if (k < Ramp) {
				St.Speed = KeepSpeeds ? -1 : Along;
				St.Tempo = KeepSpeeds ? ScaledTempo(Bpm) : NearestTempo(S, Bpm, Along);
			}
			Steps.push_back(St);
		}
	const int Home = SpeedHome(S);
	int Speed = Speed0, Tempo = Tempo0, Lost = 0, LowTempo = 999, HighTempo = 0;
	for (size_t i = 0; i < Steps.size(); ++i) {
		const Step &St = Steps[i];
		if (St.Speed > 0 && St.Speed != Speed) {
			Lost += PutSongEffect(S, D, Home, St.Row, EFF_SPEED, St.Speed) ? 0 : 1;
			Speed = St.Speed;
		}
		if (St.Tempo != Tempo) {
			Lost += PutSongEffect(S, D, Home, St.Row, EFF_SPEED, St.Tempo) ? 0 : 1;
			Tempo = St.Tempo;
		}
		if (i + 1 < Steps.size() || St.Speed == Along || St.Speed < 0) {
			LowTempo = std::min(LowTempo, St.Tempo);
			HighTempo = std::max(HighTempo, St.Tempo);
		}
	}

	// From End on as the song had it
	bool Back = false;
	if (End < Total) {
		int SpeedNow, TempoNow;
		SpeedTempoAt(S, Drafted, End + 1, SpeedNow, TempoNow);
		if (SpeedNow != SpeedAfter) {
			Lost += PutSongEffect(S, D, Home, End, EFF_SPEED, SpeedAfter) ? 0 : 1;
			Back = true;
		}
		if (TempoNow != TempoAfter) {
			Lost += PutSongEffect(S, D, Home, End, EFF_SPEED, TempoAfter) ? 0 : 1;
			Back = true;
		}
	}

	// Where the loop comes back: the speed and tempo its start has the first
	// time (when the song played the loop alike before)
	int Rows = 0;
	const SongFlow F = D.Flow(Rows);
	bool Seam = false;
	if (!F.Halts()) {
		const int Loop = F.LoopRow(S.Time.PatternLength), Last = F.EndRow(S.Time.PatternLength) - 1;
		int SpeedFirst, TempoFirst, SpeedAgain, TempoAgain, WasFirst[2], WasAgain[2];
		SpeedTempoAt(S, Drafted, Loop, SpeedFirst, TempoFirst);
		SpeedTempoAt(S, Drafted, Last + 1, SpeedAgain, TempoAgain);
		SpeedTempoAt(S, Song, Loop, WasFirst[0], WasFirst[1]);
		SpeedTempoAt(S, Song, Last + 1, WasAgain[0], WasAgain[1]);
		int SpeedOwn = 0, TempoOwn = 0;	// what the loop's first row sets itself
		for (int c = 0; c < S.ChannelCount(); ++c)
			if (Loop < static_cast<int>(D.View(c).size()))
				ApplySpeedCommands(D.View(c)[static_cast<size_t>(Loop)], S.Channel(c).EffectColumns, Split, SpeedOwn, TempoOwn);
		if (SpeedAgain != SpeedFirst && SpeedOwn == 0 && WasAgain[0] == WasFirst[0]) {
			Lost += PutSongEffect(S, D, Home, Loop, EFF_SPEED, SpeedFirst) ? 0 : 1;
			Seam = true;
		}
		if (TempoAgain != TempoFirst && TempoOwn == 0 && WasAgain[1] == WasFirst[1]) {
			Lost += PutSongEffect(S, D, Home, Loop, EFF_SPEED, TempoFirst) ? 0 : 1;
			Seam = true;
		}
		if (Seam)
			Warnings.push_back(Format("Where the loop comes back (%s) the song gets the speed and tempo it has there the first time, "
				"so the loop plays the same each time.", StartPosition(S, Loop).c_str()));
	}
	if (Lost > 0)
		throw Problem(Format("%s had no free effect column for the speed and tempo (all four were full); show another effect "
			"column in FamiTracker or free one there.", Plural(Lost, "row", "rows").c_str()));

	// In words
	const std::string From = StartPosition(S, First), Old = KeepSpeeds ? Format("%s BPM (tempo %d)",
		FormatNumber(std::floor(Bpm0 * 10 + 0.5) / 10).c_str(), TempoAt) : TempoText(S, SpeedAt, TempoAt);
	std::string Text;
	const std::string New = KeepSpeeds ? Format("%s BPM (tempo %d)", FormatNumber(std::floor(Plan.Bpm * 10 + 0.5) / 10).c_str(),
		Tempo1) : TempoText(S, Speed1, Tempo1);
	const int RampRows = static_cast<int>(Steps.size()) * R;
	const std::string Over = RampRows % std::max(1, S.Time.RowsPerBar) == 0 ?
		Plural(RampRows / std::max(1, S.Time.RowsPerBar), "bar", "bars") : S.Time.Length(RampRows);
	if (Steps.size() > 1)
		Text = Format("from %s it %s gradually over %s, a step a beat, from %s to %s (tempo commands F%02X-F%02X%s)", From.c_str(),
			Plan.Bpm < Bpm0 ? "slows down" : "speeds up", Over.c_str(), Old.c_str(),
			New.c_str(), Plan.Bpm < Bpm0 ? HighTempo : LowTempo, Plan.Bpm < Bpm0 ? LowTempo : HighTempo,
			!KeepSpeeds && Along != Speed0 ? Format(" at speed %d", Along).c_str() : "");
	else
		Text = Format("from %s it plays at %s instead of %s", From.c_str(), New.c_str(), Old.c_str());
	if (KeepSpeeds)
		Text += "; the song's speed changes there stay (a swing, say), so the tempo carries the change";
	if (End < Total)
		Text += Back ? Format(", and from %s at %s again", StartPosition(S, End).c_str(), KeepSpeeds ?
			Format("tempo %d", TempoAfter).c_str() : TempoText(S, SpeedAfter, TempoAfter).c_str()) :
			Format(" until %s", StartPosition(S, End).c_str());
	else
		Text += " to the song's end";
	// Nothing to say when the song stays as it was
	bool Changed = false;
	for (int c = 0; c < S.ChannelCount() && !Changed; ++c)
		Changed = D.View(c) != S.Cells(c);
	return Changed ? Text : std::string();
}

// set_tempo for some bars: speed and tempo commands from a bar (and beat) on,
// at once or gradually, the tempo the song had coming back after to_bar
std::string TempoInsideTool(Session &S, const Json &Args, bool ByBpm, bool BySpeed, bool ByTempo)
{
	const int Bars = S.Time.BarCount(), R = std::max(1, S.Time.RowsPerBeat);
	const int MaxSpeed = std::max(1, std::min(31, S.Song.SplitPoint - 1)), MinTempo = std::max(32, S.Song.SplitPoint);
	int From, To;
	if (!SectionBars(S, Args, From, To)) {	// a section: its own tempo, and the old one after it
		From = IntArg(Args, "from_bar", 1, 1, Bars);
		To = IntArg(Args, "to_bar", Bars, From, Bars);
	}
	int First = S.Time.BarStart(From);
	if (Arg(Args, "beat") != 0) {
		bool Exact;
		const double Beat = NumberArg(Args, "beat", 1.0, 1.0, 64.0);
		if (!S.Time.PositionToRow(From, Beat, First, Exact))
			throw Problem(Format("Bar %d has %s; beat is one of them, like 3 or 2.5.", From,
				Plural(S.Time.BeatsPerBar(From), "beat", "beats").c_str()));
	}
	int Speed0, Tempo0;
	SpeedTempoAt(S, [&](int c) -> const std::vector<Cell> & { return S.Cells(c); }, First, Speed0, Tempo0);
	int Speed = BySpeed ? IntArg(Args, "speed", Speed0, 1, MaxSpeed) : Speed0;
	int Tempo = ByTempo ? IntArg(Args, "tempo", Tempo0, MinTempo, 255) : Tempo0;
	double Bpm;
	if (ByBpm) {
		Bpm = NumberArg(Args, "bpm", 0.0, 10.0, 1000.0);
		ChooseSpeedTempo(Bpm, R, S.Song.FrameRate, Speed0, S.Song.SplitPoint, Speed, Tempo, BySpeed ? Speed : 0, ByTempo ? Tempo : 0);
	}
	else
		Bpm = BeatsPerMinute(Speed, Tempo, S.Song.FrameRate, R);
	int Ramp = 0;
	if (Arg(Args, "over_bars") != 0) {
		const double Over = NumberArg(Args, "over_bars", 0.0, 0.25, 64.0);
		Ramp = std::max(1, static_cast<int>(std::floor(Over * S.Time.BeatsPerBar(From) + 0.5)));
	}
	const TempoChange Plan = { First, S.Time.BarEnd(To), Bpm, Speed, Tempo, Ramp, BySpeed };
	Draft D(S);
	std::vector<std::string> Warnings;
	bool KeptSpeeds = false;
	const std::string What = WriteTempoChange(S, D, Plan, Warnings, &KeptSpeeds);
	std::vector<Change> Changes;
	int Start = First;
	if (What.empty() || !D.Collect(First, true, Changes, Start, Warnings))
		return Format("It plays at %s there already.", KeptSpeeds ? (FormatNumber(std::floor(Bpm * 10 + 0.5) / 10) + " BPM").c_str() :
			TempoText(S, Speed, Tempo).c_str());
	std::string Text = Commit(S, Changes, Start, false, "", What);
	if (Ramp <= 1 && !KeptSpeeds && !EvenRows(Speed, Tempo, S.Song.FrameRate))
		Text += UnevenText(S, Speed, Tempo, true);
	return WithRemarks(S, Text, Warnings);
}

std::string SetTempoTool(Session &S, const Json &Args)
{
	if (!S.Song.DirectChanges)
		throw Problem(Format("Changing the tempo changes the song, and the user hasn't allowed direct changes. Suggest the user sets "
			"it with the speed and tempo boxes in FamiTracker's toolbar (now speed %d, tempo %d), or allows direct changes in "
			"File > Connect Claude Code.", S.Song.Speed, S.Song.Tempo));
	const bool ByBpm = Arg(Args, "bpm") != 0, BySpeed = Arg(Args, "speed") != 0, ByTempo = Arg(Args, "tempo") != 0;
	if (!ByBpm && !BySpeed && !ByTempo)
		throw Problem("Give the tempo as bpm, like {\"bpm\": 120}, or FamiTracker's speed and tempo, like {\"speed\": 5, \"tempo\": 150}.");
	if (ByBpm && BySpeed && ByTempo)
		throw Problem("Give bpm, or speed and tempo. With bpm, give at most one of speed and tempo: it stays, and the other is picked "
			"for the bpm.");
	if (RangeGiven(Args) || Arg(Args, "beat") != 0 || Arg(Args, "over_bars") != 0)
		return TempoInsideTool(S, Args, ByBpm, BySpeed, ByTempo);
	const int MaxSpeed = std::max(1, std::min(31, S.Song.SplitPoint - 1)), MinTempo = std::max(32, S.Song.SplitPoint);
	int Speed = BySpeed ? IntArg(Args, "speed", S.Song.Speed, 1, MaxSpeed) : S.Song.Speed;
	int Tempo = ByTempo ? IntArg(Args, "tempo", S.Song.Tempo, MinTempo, 255) : S.Song.Tempo;
	if (ByBpm) {
		const double Bpm = NumberArg(Args, "bpm", 0.0, 10.0, 1000.0);
		if (BySpeed || ByTempo)
			ChooseSpeedTempo(Bpm, S.Time.RowsPerBeat, S.Song.FrameRate, S.Song.Speed, S.Song.SplitPoint, Speed, Tempo,
				BySpeed ? Speed : 0, ByTempo ? Tempo : 0);
		else
			SpeedTempoFor(S, Bpm, S.Time.RowsPerBeat, Speed, Tempo);
	}
	bool Speeds = false, Tempos = false;
	SpeedCommands(S, Speeds, Tempos);
	const bool Nearby = !Speeds && !Tempos;	// with speed commands, other speeds wouldn't last
	if (Speed == S.Song.Speed && Tempo == S.Song.Tempo)
		return "The song plays at " + TempoText(S, Speed, Tempo) + " already." + UnevenText(S, Speed, Tempo, Nearby);
	std::string Why, Error;
	if (!S.Host().CanChange(Why))
		throw Problem(Why);
	if (!S.Host().SetSpeedTempo(Speed, Tempo, Error))
		throw Problem(Error.empty() ? "The tempo couldn't be set." : Error);
	std::string Text = "Tempo set to " + TempoText(S, Speed, Tempo) + "; it was " + TempoText(S, S.Song.Speed, S.Song.Tempo) +
		". One Ctrl+Z undoes it." + UnevenText(S, Speed, Tempo, Nearby);
	// Fxx effects change it again while playing
	for (int c = 0; c < S.ChannelCount(); ++c) {
		const std::vector<Cell> &Cells = S.Cells(c);
		for (size_t r = 0; r < Cells.size(); ++r) {
			for (int k = 0; k < S.Channel(c).EffectColumns && k < EFFECT_COLUMNS; ++k) {
				if (Cells[r].Effect[k] == EFF_SPEED) {
					return Text + Format(" Note: the song sets speed or tempo with an F%02X effect at %s on %s, which still applies there.",
						Cells[r].Param[k], S.Time.Position(static_cast<int>(r)).c_str(), S.Channel(c).FullName().c_str());
				}
			}
		}
	}
	return Text;
}

// The meter

std::string SetMeterTool(Session &S, const Json &Args)
{
	if (!S.Song.DirectChanges)
		throw Problem("Changing the meter changes the song, and the user hasn't allowed direct changes. Suggest the user sets the row "
			"highlights in FamiTracker's toolbar (the first is rows a beat, the second rows a bar), or allows direct changes in "
			"File > Connect Claude Code.");
	std::string Meter = Lowercase(Trim(StringArg(Args, "meter")));
	if (Meter.empty())
		throw Problem("Say which meter, like {\"meter\": \"3/4\"} (a waltz) or \"6/8\" (a jig, a sea shanty).");
	static const struct { const char *Word, *Meter; } WORDS[] = { { "waltz", "3/4" }, { "march", "2/4" }, { "jig", "6/8" },
		{ "shanty", "6/8" }, { "common", "4/4" }, { "common time", "4/4" }, { "cut", "2/2" }, { "cut time", "2/2" } };
	for (size_t i = 0; i < sizeof(WORDS) / sizeof(WORDS[0]); ++i)
		if (Meter == WORDS[i].Word)
			Meter = WORDS[i].Meter;
	int Top = 0, Bottom = 0;
	{
		// "6/8": two numbers and a slash between them, nothing else
		const size_t Slash = Meter.find('/');
		const std::string A = Slash == std::string::npos ? std::string() : Trim(Meter.substr(0, Slash));
		const std::string B = Slash == std::string::npos ? std::string() : Trim(Meter.substr(Slash + 1));
		if (!A.empty() && A.size() <= 2 && A.find_first_not_of("0123456789") == std::string::npos &&
			!B.empty() && B.size() <= 2 && B.find_first_not_of("0123456789") == std::string::npos) {
			Top = std::atoi(A.c_str());
			Bottom = std::atoi(B.c_str());
		}
	}
	if (Top < 1 || Top > 16 || (Bottom != 2 && Bottom != 4 && Bottom != 8))
		throw Problem("meter: like \"4/4\", \"3/4\", \"2/4\", \"6/8\", \"12/8\" or \"5/4\" (1-16 beats over 2, 4 or 8), or waltz, "
			"march or jig.");
	Meter = Format("%d/%d", Top, Bottom);
	// The beat: a quarter (a half in x/2); in 6/8, 9/8 and 12/8 a dotted quarter of three eighths; in other x/8 an eighth
	const bool Compound = Bottom == 8 && Top >= 6 && Top % 3 == 0;
	const int Beats = Compound ? Top / 3 : Top;
	const int Current = S.Time.RowsPerBeat;
	int Default;
	if (Compound)
		Default = Current >= 3 && Current <= 12 && Current % 3 == 0 ? Current : 6;
	else if (Bottom == 8)
		Default = 2;
	else if (Bottom == 2)
		Default = 8;
	else
		Default = Current >= 2 && Current <= 12 ? Current : 4;
	const int RowsPerBeat = IntArg(Args, "rows_per_beat", Default, 1, 32);
	if (Compound && RowsPerBeat % 3 != 0)
		throw Problem(Format("In %s a beat is three eighths: rows_per_beat 3, 6, 9 or 12 puts each eighth on a row.", Meter.c_str()));
	const int RowsPerBar = Beats * RowsPerBeat;
	if (RowsPerBar > 256)
		throw Problem("That bar is longer than a pattern can be (256 rows): give fewer rows_per_beat.");

	// A track with notes keeps its patterns, so its bars have to divide them; one without gets patterns of whole bars
	bool Notes = false;
	for (int c = 0; c < S.ChannelCount() && !Notes; ++c)
		Notes = !S.Notes(c).empty();
	int Length = S.Time.PatternLength;
	if (Notes) {
		if (Arg(Args, "bars_per_frame") != 0)
			throw Problem("The track has notes, so its patterns stay as long as they are: bars_per_frame is for a track without "
				"notes.");
		if (Length % RowsPerBar != 0)
			throw Problem(Format("The track has notes in patterns of %d rows, which bars of %d rows (%s at %d rows a beat) don't "
				"divide: its bars would run across frames. Set the meter before writing the notes (on a new song, or on a track of its "
				"own with select_track), or give rows_per_beat so a bar divides %d rows.", Length, RowsPerBar, Meter.c_str(),
				RowsPerBeat, Length));
	}
	else {
		int Bars = IntArg(Args, "bars_per_frame", 4, 1, 64);
		while (Bars > 1 && Bars * RowsPerBar > 256)
			--Bars;
		Length = Bars * RowsPerBar;
	}
	if (RowsPerBeat == S.Time.RowsPerBeat && RowsPerBar == S.Time.RowsPerBar && Length == S.Time.PatternLength)
		return Format("The song is in %s already: %d rows a beat, %d a bar, %d bars to a frame.", Meter.c_str(), RowsPerBeat, RowsPerBar,
			Length / RowsPerBar);
	std::string Why, Error;
	if (!S.Host().CanChange(Why))
		throw Problem(Why);
	if (!S.Host().SetMeter(RowsPerBeat, RowsPerBar, Length == S.Time.PatternLength ? 0 : Length, Error))
		throw Problem(Error.empty() ? "The meter couldn't be set." : Error);
	const int OldLength = S.Time.PatternLength;
	S.Load();
	std::string Beat = Compound ? Format("a dotted quarter of three eighths, %d rows (an eighth is %s)", RowsPerBeat,
		Plural(RowsPerBeat / 3, "row", "rows").c_str()) :
		Bottom == 8 ? Format("an eighth, %s", Plural(RowsPerBeat, "row", "rows").c_str()) :
		Format("a %s, %s", Bottom == 2 ? "half note" : "quarter note", Plural(RowsPerBeat, "row", "rows").c_str());
	std::string Text = Format("The song is in %s now: %s a bar, each beat %s; %d rows a bar (FamiTracker's row highlights %d and %d)",
		Meter.c_str(), Plural(Beats, "beat", "beats").c_str(), Beat.c_str(), RowsPerBar, RowsPerBeat, RowsPerBar);
	if (Length != OldLength)
		Text += Format(", %s to a frame (patterns of %d rows, were %d)", Plural(Length / RowsPerBar, "bar", "bars").c_str(), Length,
			OldLength);
	else
		Text += Format(", %s to a frame", Plural(Length / RowsPerBar, "bar", "bars").c_str());
	Text += ". Every tool counts bars and beats this way now";
	if (Compound)
		Text += Format(" (in write_notes the eighths of beat 1 are beats 1, %s and %s)", FormatNumber(1.0 + 1.0 / 3).c_str(),
			FormatNumber(1.0 + 2.0 / 3).c_str());
	Text += ". At " + TempoText(S, S.Song.Speed, S.Song.Tempo) + " for this beat; set_tempo with bpm picks speed and tempo for "
		"another. One Ctrl+Z undoes it.";
	if (S.Song.Tracks > 1)
		Text += " The row highlights are the module's: its other tracks count their bars in " + Meter + " too.";
	return Text;
}

// Swing

// The speed a row plays at: the last speed command (Fxx under the split
// point) before it in the song's rows, else the track's speed
int SpeedBefore(Session &S, int Row)
{
	for (int r = Row - 1; r >= 0; --r) {
		int Speed = 0;
		for (int c = 0; c < S.ChannelCount(); ++c) {
			const std::vector<Cell> &Cells = S.Cells(c);
			if (r >= static_cast<int>(Cells.size()))
				continue;
			for (int k = 0; k < std::min(EFFECT_COLUMNS, S.Channel(c).EffectColumns); ++k) {
				const int Param = std::max(1, static_cast<int>(Cells[r].Param[k]));
				if (Cells[r].Effect[k] == EFF_SPEED && Param < S.Song.SplitPoint)
					Speed = Param;	// a later channel's wins on its row, as FamiTracker reads them
			}
		}
		if (Speed > 0)
			return Speed;
	}
	return S.Song.Speed;
}

// The speeds of a swing: A for the first of each pair of units, B for the
// second, A + B twice Speed so the beat keeps its length; the pair whose A
// share is nearest Share (A == B == Speed when none is nearer than straight)
void SwingSpeeds(int Speed, int MaxSpeed, double Share, int &A, int &B)
{
	A = B = Speed;
	double Best = std::fabs(Share - 0.5);
	for (int a = Speed + 1; a <= MaxSpeed && 2 * Speed - a >= 1; ++a) {
		const double Miss = std::fabs(Share - static_cast<double>(a) / (2 * Speed));
		if (Miss < Best - 1e-9) {
			Best = Miss;
			A = a;
			B = 2 * Speed - a;
		}
	}
}

// A swing made with note delays (Gxx) on some channels only: each note that
// falls on the second unit of a pair (an eighth's "and", or a sixteenth's)
// starts late by the ticks the swing asks for at the row's speed, as
// FamiTracker composers shuffle a busy part while the rest plays straight.
// Share 0.5 takes the delays off those rows.
std::string SwingByDelays(Session &S, const Json &Args, double Share, int Parts, int First, int End, int From, int To)
{
	const int R = S.Time.RowsPerBeat, Unit = R / Parts;
	std::vector<int> Channels;
	if (Arg(Args, "channels") != 0)
		Channels = ChannelsArg(S, Args, "channels");
	else
		for (int c = 0; c < S.ChannelCount(); ++c)
			if (HasNotesIn(S, c, First, End))
				Channels.push_back(c);
	if (Channels.empty())
		throw Problem("No channel plays in those bars to swing.");
	// The speed of each row, as the song's speed commands set it
	std::vector<int> Speeds(static_cast<size_t>(End), S.Song.Speed);
	int Speed = S.Song.Speed;
	for (int r = 0; r < End; ++r) {
		for (int c = 0; c < S.ChannelCount(); ++c) {
			const std::vector<Cell> &Cells = S.Cells(c);
			if (r < static_cast<int>(Cells.size()))
				for (int k = 0; k < std::min(EFFECT_COLUMNS, S.Channel(c).EffectColumns); ++k)
					if (Cells[r].Effect[k] == EFF_SPEED && std::max(1, static_cast<int>(Cells[r].Param[k])) < S.Song.SplitPoint)
						Speed = std::max(1, static_cast<int>(Cells[r].Param[k]));
		}
		Speeds[static_cast<size_t>(r)] = Speed;
	}
	Draft D(S);
	int Delayed = 0, Lost = 0, Low = 99, High = 0;
	for (size_t i = 0; i < Channels.size(); ++i) {
		const int c = Channels[i];
		std::vector<Cell> &Cells = D.Cells(c);
		const int Columns = S.Channel(c).EffectColumns;
		for (int r = First; r < End && r < static_cast<int>(Cells.size()); ++r) {
			const int InBeat = (r - S.Time.BarStart(S.Time.BarOf(r))) % R;
			if (InBeat % (2 * Unit) != Unit)
				continue;	// not the second unit of a pair
			Cell &C = Cells[static_cast<size_t>(r)];
			for (int k = 0; k < EFFECT_COLUMNS; ++k)
				if (C.Effect[k] == EFF_DELAY) {
					C.Effect[k] = EFF_NONE;
					C.Param[k] = 0;
				}
			if (Share <= 0.5 || C.Note == NOTE_NONE)
				continue;
			const int Ticks = Speeds[static_cast<size_t>(r)];
			const int Delay = std::min(Ticks - 1, static_cast<int>(std::floor((2.0 * Share - 1.0) * Unit * Ticks + 0.5)));
			if (Delay < 1)
				continue;
			if (!AddEffect(C, EFF_DELAY, Delay, Columns)) {
				++Lost;
				continue;
			}
			Low = std::min(Low, Delay);
			High = std::max(High, Delay);
			++Delayed;
		}
	}
	std::vector<Change> Changes;
	std::vector<std::string> Warnings;
	if (Lost > 0)
		Warnings.push_back(Format("%s had no free effect column for the delay (all four were full).",
			Plural(Lost, "note", "notes").c_str()));
	int Start = First;
	std::string Names;
	for (size_t i = 0; i < Channels.size(); ++i)
		Names += (i == 0 ? "" : i + 1 == Channels.size() ? " and " : ", ") + S.Channel(Channels[i]).FullName();
	const std::string Where = RangeText(From, To);
	if (!D.Collect(First, true, Changes, Start, Warnings))
		return Share <= 0.5 ? "No delays to take off there, " + Where + "." :
			(Delayed == 0 ? "Nothing to delay there: no notes fall on the second " + std::string(Parts == 2 ? "eighth" : "sixteenth") +
			" of a pair, or the rows are too short for a delay, " + Where + "." : "It swings that way there already, " + Where + ".");
	std::string What;
	if (Share <= 0.5)
		What = Format("the delays of a swing taken off %s, %s", Names.c_str(), Where.c_str());
	else
		What = Format("a %d%% swing on the %s of %s, %s, by delays: %s late by %s (G%02X%s)",
			static_cast<int>(std::floor(100.0 * Share + 0.5)), Parts == 2 ? "eighths" : "sixteenths", Names.c_str(), Where.c_str(),
			Plural(Delayed, "note", "notes").c_str(), Low == High ? Plural(Low, "frame", "frames").c_str() :
			Format("%d-%d frames", Low, High).c_str(), Low, Low == High ? "" : Format("-G%02X", High).c_str());
	std::string Text = Commit(S, Changes, Start, false, "", What);
	if (Share > 0.5)
		Text += " The other channels play straight; set_swing without by swings them all with the speed.";
	return WithRemarks(S, Text, Warnings);
}

std::string SetSwingTool(Session &S, const Json &Args)
{
	if (!S.Song.DirectChanges)
		throw Problem("Swing changes the song's speed every half beat, which needs direct changes; the user can allow them in "
			"File > Connect Claude Code.");
	// How much: the long unit's share of each pair
	double Share = 0.5;
	bool Light = false;	// at most a lilt: never more than 61%, nor a triplet shuffle where the speed allows nothing in between
	const Json *pAmount = Arg(Args, "amount");
	if (pAmount == 0)
		throw Problem("Give amount: none, light, medium, hard (triplet), or a percentage from 50 (straight) to 75.");
	if (pAmount->IsNumber())
		Share = NumberArg(Args, "amount", 50.0, 50.0, 80.0) / 100.0;
	else {
		const std::string Word = Squeezed(StringArg(Args, "amount"));
		// A percentage in words: "61" or "61%"
		char *pAfter = 0;
		const double Percent = std::strtod(Word.c_str(), &pAfter);
		const bool Number = !Word.empty() && pAfter != Word.c_str() && (*pAfter == 0 || std::string(pAfter) == "%");
		if (Number && (Percent < 50.0 || Percent > 80.0))
			throw Problem("amount: a percentage from 50 (straight) to 75 (a hard shuffle), or none, light, medium or hard.");
		if (Number)
			Share = Percent / 100.0;
		else if (Word == "none" || Word == "straight" || Word == "off" || Word == "even")
			Share = 0.5;
		else if (Word == "light" || Word == "subtle" || Word == "gentle" || Word == "lazy") {
			Share = 0.57;	// a lilt: 56% at speeds 8 and 9, 58% at 6 and 12
			Light = true;
		}
		else if (Word == "medium" || Word == "normal")
			Share = 0.625;
		else if (Word == "hard" || Word == "triplet" || Word == "triplets" || Word == "shuffle" || Word == "heavy" || Word == "full")
			Share = 2.0 / 3.0;
		else
			throw Problem("amount: none, light, medium, hard (triplet), or a percentage from 50 (straight) to 75.");
	}
	const std::string UnitWord = Squeezed(StringArg(Args, "unit", "eighths"));
	const int R = S.Time.RowsPerBeat;
	int Parts;
	if (UnitWord == "eighths" || UnitWord == "eighth" || UnitWord == "8ths" || UnitWord == "halfbeats")
		Parts = 2;
	else if (UnitWord == "sixteenths" || UnitWord == "sixteenth" || UnitWord == "16ths" || UnitWord == "quarterbeats")
		Parts = 4;
	else
		throw Problem("unit: eighths (half beats, the usual swing) or sixteenths (quarter beats).");
	if (R % Parts != 0)
		throw Problem(Format("A beat here is %s, which doesn't split into %s; swing needs beats that do (row highlight %d is %d "
			"rows a beat).", Plural(R, "row", "rows").c_str(), Parts == 2 ? "halves" : "quarters", R, R));
	const int Unit = R / Parts;
	int From = 1, To = S.Time.BarCount();
	if (RangeGiven(Args))
		BarRange(S, Args, From, To);
	const int First = S.Time.BarStart(From), End = std::min(S.Time.TotalRows(), S.Time.BarEnd(To));
	const int Split = S.Song.SplitPoint;
	const std::string By = Squeezed(StringArg(Args, "by", "speed"));
	if (By == "delays" || By == "delay" || By == "gxx" || By == "notedelays")
		return SwingByDelays(S, Args, Share, Parts, First, End, From, To);
	if (By != "speed" && By != "speeds" && By != "fxx")
		throw Problem("by: speed (every channel swings, by speed changes) or delays (only the channels named, by note delays).");

	// The speed the rows play at on average there now (a swing there comes out as its middle)
	long long Ticks = 0;
	{
		int Speed = SpeedBefore(S, First);
		std::vector<int> Set(static_cast<size_t>(End - First), 0);
		for (int c = 0; c < S.ChannelCount(); ++c) {
			const std::vector<Cell> &Cells = S.Cells(c);
			for (int r = First; r < End && r < static_cast<int>(Cells.size()); ++r)
				for (int k = 0; k < std::min(EFFECT_COLUMNS, S.Channel(c).EffectColumns); ++k)
					if (Cells[r].Effect[k] == EFF_SPEED && std::max(1, static_cast<int>(Cells[r].Param[k])) < Split)
						Set[static_cast<size_t>(r - First)] = std::max(1, static_cast<int>(Cells[r].Param[k]));
		}
		for (int r = First; r < End; ++r) {
			if (Set[static_cast<size_t>(r - First)] != 0)
				Speed = Set[static_cast<size_t>(r - First)];
			Ticks += Speed;
		}
	}
	const int Base = std::max(1, static_cast<int>((Ticks + (End - First) / 2) / std::max(1, End - First)));
	int A, B;
	SwingSpeeds(Base, std::min(31, Split - 1), Share, A, B);
	if (Light && A > B && static_cast<double>(A) / (A + B) > 0.61)
		A = B = Base;
	std::string Fits;	// the swings the speed's ticks allow
	for (int a = Base + 1; a <= std::min(31, Split - 1) && 2 * Base - a >= 1; ++a)
		Fits += (Fits.empty() ? "" : ", ") + Format("%d%%", static_cast<int>(std::floor(100.0 * a / (2 * Base) + 0.5)));
	if (A == B && Share > 0.5)
		throw Problem(Fits.empty() ? Format("At speed %d a beat can't swing: its rows have too few ticks to split unevenly. A higher "
			"speed (with a higher tempo to keep the BPM) can.", Base) :
			Format("At speed %d a beat can't swing that little; the swings that fit are %s.", Base, Fits.c_str()));
	const int After = End < S.Time.TotalRows() ? SpeedBefore(S, End + 1) : -1;	// what plays after the bars, as it was

	// The speed commands there go; the swing's come in, on the channel that has
	// the song's speed commands (else the last one), or another with room
	int Home = S.ChannelCount() - 1;
	for (int c = S.ChannelCount() - 1; c >= 0; --c) {
		bool Has = false;
		for (size_t r = 0; r < S.Cells(c).size() && !Has; ++r)
			for (int k = 0; k < std::min(EFFECT_COLUMNS, S.Channel(c).EffectColumns); ++k)
				Has = Has || S.Cells(c)[r].Effect[k] == EFF_SPEED;
		if (Has) {
			Home = c;
			break;
		}
	}
	Draft D(S);
	int Removed = 0, Lost = 0;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		std::vector<Cell> &Cells = D.Cells(c);
		for (int r = First; r < End && r < static_cast<int>(Cells.size()); ++r)
			for (int k = 0; k < EFFECT_COLUMNS; ++k)
				if (Cells[r].Effect[k] == EFF_SPEED && std::max(1, static_cast<int>(Cells[r].Param[k])) < Split) {
					Cells[r].Effect[k] = EFF_NONE;
					Cells[r].Param[k] = 0;
					++Removed;
				}
	}
	auto Put = [&](int Row, int Speed) {
		if (!PutSongEffect(S, D, Home, Row, EFF_SPEED, Speed))
			++Lost;	// a tempo command there stays beside it
	};
	int Written = 0;
	if (A != B) {
		for (int r = First; r < End; ++r) {
			const int Bar = S.Time.BarOf(r), InBar = r - S.Time.BarStart(Bar);
			if ((InBar % R) % Unit != 0)
				continue;
			Put(r, ((InBar % R) / Unit) % 2 == 0 ? A : B);
			++Written;
		}
	}
	else if (SpeedBefore(S, First) != Base) {
		Put(First, Base);
		++Written;
	}
	if (After > 0) {
		// The rows after play at the speed they did
		bool Own = false;
		for (int c = 0; c < S.ChannelCount(); ++c)
			for (int k = 0; k < EFFECT_COLUMNS; ++k)
				Own = Own || (D.Cells(c)[static_cast<size_t>(End)].Effect[k] == EFF_SPEED &&
					std::max(1, static_cast<int>(D.Cells(c)[static_cast<size_t>(End)].Param[k])) < Split);
		if (!Own && (A != B ? B : Base) != After)
			Put(End, After);
	}
	if (Lost > 0)
		throw Problem(Format("%s had no free effect column for the swing's speed changes (all four were full; on %s, say).", Plural(Lost, "row", "rows").c_str(), S.Channel(Home).FullName().c_str()));
	std::vector<Change> Changes;
	std::vector<std::string> Warnings;
	int Start = First;
	const std::string Where = RangeText(From, To);
	if (!D.Collect(First, true, Changes, Start, Warnings))
		return A == B ? "The song plays straight there already (no swing), " + Where + "." :
			Format("The song swings that way there already (F%02X and F%02X), %s.", A, B, Where.c_str());
	std::string What;
	if (A == B)
		What = Format("swing taken off, %s: straight at speed %d", Where.c_str(), Base);
	else
		What = Format("a %d%% swing on the %s, %s: speed %d then %d (F%02X, F%02X) in turn, which averages the speed it had (%d), "
			"so the tempo stays", static_cast<int>(std::floor(100.0 * A / (A + B) + 0.5)), Parts == 2 ? "eighths" : "sixteenths",
			Where.c_str(), A, B, A, B, Base);
	std::string Text = Commit(S, Changes, Start, false, "", What);
	if (A != B && std::fabs(static_cast<double>(A) / (A + B) - Share) > 0.03)
		Text += Format(" At speed %d the swings that fit are %s; a higher speed (with a higher tempo to keep the BPM) splits "
			"the beat finer.", Base, Fits.c_str());
	if (Removed > Written && A != B)
		Warnings.push_back(Format("%s there went for the swing's.", Plural(Removed, "speed change", "speed changes").c_str()));
	return WithRemarks(S, Text, Warnings);
}

int FreeChannel(Session &S, int First, int End, int Avoid, bool (*Fits)(const ChannelInfo &))
{
	for (int Pass = 0; Pass < 2; ++Pass) {
		for (int c = 0; c < S.ChannelCount(); ++c) {
			if (c == Avoid || !Fits(S.Channel(c)))
				continue;
			if (Pass == 1 || !HasNotesIn(S, c, First, End))
				return Pass == 0 ? c : -1 - c;	// -1 - c: taken, but the only kind there is
		}
	}
	return -1000;
}

bool IsChordChannel(const ChannelInfo &Channel)
{
	return (Channel.Kind == KIND_PULSE && (Channel.Chip == "2A03" || Channel.Chip == "VRC6" || Channel.Chip == "MMC5")) ||
		Channel.Kind == KIND_FM || Channel.Kind == KIND_SQUARE;
}

// A channel for lush chords: a pulse or 5B square whose instruments can have arpeggios
bool IsLushChordChannel(const ChannelInfo &Channel)
{
	return (Channel.Kind == KIND_PULSE && (Channel.Chip == "2A03" || Channel.Chip == "VRC6" || Channel.Chip == "MMC5")) ||
		Channel.Kind == KIND_SQUARE;
}

// The kinds of channel that voice chords together, in the order they're tried: the VRC7's, the
// N163's, the 5B's, then the pulses
const int CHORD_GROUPS = 4;

bool InChordGroup(const ChannelInfo &Info, int Group)
{
	switch (Group) {
	case 0: return Info.Kind == KIND_FM;
	case 1: return Info.Chip == "N163";
	case 2: return Info.Kind == KIND_SQUARE;
	default: return Info.Kind == KIND_PULSE && IsLushChordChannel(Info);
	}
}

bool IsBassChannel(const ChannelInfo &Channel)
{
	return IsBass(Channel);
}

int EchoDelayOf(Session &S, int Channel, int Source, int First, int End);

// The parts a song already plays in [First, End), which new chords and a new
// bass line there replace rather than stack on

// The chord part: the channel beside the melody with the most notes there that
// sound a chord (a lush or arpeggio instrument, or 0xy); -1 if none
int ChordPartIn(Session &S, int First, int End, int Melody)
{
	int Best = -1, BestCount = 0;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (c == Melody || !IsMelodic(S.Channel(c)) || IsBass(S.Channel(c)))
			continue;
		int Count = 0;
		const std::vector<NoteInfo> &Notes = S.Notes(c);
		for (size_t i = 0; i < Notes.size(); ++i)
			if (Notes[i].Row >= First && Notes[i].Row < End && SoundsChord(S, Notes[i]))
				++Count;
		if (Count > BestCount) {
			Best = c;
			BestCount = Count;
		}
	}
	return Best;
}

// The bass line: the triangle or sawtooth beside the melody with the most notes there; -1 if none
int BassPartIn(Session &S, int First, int End, int Melody)
{
	int Best = -1, BestCount = 0;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (c == Melody || !IsBass(S.Channel(c)))
			continue;
		const int Count = static_cast<int>(NotesIn(S.Notes(c), First, End).size());
		if (Count > BestCount) {
			Best = c;
			BestCount = Count;
		}
	}
	return Best;
}

// The instrument most of Notes play
int UsualInstrument(const std::vector<NoteInfo> &Notes)
{
	std::map<int, int> Count;
	int Best = NO_INSTRUMENT, BestCount = 0;
	for (size_t i = 0; i < Notes.size(); ++i) {
		const int n = ++Count[Notes[i].Instrument];
		if (n > BestCount) {
			Best = Notes[i].Instrument;
			BestCount = n;
		}
	}
	return Best;
}

// Voiced chords: two to four channels of one kind (FM, N163, 5B or pulses) beside
// the melody, not an echo of it, whose notes there mostly start together; empty if none
std::vector<int> ChordVoicesIn(Session &S, int First, int End, int Melody)
{
	for (int Group = 0; Group < CHORD_GROUPS; ++Group) {
		std::vector<int> Channels;
		std::vector<std::set<int> > Starts;
		for (int c = 0; c < S.ChannelCount(); ++c) {
			const ChannelInfo &Info = S.Channel(c);
			const bool Fits = InChordGroup(Info, Group);
			if (!Fits || c == Melody || (Melody >= 0 && EchoDelayOf(S, c, Melody, First, End) > 0))
				continue;
			const std::vector<NoteInfo> Notes = NotesIn(S.Notes(c), First, End);
			if (Notes.size() < 2)
				continue;
			std::set<int> Rows;
			for (size_t i = 0; i < Notes.size(); ++i)
				Rows.insert(Notes[i].Row);
			Channels.push_back(c);
			Starts.push_back(Rows);
		}
		// The channels that start most of their notes with another's
		std::vector<int> Voices;
		for (size_t a = 0; a < Channels.size(); ++a) {
			bool Together = false;
			for (size_t b = 0; b < Channels.size() && !Together; ++b) {
				if (a == b)
					continue;
				int Shared = 0;
				for (std::set<int>::const_iterator it = Starts[a].begin(); it != Starts[a].end(); ++it)
					Shared += Starts[b].count(*it) > 0 ? 1 : 0;
				Together = Shared * 10 >= static_cast<int>(Starts[a].size()) * 7;
			}
			if (Together && Voices.size() < 4)
				Voices.push_back(Channels[a]);
		}
		if (Voices.size() >= 2)
			return Voices;
	}
	return std::vector<int>();
}

// Arranging: chords in a style, bass lines, drums, harmony and counter-melodies

std::vector<BarSpan> BarSpans(const std::vector<transcribe::Bar> &Bars)
{
	std::vector<BarSpan> Out;
	for (size_t i = 0; i < Bars.size(); ++i)
		Out.push_back(BarSpan(Bars[i].row, Bars[i].length));
	return Out;
}

std::vector<BarSpan> SongBarSpans(const Session &S, int First, int End)
{
	return BarSpans(transcribe::SongBars(First, End, S.Time.PatternLength, S.Time.RowsPerBar));
}

// The harmony code's chords (triads), to arrange
std::vector<ChordAt> ChordsOf(const std::vector<transcribe::ChordSpan> &Spans)
{
	std::vector<ChordAt> Out;
	for (size_t i = 0; i < Spans.size(); ++i) {
		ChordAt A;
		A.Row = Spans[i].row;
		A.Rows = Spans[i].length;
		const transcribe::Chord &C = Spans[i].chord;
		std::vector<int> Tones;
		Tones.push_back(C.quality == transcribe::Chord::Major ? 4 : 3);
		Tones.push_back(C.quality == transcribe::Chord::Diminished ? 6 : 7);
		A.C = Chord(C.root, Tones);
		Out.push_back(A);
	}
	return Out;
}

// A style named by an argument, or Default
int StyleArg(const Json &Args, const char *Name, const std::vector<StyleInfo> &Styles, int Default)
{
	const std::string Text = StringArg(Args, Name);
	if (Text.empty())
		return Default;
	const int Index = FindStyle(Styles, Text);
	if (Index < 0) {
		std::string Names;
		for (size_t i = 0; i < Styles.size(); ++i)
			Names += (i == 0 ? "" : ", ") + std::string(Styles[i].Name);
		throw Problem(std::string(Name) + ": \"" + Text + "\" isn't one. Choose from " + Names + ".");
	}
	return Index;
}

// A progression from an argument: text with bar lines ("| C | Am7 | F G |"),
// chords a bar each without them ("C Am F G", "I-vi-IV-V"), or a list of bars
std::vector<std::string> ProgressionArg(const Json &Args, const char *Name)
{
	const Json *pValue = Arg(Args, Name);
	std::vector<std::string> Bars;
	if (pValue == 0)
		return Bars;
	if (pValue->IsString())
		Bars = SplitProgression(pValue->String());
	else if (pValue->IsArray()) {
		for (size_t i = 0; i < pValue->Size(); ++i) {
			const Json &Item = pValue->At(i);
			if (!Item.IsString())
				throw Problem(std::string(Name) + ": each bar is text, like \"Am7\" or \"F G7\".");
			const std::string Text = Trim(Item.String());
			if (Text.find('|') != std::string::npos) {
				const std::vector<std::string> Split = SplitProgression(Text);
				Bars.insert(Bars.end(), Split.begin(), Split.end());
			}
			else
				Bars.push_back(Text.empty() ? "." : Text);
		}
	}
	else
		throw Problem(std::string(Name) + " should be text like \"| C | Am7 | F G7 | C |\" or a list of bars like [\"C\", \"Am7\", \"F G7\", \"C\"].");
	if (Bars.empty())
		throw Problem(std::string(Name) + " has no chords in it.");
	return Bars;
}

// Where chords go on a channel: their lowest notes about an octave and a
// half under the melody's middle (a rolling pattern spreads two octaves up,
// so it starts lower), as both sound (Lifted: how far over its sound the
// melody's channel writes a note)
void ChordRegister(ChordPartOptions &O, const ChannelInfo &Info, const std::vector<NoteInfo> &Melody, int Lifted)
{
	int Top = Melody.empty() ? 43 : MiddleOf(Melody, 52) - Lifted - 7;
	Top = std::max(36, std::min(48, Top));
	if (O.Style == CHORDS_BROKEN && O.Pattern == BROKEN_ROLLING)
		Top -= 5;
	else if (O.Style == CHORDS_LUSH)
		Top -= O.Pattern == BROKEN_ROLLING ? 7 : 3;	// the arpeggio climbs an octave and more above its root
	O.High = Written(Info, Top);
	O.Low = O.High - 12;
	// A pulse's (or the 5B's square's) broken chords stay over C-2, however low the room the melody leaves them: under it
	// a ripple turns to mud
	if (O.Style == CHORDS_BROKEN && (Info.Kind == KIND_PULSE || Info.Kind == KIND_SQUARE))
		O.Lowest = Written(Info, PULSE_BROKEN_FLOOR);
}

// A bass line's register: C-1 to G-2 as a pulse or the sawtooth plays them,
// written an octave up on the triangle, where it sounds the same
void BassRegister(BassOptions &O, const ChannelInfo &Info)
{
	O.Low = Written(Info, 9);
	O.High = Written(Info, 28);
}

// Drum hits as notes, each ringing until the next, with their instruments
// (added from the presets) and volumes scaled to Loudest from the groove's
// own loudest (Designed: GrooveLoudest)
std::vector<PartNote> DrumNotes(Session &S, int Channel, const std::vector<DrumHit> &Hits, int First, int End, int Loudest, int Designed)
{
	std::map<std::string, int> Instruments;
	std::vector<PartNote> Notes;
	for (size_t i = 0; i < Hits.size(); ++i) {
		const DrumHit &H = Hits[i];
		if (Instruments.find(H.Sound) == Instruments.end())
			Instruments[H.Sound] = ResolveInstrument(S, H.Sound, Channel);
		PartNote N;
		N.Row = H.Row;
		N.Rows = (i + 1 < Hits.size() ? Hits[i + 1].Row : End) - H.Row;
		N.Pitch = H.Pitch;
		N.Instrument = Instruments[H.Sound];
		N.Volume = std::max(1, std::min(15, (H.Volume * Loudest + Designed / 2) / std::max(1, Designed)));
		Notes.push_back(N);
	}
	TidyPart(Notes, First, End);
	return Notes;
}

// The drum kit asked for: the noise channel's (false), or sampled kick, snare
// and toms (true)
bool SampledKitArg(const Json &Args)
{
	const std::string Kit = Squeezed(StringArg(Args, "kit", "noise"));
	if (Kit == "noise" || Kit == "synth" || Kit == "noisechannel")
		return false;
	if (Kit == "samples" || Kit == "sampled" || Kit == "sample" || Kit == "dpcm" || Kit == "sampledrums")
		return true;
	throw Problem("kit: noise (every drum on the noise channel) or samples (a sampled kick, snare and toms on the DPCM channel).");
}

// The song's DPCM channel, for sampled drums
int DpcmChannel(Session &S)
{
	for (int c = 0; c < S.ChannelCount(); ++c)
		if (S.Channel(c).Kind == KIND_DPCM)
			return c;
	throw Problem("The song has no DPCM channel for sampled drums.");
}

// A drum part's changes: the noise channel's hits, and the sampled ones on the
// DPCM channel (Dpcm, -1 for none), which play the kit of add_sample_drums.
// Where says where they went.
void DrumChanges(Session &S, int Noise, int Dpcm, const std::vector<DrumHit> &Hits, int First, int End, int Loudest, bool DirectChange,
	std::vector<Change> &Changes, std::string &Where, std::vector<std::string> &Warnings, int Designed = 15)
{
	std::vector<DrumHit> NoiseHits, Sampled;
	for (size_t i = 0; i < Hits.size(); ++i)
		(Hits[i].Sampled && Dpcm >= 0 ? Sampled : NoiseHits).push_back(Hits[i]);
	Change C;
	C.Channel = Noise;
	BuildPart(S.Cells(Noise), First, End, DrumNotes(S, Noise, NoiseHits, First, End, Loudest, Designed), OptionsFor(S, Noise, DirectChange),
		C.Cells, Warnings);
	Changes.push_back(C);
	Where = " on " + S.Channel(Noise).FullName();
	if (Dpcm < 0 || Sampled.empty())
		return;
	const int Kit = SampleDrumsInstrument(S);
	std::vector<PartNote> Notes;
	for (size_t i = 0; i < Sampled.size(); ++i) {
		const DrumHit &H = Sampled[i];
		const DpcmKey *pKey = FindSampleDrum(H.Sound == "tom" ? (H.Pitch >= 8 ? "high tom" : "low tom") : H.Sound);
		if (pKey == 0)
			continue;
		PartNote N;
		N.Row = H.Row;
		N.Rows = (i + 1 < Sampled.size() ? Sampled[i + 1].Row : End) - H.Row;	// each rings until the next
		N.Pitch = pKey->Pitch;
		N.Instrument = Kit;
		Notes.push_back(N);
	}
	TidyPart(Notes, First, End);
	if (HasNotesIn(S, Dpcm, First, End))
		Warnings.push_back(S.Channel(Dpcm).FullName() + "'s notes in those bars were replaced by the sampled drums.");
	Change D;
	D.Channel = Dpcm;
	BuildPart(S.Cells(Dpcm), First, End, Notes, OptionsFor(S, Dpcm, DirectChange), D.Cells, Warnings);
	Changes.push_back(D);
	// What the samples play: a kick and a snare (their toms in fills), or what a groove without a snare has
	bool Kick = false, Snare = false, Toms = false;
	for (size_t i = 0; i < Sampled.size(); ++i) {
		Kick = Kick || Sampled[i].Sound == "kick";
		Snare = Snare || Sampled[i].Sound == "snare";
		Toms = Toms || Sampled[i].Sound == "tom";
	}
	const std::string What = Kick && Snare ? "sampled kick and snare" : Kick ? (Toms ? "a sampled kick and toms" : "a sampled kick") :
		Snare ? (Toms ? "a sampled snare and toms" : "a sampled snare") : "sampled toms";
	Where = ": " + What + " on " + S.Channel(Dpcm).FullName() + ", hi-hats on " + S.Channel(Noise).FullName();
}

// A lush chord instrument's name: the sound's, the chord's ("maj7", "m9",
// "major"), and the pattern and frames when they aren't the usual ones:
// "Lush maj7", "Pluck m7 down", "Lush m9, 3 frames"
std::string LushName(const Preset &Sound, const std::vector<int> &Notes, int Pattern, int Frames)
{
	std::vector<int> Tones;
	for (size_t i = 0; i < Notes.size(); ++i)
		Tones.push_back((Notes[i] % 12 + 12) % 12);
	std::sort(Tones.begin(), Tones.end());
	Tones.erase(std::unique(Tones.begin(), Tones.end()), Tones.end());
	std::string Quality = ChordName(Chord(0, Tones), Key(0, MODE_MAJOR)).substr(1);
	if (Quality.empty())
		Quality = "major";
	else if (Quality == "m")
		Quality = "minor";
	std::string Name = Sound.Name == "lush chords" ? std::string("lush") : Sound.Name;
	Name += " " + Quality;
	if (Pattern != BROKEN_UP)
		Name += std::string(" ") + BrokenPatterns()[static_cast<size_t>(Pattern)].Name;
	if (Frames != 2)
		Name += Format(", %d frame%s", Frames, Frames == 1 ? "" : "s");
	return Name;
}

// The lush chord instrument for a shape: Sound's with the shape looping as
// its arpeggio, Frames frames a note, named by LushName; added when the song
// has none of that name (its label goes into Added and Count counts it)
int LushInstrument(Session &S, const std::string &Chip, bool Sawtooth, const Preset &Sound, const std::vector<int> &Shape, int Pattern,
	int Frames, std::string &Added, int &Count)
{
	const Preset P = WithArpeggio(Sound, Shape, Frames, LushName(Sound, Shape, Pattern, Frames));
	const size_t Before = S.Song.Instruments.size();
	std::string Error;
	const int Index = S.Host().AddInstrument(P, Chip, Sawtooth, Error);
	if (Index < 0)
		throw Problem(Error.empty() ? "The instrument couldn't be added." : Error);
	S.Refresh();
	if (S.Song.Instruments.size() > Before) {
		Added += (Count == 0 ? "" : ", ") + InstrumentLabel(S.Song, Index);
		++Count;
	}
	return Index;
}

// One of the song's instruments by its name (ignoring case) or its number as the instrument list shows it ("0D"); 0 if none
const InstrumentInfo *SongInstrumentNamed(const Session &S, const std::string &Text)
{
	const std::string Lower = Lowercase(Trim(Text));
	for (size_t i = 0; i < S.Song.Instruments.size(); ++i)
		if (Lowercase(S.Song.Instruments[i].Name) == Lower)
			return &S.Song.Instruments[i];
	char *pEnd = 0;
	const long Index = std::strtol(Lower.c_str(), &pEnd, 16);
	if (!Lower.empty() && Lower.size() <= 2 && *pEnd == 0)
		return FindInstrument(S.Song, static_cast<int>(Index));
	return 0;
}

// One of the song's own instruments as a sound for lush chords on a channel of Chip (2A03, VRC6 or 5B): its volume,
// pitch, hi-pitch and duty sequences as a preset's (each chord then gets its notes as the arpeggio), a 2A03 pulse's width
// the nearest on the VRC6 and back, a 5B instrument on the 5B only. False for a sound lush chords can't be made from (the
// N163's waves, the FDS's, the VRC7's patches, a 5B sound on a pulse).
bool SoundOfInstrument(const InstrumentInfo &I, const std::string &Chip, Preset &Out)
{
	if ((I.Chip != "2A03" && I.Chip != "VRC6" && I.Chip != "5B") || (I.Chip == "5B" && Chip != "5B"))
		return false;
	Out = Preset();
	Out.Name = I.Name;
	Out.Drum = false;
	Out.Vrc7Patch = 0;
	std::vector<PresetSequence> List;
	auto Add = [&](int Type, const std::vector<int> &Items, int Loop, int Release, int Setting) {
		if (Items.empty())
			return;
		PresetSequence Sequence;
		Sequence.Type = Type;
		Sequence.Items = Items;
		Sequence.Loop = Loop;
		Sequence.Release = Release;
		Sequence.Setting = Setting;
		List.push_back(Sequence);
	};
	Add(SEQUENCE_VOLUME, I.Volume, I.VolumeLoop, I.VolumeRelease, 0);
	Add(SEQUENCE_PITCH, I.Pitch.Items, I.Pitch.Loop, I.Pitch.Release, I.Pitch.Setting);
	Add(SEQUENCE_HIPITCH, I.HiPitch.Items, I.HiPitch.Loop, I.HiPitch.Release, I.HiPitch.Setting);
	if (I.Chip == "5B") {
		Add(SEQUENCE_DUTY, I.Mode.Items, I.Mode.Loop, I.Mode.Release, I.Mode.Setting);
		Out.Sequences5B = List;
		return true;
	}
	// The pulse's width on the other pulse chip: the 2A03's 12.5%, 25%, 50% and 75% (25% turned over) as the VRC6's 2/16,
	// 4/16 and 8/16, the VRC6's sixteenths as the nearest of the 2A03's; the 5B's square has none (Preset5BSequences)
	const std::string Home = Chip == "5B" ? std::string("2A03") : Chip;
	std::vector<int> Duty = I.Duty.Items;
	for (size_t i = 0; i < Duty.size() && I.Chip != Home; ++i) {
		static const int TO_VRC6[4] = { 1, 3, 7, 3 };
		Duty[i] = I.Chip == "2A03" ? TO_VRC6[std::max(0, std::min(3, Duty[i]))] : Duty[i] <= 1 ? 0 : Duty[i] <= 4 ? 1 : 2;
	}
	if (Chip != "5B")
		Add(SEQUENCE_DUTY, Duty, I.Duty.Loop, I.Duty.Release, I.Duty.Setting);
	(Home == "VRC6" ? Out.SequencesVRC6 : Out.Sequences2A03) = List;
	return true;
}

// Lush chords' instruments: Sound's (a preset, or one of the song's own
// instruments by name or number) with each chord's notes looping as its
// arpeggio, Frames frames a note, one instrument a chord shape, added when
// first needed and played by the notes with that shape
void LushInstruments(Session &S, int Channel, const std::string &Sound, int Pattern, int Frames, std::vector<PartNote> &Notes)
{
	const std::string Chip = InstrumentChip(S.Channel(Channel));
	const std::string ChannelName = S.Channel(Channel).FullName();
	const bool Sawtooth = S.Channel(Channel).Kind == KIND_SAWTOOTH;
	if (Chip != "2A03" && Chip != "VRC6" && Chip != "5B")
		throw Problem(Format("Lush chords are instruments with arpeggios, which %s can't play; give them a pulse channel "
			"(2A03, MMC5 or VRC6) or a 5B channel, or choose another chord_style.", ChannelName.c_str()));
	const Preset *pSound = Chip == "5B" ? FindSoundFor5B(Sound) : FindPreset(Sound);
	// A preset by its own name; else the song's instrument of that name (a designed one), before a preset a word names
	Preset Own;
	const InstrumentInfo *pOwn = pSound != 0 && Squeezed(pSound->Name) == Squeezed(Sound) ? 0 : SongInstrumentNamed(S, Sound);
	if (pOwn != 0 && SoundOfInstrument(*pOwn, Chip, Own))
		pSound = &Own;
	else if (pOwn != 0)
		throw Problem(Format("Lush chords on %s are made from a 2A03 or VRC6 sound (a 5B one on the 5B); %s is the %s's, so it "
			"can't play them there: name a pulse instrument of the song, or a preset (lush chords, soft chords, pluck, bell...).",
			ChannelName.c_str(), InstrumentLabel(S.Song, pOwn->Index).c_str(), pOwn->Chip.c_str()));
	if (pSound == 0 || pSound->Drum)
		throw Problem(Format("Lush chords are made from a preset's sound (lush chords, soft chords, pluck, bell, warm pad...) or "
			"one of the song's own pulse instruments, by name or number (each chord gets a copy of it playing its notes); \"%s\" "
			"is neither.", Sound.c_str()));
	std::map<std::vector<int>, int> Made;
	std::string Added;
	int Count = 0;
	for (size_t i = 0; i < Notes.size(); ++i) {
		if (Notes[i].Arpeggio.empty())
			continue;
		std::map<std::vector<int>, int>::const_iterator Found = Made.find(Notes[i].Arpeggio);
		if (Found == Made.end())
			Found = Made.insert(std::make_pair(Notes[i].Arpeggio, LushInstrument(S, Chip, Sawtooth, *pSound, Notes[i].Arpeggio, Pattern,
				Frames, Added, Count))).first;
		Notes[i].Instrument = Found->second;
	}
	if (Count > 0)
		S.Remarks.push_back(Format("Added %d lush chord instrument%s (%s, from %s \"%s\"): %s.", Count, Count == 1 ? "" : "s",
			Chip.c_str(), pSound == &Own ? "the song's instrument" : "the preset", pSound->Name.c_str(), Added.c_str()));
}

// A lush chord's instrument's name (LushName) read back: its preset (or the
// song's instrument it was made from, as a sound on Chip, into Own), pattern
// and frames; false for other instruments
bool ParseLushName(const Session &S, const std::string &Chip, const std::string &Name, const Preset *&pSound, Preset &Own, int &Pattern,
	int &Frames)
{
	std::string Rest = Lowercase(Trim(Name));
	Frames = 2;
	const size_t Comma = Rest.rfind(", ");
	if (Comma != std::string::npos) {
		const char *pFrom = Rest.c_str() + Comma + 2;
		char *pAfter = 0;
		const long n = std::strtol(pFrom, &pAfter, 10);
		if (pAfter == pFrom || std::string(pAfter).compare(0, 6, " frame") != 0 || n < 1 || n > 6)
			return false;
		Frames = static_cast<int>(n);
		Rest.erase(Comma);
	}
	Pattern = BROKEN_UP;
	const size_t Space = Rest.rfind(' ');
	if (Space == std::string::npos)
		return false;
	for (size_t p = 0; p < BrokenPatterns().size(); ++p)
		if (p != BROKEN_UP && Rest.compare(Space + 1, std::string::npos, BrokenPatterns()[p].Name) == 0) {
			Pattern = static_cast<int>(p);
			Rest.erase(Space);
			break;
		}
	if (Rest.compare(0, 5, "lush ") == 0 && Rest.size() > 5) {
		pSound = FindPreset("lush chords");
		return pSound != 0;
	}
	const std::vector<Preset> *const LISTS[] = { &Presets(), &Sunsoft5BSounds() };	// a 5B sound's too
	for (size_t l = 0; l < 2; ++l) {
		const std::vector<Preset> &All = *LISTS[l];
		for (size_t i = 0; i < All.size(); ++i) {
			const std::string Prefix = Lowercase(All[i].Name) + " ";
			if (!All[i].Drum && Rest.size() > Prefix.size() && Rest.compare(0, Prefix.size(), Prefix) == 0) {
				pSound = &All[i];
				return true;
			}
		}
	}
	// The song's own instrument it was made from: the longest name it starts with
	const InstrumentInfo *pBest = 0;
	for (size_t i = 0; i < S.Song.Instruments.size(); ++i) {
		const std::string Prefix = Lowercase(S.Song.Instruments[i].Name) + " ";
		if (Rest.size() > Prefix.size() && Rest.compare(0, Prefix.size(), Prefix) == 0 && (pBest == 0 || Prefix.size() > pBest->Name.size() + 1))
			pBest = &S.Song.Instruments[i];
	}
	if (pBest == 0 || !SoundOfInstrument(*pBest, Chip, Own))
		return false;
	pSound = &Own;
	return true;
}

// Lush chords a key change moved (the cells in the draft moved by MapToKey):
// each chord's notes moved as the key moves them, and the chord given the
// lush instrument for its new shape (made when the song has none). How many
// chords changed instruments; Unknown counts those played by arpeggio
// instruments that aren't the lush style's, which keep their shapes.
int RevoiceLushChords(Session &S, Draft &D, int Channel, int First, int End, const Key &FromKey, const Key &ToKey, int &Unknown,
	const KeyMove *pMove)
{
	const std::string Chip = InstrumentChip(S.Channel(Channel));
	if (Chip != "2A03" && Chip != "VRC6" && Chip != "5B")
		return 0;
	const std::vector<Cell> Old = S.Cells(Channel);
	std::vector<Cell> &Cells = D.Cells(Channel);
	const bool Sawtooth = S.Channel(Channel).Kind == KIND_SAWTOOTH;
	int Instrument = StateAt(Old, std::max(0, First), S.Channel(Channel).EffectColumns).Instrument;	// as the song had it
	int Playing = Instrument;	// as the draft has it
	int Changed = 0, Count = 0;
	std::string Added, SoundAdded = "the preset \"lush chords\"";
	for (int r = std::max(0, First); r < End && r < static_cast<int>(Old.size()) && r < static_cast<int>(Cells.size()); ++r) {
		if (Old[r].Instrument != NO_INSTRUMENT && !Old[r].IsEnd())
			Instrument = Old[r].Instrument;
		if (Cells[r].Instrument != NO_INSTRUMENT && !Cells[r].IsEnd())
			Playing = Cells[r].Instrument;
		if (!Old[r].HasNote() || !Cells[r].HasNote())
			continue;
		int Wanted = Instrument;
		const std::vector<int> Above = InstrumentChord(S, Instrument);
		if (!Above.empty()) {
			const int OldRoot = Old[r].Pitch(), NewRoot = Cells[r].Pitch();
			std::vector<int> Tones(1, 0);
			bool Same = true;
			for (size_t a = 0; a < Above.size(); ++a) {
				const int Moved = (pMove != 0 ? (*pMove)(OldRoot + Above[a], r) : MapToKey(OldRoot + Above[a], FromKey, ToKey)) - NewRoot;
				Same = Same && Moved == Above[a];
				Tones.push_back((Moved % 12 + 12) % 12);
			}
			const InstrumentInfo *pInfo = FindInstrument(S.Song, Instrument);
			const Preset *pSound = 0;
			Preset Own;
			int Pattern = BROKEN_UP, Frames = 2;
			if (Same)
				Wanted = Instrument;
			else if (pInfo == 0 || !ParseLushName(S, Chip, pInfo->Name, pSound, Own, Pattern, Frames))
				++Unknown;
			else {
				std::sort(Tones.begin(), Tones.end());
				Tones.erase(std::unique(Tones.begin(), Tones.end()), Tones.end());
				const int Before = Count;
				Wanted = LushInstrument(S, Chip, Sawtooth, *pSound, LushShape(Chord(NewRoot % 12, Tones), Pattern), Pattern, Frames, Added,
					Count);
				if (Count > Before)
					SoundAdded = (pSound == &Own ? "the song's instrument \"" : "the preset \"") + pSound->Name + "\"";
				++Changed;
			}
		}
		if (Wanted != Playing) {
			Cells[r].Instrument = static_cast<unsigned char>(Wanted);
			Playing = Wanted;
		}
	}
	if (Count > 0)
		S.Remarks.push_back(Format("Added %d lush chord instrument%s (%s, from %s): %s.", Count, Count == 1 ? "" : "s",
			Chip.c_str(), SoundAdded.c_str(), Added.c_str()));
	return Changed;
}

// An instrument for a part: the one named by the argument, else the preset
// (which is only added when it's used)
int PartInstrument(Session &S, const Json &Args, const char *Name, int Channel, const char *Preset)
{
	if (Arg(Args, Name) != 0)
		return InstrumentArg(S, Args, Name, Channel, NO_INSTRUMENT);
	return ResolveInstrument(S, Preset, Channel);
}

// An N163 sound made from one of the song's N163 instruments (its waves and sequences as FamiTracker reports them),
// named Name
WaveSound WaveSoundOfInstrument(const InstrumentInfo &I, const std::string &Name)
{
	WaveSound W;
	W.Name = Name;
	W.Description = "a copy of " + I.Name;
	W.Waves = I.Waves;
	auto Add = [&](int Type, const std::vector<int> &Items, int Loop, int Release, int Setting) {
		if (Items.empty())
			return;
		PresetSequence P;
		P.Type = Type;
		P.Items = Items;
		P.Loop = Loop;
		P.Release = Release;
		P.Setting = Setting;
		W.Sequences.push_back(P);
	};
	Add(SEQUENCE_VOLUME, I.Volume, I.VolumeLoop, I.VolumeRelease, 0);
	Add(SEQUENCE_ARPEGGIO, I.Steps.Items, I.Steps.Loop, I.Steps.Release, I.Steps.Setting);
	Add(SEQUENCE_PITCH, I.Pitch.Items, I.Pitch.Loop, I.Pitch.Release, I.Pitch.Setting);
	Add(SEQUENCE_HIPITCH, I.HiPitch.Items, I.HiPitch.Loop, I.HiPitch.Release, I.HiPitch.Setting);
	Add(SEQUENCE_DUTY, I.Duty.Items, I.Duty.Loop, I.Duty.Release, I.Duty.Setting);
	return W;
}

// The instruments the N163 channels but those in Skip play over [First, End) (as the draft has them, when given)
std::set<int> N163SoundsBeside(Session &S, Draft *pD, const std::vector<int> &Skip, int First, int End)
{
	std::set<int> Out;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (S.Channel(c).Chip != "N163" || std::find(Skip.begin(), Skip.end(), c) != Skip.end())
			continue;
		const std::vector<NoteInfo> Notes = pD != 0 ? ReadNotes(pD->View(c), S.Channel(c).EffectColumns) : S.Notes(c);
		for (size_t i = 0; i < Notes.size(); ++i)
			if (Notes[i].Row < End && Notes[i].Row + Notes[i].Rows > First && Notes[i].Volume > 0 && Notes[i].Instrument != NO_INSTRUMENT)
				Out.insert(Notes[i].Instrument);
	}
	return Out;
}

// The name a copy of an N163 sound counts from: "String pad" for "String pad 2"
std::string CopyBase(const std::string &Name)
{
	const size_t Cut = Name.find_last_not_of("0123456789");
	if (Cut != std::string::npos && Cut + 1 < Name.size() && Name[Cut] == ' ')
		return Name.substr(0, Cut);
	return Name;
}

// The N163 keeps each instrument's waves at one place in its memory, and a sound whose wave changes as it plays (a wave
// sequence through several waves) writes them there as each of its notes goes on: two N163 channels playing such a sound
// at once rewrite each other's waves, and one of them plays wrong (the composers of a lively stage gave each channel its
// own sound). An instrument for a part on an N163 channel: Instrument itself, unless Taken (what the other N163 channels
// play there) has it and its sound changes waves; then a copy of it with its waves at a place of their own, "String pad
// 2" (the song's, when it has one Taken hasn't got; else made, as a remark says)
int OwnWaveSound(Session &S, int Instrument, const std::set<int> &Taken)
{
	const InstrumentInfo *pInfo = FindInstrument(S.Song, Instrument);
	if (pInfo == 0 || pInfo->Chip != "N163" || Taken.count(Instrument) == 0 || pInfo->Waves.size() <= 1)
		return Instrument;
	const InstrumentInfo Original = *pInfo;	// adding an instrument reads the song's list again
	if (Original.WaveSize != N163_WAVE_SIZE) {
		S.Remarks.push_back(Format("%s plays on two N163 channels at once, and its waves aren't %d samples, so no copy of it was "
			"made: give one of them another sound (an N163 sound whose wave changes plays on one channel at a time).",
			InstrumentLabel(S.Song, Instrument).c_str(), N163_WAVE_SIZE));
		return Instrument;
	}
	const std::string Base = CopyBase(Original.Name).substr(0, 28);
	for (int n = 2; n <= 9; ++n) {
		const std::string Name = Base + Format(" %d", n);
		const InstrumentInfo *pCopy = 0;
		for (size_t i = 0; i < S.Song.Instruments.size() && pCopy == 0; ++i)
			if (S.Song.Instruments[i].Chip == "N163" && Lowercase(S.Song.Instruments[i].Name) == Lowercase(Name))
				pCopy = &S.Song.Instruments[i];
		if (pCopy != 0) {
			if (Taken.count(pCopy->Index) == 0)
				return pCopy->Index;
			continue;
		}
		std::string Where;
		int Index = NO_INSTRUMENT;
		try {
			Index = AddWaveInstrument(S, WaveSoundOfInstrument(Original, Name), Where);
		}
		catch (const Problem &P) {
			S.Remarks.push_back(Format("%s plays on two N163 channels at once, and no copy of it could be made, so they share it (one "
				"of them plays the other's waves): give one of them another sound. ", InstrumentLabel(S.Song, Original.Index).c_str()) +
				P.Text);
			return Instrument;
		}
		S.Remarks.push_back(Format("Added %s, a copy of %s with its waves at a place of their own (%s): an N163 sound whose wave "
			"changes plays on one channel at a time, since another channel playing it rewrites its waves.",
			InstrumentLabel(S.Song, Index).c_str(), InstrumentLabel(S.Song, Original.Index).c_str(), Where.c_str()));
		return Index;
	}
	return Instrument;
}

// A part's notes on an N163 channel each with a sound of its own there (OwnWaveSound), against the other N163 channels
// over [First, End) (as the draft has them, when given)
void OwnWaveSounds(Session &S, Draft *pD, int Channel, int First, int End, std::vector<PartNote> &Notes)
{
	if (S.Channel(Channel).Chip != "N163")
		return;
	const std::set<int> Taken = N163SoundsBeside(S, pD, std::vector<int>(1, Channel), First, End);
	std::map<int, int> Own;
	for (size_t i = 0; i < Notes.size(); ++i) {
		if (Notes[i].Instrument == NO_INSTRUMENT)
			continue;
		std::map<int, int>::const_iterator it = Own.find(Notes[i].Instrument);
		if (it == Own.end())
			it = Own.insert(std::make_pair(Notes[i].Instrument, OwnWaveSound(S, Notes[i].Instrument, Taken))).first;
		Notes[i].Instrument = it->second;
	}
}

// A voice's sound, for telling voiced chords from a melody over them: its copies ("String pad 2") as it, and the soft
// layer's pads, which voiced chords there play in turn, as one
std::string VoiceSound(const std::string &Name)
{
	const std::string Lower = Lowercase(CopyBase(Name));
	return Lower == "string pad" || Lower == "choir pad" || Lower == "string ensemble" ? std::string("soft pads") : Lower;
}

// Where a long melody note rubs a semitone against chords that were given
void RubWarnings(const Session &S, const std::vector<ChordAt> &Chords, const std::vector<NoteInfo> &Melody, const Key &K,
	std::vector<std::string> &Warnings)
{
	std::string Places;
	int Count = 0;
	for (size_t i = 0; i < Chords.size(); ++i) {
		const ChordAt &A = Chords[i];
		const std::vector<int> Classes = A.C.PitchClasses();
		// A melody note that is itself one of the chord's (the C# of a Dmaj7) is its color, not a rub
		std::vector<NoteInfo> Outside;
		for (size_t m = 0; m < Melody.size(); ++m)
			if (!A.C.HasPitchClass(Melody[m].Pitch % 12))
				Outside.push_back(Melody[m]);
		for (size_t t = 0; t < Classes.size(); ++t) {
			if (MelodyRub(Outside, A.Row, A.Row + A.Rows, Classes[t], S.Time.RowsPerBeat) < 1.0)
				continue;
			if (Count < 4)
				Places += Format("%sbar %d (%s)", Count == 0 ? "" : ", ", S.Time.BarOf(A.Row), ChordName(A.C, K).c_str());
			++Count;
			break;
		}
	}
	if (Count > 0)
		Warnings.push_back("A long melody note rubs a semitone against a chord tone in " + Places + (Count > 4 ? " and more" : "") +
			". Another chord there, or another melody note, would sound cleaner.");
}

// The notes the song's parts other than one (and Also, a part about to be
// written over) play, as pitch classes, with the chords their 0xy arpeggios
// (lasting until a 000, wherever it is) and arpeggio instruments sound
std::vector<HeardNote> HeardNotes(Session &S, int Except, int First, int End, int Also = -1)
{
	std::vector<HeardNote> Out;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (c == Except || c == Also || !IsMelodic(S.Channel(c)))
			continue;
		const bool Bass = IsBass(S.Channel(c));
		const std::vector<NoteInfo> &Notes = S.Notes(c);
		const std::vector<int> Arpeggios = StickyAt(S.Cells(c), Notes, S.Channel(c).EffectColumns, EFF_ARPEGGIO);
		for (size_t i = 0; i < Notes.size(); ++i) {
			const NoteInfo &N = Notes[i];
			const int Arpeggio = Arpeggios[i];
			if (N.Row >= End || N.Row + N.Rows <= First)
				continue;
			HeardNote H;
			H.Row = N.Row;
			H.Rows = N.Rows;
			H.PitchClass = N.Pitch % 12;
			H.Weight = std::max(0.3, N.Volume / 15.0);
			H.Bass = Bass;
			Out.push_back(H);
			const std::vector<int> Above = ChordAbove(S, N, Arpeggio);
			for (size_t a = 0; a < Above.size(); ++a) {
				H.Bass = false;
				H.PitchClass = (N.Pitch + Above[a]) % 12;
				Out.push_back(H);
			}
		}
	}
	return Out;
}

// The chords a part around a melody follows: the ones given (chords), the
// ones the song's other parts play when they cover most of the bars, or
// chords fitted to the melody. Source says which. Target's own notes there,
// which the part replaces, aren't heard (a harmony written again would follow
// its own old notes).
std::vector<ChordAt> ChordsForMelody(Session &S, const Json &Args, int Melody, const std::vector<BarSpan> &Bars, const Key &K,
	std::string &Source, int Target = -1)
{
	std::vector<ChordAt> Chords;
	const std::vector<std::string> Progression = ProgressionArg(Args, "chords");
	if (!Progression.empty()) {
		std::string Error;
		if (!LayOutProgression(Progression, Bars, S.Time.RowsPerBeat, K, Chords, Error))
			throw Problem(Error);
		Source = "the chords given";
		return Chords;
	}
	const int First = Bars.front().Row, End = Bars.back().Row + Bars.back().Rows;
	Chords = HearChords(HeardNotes(S, Melody, First, End, Target), Bars, S.Time.RowsPerBeat, K, true);
	int Covered = 0;
	for (size_t i = 0; i < Chords.size(); ++i)
		Covered += Chords[i].Rows;
	if (Covered * 2 >= End - First) {
		Source = "the chords the other parts play";
		return Chords;
	}
	std::vector<transcribe::MelodyNote> Line = MelodyOf(S.Notes(Melody), First, End);
	std::sort(Line.begin(), Line.end(), [](const transcribe::MelodyNote &a, const transcribe::MelodyNote &b) { return a.row < b.row; });
	std::vector<transcribe::Bar> TBars;
	for (size_t i = 0; i < Bars.size(); ++i) {
		transcribe::Bar B;
		B.row = Bars[i].Row;
		B.length = Bars[i].Rows;
		TBars.push_back(B);
	}
	transcribe::HarmonyOptions Options;
	Options.rowsPerBeat = S.Time.RowsPerBeat;
	Chords = ChordsOf(transcribe::ChooseChords(Line, TBars, HarmonyKey(K), Options));
	Source = "chords fitted to the melody";
	return Chords;
}

std::string AddBackingTool(Session &S, const Json &Args)
{
	const bool AsClip = BoolArg(Args, "as_clip", false);
	const bool DirectChange = Direct(S, AsClip);
	const int R = S.Time.RowsPerBeat;
	const std::vector<std::string> Progression = ProgressionArg(Args, "chords");
	const bool Given = !Progression.empty();
	const int Style = StyleArg(Args, "chord_style", ChordStyles(), CHORDS_ARPEGGIO);
	const int BassStyle = StyleArg(Args, "bass_style", BassStyles(), BASS_ROOT_FIFTH);

	// The melody: the chords are fitted to it, or with chords given it colors
	// them (then only a channel that plays in the bars counts as one)
	const bool Range = RangeGiven(Args);
	int From = 1, To = 1;
	if (Range) {
		BarRange(S, Args, From, To, Given);
		if (Given && Arg(Args, "to_bar") == 0 && Arg(Args, "section") == 0)
			To = std::max(To, std::min(S.MaxBars(), From + static_cast<int>(Progression.size()) - 1));
	}
	int Melody = -1;
	if (Arg(Args, "melody_channel") != 0) {
		Melody = ChannelArg(S, Args, "melody_channel");
		if (!IsMelodic(S.Channel(Melody)))
			throw Problem("The melody channel needs notes, not drums or samples.");
	}
	else {
		const int GuessFrom = Given && Range ? S.Time.BarStart(From) : 0, GuessEnd = Given && Range ? S.Time.BarEnd(To) : S.Time.TotalRows();
		Melody = GuessMelodyChannel(S, GuessFrom, GuessEnd);
		if (Given && Melody >= 0) {
			// Only chords play there (a groove with no melody yet): they're what the new chords replace
			const std::vector<NoteInfo> Notes = NotesIn(S.Notes(Melody), GuessFrom, GuessEnd);
			int Chords = 0;
			for (size_t i = 0; i < Notes.size(); ++i)
				Chords += SoundsChord(S, Notes[i]) ? 1 : 0;
			if (Chords * 3 >= static_cast<int>(Notes.size()))
				Melody = -1;
		}
		if (Melody >= 0) {
			// Nor is the top voice of voiced chords with no melody over them (it plays their sound, on any chip)
			const std::vector<int> Voices = ChordVoicesIn(S, GuessFrom, GuessEnd, -1);
			auto SoundOf = [&](int Channel) {
				const InstrumentInfo *pInfo = FindInstrument(S.Song, UsualInstrument(NotesIn(S.Notes(Channel), GuessFrom, GuessEnd)));
				return pInfo == 0 ? std::string() : VoiceSound(pInfo->Name);
			};
			if (std::find(Voices.begin(), Voices.end(), Melody) != Voices.end()) {
				const std::string Mine = SoundOf(Melody);
				for (size_t v = 0; v < Voices.size() && Melody >= 0; ++v)
					if (Voices[v] != Melody && SoundOf(Voices[v]) == Mine)
						Melody = -1;
			}
		}
	}
	if (Melody < 0 && !Given)
		throw Problem("There's no melody to fit chords to yet. Give chords (like \"| C | Am | F | G |\") to write a backing without one.");

	// The bars: as asked, the melody's, or the progression's from bar 1
	std::vector<transcribe::MelodyNote> Line;
	if (Melody >= 0)
		Line = MelodyOf(S.Notes(Melody), 0, S.Time.TotalRows());
	std::vector<transcribe::Bar> Bars;
	if (Range) {
		Bars = transcribe::SongBars(S.Time.BarStart(From), S.Time.BarEnd(To), S.Time.PatternLength, S.Time.RowsPerBar);
		if (Melody >= 0)
			Line = MelodyOf(S.Notes(Melody), S.Time.BarStart(From), S.Time.BarEnd(To));
	}
	else if (!Line.empty()) {
		Bars = transcribe::MelodyBars(Line, S.Time.PatternLength, S.Time.RowsPerBar);
		// Chords given for more bars than the melody plays: an intro before it, ending with it, when they fit
		if (Given && !Bars.empty() && Progression.size() > Bars.size()) {
			const int MelodyFrom = S.Time.BarOf(Bars.front().row), MelodyTo = S.Time.BarOf(Bars.back().row);
			const int Start = MelodyTo - static_cast<int>(Progression.size()) + 1;
			if (Start >= 1) {
				Bars = transcribe::SongBars(S.Time.BarStart(Start), S.Time.BarEnd(MelodyTo), S.Time.PatternLength, S.Time.RowsPerBar);
				S.Remarks.push_back(Format("The chords are %d bars and the melody plays in bars %d-%d, so they start at bar %d "
					"and end with it (from_bar sets where they start).", static_cast<int>(Progression.size()), MelodyFrom, MelodyTo,
					Start));
			}
			else
				S.Remarks.push_back(Format("The chords are %d bars, more than the melody's %d (bars %d-%d), so the last %d were "
					"left out; from_bar and to_bar set where they go.", static_cast<int>(Progression.size()),
					static_cast<int>(Bars.size()), MelodyFrom, MelodyTo, static_cast<int>(Progression.size() - Bars.size())));
		}
	}
	else {
		const int To = std::min(S.MaxBars(), static_cast<int>(Progression.size()));
		Bars = transcribe::SongBars(0, S.Time.BarEnd(To), S.Time.PatternLength, S.Time.RowsPerBar);
	}
	if (!Given && (Line.empty() || Bars.empty()))
		throw Problem(Format("%s has no notes there to fit chords to.", S.Channel(Melody).FullName().c_str()));
	if (Bars.empty())
		throw Problem("There are no bars there.");
	const int First = Bars.front().row, End = Bars.back().row + Bars.back().length;
	const std::vector<BarSpan> Spans = BarSpans(Bars);

	// The channels: as asked ("none" leaves one out), the ones that play the
	// chords and the bass there already (new ones replace them rather than
	// stack a second part on them), or free ones
	const int OldChords = ChordPartIn(S, First, End, Melody), OldBass = BassPartIn(S, First, End, Melody);
	const std::vector<int> OldVoices = ChordVoicesIn(S, First, End, Melody);
	std::vector<int> Replaced;
	auto Pick = [&](const char *Name, bool (*Fits)(const ChannelInfo &), const char *Kind, int Playing) -> int {
		const Json *pValue = Arg(Args, Name);
		if (pValue != 0 && pValue->IsString() && Lowercase(pValue->String()) == "none")
			return -1;
		if (pValue != 0) {
			const int Channel = ParseChannel(S, *pValue, Name);
			if (!Fits(S.Channel(Channel)) || Channel == Melody)
				throw Problem(Format("%s needs %s other than the melody's.", Name, Kind));
			return Channel;
		}
		if (Playing >= 0 && Fits(S.Channel(Playing))) {
			Replaced.push_back(Playing);
			return Playing;
		}
		const int Free = FreeChannel(S, First, End, Melody, Fits);
		if (Free >= 0)
			return Free;
		if (Free == -1000)
			return -1;	// the song has none
		throw Problem(Format("Every %s already plays in those bars. Name one with %s (its notes there are replaced), or \"none\".",
			Kind, Name));
	};
	// Voiced chords take channels of their own: as asked, or free ones of the chip that plays chords
	// best (the VRC7's FM channels, the N163's, then the pulses)
	std::vector<int> VoiceChannels;
	if (Style == CHORDS_VOICES) {
		const Json *pVoices = Arg(Args, "chord_channels");
		if (pVoices != 0 && !(pVoices->IsString() && Lowercase(pVoices->String()) == "none")) {
			VoiceChannels = ChannelsArg(S, Args, "chord_channels");
			for (size_t i = 0; i < VoiceChannels.size(); ++i) {
				const ChannelInfo &Info = S.Channel(VoiceChannels[i]);
				if (!IsMelodic(Info) || Info.Kind == KIND_TRIANGLE || VoiceChannels[i] == Melody)
					throw Problem(Format("chord_channels: %s can't take a voice of the chords (pick pulses, FM or N163 channels other "
						"than the melody's).", Info.FullName().c_str()));
			}
			if (VoiceChannels.size() < 2 || VoiceChannels.size() > 4)
				throw Problem("chord_channels: voiced chords take 2 to 4 channels.");
		}
		else if (pVoices == 0 && !OldVoices.empty()) {
			VoiceChannels = OldVoices;	// the voices that play there already
			Replaced.insert(Replaced.end(), OldVoices.begin(), OldVoices.end());
		}
		else if (pVoices == 0) {
			// Free channels, or the one whose chords these replace
			for (int Group = 0; Group < CHORD_GROUPS && VoiceChannels.size() < 2; ++Group) {
				VoiceChannels.clear();
				for (int c = 0; c < S.ChannelCount() && VoiceChannels.size() < 3; ++c) {
					const ChannelInfo &Info = S.Channel(c);
					const bool Fits = InChordGroup(Info, Group);
					if (Fits && c != Melody && (c == OldChords || !HasNotesIn(S, c, First, End)))
						VoiceChannels.push_back(c);
				}
			}
			if (OldChords >= 0 && std::find(VoiceChannels.begin(), VoiceChannels.end(), OldChords) != VoiceChannels.end())
				Replaced.push_back(OldChords);
			if (VoiceChannels.size() < 2)
				throw Problem("Voiced chords need two to four free channels; name them with chord_channels (their notes there are "
					"replaced).");
		}
	}
	const int ChordChannel = Style == CHORDS_VOICES ? (VoiceChannels.empty() ? -1 : VoiceChannels[0]) :
		Style == CHORDS_LUSH ? Pick("chord_channel", IsLushChordChannel, "a 2A03, MMC5 or VRC6 pulse channel or a 5B channel", OldChords) :
		Pick("chord_channel", IsChordChannel, "a pulse channel", OldChords);
	const int BassChannel = Pick("bass_channel", IsBassChannel, "the triangle or the sawtooth", OldBass);
	if (ChordChannel < 0 && BassChannel < 0)
		throw Problem("There's no channel for chords or a bass line.");
	std::vector<std::string> Warnings;
	{
		// The old chords that still play under the new ones
		std::vector<int> Old = OldVoices;
		if (OldChords >= 0 && std::find(Old.begin(), Old.end(), OldChords) == Old.end())
			Old.push_back(OldChords);
		std::string Kept;
		int KeptCount = 0;
		for (size_t i = 0; i < Old.size(); ++i) {
			const int c = Old[i];
			const bool Writes = c == ChordChannel || std::find(VoiceChannels.begin(), VoiceChannels.end(), c) != VoiceChannels.end();
			if (Writes || c == BassChannel || (ChordChannel < 0 && VoiceChannels.empty()))
				continue;
			Kept += (Kept.empty() ? "" : ", ") + S.Channel(c).FullName();
			++KeptCount;
		}
		if (!Kept.empty())
			Warnings.push_back(Format("The chords on %s there still play under the new ones; clear %s (write_notes with an empty "
				"list) or name %s as the chord channel to replace them.", Kept.c_str(), KeptCount > 1 ? "them" : "it",
				KeptCount > 1 ? "one of them" : "it"));
	}

	// The key, and the chords
	bool Found;
	Key K = KeyArg(S, Args, "key", First, End, Found);
	if (!Found) {
		if (Given && WrittenAsDegrees(Progression))
			throw Problem("Chords written as degrees (I, vi, V7...) need the key: give key, like \"C major\".");
		K = Key(0, MODE_MAJOR);
	}
	const std::vector<NoteInfo> MelodyNotes = Melody >= 0 ? NotesIn(S.Notes(Melody), First, End) : std::vector<NoteInfo>();
	std::vector<ChordAt> Chords;
	if (Given) {
		std::string Error;
		if (!LayOutProgression(Progression, Spans, R, K, Chords, Error))
			throw Problem(Error);
	}
	else {
		const transcribe::Key HK = HarmonyKey(K);
		transcribe::HarmonyOptions Options;
		Options.rowsPerBeat = R;
		Options.halfBars = BoolArg(Args, "half_bars", true);
		std::sort(Line.begin(), Line.end(), [](const transcribe::MelodyNote &a, const transcribe::MelodyNote &b) { return a.row < b.row; });
		Chords = ChordsOf(transcribe::ChooseChords(Line, Bars, HK, Options));
		if (Chords.empty())
			throw Problem("The melody is too short to fit chords to.");
	}
	chord_color Color;
	if (!ParseColor(StringArg(Args, "color", Style == CHORDS_LUSH || Style == CHORDS_VOICES ? "rich" : "plain"), Color))
		throw Problem("color: plain (triads), sevenths or rich.");
	ColorChords(Chords, MelodyNotes, K, R, Color);
	if (Given && !MelodyNotes.empty())
		RubWarnings(S, Chords, MelodyNotes, K, Warnings);

	// The bass line first: the chords keep over it
	BassOptions BassO;
	std::vector<PartNote> BassNotes;
	if (BassChannel >= 0) {
		BassO.Style = BassStyle;
		BassO.RowsPerBeat = R;
		BassO.K = K;
		BassRegister(BassO, S.Channel(BassChannel));
		BassO.Volume = 15;
		BassNotes = BassPart(Chords, Spans, BassO);
	}
	// The room the chords keep, as the parts sound: under the melody's notes and over the bass's while each chord sounds
	// (ChordPartOptions::Above and Below), voiced under the melody's low notes where it doesn't play
	std::vector<NoteInfo> MelodySounds, BassSounds;
	for (size_t i = 0; i < MelodyNotes.size(); ++i) {
		NoteInfo N = MelodyNotes[i];
		N.Pitch = LandedPitch(N) - Written(S.Channel(Melody), 0);
		MelodySounds.push_back(N);
	}
	for (size_t i = 0; i < BassNotes.size(); ++i) {
		NoteInfo N = NoteInfo();
		N.Row = BassNotes[i].Row;
		N.Rows = BassNotes[i].Rows;
		N.Pitch = BassNotes[i].Pitch - Written(S.Channel(BassChannel), 0);
		BassSounds.push_back(N);
	}
	for (int c = 0; c < S.ChannelCount() && BassChannel < 0; ++c) {
		// Another channel's bass line, which the new chords play over
		const bool Voice = std::find(VoiceChannels.begin(), VoiceChannels.end(), c) != VoiceChannels.end();
		if (c == Melody || c == ChordChannel || Voice || !IsBass(S.Channel(c)))
			continue;
		const std::vector<NoteInfo> Notes = NotesIn(S.Notes(c), First, End);
		for (size_t i = 0; i < Notes.size(); ++i) {
			NoteInfo N = Notes[i];
			N.Pitch -= Written(S.Channel(c), 0);
			BassSounds.push_back(N);
		}
	}
	int UsualLow = -1;	// the melody's low notes, the ones it often dips to (a fifth of its notes are lower)
	if (!MelodySounds.empty()) {
		std::vector<int> Pitches;
		for (size_t i = 0; i < MelodySounds.size(); ++i)
			Pitches.push_back(MelodySounds[i].Pitch);
		std::sort(Pitches.begin(), Pitches.end());
		UsualLow = Pitches[Pitches.size() / 5];
	}
	// The room for a part written at Lift over its sound (Written(channel, 0))
	auto KeepRoom = [&](ChordPartOptions &O, int Lift) {
		O.Above = MelodySounds;
		O.Below = BassSounds;
		for (size_t i = 0; i < O.Above.size(); ++i)
			O.Above[i].Pitch += Lift;
		for (size_t i = 0; i < O.Below.size(); ++i)
			O.Below[i].Pitch += Lift;
		O.Ceiling = UsualLow >= 0 ? std::max(0, UsualLow - CHORD_ROOM + Lift) : -1;
	};

	std::vector<Change> Changes;
	std::string Where;
	if (Style == CHORDS_VOICES && !VoiceChannels.empty()) {
		ChordPartOptions O;
		O.Style = Style;
		O.Rhythm = StyleArg(Args, "rhythm", ChordRhythms(), -1);
		O.RowsPerBeat = R;
		// Under the melody, a voice to a channel: well under its middle, and under the low notes it often dips to,
		// so the top voice doesn't blur it (as they sound: each voice is written for its channel below); each chord then
		// keeps under the melody's lowest note while it sounds and over the bass (KeepRoom)
		const int Lifted = Melody >= 0 ? Written(S.Channel(Melody), 0) : 0;
		int Top = MelodyNotes.empty() ? 50 : MiddleOf(MelodyNotes, 57) - Lifted - 9;
		if (UsualLow >= 0)
			Top = std::min(Top, UsualLow - 4);
		Top = std::max(31, std::min(55, Top));
		O.Low = Top - 10;
		O.High = Top + 3;
		KeepRoom(O, 0);
		O.RootInBass = BassChannel >= 0;
		for (int c = 0; c < S.ChannelCount() && !O.RootInBass; ++c)
			O.RootInBass = std::find(VoiceChannels.begin(), VoiceChannels.end(), c) == VoiceChannels.end() && IsBass(S.Channel(c)) &&
				HasNotesIn(S, c, First, End);
		O.Volume = Arg(Args, "chord_volume") != 0 ? IntArg(Args, "chord_volume", 10, 1, 15) : PartVolume(S.Channel(VoiceChannels[0]), 10);
		const std::vector<std::vector<PartNote> > Voices = VoicedChordParts(Chords, Spans, O, static_cast<int>(VoiceChannels.size()));
		// Strummed: each voice a frame or more after the one below it (Gxx), as a hand rolls a chord, within the row
		const int Strum = std::min(IntArg(Args, "strum", 1, 0, 3), std::max(0, (S.Song.Speed - 1) / std::max(1,
			static_cast<int>(VoiceChannels.size()) - 1)));
		// Each voice on the N163 its own sound (OwnWaveSound): on the soft layer its pads in turn from the lowest voice, the
		// string pad, the choir pad and the string ensemble (a fourth voice a copy of the string pad), as composers voice them
		static const char *const SOFT_VOICES[] = { "string pad", "choir pad", "string ensemble" };
		std::set<int> Taken = N163SoundsBeside(S, 0, VoiceChannels, First, End);
		std::string Names, OwnSounds;
		std::set<int> N163Sounds;
		int SoftVoice = 0, N163Voices = 0;
		for (size_t v = 0; v < VoiceChannels.size(); ++v) {
			const int c = VoiceChannels[v];
			const ChannelInfo &Info = S.Channel(c);
			const std::string Sound = Arg(Args, "chord_instrument") != 0 ? StringArg(Args, "chord_instrument") : IsSoftLayer(Info) ?
				SOFT_VOICES[SoftVoice++ % 3] : Info.Kind == KIND_FM || Info.Chip == "N163" ? "electric piano" : "soft chords";
			int Instrument = ResolveInstrument(S, Sound, c);
			if (S.Channel(c).Chip == "N163") {
				Instrument = OwnWaveSound(S, Instrument, Taken);
				Taken.insert(Instrument);
				N163Sounds.insert(Instrument);
				OwnSounds += (N163Voices++ == 0 ? "" : ", ") + S.Channel(c).Name + " " + InstrumentLabel(S.Song, Instrument);
			}
			std::vector<PartNote> Notes = Voices[v];
			for (size_t i = 0; i < Notes.size(); ++i) {
				Notes[i].Pitch = std::min(PITCHES - 1, Written(Info, Notes[i].Pitch));
				Notes[i].Instrument = Instrument;
				if (Strum > 0 && v > 0)
					Notes[i].Effects.push_back(std::make_pair(static_cast<int>(EFF_DELAY), Strum * static_cast<int>(v)));
			}
			Change C;
			C.Channel = c;
			BuildPart(S.Cells(c), First, End, Notes, OptionsFor(S, c, DirectChange), C.Cells, Warnings);
			Changes.push_back(C);
			Names += (v == 0 ? "" : v + 1 == VoiceChannels.size() ? " and " : ", ") + S.Channel(c).FullName();
		}
		std::string Kind = "voices";
		if (O.Rhythm >= 0)
			Kind += std::string(" (") + ChordRhythms()[static_cast<size_t>(O.Rhythm)].Name + ")";
		Where = Kind + " chords on " + Names;
		if (Strum > 0)
			Where += Format(", strummed upward %s apart (Gxx)", Plural(Strum, "frame", "frames").c_str());
		if (N163Sounds.size() >= 2)
			Where += " (the N163 voices' sounds: " + OwnSounds + "; an N163 sound whose wave changes plays on one channel at a time)";
	}
	else if (ChordChannel >= 0) {
		const ChannelInfo &Info = S.Channel(ChordChannel);
		ChordPartOptions O;
		O.Style = Style;
		O.Rhythm = StyleArg(Args, "rhythm", ChordRhythms(), -1);
		O.Pattern = StyleArg(Args, "pattern", BrokenPatterns(), BROKEN_UP);
		O.StepRows = std::max(1, R / IntArg(Args, "notes_per_beat", 2, 1, 4));
		O.RowsPerBeat = R;
		ChordRegister(O, Info, MelodyNotes, Melody >= 0 ? Written(S.Channel(Melody), 0) : 0);
		KeepRoom(O, Written(Info, 0));
		O.RootInBass = BassChannel >= 0;
		for (int c = 0; c < S.ChannelCount() && !O.RootInBass; ++c)
			O.RootInBass = c != ChordChannel && IsBass(S.Channel(c)) && HasNotesIn(S, c, First, End);
		const int DefaultVolume = Style == CHORDS_STABS ? 11 : Style == CHORDS_BROKEN ? 10 : Style == CHORDS_LUSH ? 6 : 15;
		O.Volume = Arg(Args, "chord_volume") != 0 ? IntArg(Args, "chord_volume", DefaultVolume, 1, 15) : PartVolume(Info, DefaultVolume);
		const char *Sound = Style == CHORDS_GUIDE ? "warm pad" : Style == CHORDS_ARPEGGIO ? "soft chords" :
			Style == CHORDS_LUSH ? "lush chords" : "pluck";
		std::vector<PartNote> Notes = ChordPart(Chords, Spans, O);
		if (Style == CHORDS_LUSH) {
			const Json *pSound = Arg(Args, "chord_instrument");
			if (pSound != 0 && !pSound->IsString() && !pSound->IsNumber())
				throw Problem("chord_instrument: lush chords are made from a preset's sound, named like \"lush chords\" or \"pluck\", or "
					"one of the song's instruments, by name or number.");
			const std::string Named = pSound != 0 && pSound->IsNumber() ? Format("%02X", static_cast<int>(pSound->Number())) :
				StringArg(Args, "chord_instrument", Sound);
			LushInstruments(S, ChordChannel, Named, O.Pattern, IntArg(Args, "arp_frames", 2, 1, 6), Notes);
		}
		else {
			const int Instrument = PartInstrument(S, Args, "chord_instrument", ChordChannel, Sound);
			for (size_t i = 0; i < Notes.size(); ++i)
				Notes[i].Instrument = Instrument;
		}
		Change C;
		C.Channel = ChordChannel;
		BuildPart(S.Cells(ChordChannel), First, End, Notes, OptionsFor(S, ChordChannel, DirectChange), C.Cells, Warnings);
		Changes.push_back(C);
		std::string Kind = ChordStyles()[static_cast<size_t>(Style)].Name;
		if (Style == CHORDS_BROKEN || (Style == CHORDS_LUSH && O.Pattern != BROKEN_UP))
			Kind += std::string(" (") + BrokenPatterns()[static_cast<size_t>(O.Pattern)].Name + ")";
		if (Style != CHORDS_BROKEN && O.Rhythm >= 0)
			Kind += std::string(" (") + ChordRhythms()[static_cast<size_t>(O.Rhythm)].Name + ")";
		Where = Kind + " chords on " + S.Channel(ChordChannel).FullName();
	}
	if (BassChannel >= 0) {
		const ChannelInfo &Info = S.Channel(BassChannel);
		const int Instrument = PartInstrument(S, Args, "bass_instrument", BassChannel, "bass");
		std::vector<PartNote> Notes = BassNotes;
		for (size_t i = 0; i < Notes.size(); ++i)
			Notes[i].Instrument = Instrument;
		Change C;
		C.Channel = BassChannel;
		BuildPart(S.Cells(BassChannel), First, End, Notes, OptionsFor(S, BassChannel, DirectChange), C.Cells, Warnings);
		Changes.push_back(C);
		Where += (Where.empty() ? "a " : " and a ") + std::string(BassStyles()[static_cast<size_t>(BassStyle)].Name) +
			" bass line on " + Info.FullName();
	}
	std::string What = Where + ", " + RangeText(S.Time.BarOf(First), S.Time.BarOf(End - 1)) + ", in " + KeyName(K);
	{
		// Which parts it took the place of
		bool Chords = false, Bass = false;
		for (size_t i = 0; i < Replaced.size(); ++i) {
			Bass = Bass || Replaced[i] == BassChannel;
			Chords = Chords || Replaced[i] != BassChannel;
		}
		if (Chords || Bass)
			What += Format(" (in place of the %s%s%s that played there)", Chords ? "chords" : "", Chords && Bass ? " and " : "",
				Bass ? "bass line" : "");
	}
	std::sort(Changes.begin(), Changes.end(), [](const Change &a, const Change &b) { return a.Channel < b.Channel; });
	const std::string Result = Commit(S, Changes, First, AsClip, StringArg(Args, "clip_name"), What);
	return WithRemarks(S, Result + "\nChords: " + ProgressionText(Chords, Spans, K) + "\nAs degrees of " + KeyName(K) + ": " +
		ProgressionText(Chords, Spans, K, true), Warnings);
}

bool SameKind(const ChannelInfo &a, const ChannelInfo &b)
{
	return a.Kind == b.Kind && InstrumentChip(a) == InstrumentChip(b);
}

// A channel for an echo of Source over [First, End): one of the same kind
// with nothing there, else another melodic one with nothing there; -1 if none
int EchoTarget(Session &S, int Source, int First, int End)
{
	for (int Pass = 0; Pass < 2; ++Pass) {
		for (int c = 0; c < S.ChannelCount(); ++c) {
			if (c == Source || !IsMelodic(S.Channel(c)) || IsBass(S.Channel(c)) != IsBass(S.Channel(Source)))
				continue;
			if (Pass == 0 && !SameKind(S.Channel(c), S.Channel(Source)))
				continue;
			if (!HasNotesIn(S, c, First, End))
				return c;
		}
	}
	return -1;
}

// The echo settings from an object (add_echo's arguments, or change_mood's echo)
struct EchoPlan {
	int Source, Target, Delay, Volume, Instrument;
	int Detune;		// fine pitch steps up (+) or down (-), 0 for none
	bool OtherChip;	// Instrument is the source's sound on the target's chip, picked by name
	int Pan;		// the echo's pan (8xx), -1 to leave its channel's as it is
	bool Opposite;	// on the other side of the source, note by note
};

// The other side of a pan: a sound in the middle has its echo halfway to the right
int OppositePan(int Pan)
{
	return Pan == PAN_CENTER ? PanParam(0.5) : PanParam(-PanPosition(Pan));
}

EchoPlan EchoArgs(Session &S, const Json &Args, int First, int End)
{
	EchoPlan Plan;
	Plan.Source = ChannelArg(S, Args, "channel");
	if (!IsMelodic(S.Channel(Plan.Source)))
		throw Problem("The echo copies a melodic channel's notes.");
	bool Exact;
	Plan.Delay = S.Time.BeatsToRows(NumberArg(Args, "delay_beats", 3.0 / S.Time.RowsPerBeat, 0.01, 16.0), Exact);
	Plan.Volume = IntArg(Args, "volume", 6, 1, 15);
	Plan.Detune = IntArg(Args, "detune", 0, -8, 8);
	Plan.Pan = -1;
	Plan.Opposite = false;
	if (Arg(Args, "pan") != 0) {
		const Json &Value = *Arg(Args, "pan");
		if (Value.IsString() && (Squeezed(Value.String()) == "opposite" || Squeezed(Value.String()) == "otherside"))
			Plan.Opposite = true;
		else if (!ParsePanValue(Value, Plan.Pan))
			throw Problem("pan: opposite (the other side of the original, note by note), left, right, center, or a number from "
				"-1 (left) to 1 (right).");
	}
	if (Arg(Args, "to_channel") != 0) {
		Plan.Target = ChannelArg(S, Args, "to_channel");
		if (Plan.Target == Plan.Source || !IsMelodic(S.Channel(Plan.Target)))
			throw Problem("The echo's to_channel needs another melodic channel.");
	}
	else {
		Plan.Target = EchoTarget(S, Plan.Source, First + Plan.Delay, End + Plan.Delay);
		if (Plan.Target < 0)
			throw Problem("No free channel for the echo in those bars; name one with to_channel (its notes there are replaced).");
	}
	Plan.Instrument = Arg(Args, "instrument") != 0 ? InstrumentArg(S, Args, "instrument", Plan.Target, NO_INSTRUMENT) : NO_INSTRUMENT;
	Plan.OtherChip = false;
	if (Plan.Instrument == NO_INSTRUMENT && InstrumentChip(S.Channel(Plan.Target)) != InstrumentChip(S.Channel(Plan.Source))) {
		// The melody's own sound on the echo's chip, when it's a preset (or one of the VRC7's or N163's sounds)
		const InstrumentInfo *pInfo = FindInstrument(S.Song, UsualInstrument(NotesIn(S.Notes(Plan.Source), First, End)));
		if (pInfo != 0) {
			try {
				Plan.Instrument = ResolveInstrument(S, pInfo->Name, Plan.Target);
				Plan.OtherChip = true;
			}
			catch (const Problem &) {
				Plan.Instrument = NO_INSTRUMENT;
			}
		}
		if (Plan.Instrument == NO_INSTRUMENT)
			throw Problem(Format("%s needs %s instruments; give the echo an instrument (a preset works).",
				S.Channel(Plan.Target).FullName().c_str(), InstrumentChip(S.Channel(Plan.Target)).c_str()));
	}
	return Plan;
}

// The echo of the source's notes that start in [First, End) in the draft:
// Delay rows later on the target, quieter (Volume at full loudness, following
// the original's), replacing what the target plays there. It stops at the
// song's end rather than making the song longer (which would change where it
// loops). How many notes.
// A sticky effect's parameter in effect as each note starts (0 when it's off)
std::vector<int> StickyAt(const std::vector<Cell> &Cells, const std::vector<NoteInfo> &Notes, int Columns, int Effect)
{
	std::vector<int> Out(Notes.size(), 0);
	int Current = 0;
	size_t n = 0;
	for (size_t r = 0; r < Cells.size() && n < Notes.size(); ++r) {
		for (int k = 0; k < Columns && k < EFFECT_COLUMNS; ++k)
			if (Cells[r].Effect[k] == Effect)
				Current = Cells[r].Param[k];
		while (n < Notes.size() && static_cast<int>(r) == Notes[n].Row)
			Out[n++] = Current;
	}
	return Out;
}

// Whether two pitches, as they sound, rub: a semitone apart, or a semitone and
// octaves (a minor ninth, an echo's F-4 over a pad's E-2). check_song hears
// these as clashes, and add_echo and add_harmony keep their notes off them,
// by this one rule; a major seventh is a chord's color (as in a maj7)
bool SemitoneRub(int Sounds, int Other)
{
	return std::abs(Sounds - Other) % 12 == 1;
}

// Echo notes that wouldn't grate: one a semitone (or a semitone and octaves,
// SemitoneRub) from a note another part sounds as it starts (the melody, the
// chords, an arpeggio's notes too) is left out, one another part moves against
// on its way is cut short there. Only those intervals grate, counted as the
// parts sound (the triangle and the VRC7 an octave under their notes): a major
// seventh, over the bass or under the melody, is a chord's color (as in a
// maj7) and stays. Dropped and Shortened count them.
std::vector<PartNote> EchoWithoutRubs(Session &S, Draft &D, int Target, const std::vector<PartNote> &Notes, int &Dropped,
	int &Shortened)
{
	struct Other { int Row, End; std::vector<int> Pitches; };	// as they sound
	std::vector<Other> Others;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (c == Target || !IsMelodic(S.Channel(c)))
			continue;
		const int Lift = Written(S.Channel(c), 0);
		const std::vector<NoteInfo> Theirs = D.Notes(c);
		const std::vector<int> Arps = StickyAt(D.Cells(c), Theirs, S.Channel(c).EffectColumns, EFF_ARPEGGIO);
		for (size_t i = 0; i < Theirs.size(); ++i) {
			Other o;
			o.Row = Theirs[i].Row;
			o.End = Theirs[i].Row + Theirs[i].Rows;
			o.Pitches.push_back(Theirs[i].Pitch - Lift);
			const std::vector<int> Above = ChordAbove(S, Theirs[i], Arps[i]);
			for (size_t a = 0; a < Above.size(); ++a)
				o.Pitches.push_back(Theirs[i].Pitch - Lift + Above[a]);
			Others.push_back(o);
		}
	}
	const int Lifted = Written(S.Channel(Target), 0);
	Dropped = Shortened = 0;
	std::vector<PartNote> Out;
	for (size_t i = 0; i < Notes.size(); ++i) {
		PartNote E = Notes[i];
		const int Sounds = E.Pitch - Lifted;
		int CutAt = E.Row + E.Rows;
		for (size_t k = 0; k < Others.size(); ++k) {
			const Other &o = Others[k];
			if (o.Row >= E.Row + E.Rows || o.End <= E.Row)
				continue;
			for (size_t p = 0; p < o.Pitches.size(); ++p)
				if (SemitoneRub(Sounds, o.Pitches[p]))
					CutAt = std::min(CutAt, std::max(o.Row, E.Row));
		}
		if (CutAt <= E.Row) {
			++Dropped;
			continue;
		}
		if (CutAt < E.Row + E.Rows) {
			E.Rows = CutAt - E.Row;
			++Shortened;
		}
		Out.push_back(E);
	}
	return Out;
}

double FramesPerRow(const Session &S);

// Whether an effect on a note of From's means the same on To and To plays it: To's chip's own (the FDS's modulator Hxx-Jxx
// only on the FDS: elsewhere H and I are a sweep or the 5B's envelope) or one every channel plays; a duty (Vxx) only
// between channels of one chip, whose widths count alike
bool CarriesEffect(const ChannelInfo &From, const ChannelInfo &To, int Effect, int Param)
{
	if (Effect == EFF_DUTY_CYCLE && InstrumentChip(From) != InstrumentChip(To))
		return false;
	return ChannelPlaysEffect(To, Effect, Param);
}

// How loud a note plays over its first Frames frames as FamiTracker works its volume out (the column times the
// instrument's envelope, rounded down, at least 1 while both sound; the VRC7 has none), on the chip's level, in dB
// against a pulse at 15 (the power's mean); the mixer's fader not counted
double PlayedDb(const Session &S, const ChannelInfo &Channel, int Instrument, int Column, int Frames)
{
	ChannelInfo Info = Channel;
	Info.MixLevel = 0;
	const std::vector<int> Envelope = HeldEnvelope(Channel.Kind == KIND_FM ? 0 : FindInstrument(S.Song, Instrument), std::max(1, Frames));
	double Power = 0.0;
	for (size_t f = 0; f < Envelope.size(); ++f)
		Power += std::pow(10.0, LevelDb(Info, PlayedVolume(Info, Column, Envelope[f])) / 10.0);
	return 10.0 * std::log10(std::max(1e-12, Power / static_cast<double>(Envelope.size())));
}

// The volume column of an echo note on Target playing Instrument that sounds Ratio as loud as N does on Source (0.4: about
// 8 dB under), both heard as FamiTracker plays them over the note's first two beats: each chip's level, each instrument's
// envelope and the rounding of a low column counted (a pulse at 3 under an envelope of 12 plays 2). The mixer's faders aren't:
// they stay the mixer's, so the column doesn't make up for one.
int EchoVolume(const Session &S, const ChannelInfo &Source, const NoteInfo &N, const ChannelInfo &Target, int Instrument, double Ratio)
{
	if (N.Volume <= 0)
		return 0;
	const int Frames = std::max(1, static_cast<int>(std::ceil(std::min(N.Rows, 2 * S.Time.RowsPerBeat) * FramesPerRow(S))));
	const double Want = PlayedDb(S, Source, N.Instrument, N.Volume, Frames) + 20.0 * std::log10(std::max(0.01, Ratio));
	int Best = 1;
	double BestMiss = 1e9;
	for (int v = 1; v <= 15; ++v) {
		const double Miss = std::fabs(PlayedDb(S, Target, Instrument, v, Frames) - Want);
		if (Miss < BestMiss - 1e-9) {
			BestMiss = Miss;
			Best = v;
		}
	}
	return Best;
}

// pStop: where the rows written end, for Draft::Collect, so the notes the echo wrote alike (a pan carried over
// them) count as its own
int MakeEcho(Session &S, Draft &D, const EchoPlan &Plan, int First, int End, std::vector<std::string> &Warnings, int *pStop = 0)
{
	int Stop = std::min(End + Plan.Delay, std::max(End, S.Time.TotalRows()));
	if (pStop != 0)
		*pStop = Stop;
	// Past the bars asked for, the echo rings on only until the target's own next note there: a part it isn't replacing
	{
		const std::vector<NoteInfo> Theirs = D.Notes(Plan.Target);
		for (size_t i = 0; i < Theirs.size(); ++i) {
			if (Theirs[i].Row >= End && Theirs[i].Row < Stop) {
				Stop = Theirs[i].Row;
				break;
			}
		}
	}
	const std::vector<NoteInfo> Played = D.Notes(Plan.Source);
	std::vector<PartNote> Notes;
	std::map<int, int> Pans;	// the pan each echo note gets, by its row: its own place, not the original's
	for (size_t i = 0; i < Played.size(); ++i) {
		const NoteInfo &N = Played[i];
		if (N.Row < First || N.Row >= End || N.Row + Plan.Delay >= Stop)
			continue;
		PartNote E;
		E.Row = N.Row + Plan.Delay;
		E.Rows = std::min(N.Rows, Stop - E.Row);
		E.Pitch = WrittenOn(S.Channel(Plan.Source), S.Channel(Plan.Target), N.Pitch);	// at the same pitch as it sounds
		E.Instrument = Plan.Instrument != NO_INSTRUMENT ? Plan.Instrument : N.Instrument;
		E.Volume = EchoVolume(S, S.Channel(Plan.Source), N, S.Channel(Plan.Target), E.Instrument, Plan.Volume / 15.0);
		for (size_t e = 0; e < N.Effects.size(); ++e) {
			if (N.Effects[e].second.first == EFF_PAN ||
				!CarriesEffect(S.Channel(Plan.Source), S.Channel(Plan.Target), N.Effects[e].second.first, N.Effects[e].second.second))
				continue;
			if (N.Effects[e].first == 0)
				E.Effects.push_back(N.Effects[e].second);
			else if (N.Effects[e].first < E.Rows)
				E.LaterEffects.push_back(N.Effects[e]);
		}
		if (Plan.Opposite || Plan.Pan >= 0)
			Pans[E.Row] = Plan.Opposite ? OppositePan(N.Pan) : Plan.Pan;
		Notes.push_back(E);
	}
	if (Notes.empty())
		return 0;
	for (size_t i = 0; i + 1 < Notes.size(); ++i)
		Notes[i].Rows = std::min(Notes[i].Rows, Notes[i + 1].Row - Notes[i].Row);
	int Dropped, Shortened;
	Notes = EchoWithoutRubs(S, D, Plan.Target, Notes, Dropped, Shortened);
	if (Dropped > 0 || Shortened > 0)
		Warnings.push_back(Format("Where the echo would grate a semitone against another part, %s%s%s.",
			Dropped > 0 ? (Plural(Dropped, "echo note was", "echo notes were") + " left out").c_str() : "",
			Dropped > 0 && Shortened > 0 ? " and " : "",
			Shortened > 0 ? (Plural(Shortened, "was", "were") + " cut short").c_str() : ""));
	if (Notes.empty())
		return 0;
	// On the N163, a sound another N163 channel plays there (the melody's own, from another soft channel) as a copy of its own
	OwnWaveSounds(S, &D, Plan.Target, First + Plan.Delay, Stop, Notes);
	if (Plan.Detune != 0) {
		// A little off the melody's pitch, so the two shimmer where they overlap; back in tune after
		Notes.front().Effects.push_back(std::make_pair(static_cast<int>(EFF_PITCH), 0x80 + Plan.Detune));
		Notes.back().EndEffects.push_back(std::make_pair(static_cast<int>(EFF_PITCH), 0x80));
	}
	// Its place between the speakers, on the notes where it changes (the ones between keep it)
	int Last = -1;
	for (size_t i = 0; i < Notes.size(); ++i) {
		const std::map<int, int>::const_iterator It = Pans.find(Notes[i].Row);
		if (It != Pans.end() && It->second != Last) {
			Notes[i].Effects.push_back(std::make_pair(static_cast<int>(EFF_PAN), It->second));
			Last = It->second;
		}
	}
	if (HasNotesIn(S, Plan.Target, First + Plan.Delay, Stop))
		Warnings.push_back(Format("%s's own notes in those bars were replaced by the echo.", S.Channel(Plan.Target).FullName().c_str()));
	PartOptions Options = OptionsFor(S, Plan.Target, false);
	Options.KeepFollowing = false;	// the draft's comparison with the song takes care of what follows
	Options.StopAtEnd = Stop < End + Plan.Delay;	// at the song's end, the last row ends it
	std::vector<Cell> Out;
	BuildPart(D.Cells(Plan.Target), First + Plan.Delay, Stop, Notes, Options, Out, Warnings);
	D.Put(Plan.Target, First + Plan.Delay, Out);
	return static_cast<int>(Notes.size());
}

std::string AddEchoTool(Session &S, const Json &Args)
{
	int From, To;
	BarRange(S, Args, From, To);
	const int First = S.Time.BarStart(From), End = S.Time.BarEnd(To);
	const bool AsClip = BoolArg(Args, "as_clip", false);
	const EchoPlan Plan = EchoArgs(S, Args, First, End);
	std::vector<std::string> Warnings;
	Draft D(S);
	int Stop = 0;
	if (MakeEcho(S, D, Plan, First, End, Warnings, &Stop) == 0)
		throw Problem(Format("%s has no notes in %s to echo.", S.Channel(Plan.Source).FullName().c_str(), RangeText(From, To).c_str()));
	std::vector<Change> Changes;
	int Start;
	if (!D.Collect(First + Plan.Delay, Direct(S, AsClip), Changes, Start, Warnings, Stop))
		throw Problem("The echo is already there.");
	// The number written: each note's as far under it as both sounds play (each chip's level, the instruments' envelopes)
	std::string Level = Format("at volume %d", Plan.Volume);
	const ChannelInfo &Source = S.Channel(Plan.Source), &Target = S.Channel(Plan.Target);
	{
		const std::vector<NoteInfo> Played = NotesIn(S.Notes(Plan.Source), First, End);
		const NoteInfo *pLoudest = 0;
		for (size_t i = 0; i < Played.size(); ++i)
			if (pLoudest == 0 || Played[i].Volume > pLoudest->Volume)
				pLoudest = &Played[i];
		if (pLoudest != 0 && pLoudest->Volume > 0) {
			// Said where it isn't the plain share of the melody's: chips that count volume otherwise, or envelopes
			const int Column = EchoVolume(S, Source, *pLoudest, Target, Plan.Instrument != NO_INSTRUMENT ? Plan.Instrument :
				pLoudest->Instrument, Plan.Volume / 15.0);
			const bool Alike = !StepVolume(Source) && !StepVolume(Target) && FullDb(Source) == FullDb(Target);
			if (!Alike || Column != std::max(1, (Plan.Volume * pLoudest->Volume + 7) / 15))
				Level += Format(" (%.0f dB under each note as both sounds play: %d where the melody plays %d)", -20.0 *
					std::log10(Plan.Volume / 15.0), Column, pLoudest->Volume);
		}
	}
	std::string Side;
	if (Plan.Opposite) {
		const std::vector<NoteInfo> Played = NotesIn(S.Notes(Plan.Source), First, End);
		const double Where = PanPositionOf(Played);
		Side = std::fabs(Where) < 0.05 ? Format(", %s (8%02X) while the original plays in the middle", PanName(OppositePan(PAN_CENTER)).c_str(),
			OppositePan(PAN_CENTER)) : ", on the other side of the original";
	}
	else if (Plan.Pan >= 0)
		Side = Format(", %s (8%02X)", PanName(Plan.Pan).c_str(), Plan.Pan);
	std::string What = Format("an echo of %s on %s, %s later %s%s%s, %s", Source.FullName().c_str(), Target.FullName().c_str(),
		S.Time.Length(Plan.Delay).c_str(), Level.c_str(), Plan.Detune == 0 ? "" : Format(" detuned P%02X", 0x80 + Plan.Detune).c_str(),
		Side.c_str(), RangeText(From, To).c_str());
	if (Plan.OtherChip)
		What += Format(" (playing the melody's sound on the %s: %s)", InstrumentChip(S.Channel(Plan.Target)).c_str(),
			InstrumentLabel(S.Song, Plan.Instrument).c_str());
	return WithRemarks(S, Commit(S, Changes, Start, AsClip, StringArg(Args, "clip_name"), What), Warnings);
}

// Mixing

SongFlow Flow(Session &S);

// How many rows later Channel copies Source's notes in [First, End), as an
// echo does (most of its notes Source's pitches that many rows on); 0 if not
int EchoDelayOf(Session &S, int Channel, int Source, int First, int End)
{
	const std::vector<NoteInfo> &Mine = S.Notes(Channel), &Theirs = S.Notes(Source);
	std::map<int, int> Pitches;
	for (size_t i = 0; i < Theirs.size(); ++i)
		if (Theirs[i].Row < End)
			Pitches[Theirs[i].Row] = Theirs[i].Pitch;
	const int Lift = Written(S.Channel(Channel), 0) - Written(S.Channel(Source), 0);	// the same note as it sounds
	int Count = 0;
	for (size_t i = 0; i < Mine.size(); ++i)
		if (Mine[i].Row >= First && Mine[i].Row < End)
			++Count;
	if (Count < 4)
		return 0;
	int Best = 0, BestHits = 0;
	for (int Delay = 1; Delay <= 3 * S.Time.RowsPerBeat; ++Delay) {
		int Hits = 0;
		for (size_t i = 0; i < Mine.size(); ++i) {
			if (Mine[i].Row < First || Mine[i].Row >= End)
				continue;
			std::map<int, int>::const_iterator it = Pitches.find(Mine[i].Row - Delay);
			if (it != Pitches.end() && (it->second == Mine[i].Pitch || it->second + Lift == Mine[i].Pitch))
				++Hits;
		}
		if (Hits > BestHits) {
			BestHits = Hits;
			Best = Delay;
		}
	}
	return BestHits * 2 >= Count ? Best : 0;
}

// AMBIENCE: a noise channel that only plays swells (wind, waves), not drums: it keeps its level
enum mix_role { ROLE_NONE, ROLE_MELODY, ROLE_ECHO, ROLE_CHORDS, ROLE_LINE, ROLE_BASS, ROLE_DRUMS, ROLE_AMBIENCE };

// Whether a channel that can play the bass plays it in [First, End): over a
// triangle bass, a sawtooth (or an N163 voice, SoftBass) plays it only where
// it doubles the triangle's notes (on others it's a second line or a pad's
// voice, however low); with no triangle there, where it's low
bool PlaysTheBass(Session &S, int Channel, int First, int End)
{
	if (S.Channel(Channel).Kind != KIND_SAWTOOTH && S.Channel(Channel).Chip != "N163")
		return true;
	const std::vector<NoteInfo> Mine = NotesIn(S.Notes(Channel), First, End);
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (S.Channel(c).Kind != KIND_TRIANGLE || !HasNotesIn(S, c, First, End))
			continue;
		const std::vector<NoteInfo> Bass = NotesIn(S.Notes(c), First, End);
		int Together = 0, Same = 0;
		for (size_t m = 0; m < Mine.size(); ++m)
			for (size_t b = 0; b < Bass.size(); ++b) {
				const int Overlap = std::min(Mine[m].Row + Mine[m].Rows, Bass[b].Row + Bass[b].Rows) - std::max(Mine[m].Row, Bass[b].Row);
				if (Overlap <= 0)
					continue;
				Together += Overlap;
				if ((Mine[m].Pitch - Bass[b].Pitch) % 12 == 0)
					Same += Overlap;
			}
		if (Together > 0)
			return Same * 2 >= Together;
	}
	return MiddleOf(Mine, 0) < 36;	// under C-3
}

// The FDS channel playing the bass: its notes in [First, End) sound under C-3
// (written two octaves up, where the FDS's round and growling basses go)
bool FdsBass(Session &S, int Channel, int First, int End)
{
	if (S.Channel(Channel).Chip != "FDS")
		return false;
	const std::vector<NoteInfo> Mine = NotesIn(S.Notes(Channel), First, End);
	return !Mine.empty() && MiddleOf(Mine, 0) - Written(S.Channel(Channel), 0) < 36;
}

// A soft voice holding the bass: an N163 channel (the VRC6 Plus's soft layer, or the N163's own) whose notes in
// [First, End) sound under C-3, as a cue's sub bass holds its root, however few, a fifth or more under every other part
// there (a pad's low voice sits a third or a fourth under the next); over a triangle bass, only where it doubles the
// triangle's notes (PlaysTheBass)
bool SoftBass(Session &S, int Channel, int First, int End)
{
	const std::vector<NoteInfo> Mine = NotesIn(S.Notes(Channel), First, End);
	if (S.Channel(Channel).Chip != "N163" || Mine.empty() || !PlaysTheBass(S, Channel, First, End))
		return false;
	const int Low = MiddleOf(Mine, 0) - Written(S.Channel(Channel), 0);	// as they sound
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (c == Channel || !IsMelodic(S.Channel(c)))
			continue;
		const std::vector<NoteInfo> Theirs = NotesIn(S.Notes(c), First, End);
		if (!Theirs.empty() && MiddleOf(Theirs, 0) - Written(S.Channel(c), 0) < Low + 7)
			return false;
	}
	return true;
}

// Whether a channel plays the song's bass part in [First, End): the triangle or a sawtooth there, the FDS low, or a soft
// voice holding it
bool PlaysBassPart(Session &S, int Channel, int First, int End)
{
	return (IsBass(S.Channel(Channel)) && PlaysTheBass(S, Channel, First, End)) || FdsBass(S, Channel, First, End) ||
		SoftBass(S, Channel, First, End);
}

// How many rows later Channel follows Source's notes in [First, End), as an echo does: EchoDelayOf for four notes or more;
// fewer (the echo of a cue's high note) each start that many rows after a note of Source's of their pitch and last about
// as long (at most twice, and the delay), so a pad holding a chord's note the melody touched isn't one. 0 if not
int FollowDelay(Session &S, int Channel, int Source, int First, int End)
{
	const std::vector<NoteInfo> Mine = NotesIn(S.Notes(Channel), First, End);
	if (Mine.empty())
		return 0;
	if (Mine.size() >= 4)
		return EchoDelayOf(S, Channel, Source, First, End);
	const std::vector<NoteInfo> &Theirs = S.Notes(Source);
	const int Lift = Written(S.Channel(Channel), 0) - Written(S.Channel(Source), 0);	// the same note as it sounds
	for (int Delay = 1; Delay <= 3 * S.Time.RowsPerBeat; ++Delay) {
		bool All = true;
		for (size_t i = 0; i < Mine.size() && All; ++i) {
			bool Found = false;
			for (size_t k = 0; k < Theirs.size() && !Found; ++k)
				Found = Theirs[k].Row == Mine[i].Row - Delay && (Theirs[k].Pitch == Mine[i].Pitch || Theirs[k].Pitch + Lift == Mine[i].Pitch) &&
					Mine[i].Rows <= 2 * std::max(1, Theirs[k].Rows) + Delay;
			All = Found;
		}
		if (All)
			return Delay;
	}
	return 0;
}

// How loud a channel's notes in [First, End) usually play: the louder quarter's level, each note over its first beat as
// FamiTracker plays it (its chip's level, its instrument's envelope and the channel's fader), in dB against a pulse at
// 15; the triangle a little under that. -60 with no notes
double UsualDb(Session &S, int Channel, int First, int End)
{
	const ChannelInfo &Info = S.Channel(Channel);
	const std::vector<NoteInfo> Notes = NotesIn(S.Notes(Channel), First, End);
	const double RowFrames = FramesPerRow(S);
	std::vector<double> Levels;
	for (size_t i = 0; i < Notes.size(); ++i) {
		const int Frames = std::max(1, static_cast<int>(std::floor(std::min(std::max(1, Notes[i].Rows), S.Time.RowsPerBeat) * RowFrames + 0.5)));
		Levels.push_back(FaderDb(Info) + (Info.Kind == KIND_TRIANGLE ? -1.0 : PlayedDb(S, Info, Notes[i].Instrument, Notes[i].Volume, Frames)));
	}
	if (Levels.empty())
		return -60.0;
	std::sort(Levels.begin(), Levels.end());
	return Levels[Levels.size() * 3 / 4];
}

// A sparkle: a quiet arpeggio over the melody (a cue's shimmer on top, a bell's glint), a line of its own rather than the
// song's chords. Its notes in [First, End) mostly sound chords (0xy, or an arpeggio instrument), two in three or more
// start over the melody's note sounding then (as they sound), and it plays 3 dB or more under the melody (UsualDb)
bool IsSparkle(Session &S, int Channel, int Melody, int First, int End)
{
	if (Melody < 0 || Channel == Melody || S.Channel(Channel).Kind == KIND_TRIANGLE)
		return false;
	const std::vector<NoteInfo> Mine = NotesIn(S.Notes(Channel), First, End);
	const std::vector<NoteInfo> &Tune = S.Notes(Melody);
	const int Lift = Written(S.Channel(Channel), 0), Lead = Written(S.Channel(Melody), 0);
	int Chords = 0, Over = 0;
	for (size_t i = 0; i < Mine.size(); ++i) {
		if (SoundsChord(S, Mine[i]))
			++Chords;
		for (size_t k = 0; k < Tune.size(); ++k)
			if (Tune[k].Row <= Mine[i].Row && Tune[k].Row + std::max(1, Tune[k].Rows) > Mine[i].Row) {
				Over += Mine[i].Pitch - Lift > Tune[k].Pitch - Lead ? 1 : 0;
				break;
			}
	}
	const int Count = static_cast<int>(Mine.size());
	return Count > 0 && Chords * 3 >= Count && Over * 3 >= Count * 2 && UsualDb(S, Channel, First, End) <= UsualDb(S, Melody, First, End) - 3.0;
}

// What a channel plays in [First, End), for mixing
int MixRole(Session &S, int Channel, int Melody, int First, int End)
{
	const ChannelInfo &Info = S.Channel(Channel);
	if (Info.Kind == KIND_DPCM || Info.Kind == KIND_TRIANGLE || !HasNotesIn(S, Channel, First, End))
		return ROLE_NONE;	// no volume of their own (the DPCM level softens the triangle)
	if (Info.Kind == KIND_NOISE) {
		// Drums, unless it only plays swells (wind, waves), whose level is the song's own
		const double RowFrames = FramesPerRow(S);
		const std::vector<NoteInfo> &Notes = S.Notes(Channel);
		for (size_t i = 0; i < Notes.size(); ++i)
			if (Notes[i].Row >= First && Notes[i].Row < End &&
				IsDrumHit(S, Notes[i], static_cast<int>(std::floor(Notes[i].Rows * RowFrames + 0.5))))
				return ROLE_DRUMS;
		return ROLE_AMBIENCE;
	}
	if (Channel == Melody)
		return ROLE_MELODY;
	if (Melody >= 0 && FollowDelay(S, Channel, Melody, First, End) > 0)
		return ROLE_ECHO;
	if (PlaysBassPart(S, Channel, First, End))
		return ROLE_BASS;
	const std::vector<NoteInfo> &Notes = S.Notes(Channel);
	for (size_t i = 0; i < Notes.size(); ++i)
		if (Notes[i].Row >= First && Notes[i].Row < End && SoundsChord(S, Notes[i]))
			return IsSparkle(S, Channel, Melody, First, End) ? ROLE_LINE : ROLE_CHORDS;	// a sparkle over the melody is a line
	return ROLE_LINE;
}

const char *RoleName(int Role)
{
	switch (Role) {
	case ROLE_MELODY: return "melody";
	case ROLE_ECHO: return "echo";
	case ROLE_CHORDS: return "chords";
	case ROLE_LINE: return "a second line";
	case ROLE_BASS: return "bass";
	case ROLE_DRUMS: return "drums";
	case ROLE_AMBIENCE: return "swells, not drums";
	}
	return "";
}

// The triangle's and the noise's loudness at a DPCM level, against level 0:
// the NES mixes the three together, and the triangle's swing shrinks as the
// DPCM's output rises
double TriangleShare(int Level)
{
	auto Mix = [](double Triangle, double Dpcm) {
		const double Sum = Triangle / 8227.0 + Dpcm / 22638.0;
		return Sum <= 0.0 ? 0.0 : 159.79 / (1.0 / Sum + 100.0);
	};
	const double Full = Mix(15.0, 0.0);
	return (Mix(15.0, Level) - Mix(0.0, Level)) / Full;
}

// The frames a row lasts at the track's speed and tempo
double FramesPerRow(const Session &S)
{
	const double Rows = RowsPerMinute(S.Song.Speed, S.Song.Tempo, S.Song.FrameRate);
	return Rows > 0.0 ? 60.0 * S.Song.FrameRate / Rows : std::max(1, S.Song.Speed);
}

// Volume slides (Axy), as CChannelHandler runs them: the volume in eighths of
// a step (m_iVolume, 0-127, 127 when the song starts), set by the volume
// column, and each frame the slide takes its low digit off and adds its high
// one, held between 0 and 127; a slide runs on across notes until A00

void SlideRow(const Cell &C, int Columns, int &Level, int &Slide)
{
	for (int k = 0; k < std::min(EFFECT_COLUMNS, Columns); ++k)
		if (C.Effect[k] == EFF_VOLUME_SLIDE)
			Slide = C.Param[k];
	if (C.Volume < NO_VOLUME)
		Level = C.Volume << 3;
}

void SlideFrames(int &Level, int Slide, int Frames)
{
	for (int f = 0; f < Frames && Slide != 0; ++f) {
		Level = std::max(0, Level - (Slide & 15));
		Level = std::min(127, Level + (Slide >> 4));
	}
}

// The level and slide as Row starts
void SlideBefore(const std::vector<Cell> &Cells, int Row, int Columns, const std::vector<int> &Frames, int &Level, int &Slide)
{
	Level = 127;
	Slide = 0;
	for (int r = 0; r < Row && r < static_cast<int>(Cells.size()); ++r) {
		SlideRow(Cells[static_cast<size_t>(r)], Columns, Level, Slide);
		SlideFrames(Level, Slide, r < static_cast<int>(Frames.size()) ? Frames[static_cast<size_t>(r)] : 1);
	}
}

// The frames each song row lasts the first time through, its speed and tempo
// commands in (rows it never reaches at the track's speed and tempo)
std::vector<int> RowFramesOf(Session &S)
{
	const int Total = S.Time.TotalRows();
	std::vector<int> Out(static_cast<size_t>(Total), std::max(1, static_cast<int>(std::floor(FramesPerRow(S) + 0.5))));
	std::vector<std::vector<Cell> > Cells;
	std::vector<int> Columns;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		Cells.push_back(S.Cells(c));
		Columns.push_back(S.Channel(c).EffectColumns);
	}
	int EndTick = 0;
	const std::vector<TimedRow> Rows = TimeRows(Cells, Columns, Flow(S), S.Time.PatternLength, S.Song.Speed, S.Song.Tempo,
		S.Song.SplitPoint, S.Song.FrameRate, 1, EndTick);
	std::vector<char> Seen(static_cast<size_t>(Total), 0);
	for (size_t i = 0; i < Rows.size(); ++i) {
		const int Row = Rows[i].Row;
		if (Row < 0 || Row >= Total || Seen[static_cast<size_t>(Row)])
			continue;
		Seen[static_cast<size_t>(Row)] = 1;
		Out[static_cast<size_t>(Row)] = std::max(1, (i + 1 < Rows.size() ? Rows[i + 1].Tick : EndTick) - Rows[i].Tick);
	}
	return Out;
}

// The loudest a part's volume slides take it in [First, End) while it swells
// (in volume steps, 0 when none climbs), the instrument then playing in Peak
int SlidePeak(const std::vector<Cell> &Cells, int First, int End, int Columns, const std::vector<int> &Frames, int &Instrument)
{
	int Level, Slide, Peak = 0;
	SlideBefore(Cells, First, Columns, Frames, Level, Slide);
	int Playing = StateAt(Cells, First, Columns).Instrument;
	Instrument = NO_INSTRUMENT;
	for (int r = First; r < End && r < static_cast<int>(Cells.size()); ++r) {
		const Cell &C = Cells[static_cast<size_t>(r)];
		SlideRow(C, Columns, Level, Slide);
		if (C.Instrument != NO_INSTRUMENT && !C.IsEnd())
			Playing = C.Instrument;
		for (int f = 0; f < Frames[static_cast<size_t>(r)] && (Slide >> 4) != 0; ++f) {
			SlideFrames(Level, Slide, 1);
			if ((Level >> 3) > Peak) {
				Peak = Level >> 3;
				Instrument = Playing;
			}
		}
	}
	return Peak;
}

// mix's volume slides in a part's rows [First, End) of Cells (mixed already,
// Original as it was): each slide as much faster or slower as the part's
// volumes moved (Slope; the VRC7 counts 3 dB a step and keeps its slides).
// Where a slide now climbs past where the original's goes, moved the same way
// (Map), as one too slow to scale does (a speed of 1 can't go slower), it
// stops there (A00), and the volume column follows the original's slide a
// step at a time until that slide ends or another starts
struct SlideMix {
	int Scaled, Stopped, Lost;
};

SlideMix MixSlides(const std::vector<Cell> &Original, std::vector<Cell> &Cells, int First, int End, int Columns,
	const std::vector<int> &Frames, double Slope, double ShiftSteps, bool Fm)
{
	SlideMix Out = { 0, 0, 0 };
	auto Scale = [&](int Param) {
		if (Fm)
			return Param;
		auto Digit = [&](int Value) {
			return Value == 0 ? 0 : std::max(1, std::min(15, static_cast<int>(std::floor(Value * Slope + 0.5))));
		};
		return (Digit(Param >> 4) << 4) | Digit(Param & 15);
	};
	auto Map = [&](int Level) {
		const double Moved = Fm ? Level + ShiftSteps * 8.0 : Level * Slope;
		return std::max(0, std::min(127, static_cast<int>(std::floor(Moved + 0.5))));
	};
	const int Last = std::min(End, static_cast<int>(std::min(Original.size(), Cells.size())));
	for (int r = First; r < Last; ++r)
		for (int k = 0; k < std::min(EFFECT_COLUMNS, Columns); ++k) {
			Cell &C = Cells[static_cast<size_t>(r)];
			if (C.Effect[k] == EFF_VOLUME_SLIDE && C.Param[k] != 0 && Scale(C.Param[k]) != C.Param[k]) {
				C.Param[k] = static_cast<unsigned char>(Scale(C.Param[k]));
				++Out.Scaled;
			}
		}
	int Was, WasSlide, Now, NowSlide;
	SlideBefore(Original, First, Columns, Frames, Was, WasSlide);
	SlideBefore(Cells, First, Columns, Frames, Now, NowSlide);
	bool Stopped = false;
	for (int r = First; r < Last; ++r) {
		const Cell &O = Original[static_cast<size_t>(r)];
		Cell &C = Cells[static_cast<size_t>(r)];
		SlideRow(O, Columns, Was, WasSlide);
		int WasEnd = Was;
		SlideFrames(WasEnd, WasSlide, Frames[static_cast<size_t>(r)]);
		const int Target = std::max(0, std::min(15, (Map(WasEnd) + 4) >> 3));	// where the original's slide is, moved
		if (Stopped && (HasEffect(O, EFF_VOLUME_SLIDE, Columns) || WasSlide == 0))
			Stopped = false;	// another slide, or none: the mixed row has it too
		if (Stopped) {
			// The volume column follows the original's slide
			if (C.Volume == NO_VOLUME && Target != (Now >> 3))
				C.Volume = static_cast<unsigned char>(Target);
			if (C.Volume < NO_VOLUME)
				Now = C.Volume << 3;
			Was = WasEnd;
			continue;
		}
		SlideRow(C, Columns, Now, NowSlide);
		int NowEnd = Now;
		SlideFrames(NowEnd, NowSlide, Frames[static_cast<size_t>(r)]);
		if ((NowSlide >> 4) != 0 && NowEnd > Map(WasEnd) + 8 && C.Volume == NO_VOLUME && !HasEffect(C, EFF_VOLUME_SLIDE, Columns)) {
			// The climb stops here, at the level the original's reaches, moved as the part was
			if (AddEffect(C, EFF_VOLUME_SLIDE, 0, Columns)) {
				C.Volume = static_cast<unsigned char>(std::max(1, Target));
				NowEnd = C.Volume << 3;
				NowSlide = 0;
				Stopped = true;
				++Out.Stopped;
			}
			else
				++Out.Lost;
		}
		Was = WasEnd;
		Now = NowEnd;
	}
	return Out;
}

// How loud parts sound, as the soundtrack's stems are measured (BS.1770 loudness, as ffmpeg's ebur128 and
// export_for_game count it), for mix's calm and lively styles and the review: each frame of each note as FamiTracker
// plays it (the volume column, volume slides and the instrument's envelope, duty, wave and arpeggio a frame at a time,
// as each chip plays them; the fader, the pan and Soft), its timbre and pitch weighed as loudness meters weigh sound
// (K-weighting: a high shelf of +4 dB over about 2 kHz, deep bass counting less), over 400 ms blocks with the meters'
// gates, so rests don't count and a short note counts with the silence after it. Measured under Wine against
// FamiTracker's renders (October 2026): the 2A03's and the VRC6's pulses of every width at every pitch and volume within
// 0.2 dB (the 2A03's DAC is nonlinear, so its quiet notes play a little louder), the sawtooth, the N163's waves and the
// triangle within 0.5 (the triangle about 1 dB louder under a high DPCM level than it plays), and the parts of two calm
// tracks, each measured alone, within about 0.5. In dB against a 2A03 pulse of 50% at 15 playing A-3 in the middle
// (-20.9 LUFS as FamiTracker renders it). Space isn't counted: it adds little to a part's loudness.
const double HEARD_SAW_DB = 4.55, HEARD_TRIANGLE_DB = 4.0, HEARD_N163_DB = -0.9, HEARD_NOISE_DB = 0.9;
const double NO_LOUDNESS = -99.0;

// The shapes the estimate hears a note's timbre in (FLAT: no timbre counted, for the noise, the VRC7 and the FDS)
enum heard_shape { SHAPE_FLAT, SHAPE_PULSE, SHAPE_SAW, SHAPE_TRIANGLE, SHAPE_WAVE };

struct KFilter {
	double B[2][3], A[2][3];
};

// BS.1770's two filters at 48 kHz, made from their analog prototypes as libebur128 makes them
KFilter MakeKFilter()
{
	const double FS = 48000.0, PI = 3.14159265358979323846;
	KFilter F;
	double K = std::tan(PI * 1681.974450955533 / FS), Q = 0.7071752369554196;
	const double Vh = std::pow(10.0, 3.999843853973347 / 20.0), Vb = std::pow(Vh, 0.4996667741545416);
	double A0 = 1.0 + K / Q + K * K;
	F.B[0][0] = (Vh + Vb * K / Q + K * K) / A0;
	F.B[0][1] = 2.0 * (K * K - Vh) / A0;
	F.B[0][2] = (Vh - Vb * K / Q + K * K) / A0;
	F.A[0][0] = 1.0;
	F.A[0][1] = 2.0 * (K * K - 1.0) / A0;
	F.A[0][2] = (1.0 - K / Q + K * K) / A0;
	K = std::tan(PI * 38.13547087602444 / FS);
	Q = 0.5003270373238773;
	A0 = 1.0 + K / Q + K * K;
	F.B[1][0] = 1.0;
	F.B[1][1] = -2.0;
	F.B[1][2] = 1.0;
	F.A[1][0] = 1.0;
	F.A[1][1] = 2.0 * (K * K - 1.0) / A0;
	F.A[1][2] = (1.0 - K / Q + K * K) / A0;
	return F;
}

// K-weighting's power gain at a frequency (Hz); 0 past half of 48 kHz
double KWeightPower(double Hz)
{
	static const KFilter F = MakeKFilter();
	if (Hz <= 0.0 || Hz >= 24000.0)
		return 0.0;
	const std::complex<double> Z1 = std::polar(1.0, -2.0 * 3.14159265358979323846 * Hz / 48000.0), Z2 = Z1 * Z1;
	double Gain = 1.0;
	for (int s = 0; s < 2; ++s)
		Gain *= std::norm(F.B[s][0] + F.B[s][1] * Z1 + F.B[s][2] * Z2) / std::norm(F.A[s][0] + F.A[s][1] * Z1 + F.A[s][2] * Z2);
	return Gain;
}

// Soft's low-pass (the mixer's CSoftFilter): its cutoff in Hz, from 12 kHz at 1 to 1.8 kHz at 100; 0 when off
double SoftCutoff(int Soft)
{
	return Soft <= 0 ? 0.0 : 12000.0 * std::pow(1800.0 / 12000.0, std::min(100, Soft) / 100.0);
}

// The K-weighted power of a waveform of peak to peak 1 at a pitch (Hz), through Soft (its cutoff, 0 for none):
// a pulse of Duty (0-1), a sawtooth, a triangle, or a stepped wave of 0-15 samples (an N163's)
double ShapePower(int Shape, double Duty, const std::vector<int> *pWave, double Hz, double SoftHz)
{
	const double PI = 3.14159265358979323846;
	const int N = Shape == SHAPE_WAVE && pWave != 0 ? static_cast<int>(pWave->size()) : 0;
	std::vector<std::complex<double> > X(static_cast<size_t>(std::max(1, N)));
	if (N > 0) {
		double Mean = 0.0;
		for (int j = 0; j < N; ++j)
			Mean += (*pWave)[static_cast<size_t>(j)] / 15.0;
		Mean /= N;
		for (int k = 0; k < N; ++k)
			for (int j = 0; j < N; ++j)
				X[static_cast<size_t>(k)] += ((*pWave)[static_cast<size_t>(j)] / 15.0 - Mean) * std::polar(1.0 / N, -2.0 * PI * k * j / N);
	}
	const double SoftA = SoftHz > 0.0 ? 1.0 - std::exp(-2.0 * PI * SoftHz / 48000.0) : 1.0;
	double Sum = 0.0;
	for (int k = 1; k <= 512 && k * Hz < 20000.0; ++k) {
		double P = 0.0;
		if (Shape == SHAPE_PULSE)
			P = std::pow(2.0 / (k * PI), 2) * std::pow(std::sin(k * PI * Duty), 2) / 2.0;
		else if (Shape == SHAPE_SAW)
			P = 1.0 / (2.0 * std::pow(k * PI, 2));
		else if (Shape == SHAPE_TRIANGLE)
			P = k % 2 != 0 ? 8.0 / std::pow(k * PI, 4) : 0.0;
		else if (N > 0 && k % N != 0) {
			const double Hold = std::sin(PI * k / N) / (PI * k / N);	// the steps' sample and hold
			P = 2.0 * std::norm(X[static_cast<size_t>(k % N)]) * Hold * Hold;
		}
		const double W = 2.0 * PI * k * Hz / 48000.0;
		const double Soft = SoftHz > 0.0 ? SoftA * SoftA / (1.0 - 2.0 * (1.0 - SoftA) * std::cos(W) + (1.0 - SoftA) * (1.0 - SoftA)) : 1.0;
		Sum += P * KWeightPower(k * Hz) * Soft;
	}
	return Sum;
}

// A timbre's loudness against a 50% pulse playing A-3, in dB (0 for SHAPE_FLAT)
double TimbreDb(int Shape, double Duty, const std::vector<int> *pWave, double Hz, double SoftHz)
{
	static const double REFERENCE = ShapePower(SHAPE_PULSE, 0.5, 0, 440.0, 0.0);
	if (Shape == SHAPE_FLAT)
		return 0.0;
	const double Power = ShapePower(Shape, Duty, pWave, Hz, SoftHz);
	return Power > 0.0 ? 10.0 * std::log10(Power / REFERENCE) : -60.0;
}

// The dB a pan takes off a part's loudness as the mixer pans it (PanGains: the side it moves away from fades out, the
// other keeps all of it; meters add the two sides' powers)
double PanDb(int Pan)
{
	double Left = 1.0, Right = 1.0;
	if (Pan < 0x80)
		Right = std::max(0, Pan) / 128.0;
	else if (Pan > 0x80)
		Left = (0xFF - std::min(0xFF, Pan)) / 127.0;
	return 10.0 * std::log10(std::max(1e-9, (Left * Left + Right * Right) / 2.0));
}

// An instrument's sequence as CSequenceHandler runs it, a frame at a time: from the start, back to its loop point at
// its end or past its release point (waiting there without a loop), its last value once it ends; a release sends it on
// from its release point (ReleaseSequence)
class SequenceRun {
public:
	SequenceRun() : m_pItems(0), m_Loop(-1), m_Release(-1), m_Pointer(0), m_Value(0), m_Ended(true), m_Releasing(false) {}
	void Start(const std::vector<int> &Items, int Loop, int Release, int Default)
	{
		m_pItems = Items.empty() ? 0 : &Items;
		m_Loop = Loop;
		m_Release = Release;
		m_Pointer = 0;
		m_Value = Default;
		m_Ended = m_pItems == 0;
		m_Releasing = false;
	}
	void Release()
	{
		m_Releasing = true;
		if (m_pItems != 0 && !m_Ended && m_Release >= 0)
			m_Pointer = m_Release;
	}
	bool Has() const { return m_pItems != 0; }
	int Step()
	{
		if (m_pItems == 0 || m_Ended)
			return m_Value;
		const int Items = static_cast<int>(m_pItems->size());
		m_Value = (*m_pItems)[static_cast<size_t>(std::max(0, std::min(m_Pointer, Items - 1)))];
		++m_Pointer;
		if (m_Pointer == m_Release + 1 || m_Pointer >= Items) {
			if (m_Loop >= 0 && m_Loop < Items && !(m_Releasing && m_Release >= 0))
				m_Pointer = m_Loop;
			else if (m_Pointer >= Items)
				m_Ended = true;
			else if (!m_Releasing)
				--m_Pointer;
		}
		return m_Value;
	}

private:
	const std::vector<int> *m_pItems;
	int m_Loop, m_Release, m_Pointer, m_Value;
	bool m_Ended, m_Releasing;
};

// The triangle's level through the 2A03's second pin (the triangle, the noise and the DPCM mixed as 159.79 / (1 / (t /
// 8227 + n / 12241 + d / 22638) + 100)) against its level alone at 0 dB: the DPCM's level narrows its swing
// (TriangleShare), and a fader (Gain) scales only the triangle's share of the pin, so under a high DPCM level it takes
// off more than its dB (at Z50 a fader of -2 dB takes 2.8)
double TrianglePinShare(int Dac, double Gain)
{
	auto Pin = [](double Sum) { return Sum <= 0.0 ? 0.0 : 159.79 / (1.0 / Sum + 100.0); };
	const double T = 15.0 / 8227.0, D = std::max(0, Dac) / 22638.0;
	const double Full = Pin(T + D), Share = T / (T + D);
	return std::max(0.0, Gain * Share * Full + (1.0 - Share) * Full - Pin(D)) / Pin(T);
}

// A 2A03 pulse's level at a volume against its level at 15: its DAC (95.88 / (8128 / v + 100)) is nonlinear
double PulseDacDb(int Volume)
{
	auto Out = [](int v) { return v <= 0 ? 0.0 : 95.88 / (8128.0 / v + 100.0); };
	return Volume <= 0 ? -60.0 : 20.0 * std::log10(Out(Volume) / Out(15));
}

// The song as heard: each channel's loudness frame by frame (the first time through, its rows in order), for measuring
// parts as the stems would; with a draft, the song as the draft has it
class Hearing {
public:
	explicit Hearing(Session &S, Draft *pDraft = 0) : m_S(S), m_pDraft(pDraft), m_RowFrames(RowFramesOf(S))
	{
		m_FrameStart.push_back(0);
		for (size_t r = 0; r < m_RowFrames.size(); ++r)
			m_FrameStart.push_back(m_FrameStart.back() + m_RowFrames[r]);
		// The DPCM level on each row (the triangle and the noise share its pin)
		m_Dac.assign(m_RowFrames.size(), 0);
		for (int c = 0; c < S.ChannelCount(); ++c) {
			if (S.Channel(c).Kind != KIND_DPCM)
				continue;
			const std::vector<Cell> &Cells = CellsOf(c);
			int Level = 0;
			for (size_t r = 0; r < m_Dac.size(); ++r) {
				if (r < Cells.size())
					for (int k = 0; k < std::min(EFFECT_COLUMNS, S.Channel(c).EffectColumns); ++k)
						if (Cells[r].Effect[k] == EFF_DAC)
							Level = Cells[r].Param[k] & 0x7F;
				m_Dac[r] = Level;
			}
			break;
		}
	}

	// A channel's power on each frame (1: a 2A03 pulse of 50% at 15 playing A-3 in the middle; 0 where it's silent)
	const std::vector<double> &Power(int Channel)
	{
		std::map<int, std::vector<double> >::iterator it = m_Power.find(Channel);
		if (it == m_Power.end())
			it = m_Power.insert(std::make_pair(Channel, Hear(Channel))).first;
		return it->second;
	}

	// The loudness of some channels together over some spans of song rows ([first, end) each), as a meter measures it
	// (dB as above); NO_LOUDNESS when they're silent there
	double Loudness(const std::vector<int> &Channels, const std::vector<std::pair<int, int> > &Rows)
	{
		std::vector<double> Frames;
		for (size_t s = 0; s < Rows.size(); ++s) {
			const int A = FrameOf(Rows[s].first), Z = FrameOf(Rows[s].second);
			const size_t At = Frames.size();
			Frames.resize(At + static_cast<size_t>(std::max(0, Z - A)), 0.0);
			for (size_t c = 0; c < Channels.size(); ++c) {
				const std::vector<double> &P = Power(Channels[c]);
				for (int f = A; f < Z && f < static_cast<int>(P.size()); ++f)
					Frames[At + static_cast<size_t>(f - A)] += P[static_cast<size_t>(f)];
			}
		}
		// 400 ms blocks, a quarter of one apart; the meters' gates: 70 LUFS under full scale (49 dB under a pulse at
		// 15), then 10 dB under the blocks' mean
		const int Block = std::max(1, static_cast<int>(std::floor(0.4 * m_S.Song.FrameRate + 0.5))), Hop = std::max(1, Block / 4);
		std::vector<double> Means;
		for (int b = 0; b == 0 || b + Block <= static_cast<int>(Frames.size()); b += Hop) {
			const int Count = std::min(Block, static_cast<int>(Frames.size()) - b);
			if (Count <= 0)
				break;
			double Sum = 0.0;
			for (int f = b; f < b + Count; ++f)
				Sum += Frames[static_cast<size_t>(f)];
			if (Sum / Block > std::pow(10.0, -4.9))
				Means.push_back(Sum / Block);
		}
		if (Means.empty())
			return NO_LOUDNESS;
		double Mean = 0.0;
		for (size_t i = 0; i < Means.size(); ++i)
			Mean += Means[i];
		Mean /= Means.size();
		double Sum = 0.0;
		int Kept = 0;
		for (size_t i = 0; i < Means.size(); ++i)
			if (Means[i] >= Mean / 10.0) {
				Sum += Means[i];
				++Kept;
			}
		return 10.0 * std::log10(Sum / std::max(1, Kept));
	}

	int FrameOf(int Row) const
	{
		return m_FrameStart[static_cast<size_t>(std::max(0, std::min(Row, static_cast<int>(m_FrameStart.size()) - 1)))];
	}

private:
	const std::vector<Cell> &CellsOf(int Channel)
	{
		return m_pDraft != 0 ? m_pDraft->View(Channel) : m_S.Cells(Channel);
	}

	double Timbre(int Shape, double Duty, const std::vector<int> *pWave, int WaveKey, int Sounding, double SoftHz)
	{
		if (Shape == SHAPE_FLAT)
			return 0.0;
		const long long Key = ((((static_cast<long long>(Shape) * 64 + static_cast<int>(Duty * 32.0 + 0.5)) * 4096 + WaveKey) * 256 +
			(Sounding + 64)) * 32768) + static_cast<long long>(SoftHz);
		std::map<long long, double>::const_iterator it = m_Timbre.find(Key);
		if (it != m_Timbre.end())
			return it->second;
		const double Db = TimbreDb(Shape, Duty, pWave, 440.0 * std::pow(2.0, (Sounding - 45) / 12.0), SoftHz);
		m_Timbre[Key] = Db;
		return Db;
	}

	std::vector<double> Hear(int Channel)
	{
		const ChannelInfo &Info = m_S.Channel(Channel);
		std::vector<double> Out(static_cast<size_t>(m_FrameStart.back()), 0.0);
		if (Info.Kind == KIND_DPCM)
			return Out;
		const std::vector<Cell> &Cells = CellsOf(Channel);
		const int Columns = std::min(EFFECT_COLUMNS, Info.EffectColumns), Lift = Written(Info, 0);
		const double SoftHz = SoftCutoff(Info.MixSoft), Fader = FaderDb(Info);
		const bool Dac2A03 = Info.Chip == "2A03" && Info.Kind == KIND_PULSE;
		int Level = 127, Slide = 0, Pan = Info.MixPan, Duty = 0, Mode = 64, Instrument = NO_INSTRUMENT, Pitch = 0, Arp = 0;
		bool Sounding = false;
		const InstrumentInfo *pInfo = 0;
		SequenceRun Volume, Duties, Steps;
		for (size_t r = 0; r < m_RowFrames.size(); ++r) {
			const Cell C = r < Cells.size() ? Cells[r] : Cell();
			for (int k = 0; k < Columns; ++k) {
				if (C.Effect[k] == EFF_PAN)
					Pan = C.Param[k];
				else if (C.Effect[k] == EFF_DUTY_CYCLE) {
					Duty = C.Param[k];
					if (Info.Kind == KIND_SQUARE)	// Vxx: 1 the square, 2 the noise, 4 the envelope
						Mode = ((C.Param[k] & 1) ? 64 : 0) | ((C.Param[k] & 2) ? 128 : 0) | ((C.Param[k] & 4) ? 32 : 0);
				}
			}
			SlideRow(C, Columns, Level, Slide);
			if (C.Instrument != NO_INSTRUMENT && !C.IsEnd())
				Instrument = C.Instrument;
			if (C.HasNote()) {
				pInfo = FindInstrument(m_S.Song, Instrument);
				Pitch = C.Pitch();
				Arp = 0;
				Sounding = true;
				static const std::vector<int> NONE;
				if (pInfo != 0) {
					Volume.Start(pInfo->Volume, pInfo->VolumeLoop, pInfo->VolumeRelease, 15);
					const SequenceInfo &D = Info.Kind == KIND_SQUARE ? pInfo->Mode : pInfo->Duty;
					Duties.Start(D.Items, D.Loop, D.Release, Info.Kind == KIND_SQUARE ? Mode : Duty);
					Steps.Start(pInfo->Steps.Items, pInfo->Steps.Loop, pInfo->Steps.Release, 0);
				}
				else {
					Volume.Start(NONE, -1, -1, 15);
					Duties.Start(NONE, -1, -1, Info.Kind == KIND_SQUARE ? Mode : Duty);
					Steps.Start(NONE, -1, -1, 0);
				}
			}
			else if (C.Note == NOTE_RELEASE) {
				Volume.Release();
				Duties.Release();
				Steps.Release();
			}
			else if (C.Note == NOTE_HALT)
				Sounding = false;
			for (int f = 0; f < m_RowFrames[r]; ++f) {
				SlideFrames(Level, Slide, 1);
				if (!Sounding)
					continue;
				const int Envelope = Volume.Step();
				const int Shape = Duties.Has() ? Duties.Step() : (Info.Kind == KIND_SQUARE ? Mode : Duty);
				if (Steps.Has()) {
					const int Value = Steps.Step();
					Arp = pInfo != 0 && pInfo->Steps.Setting == 2 ? Arp + Value : Value;
				}
				const int Note = pInfo != 0 && pInfo->Steps.Setting == 1 && Steps.Has() ? Arp : Pitch + Arp;
				const int Sound = std::max(-60, std::min(180, Note - Lift));
				double Db;
				if (Info.Kind == KIND_TRIANGLE) {
					// Its fader works through the pin it shares with the noise and the DPCM
					if (Envelope <= 0 || (Level >> 3) <= 0)
						continue;
					Db = HEARD_TRIANGLE_DB + 20.0 * std::log10(std::max(0.01, TrianglePinShare(m_Dac[r], std::pow(10.0, Fader / 20.0)))) +
						Timbre(SHAPE_TRIANGLE, 0.0, 0, 0, Sound, SoftHz) - Fader;
				}
				else if (Info.Kind == KIND_NOISE) {
					const int Played = PlayedVolume(Level >> 3, Envelope);
					if (Played <= 0)
						continue;
					Db = 20.0 * std::log10(Played / 15.0) + HEARD_NOISE_DB + 20.0 * std::log10(std::max(0.01, TriangleShare(m_Dac[r])));
				}
				else if (Info.Kind == KIND_SQUARE) {
					// The 5B: the envelope (a buzz) plays at its own full level whatever the volume, unless that's 0
					const int Played = PlayedVolume(Info, Level >> 3, Envelope);
					if (Played <= 0)
						continue;
					ChannelInfo Unfaded = Info;
					Unfaded.MixLevel = 0;
					if (Shape & 32)
						Db = LevelDb(Unfaded, 15) + Timbre(SHAPE_SAW, 0.0, 0, 0, Sound, SoftHz);
					else if (Shape & 64)
						Db = LevelDb(Unfaded, Played) + Timbre(SHAPE_PULSE, 0.5, 0, 0, Sound, SoftHz);
					else
						Db = LevelDb(Unfaded, Played);	// the noise alone
				}
				else {
					const int Played = PlayedVolume(Level >> 3, Envelope);
					if (Played <= 0)
						continue;
					if (Info.Chip == "N163") {
						const std::vector<int> *pWave = 0;
						int WaveKey = 0;
						if (pInfo != 0 && !pInfo->Waves.empty()) {
							const int Wave = std::max(0, std::min(static_cast<int>(pInfo->Waves.size()) - 1, Shape));
							pWave = &pInfo->Waves[static_cast<size_t>(Wave)];
							WaveKey = pInfo->Index * 64 + Wave + 1;
						}
						// A wave not known plays as much rounder than a square as the ready-made ones do on average
						static const std::vector<int> SQUARE = { 15, 15, 15, 15, 15, 15, 15, 15, 0, 0, 0, 0, 0, 0, 0, 0 };
						Db = HEARD_N163_DB + (N163FullDb(Info.ChipChannels) - N163FullDb(4)) + 20.0 * std::log10(Played / 15.0) +
							(pWave != 0 ? Timbre(SHAPE_WAVE, 0.0, pWave, WaveKey, Sound, SoftHz) :
							Timbre(SHAPE_WAVE, 0.0, &SQUARE, 0, Sound, SoftHz) + N163_WAVE_DB);
					}
					else if (Info.Kind == KIND_SAWTOOTH)
						Db = HEARD_SAW_DB + 20.0 * std::log10(Played / 15.0) + Timbre(SHAPE_SAW, 0.0, 0, 0, Sound, SoftHz);
					else if (Info.Kind == KIND_PULSE) {
						static const double WIDTHS[4] = { 0.125, 0.25, 0.5, 0.75 };
						const double Width = Info.Chip == "VRC6" ? ((Shape & 7) + 1) / 16.0 : WIDTHS[Shape & 3];
						Db = (Dac2A03 ? PulseDacDb(Played) : 20.0 * std::log10(Played / 15.0)) + Timbre(SHAPE_PULSE, Width, 0, 0, Sound, SoftHz);
					}
					else {
						ChannelInfo Unfaded = Info;	// the VRC7 and the FDS, by their measured levels
						Unfaded.MixLevel = 0;
						Db = LevelDb(Unfaded, Played);
					}
				}
				Out[static_cast<size_t>(m_FrameStart[r] + f)] = std::pow(10.0, (Db + Fader + PanDb(Pan)) / 10.0);
			}
		}
		return Out;
	}

	Session &m_S;
	Draft *m_pDraft;
	std::vector<int> m_RowFrames, m_FrameStart, m_Dac;
	std::map<int, std::vector<double> > m_Power;
	std::map<long long, double> m_Timbre;
};

// What each channel plays in [First, End), frame by frame where that changes: a channel that echoes the melody in some
// frames and plays a line of its own in others (a harmony at the climax) is mixed as each, there (Leveled: the channels
// given a level, mixed as one part)
struct MixSpan {
	int Channel, First, End, Role, Target;
	double Level;
};

std::vector<MixSpan> MixSpans(Session &S, int Melody, int First, int End, const std::set<int> &Leveled)
{
	std::vector<MixSpan> Spans;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		const MixSpan All = { c, First, End, MixRole(S, c, Melody, First, End), -1, 0.0 };
		std::vector<int> Starts, Echo;	// each frame's first row, and 1 where the channel echoes the melody (-1: too few notes)
		if (All.Role != ROLE_NONE && All.Role != ROLE_DRUMS && All.Role != ROLE_AMBIENCE && All.Role != ROLE_MELODY && Melody >= 0) {
			for (int f = First; f < End; ) {
				const int FrameEnd = std::min(End, (f / S.Time.PatternLength + 1) * S.Time.PatternLength);
				const int Count = static_cast<int>(NotesIn(S.Notes(c), f, FrameEnd).size());
				Starts.push_back(f);
				Echo.push_back(Count < 4 ? -1 : EchoDelayOf(S, c, Melody, f, FrameEnd) > 0 ? 1 : 0);
				f = FrameEnd;
			}
		}
		// Frames too sparse to tell go with the frame before (the first ones with the first that tells)
		int Known = -1;
		for (size_t i = 0; i < Echo.size() && Known < 0; ++i)
			Known = Echo[i];
		bool Echoes = false, Not = false;
		for (size_t i = 0; i < Echo.size(); ++i) {
			if (Echo[i] < 0)
				Echo[i] = Known;
			Known = Echo[i];
			Echoes = Echoes || Echo[i] == 1;
			Not = Not || Echo[i] == 0;
		}
		if (!(Echoes && Not) || Leveled.count(c) > 0) {
			Spans.push_back(All);
			continue;
		}
		for (size_t i = 0; i < Starts.size(); ) {
			size_t j = i;
			while (j + 1 < Starts.size() && Echo[j + 1] == Echo[i])
				++j;
			const int SpanEnd = j + 1 < Starts.size() ? Starts[j + 1] : End;
			const MixSpan Piece = { c, Starts[i], SpanEnd, Echo[i] == 1 ? static_cast<int>(ROLE_ECHO) : MixRole(S, c, -1, Starts[i], SpanEnd),
				-1, 0.0 };
			Spans.push_back(Piece);
			i = j + 1;
		}
	}
	return Spans;
}

// As heard, the chords are every part that plays the harmony together: voiced chords on several channels (Voices) and
// broken chords in a steady run, besides arpeggios. Lines on two or more channels that start every note together (a
// pad's voices holding one chord, strummed a frame or two apart) are voiced chords too, and join Voices
void HeardRoles(Session &S, std::vector<int> &Voices, std::vector<MixSpan> &Spans)
{
	int Melody = -1;	// a sparkle over it (IsSparkle) starts its notes with a pad's, but is no voice of its chords
	for (size_t i = 0; i < Spans.size(); ++i)
		if (Spans[i].Role == ROLE_MELODY)
			Melody = Spans[i].Channel;
	std::vector<std::vector<int> > Starts(Spans.size());
	for (size_t i = 0; i < Spans.size(); ++i) {
		if (Spans[i].Role != ROLE_LINE || IsSparkle(S, Spans[i].Channel, Melody, Spans[i].First, Spans[i].End))
			continue;
		const std::vector<NoteInfo> Notes = NotesIn(S.Notes(Spans[i].Channel), Spans[i].First, Spans[i].End);
		for (size_t n = 0; n < Notes.size(); ++n)
			Starts[i].push_back(Notes[n].Row);
	}
	std::vector<char> Held(Spans.size(), 0);
	for (size_t i = 0; i < Spans.size(); ++i)
		for (size_t k = i + 1; k < Spans.size(); ++k) {
			if (Starts[i].empty() || Starts[i].size() != Starts[k].size() || Spans[i].Channel == Spans[k].Channel)
				continue;
			bool Together = true;
			for (size_t n = 0; n < Starts[i].size() && Together; ++n)
				Together = std::abs(Starts[i][n] - Starts[k][n]) <= 1;
			if (Together)
				Held[i] = Held[k] = 1;
		}
	for (size_t i = 0; i < Spans.size(); ++i)
		if (Held[i] && std::find(Voices.begin(), Voices.end(), Spans[i].Channel) == Voices.end())
			Voices.push_back(Spans[i].Channel);
	for (size_t i = 0; i < Spans.size(); ++i) {
		MixSpan &P = Spans[i];
		if (P.Role == ROLE_LINE && (std::find(Voices.begin(), Voices.end(), P.Channel) != Voices.end() ||
			RunsSteadily(S, NotesIn(S.Notes(P.Channel), P.First, P.End))))
			P.Role = ROLE_CHORDS;
	}
}

// The bars of some song rows ([first, end) each) where any of Channels sounds and the melody does too, as rows
std::vector<std::pair<int, int> > BarsWithMelody(Session &S, const std::vector<int> &Channels, int Melody,
	const std::vector<std::pair<int, int> > &Rows)
{
	std::vector<std::pair<int, int> > Out;
	for (size_t s = 0; s < Rows.size(); ++s) {
		if (Rows[s].second <= Rows[s].first)
			continue;
		for (int Bar = S.Time.BarOf(Rows[s].first); Bar <= S.Time.BarOf(Rows[s].second - 1); ++Bar) {
			const int A = std::max(Rows[s].first, S.Time.BarStart(Bar)), Z = std::min(Rows[s].second, S.Time.BarEnd(Bar));
			bool Part = false;
			for (size_t c = 0; c < Channels.size() && !Part; ++c)
				Part = HasNotesIn(S, Channels[c], A, Z);
			if (Z <= A || !Part || (Melody >= 0 && !HasNotesIn(S, Melody, A, Z)))
				continue;
			if (!Out.empty() && Out.back().second == A)
				Out.back().second = Z;
			else
				Out.push_back(std::make_pair(A, Z));
		}
	}
	return Out;
}

// The balance as heard: each part's loudness against the melody's where they play together (dB; NO_LOUDNESS for a part
// that never plays with it), the chords as layers (a voicing's voices together, any other chord part alone), and of the
// layers that play together the loudest the main one
struct HeardBalance {
	std::vector<double> Rel;					// per span
	std::vector<int> Layer;						// per span: its chord layer, -1 for none
	std::vector<std::vector<size_t> > Layers;	// each layer's spans
	std::vector<double> LayerRel;				// each layer against the melody
	std::vector<int> Main;						// each layer's main layer (itself when it's the loudest of those it plays with)
	int Triangle;								// the triangle's channel when it plays with the melody, else -1...
	double TriangleRel;							// ...and its loudness against the melody's
};

HeardBalance HearBalance(Session &S, Hearing &H, const std::vector<MixSpan> &Spans,
	const std::vector<std::vector<std::pair<int, int> > > &Refs, int Melody, const std::vector<int> &Voices, int First, int End)
{
	HeardBalance B;
	B.Rel.assign(Spans.size(), NO_LOUDNESS);
	B.Layer.assign(Spans.size(), -1);
	B.Triangle = -1;
	B.TriangleRel = NO_LOUDNESS;
	if (Melody < 0)
		return B;
	std::vector<std::pair<int, int> > MelodyRows;
	for (size_t i = 0; i < Spans.size(); ++i)
		if (Spans[i].Role == ROLE_MELODY)
			MelodyRows.insert(MelodyRows.end(), Refs[i].begin(), Refs[i].end());
	const double LeadAlone = H.Loudness(std::vector<int>(1, Melody), MelodyRows);
	// Against the melody where they play together; a part that never does, against the melody as a whole
	auto Against = [&](const std::vector<int> &Channels, const std::vector<std::pair<int, int> > &Rows, std::vector<std::pair<int, int> > *pBars) {
		const std::vector<std::pair<int, int> > Bars = BarsWithMelody(S, Channels, Melody, Rows);
		if (pBars != 0)
			*pBars = Bars;
		const double Part = H.Loudness(Channels, Bars.empty() ? Rows : Bars);
		const double Lead = Bars.empty() ? LeadAlone : H.Loudness(std::vector<int>(1, Melody), Bars);
		return Part <= NO_LOUDNESS || Lead <= NO_LOUDNESS ? NO_LOUDNESS : Part - Lead;
	};
	std::vector<std::vector<std::pair<int, int> > > LayerBars;
	for (size_t i = 0; i < Spans.size(); ++i) {
		if (Spans[i].Role != ROLE_CHORDS)
			continue;
		const bool Voice = std::find(Voices.begin(), Voices.end(), Spans[i].Channel) != Voices.end();
		int Into = -1;
		for (size_t l = 0; l < B.Layers.size() && Into < 0 && Voice; ++l) {
			const MixSpan &Other = Spans[B.Layers[l].front()];
			if (std::find(Voices.begin(), Voices.end(), Other.Channel) != Voices.end() && Other.First < Spans[i].End &&
				Spans[i].First < Other.End)
				Into = static_cast<int>(l);
		}
		if (Into < 0) {
			Into = static_cast<int>(B.Layers.size());
			B.Layers.push_back(std::vector<size_t>());
		}
		B.Layers[static_cast<size_t>(Into)].push_back(i);
		B.Layer[i] = Into;
	}
	for (size_t l = 0; l < B.Layers.size(); ++l) {
		std::vector<int> Channels;
		std::vector<std::pair<int, int> > Rows;
		for (size_t k = 0; k < B.Layers[l].size(); ++k) {
			const size_t i = B.Layers[l][k];
			if (std::find(Channels.begin(), Channels.end(), Spans[i].Channel) == Channels.end())
				Channels.push_back(Spans[i].Channel);
			Rows.insert(Rows.end(), Refs[i].begin(), Refs[i].end());
		}
		std::vector<std::pair<int, int> > Bars;
		B.LayerRel.push_back(Against(Channels, Rows, &Bars));
		LayerBars.push_back(Bars);
		for (size_t k = 0; k < B.Layers[l].size(); ++k)
			B.Rel[B.Layers[l][k]] = B.LayerRel.back();
	}
	// The main layer of each: the loudest of the layers sharing bars with it
	for (size_t l = 0; l < B.Layers.size(); ++l) {
		int Main = static_cast<int>(l);
		for (size_t m = 0; m < B.Layers.size(); ++m) {
			bool Together = false;
			for (size_t a = 0; a < LayerBars[l].size() && !Together; ++a)
				for (size_t b = 0; b < LayerBars[m].size() && !Together; ++b)
					Together = LayerBars[l][a].first < LayerBars[m][b].second && LayerBars[m][b].first < LayerBars[l][a].second;
			if (Together && B.LayerRel[m] > B.LayerRel[static_cast<size_t>(Main)])
				Main = static_cast<int>(m);
		}
		B.Main.push_back(Main);
	}
	for (size_t i = 0; i < Spans.size(); ++i)
		if (Spans[i].Role == ROLE_ECHO || Spans[i].Role == ROLE_LINE || Spans[i].Role == ROLE_BASS || Spans[i].Role == ROLE_DRUMS)
			B.Rel[i] = Against(std::vector<int>(1, Spans[i].Channel), Refs[i], 0);
	for (int c = 0; c < S.ChannelCount(); ++c)
		if (S.Channel(c).Kind == KIND_TRIANGLE && HasNotesIn(S, c, First, End)) {
			std::vector<std::pair<int, int> > Bars;
			const double Rel = Against(std::vector<int>(1, c), std::vector<std::pair<int, int> >(1, std::make_pair(First, End)), &Bars);
			if (!Bars.empty() && Rel > NO_LOUDNESS) {
				B.Triangle = c;
				B.TriangleRel = Rel;
			}
			break;
		}
	return B;
}

// How far a part plays under the melody (Low to High dB, negative over it) in words: "7.1 under", "1.2 over", "level with
// it", "from 1.0 over to 2.0 under"; for the chords (Chords) the melody's way round: "2.6 dB over" the chords, "1.5 dB
// under", "level with"
std::string GapText(double Low, double High, bool Chords)
{
	const char *const Plus = Chords ? "over" : "under", *const Minus = Chords ? "under" : "over";
	const char *const Unit = Chords ? " dB" : "";
	if (High - Low < 0.6) {
		const double Mid = (Low + High) / 2.0;
		if (std::fabs(Mid) < 0.05)
			return Chords ? "level with" : "level with it";
		return Format("%.1f%s %s", std::fabs(Mid), Unit, Mid > 0.0 ? Plus : Minus);
	}
	if (Low > -0.05)
		return Format("%.1f-%.1f%s %s", std::max(0.0, Low), High, Unit, Plus);
	if (High < 0.05)
		return Format("%.1f-%.1f%s %s", std::max(0.0, -High), -Low, Unit, Minus);
	return Format("from %.1f%s %s to %.1f%s %s", -Low, Unit, Minus, High, Unit, Plus);
}

// The balance in words, for mix's and the review's replies: "the melody (VRC6 Pulse 1) 2.6 dB over the chords, the echo
// 7.1 under, the bass 2.4 under and the triangle 2.5 under", each role's spread where it varies; Least and Most: how far
// the melody sits over the chords' main layers at the least and the most (NO_LOUDNESS for both without chords)
std::string BalanceText(Session &S, const std::vector<MixSpan> &Spans, const HeardBalance &B, int Melody, double &Least, double &Most)
{
	auto Spread = [&](int Role, double *pLow, double *pHigh) {
		double Low = 1e9, High = -1e9;
		for (size_t i = 0; i < Spans.size(); ++i) {
			if (Spans[i].Role != Role || B.Rel[i] <= NO_LOUDNESS)
				continue;
			if (Role == ROLE_CHORDS && (B.Layer[i] < 0 || B.Main[static_cast<size_t>(B.Layer[i])] != B.Layer[i]))
				continue;
			Low = std::min(Low, -B.Rel[i]);
			High = std::max(High, -B.Rel[i]);
		}
		if (pLow != 0) {
			*pLow = High < -1e8 ? NO_LOUDNESS : Low;
			*pHigh = High < -1e8 ? NO_LOUDNESS : High;
		}
		if (High < -1e8)
			return std::string();
		return GapText(Low, High, Role == ROLE_CHORDS);
	};
	const std::string Chords = Spread(ROLE_CHORDS, &Least, &Most), Echo = Spread(ROLE_ECHO, 0, 0), Line = Spread(ROLE_LINE, 0, 0),
		Bass = Spread(ROLE_BASS, 0, 0), Drums = Spread(ROLE_DRUMS, 0, 0);
	std::vector<std::string> Parts;
	if (!Echo.empty())
		Parts.push_back("the echo " + Echo);
	if (!Line.empty())
		Parts.push_back("a second line " + Line);
	if (!Bass.empty())
		Parts.push_back("the bass " + Bass);
	if (B.Triangle >= 0)
		Parts.push_back("the triangle " + GapText(-B.TriangleRel, -B.TriangleRel, false));
	if (!Drums.empty())
		Parts.push_back("the drums " + Drums);
	std::string Text = "the melody (" + S.Channel(Melody).FullName() + ")" + (Chords.empty() ? std::string(" with no chords") :
		" " + Chords + " the chords");
	for (size_t i = 0; i < Parts.size(); ++i)
		Text += (i + 1 == Parts.size() && Parts.size() > 1 ? " and " : ", ") + Parts[i];
	return Text;
}

// Where a calm or a lively mix puts each part as heard, in dB against the melody: the chords' main layer, an echo of the
// melody, a second line or an answering voice, the bass, the drums
struct HeardPlaces {
	double Chords, Echo, Line, Bass, Drums;
	double LineTop;	// a second line louder than this comes down to Line; a quieter one (an ornament too: a bell that
					// blinks, a bird) keeps its level
	double DrumsTop;	// drums louder than this come down to Drums; quieter ones keep the volumes they were written at,
						// never raised: the soft hi-hats of a stage (written at 4-7) stay soft. Three composers of a lively
						// stage ended with the drums 10-13 dB under the melody, where a mix had raised them to 6 under
};

HeardPlaces PlacesFor(bool Calm)
{
	const HeardPlaces CALM = { -2.5, -7.0, -4.0, -2.5, -11.0, -3.0, -10.0 }, LIVELY = { -3.5, -7.0, -3.5, -3.0, -11.0, -2.5, -10.0 };
	return Calm ? CALM : LIVELY;
}

// A 5B note that plays the chip's envelope (a buzz, or a sync buzz with the square), whose level the envelope sets
// whatever the note's volume (Sticky: the Vxx in effect as it starts, for an instrument without a mode sequence)
bool PlaysEnvelope(const Session &S, const NoteInfo &N, int Sticky)
{
	const InstrumentInfo *pInfo = FindInstrument(S.Song, N.Instrument);
	if (pInfo != 0 && !pInfo->Mode.Items.empty()) {
		for (size_t i = 0; i < pInfo->Mode.Items.size(); ++i)
			if (pInfo->Mode.Items[i] & 32)
				return true;
		return false;
	}
	return (Sticky & 4) != 0;
}

// The level an instrument's envelope holds a long note at, from a third of a second to a second in (the loudest there,
// for one that loops); 0 for a sound that dies away
int EnvelopeHold(const InstrumentInfo *pInfo)
{
	const std::vector<int> Held = HeldEnvelope(pInfo, 60);
	return *std::max_element(Held.begin() + 20, Held.end());
}

// A part's loudest as mix counts it, over some rows: the loudest it plays (each note's volume as its instrument's
// envelope lets it peak, and as high as a volume slide swells it), the volume and the envelope's peak that play it, the
// highest volume written, and its level in dB as a pulse's (on the 5B, whose steps are 3 dB, an envelope counts as it
// holds, as a pulse's would: a hold two steps under the peak takes 6 dB off there, not 1; Hold is that level, 0 when
// the peak counted)
struct PartPeak {
	int Played, Column, Envelope, Highest, Hold;
	double Db;
	PartPeak() : Played(0), Column(0), Envelope(15), Highest(0), Hold(0), Db(-60.0) {}
};

PartPeak PeakOf(Session &S, int Channel, const std::vector<std::pair<int, int> > &Rows, const std::vector<int> &Frames,
	const std::vector<char> &Buzz)
{
	const ChannelInfo &Info = S.Channel(Channel);
	const std::vector<NoteInfo> &Notes = S.Notes(Channel);
	PartPeak Out;
	auto Count = [&](int Volume, int Instrument) {
		const InstrumentInfo *pInfo = FindInstrument(S.Song, Instrument);
		const int Peak = Info.Kind == KIND_FM ? 15 : EnvelopePeak(pInfo);
		const int Hold = Info.Kind == KIND_SQUARE ? EnvelopeHold(pInfo) : 0;
		const int Plays = PlayedVolume(Info, Volume, Hold > 0 ? Hold : Peak);
		const double Db = Plays <= 0 ? -60.0 : LevelDb(Info, Plays) - (Hold > 0 ? 20.0 * std::log10(Hold / 15.0) : 0.0);
		Out.Highest = std::max(Out.Highest, Volume);
		if (Db > Out.Db + 1e-9 || (std::fabs(Db - Out.Db) < 1e-9 && Volume > Out.Column)) {
			Out.Played = Plays;
			Out.Column = Volume;
			Out.Envelope = Peak;
			Out.Hold = Hold;
			Out.Db = Db;
		}
	};
	for (size_t s = 0; s < Rows.size(); ++s) {
		for (size_t i = 0; i < Notes.size(); ++i) {
			const int Row = Notes[i].Row;
			if (Row >= Rows[s].first && Row < Rows[s].second && !(Row < static_cast<int>(Buzz.size()) && Buzz[static_cast<size_t>(Row)]))
				Count(Notes[i].Volume, Notes[i].Instrument);
		}
		int Swelling = NO_INSTRUMENT;
		const int Swell = SlidePeak(S.Cells(Channel), Rows[s].first, Rows[s].second, Info.EffectColumns, Frames, Swelling);
		if (Swell > 0)
			Count(Swell, Swelling);
	}
	return Out;
}

// The DPCM level (Zxx) a DPCM channel's rows play at, each row's own counted (0 before any)
std::vector<int> DacLevels(const std::vector<Cell> &Cells, int Columns)
{
	std::vector<int> Out(Cells.size(), 0);
	int Level = 0;
	for (size_t r = 0; r < Cells.size(); ++r) {
		for (int k = 0; k < std::min(EFFECT_COLUMNS, Columns); ++k)
			if (Cells[r].Effect[k] == EFF_DAC)
				Level = Cells[r].Param[k] & 0x7F;
		Out[r] = Level;
	}
	return Out;
}

std::string MixTool(Session &S, const Json &Args)
{
	if (!S.Song.DirectChanges)
		throw Problem("Mixing changes the volumes of the whole song, which needs direct changes; the user can allow them in "
			"File > Connect Claude Code.");
	// The style: soft (the default) or full, each part's loudest note at its role's level; or as heard, calm or lively,
	// each part's loudness (as the stems measure it) set against the melody's
	const bool Picked = Arg(Args, "levels") != 0 || Arg(Args, "dac") != 0 || Arg(Args, "width") != 0;
	std::string Style = Squeezed(StringArg(Args, "style", Picked ? "" : "soft"));
	TrackStyle Chosen;
	if (Arg(Args, "style") == 0 && !Picked) {
		Chosen = ChooseStyle(S, -1, "gives the calm mix (the melody 2-3 dB over the chords, as heard)", "soft");
		if (Chosen.Style == STYLE_CALM)
			Style = "calm";
	}
	if (Style == "ambient" || Style == "night" || Style == "peaceful")
		Style = "calm";
	else if (Style == "any" || Style == "normal")
		Style = "soft";
	// The stereo picture: how far the parts that aren't the melody, the bass or the drums go to the sides (-1: as they are)
	double Width = -1.0;
	{
		const std::string Word = Squeezed(StringArg(Args, "width", "keep"));
		if (Word == "mono" || Word == "center" || Word == "centre" || Word == "middle" || Word == "none")
			Width = 0.0;
		else if (Word == "narrow")
			Width = 0.25;
		else if (Word == "wide")
			Width = 0.5;
		else if (Word == "full" || Word == "widest")
			Width = 1.0;
		else if (Word != "keep")
			throw Problem("width: keep (the pans as they are, the default), mono (every part in the middle), narrow, wide or "
				"full (how far the side parts go).");
	}
	if (!Style.empty() && Style != "soft" && Style != "full" && Style != "quiet" && Style != "loud" && Style != "atmospheric" &&
		Style != "calm" && Style != "lively")
		throw Problem("style: soft (quiet pulses under a warm triangle, as atmospheric tracks mix), full (everything near "
			"full volume), calm (as heard, the melody only 2-3 dB over the chords: night and ambient tracks) or lively (as heard, "
			"the melody 3-4 dB over the parts: stages that bounce without pressing).");
	// The faders back at 0 dB first (faders reset), so the volumes in the notes set the balance, as NSF files play it: the
	// fix check_song and review_arrangement give for faders doing the mix's work. One Ctrl+Z for both
	const std::string Faders = Squeezed(StringArg(Args, "faders", "keep"));
	if (Faders != "keep" && Faders != "reset")
		throw Problem("faders: keep (the default: the mixer's faders stay, counted in how loud each part plays) or reset (every fader "
			"back to 0 dB first, the pans, Soft and Space kept, so the notes' volumes set the balance).");
	if (Faders == "reset") {
		const MixerSettings Before = CurrentMixer(S);
		MixerSettings Next = Before;
		std::string Moved;
		for (size_t c = 0; c < Next.Levels.size() && c < static_cast<size_t>(S.ChannelCount()); ++c)
			if (Next.Levels[c] != 0) {
				Moved += (Moved.empty() ? "" : ", ") + Format("%s %+.1f dB", S.Channel(static_cast<int>(c)).FullName().c_str(),
					Next.Levels[c] / 10.0);
				Next.Levels[c] = 0;
			}
		Json Rest = Json::MakeObject();
		for (size_t i = 0; i < Args.Members().size(); ++i)
			if (Args.Members()[i].first != "faders")
				Rest.Set(Args.Members()[i].first, Args.Members()[i].second);
		if (Moved.empty())
			return "Every fader is at 0 dB already. " + MixTool(S, Rest);
		// As heard (calm, lively), the melody keeps its level and the parts are set against it: it plays as loud as it did
		// with its fader, less the lift the others' faders gave them beyond what their volumes can make up (the drums aside,
		// which the mix only brings down), so each part can still reach its place in the notes. Left at 15, the local model's
		// lead (-4.5 dB) came out 8.9 dB over its chords, which were at 15 already
		std::string Carried;
		if ((Style == "calm" || Style == "lively") && Arg(Rest, "levels") == 0) {
			int From = 1, To = S.Time.BarCount();
			if (RangeGiven(Rest))
				BarRange(S, Rest, From, To);
			const int First = S.Time.BarStart(From), End = std::min(S.Time.TotalRows(), S.Time.BarEnd(To));
			const int Melody = Arg(Rest, "melody_channel") != 0 ? ChannelArg(S, Rest, "melody_channel") : GuessMelodyChannel(S, First, End);
			auto Loudest = [&](int c) {
				int Most = 0;
				const std::vector<NoteInfo> Notes = NotesIn(S.Notes(c), First, End);
				for (size_t i = 0; i < Notes.size(); ++i)
					Most = std::max(Most, Notes[i].Volume);
				return Most;
			};
			auto HasVolume = [&](int c) { return S.Channel(c).Kind != KIND_TRIANGLE && S.Channel(c).Kind != KIND_DPCM; };
			if (Melody >= 0 && HasVolume(Melody)) {
				double Lift = 0.0;
				for (int c = 0; c < S.ChannelCount(); ++c) {
					const int Role = c == Melody ? ROLE_NONE : MixRole(S, c, Melody, First, End);
					if (Role != ROLE_CHORDS && Role != ROLE_LINE && Role != ROLE_BASS && Role != ROLE_ECHO)
						continue;
					ChannelInfo Unfaded = S.Channel(c);
					Unfaded.MixLevel = 0;
					const int Most = Loudest(c);
					const double Room = HasVolume(c) && Most > 0 ? LevelDb(Unfaded, std::min(15, Most + 7)) - LevelDb(Unfaded, Most) : 0.0;
					Lift = std::max(Lift, FaderDb(S.Channel(c)) - Room);
				}
				const ChannelInfo &Lead = S.Channel(Melody);
				ChannelInfo Unfaded = Lead;
				Unfaded.MixLevel = 0;
				const int Most = Loudest(Melody);
				const int Level = Most > 0 ? VolumeForDb(Unfaded, LevelDb(Lead, Most) - Lift) : Most;
				if (Level < Most) {
					Json Levels = Json::MakeObject();
					Levels.Set(Lead.FullName(), Level);
					Rest.Set("levels", Levels);
					Carried = Format(", the melody's loudest at %d where it was %d (%s)", Level, Most, Lift >= 0.5 ? "under its fader's "
						"level by what the others' faders lifted them" : "as loud as it played with its fader");
				}
			}
		}
		std::string Error, Text;
		S.Host().BeginGroup();
		try {
			if (!S.Host().SetMixer(Next, Error))
				throw Problem(Error.empty() ? "FamiTracker couldn't change the mixer." : Error);
			S.Load();
			Text = MixTool(S, Rest);
		}
		catch (...) {
			std::string Ignored;
			S.Host().SetMixer(Before, Ignored);
			S.Host().EndGroup();
			throw;
		}
		S.Host().EndGroup();
		return "Set the faders back to 0 dB (they were " + Moved + "), so the notes' volumes set the balance" + Carried + "; one Ctrl+Z "
			"undoes that and the mix. " + Text;
	}
	const bool Soft = Style == "soft" || Style == "quiet" || Style == "atmospheric";
	const bool Calm = Style == "calm", Heard = Calm || Style == "lively";
	int From = 1, To = S.Time.BarCount();
	const bool Range = RangeGiven(Args);
	if (Range)
		BarRange(S, Args, From, To);
	const int First = S.Time.BarStart(From), End = std::min(S.Time.TotalRows(), S.Time.BarEnd(To));
	const int Melody = Arg(Args, "melody_channel") != 0 ? ChannelArg(S, Args, "melody_channel") : GuessMelodyChannel(S, First, End);

	std::set<int> Leveled;	// channels given a level: mixed as one part
	{
		const Json *pGiven = Arg(Args, "levels");
		if (pGiven != 0 && pGiven->IsObject())
			for (size_t i = 0; i < pGiven->Members().size(); ++i)
				Leveled.insert(ParseChannel(S, Json(pGiven->Members()[i].first), "levels"));
	}
	std::vector<MixSpan> Spans = MixSpans(S, Melody, First, End, Leveled);
	// Over some bars, each part keeps its place in the rest of the song: its loudest (or its loudness, as heard) is
	// counted where it plays that role in the whole song, so mixing section after section doesn't even them out
	std::vector<int> Voices;
	std::vector<MixSpan> Whole;
	if (Range)
		Whole = MixSpans(S, Melody, 0, S.Time.TotalRows(), Leveled);
	if (Heard) {
		Voices = ChordVoicesIn(S, First, End, Melody);
		HeardRoles(S, Voices, Spans);
		if (Range) {
			std::vector<int> WholeVoices = ChordVoicesIn(S, 0, S.Time.TotalRows(), Melody);
			HeardRoles(S, WholeVoices, Whole);
		}
	}
	std::vector<std::vector<std::pair<int, int> > > Refs(Spans.size());
	for (size_t i = 0; i < Spans.size(); ++i) {
		for (size_t w = 0; Range && Leveled.count(Spans[i].Channel) == 0 && w < Whole.size(); ++w)
			if (Whole[w].Channel == Spans[i].Channel && Whole[w].Role == Spans[i].Role)
				Refs[i].push_back(std::make_pair(Whole[w].First, Whole[w].End));
		if (Refs[i].empty())
			Refs[i].push_back(std::make_pair(Spans[i].First, Spans[i].End));
	}
	// As heard, the parts are set against the melody where they play with it in these bars (the melody keeping its own
	// level from the rest of the song): a quiet intro's parts follow its quiet melody down
	std::vector<std::vector<std::pair<int, int> > > Local(Spans.size());
	for (size_t i = 0; i < Spans.size(); ++i)
		Local[i].push_back(std::make_pair(Spans[i].First, Spans[i].End));
	std::vector<int> SpanCount(static_cast<size_t>(S.ChannelCount()), 0);
	for (size_t i = 0; i < Spans.size(); ++i)
		++SpanCount[static_cast<size_t>(Spans[i].Channel)];

	// The loudest volume each part gets: by its role for a style, as loud on its chip as that
	// volume on a pulse (a chip too quiet for its parts' levels plays the loudest at 15 and the rest as
	// far under it), or as given
	std::map<std::string, double> Short;	// per chip: how far its loudest part falls short of its level at 15
	bool Under = false;						// parts on the VRC6 Plus's soft layer, kept under the VRC6
	for (size_t i = 0; i < Spans.size(); ++i) {
		MixSpan &P = Spans[i];
		if (Style.empty() || Heard || P.Role == ROLE_NONE || P.Role == ROLE_AMBIENCE)
			continue;
		static const int SOFT[] = { -1, 9, 4, 6, 7, 10, 10 }, FULL[] = { -1, 15, 6, 12, 13, 15, 15 };
		const int AsPulse = (Soft ? SOFT : FULL)[P.Role];
		P.Level = 20.0 * std::log10(AsPulse / 15.0);
		if (IsSoftLayer(S.Channel(P.Channel)) && P.Role != ROLE_MELODY) {
			P.Level -= SOFT_LAYER_DB;
			Under = true;
		}
		ChannelInfo Unfaded = S.Channel(P.Channel);
		Unfaded.MixLevel = 0;	// a chip's shortfall is its own, whatever one channel's fader does
		const double Over = P.Level - LevelDb(Unfaded, 15);
		double &Most = Short[S.Channel(P.Channel).Chip];
		Most = std::max(Most, Over);
		P.Target = AsPulse;
	}
	bool Fm = false, Square = false, Quiet = false, Loud = false;
	for (size_t i = 0; i < Spans.size(); ++i) {
		MixSpan &P = Spans[i];
		if (P.Target < 1)
			continue;
		const ChannelInfo &Info = S.Channel(P.Channel);
		if (StepVolume(Info) || Info.Chip == "N163" || Info.Chip == "FDS") {
			P.Target = VolumeForDb(Info, P.Level - Short[Info.Chip]);
			Fm = Fm || Info.Kind == KIND_FM;
			Square = Square || Info.Kind == KIND_SQUARE;
			Quiet = Quiet || (Info.Chip == "N163" && FullDb(Info) < -1.0);
			Loud = Loud || Info.Chip == "FDS";
		}
		else if (Info.MixLevel != 0)
			P.Target = VolumeForDb(Info, P.Level);	// as loud as its role with FamiTracker's mixer's fader on it
	}
	const Json *pLevels = Arg(Args, "levels");
	if (pLevels != 0) {
		if (!pLevels->IsObject())
			throw Problem("levels: an object of channels and their loudest volume, like {\"VRC6 Pulse 1\": 9, \"Noise\": 10}.");
		for (size_t i = 0; i < pLevels->Members().size(); ++i) {
			const int c = ParseChannel(S, Json(pLevels->Members()[i].first), "levels");
			const Json &Value = pLevels->Members()[i].second;
			if (!Value.IsNumber() || Value.Number() < 1 || Value.Number() > 15)
				throw Problem("levels: each channel's loudest volume is 1-15.");
			if (S.Channel(c).Kind == KIND_TRIANGLE || S.Channel(c).Kind == KIND_DPCM)
				throw Problem(Format("%s has no volume of its own; dac softens the triangle (and the noise).", S.Channel(c).FullName().c_str()));
			for (size_t k = 0; k < Spans.size(); ++k)
				if (Spans[k].Channel == c)
					Spans[k].Target = static_cast<int>(Value.Number());
		}
	}
	// The DPCM level: soft mixes soften the triangle and the noise a little; calm and lively ones set the triangle's
	// place with it where it plays with the melody (below), and otherwise leave it
	int Dac = Soft ? 0x30 : (Style == "full" || Style == "loud") ? 0 : -1;
	const Json *pDac = Arg(Args, "dac");
	if (pDac != 0) {
		if (pDac->IsNumber())
			Dac = IntArg(Args, "dac", 0, 0, 127);
		else {
			const std::string Word = Squeezed(StringArg(Args, "dac"));
			// A level as text: "64", or the effect itself, "Z40" (hexadecimal, as FamiTracker shows it)
			const bool Effect = Word.size() == 3 && Word[0] == 'z' && std::isxdigit(static_cast<unsigned char>(Word[1])) &&
				std::isxdigit(static_cast<unsigned char>(Word[2]));
			const bool Digits = !Word.empty() && Word.size() <= 3 && Word.find_first_not_of("0123456789") == std::string::npos;
			if (Effect || Digits) {
				Dac = Effect ? static_cast<int>(std::strtol(Word.c_str() + 1, 0, 16)) : std::atoi(Word.c_str());
				if (Dac > 127)
					throw Problem("dac: a level 0-127 (Z00-Z7F).");
			}
			else if (Word == "full" || Word == "off" || Word == "zero")
				Dac = 0;
			else if (Word == "warm" || Word == "light")
				Dac = 0x30;
			else if (Word == "soft" || Word == "medium")
				Dac = 0x50;
			else if (Word == "softest" || Word == "strong" || Word == "max")
				Dac = 0x7F;
			else if (Word == "keep" || Word == "none" || Word == "leave")
				Dac = -1;
			else
				throw Problem("dac: full (Z00), warm (Z30), soft (Z50), softest (Z7F), keep, or a level 0-127.");
		}
	}
	int Dpcm = -1;
	for (int c = 0; c < S.ChannelCount(); ++c)
		if (S.Channel(c).Kind == KIND_DPCM)
			Dpcm = c;
	if (Dac >= 0 && Dpcm < 0)
		throw Problem("The song has no DPCM channel to set the level on.");
	const bool Samples = Dpcm >= 0 && HasNotesIn(S, Dpcm, 0, S.Time.TotalRows());

	// The 5B's envelope notes (a buzz, a sync buzz) play at the envelope's own level whatever their volume: the rows of
	// each channel's that do keep their volumes
	std::vector<std::vector<char> > Buzz(static_cast<size_t>(S.ChannelCount()));
	std::vector<int> Buzzes(static_cast<size_t>(S.ChannelCount()), 0);
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (S.Channel(c).Kind != KIND_SQUARE)
			continue;
		const std::vector<NoteInfo> &Notes = S.Notes(c);
		const std::vector<int> Sticky = StickyAt(S.Cells(c), Notes, S.Channel(c).EffectColumns, EFF_DUTY_CYCLE);
		std::vector<char> &Rows = Buzz[static_cast<size_t>(c)];
		Rows.assign(S.Cells(c).size(), 0);
		for (size_t i = 0; i < Notes.size(); ++i) {
			if (!PlaysEnvelope(S, Notes[i], Sticky[i]))
				continue;
			if (Notes[i].Row >= First && Notes[i].Row < End)
				++Buzzes[static_cast<size_t>(c)];
			for (int r = Notes[i].Row; r < Notes[i].Row + std::max(1, Notes[i].Rows) && r < static_cast<int>(Rows.size()); ++r)
				Rows[static_cast<size_t>(r)] = 1;
		}
	}
	const std::vector<int> Frames = RowFramesOf(S);
	std::vector<PartPeak> Peaks, Own;	// each part's loudest where it plays its role in the song (Refs), and in these bars
	for (size_t i = 0; i < Spans.size(); ++i) {
		const std::vector<char> &Buzzing = Buzz[static_cast<size_t>(Spans[i].Channel)];
		Peaks.push_back(PeakOf(S, Spans[i].Channel, Refs[i], Frames, Buzzing));
		Own.push_back(Range ? PeakOf(S, Spans[i].Channel, std::vector<std::pair<int, int> >(1, std::make_pair(Spans[i].First,
			Spans[i].End)), Frames, Buzzing) : Peaks.back());
	}

	auto LabelOf = [&](const MixSpan &P) {
		const int c = P.Channel;
		std::string Label = S.Channel(c).FullName();
		if (P.Role != ROLE_NONE || SpanCount[static_cast<size_t>(c)] > 1)
			Label += std::string(" (") + (P.Role != ROLE_NONE ? RoleName(P.Role) : "") + (SpanCount[static_cast<size_t>(c)] > 1 ?
				(std::string(P.Role != ROLE_NONE ? ", " : "") + RangeText(S.Time.BarOf(P.First), S.Time.BarOf(P.End - 1))) : "") + ")";
		return Label;
	};

	// The stereo picture: the melody, the bass and the drums in the middle; the other parts out to the sides by Width,
	// an echo first to the right, then each part to the side with fewer, and chord voices sounding together spread
	// over the width, the lowest on the left
	auto ApplyPans = [&](Draft &Into, std::vector<std::string> *pDone, int &Lost) {
		std::vector<double> Place(Spans.size(), 0.0);
		std::vector<bool> Placed(Spans.size(), false);
		int Lefts = 0, Rights = 0;
		auto Overlaps = [&](const MixSpan &a, const MixSpan &b) { return a.First < b.End && b.First < a.End; };
		auto Middle = [&](const MixSpan &P) { return MiddleOf(NotesIn(S.Notes(P.Channel), P.First, P.End), 0); };
		for (int Pass = 0; Pass < 3 && Width > 0.0; ++Pass) {
			const int Role = Pass == 0 ? static_cast<int>(ROLE_ECHO) : Pass == 1 ? static_cast<int>(ROLE_CHORDS) : static_cast<int>(ROLE_LINE);
			for (size_t i = 0; i < Spans.size(); ++i) {
				if (Spans[i].Role != Role || Placed[i])
					continue;
				std::vector<size_t> Group(1, i);
				if (Role == ROLE_CHORDS)
					for (size_t k = 0; k < Spans.size(); ++k)
						if (k != i && !Placed[k] && Spans[k].Role == ROLE_CHORDS && Spans[k].Channel != Spans[i].Channel &&
							Overlaps(Spans[i], Spans[k]))
							Group.push_back(k);
				if (Group.size() >= 2) {
					std::stable_sort(Group.begin(), Group.end(), [&](size_t a, size_t b) { return Middle(Spans[a]) < Middle(Spans[b]); });
					for (size_t g = 0; g < Group.size(); ++g) {
						Place[Group[g]] = -Width + 2.0 * Width * static_cast<double>(g) / static_cast<double>(Group.size() - 1);
						Placed[Group[g]] = true;
					}
					continue;
				}
				const bool Right = Role == ROLE_ECHO ? Rights <= Lefts : Rights < Lefts;
				Place[i] = Right ? Width : -Width;
				++(Right ? Rights : Lefts);
				Placed[i] = true;
			}
		}
		std::string Middles, Sides;
		std::set<int> Centered;
		for (size_t i = 0; i < Spans.size(); ++i) {
			const MixSpan &P = Spans[i];
			const std::vector<NoteInfo> Notes = NotesIn(S.Notes(P.Channel), P.First, P.End);
			std::vector<std::pair<int, int> > Want;
			for (size_t n = 0; n < Notes.size(); ++n)
				Want.push_back(std::make_pair(Notes[n].Row, PanParam(Place[i])));
			if (!PutPans(Into.Cells(P.Channel), P.First, P.End, S.Channel(P.Channel).EffectColumns, Want))
				++Lost;
			if (Notes.empty())
				continue;
			const std::string Label = S.Channel(P.Channel).FullName() + (P.Role != ROLE_NONE ? std::string(" (") + RoleName(P.Role) + ")" : "") +
				(SpanCount[static_cast<size_t>(P.Channel)] > 1 ? " in " + RangeText(S.Time.BarOf(P.First), S.Time.BarOf(P.End - 1)) : "");
			if (Place[i] == 0.0) {
				if (Centered.insert(P.Channel).second || SpanCount[static_cast<size_t>(P.Channel)] > 1)
					Middles += (Middles.empty() ? "" : ", ") + Label;
			}
			else
				Sides += (Sides.empty() ? "" : ", ") + Label + " " + PanName(PanParam(Place[i]));
		}
		if (pDone != 0)
			pDone->push_back(Width == 0.0 || Sides.empty() ? "every part in the middle (mono)" :
				"stereo: " + Sides + (Middles.empty() ? "" : "; in the middle " + Middles));
	};

	// As heard: each part's shift in dB, so that it plays at its place against the melody (which keeps its level, unless
	// levels gives it one); for the parts mixed by a given level or with no role, none
	const HeardPlaces Places = PlacesFor(Calm);
	std::vector<double> Shifts(Spans.size(), 0.0), Aims(Spans.size(), NO_LOUDNESS);
	std::vector<char> ByEar(Spans.size(), 0);
	std::vector<std::string> DrumsWhy(Spans.size());	// as heard: why the drums kept their volumes, or came down
	double MelodyShift = 0.0;
	int TriangleDac = -1, TriangleNow = 0;
	if (Heard && Melody >= 0) {
		Draft Panned(S);	// the pans as the mix leaves them (width), which the loudness hears
		int Ignored = 0;
		if (Width >= 0.0)
			ApplyPans(Panned, 0, Ignored);
		Hearing H(S, &Panned);
		const HeardBalance B = HearBalance(S, H, Spans, Local, Melody, Voices, First, End);
		for (size_t i = 0; i < Spans.size(); ++i) {
			if (Spans[i].Role != ROLE_MELODY || Peaks[i].Played <= 0)
				continue;
			const ChannelInfo &Info = S.Channel(Spans[i].Channel);
			// The melody keeps its level: raised, it would leave behind what keeps its own (a swell of wind, a buzz) and
			// the parts that can't follow it past 15
			MelodyShift = Spans[i].Target >= 1 ? LevelDb(Info, Spans[i].Target) - LevelDb(Info, Peaks[i].Highest) : 0.0;
			if (Spans[i].Target < 1) {
				Shifts[i] = 0.0;
				ByEar[i] = 1;
			}
		}
		// The chords' main layers at their place; the other layers playing with one keep their place under it, but
		// together at least 3 dB under it (a soft layer's pad under the VRC6's chords)
		std::vector<double> LayerShift(B.Layers.size(), 0.0);
		for (size_t m = 0; m < B.Layers.size(); ++m) {
			if (B.Main[m] != static_cast<int>(m) || B.LayerRel[m] <= NO_LOUDNESS)
				continue;
			LayerShift[m] = Places.Chords - B.LayerRel[m] + MelodyShift;
			double Together = 0.0;
			std::vector<size_t> Others;
			for (size_t l = 0; l < B.Layers.size(); ++l)
				if (l != m && B.Main[l] == static_cast<int>(m) && B.LayerRel[l] > NO_LOUDNESS) {
					Others.push_back(l);
					Together += std::pow(10.0, (B.LayerRel[l] + LayerShift[m] - MelodyShift) / 10.0);
				}
			const double Over = Others.empty() ? 0.0 : std::max(0.0, 10.0 * std::log10(Together) - (Places.Chords - SOFT_LAYER_DB));
			for (size_t o = 0; o < Others.size(); ++o)
				LayerShift[Others[o]] = LayerShift[m] - Over;
		}
		for (size_t i = 0; i < Spans.size(); ++i) {
			const MixSpan &P = Spans[i];
			if (P.Target >= 1 || B.Rel[i] <= NO_LOUDNESS || Peaks[i].Played <= 0)
				continue;
			if (P.Role == ROLE_CHORDS && B.Layer[i] >= 0) {
				Shifts[i] = LayerShift[static_cast<size_t>(B.Layer[i])];
				Aims[i] = B.Rel[i] + Shifts[i] - MelodyShift;
				ByEar[i] = 1;
				continue;
			}
			const double Place = P.Role == ROLE_ECHO ? Places.Echo : P.Role == ROLE_LINE ? Places.Line : P.Role == ROLE_BASS ?
				Places.Bass : P.Role == ROLE_DRUMS ? Places.Drums : NO_LOUDNESS;
			if (Place <= NO_LOUDNESS)
				continue;
			ByEar[i] = 1;
			if (P.Role == ROLE_LINE && B.Rel[i] <= Places.LineTop) {
				Shifts[i] = MelodyShift;	// with the melody, where levels moves it
				continue;
			}
			if (P.Role == ROLE_DRUMS) {
				// Under the melody as it will play: as written unless louder than DrumsTop, then down to their place
				const double Under = MelodyShift - B.Rel[i];
				const char *const Kind = Calm ? "calm" : "lively";
				if (B.Rel[i] - MelodyShift <= Places.DrumsTop) {
					DrumsWhy[i] = Format(" (as written: %.1f dB under the melody, and a %s mix puts drums %.0f-%.0f dB under it and never "
						"raises them)", Under, Kind, -Places.DrumsTop, -2.0 * Places.Drums + Places.DrumsTop);
					continue;
				}
				DrumsWhy[i] = Format(" (from %.1f dB under the melody: a %s mix brings drums louder than %.0f dB under it down to %.0f, "
					"never up)", Under, Kind, -Places.DrumsTop, -Places.Drums);
				Shifts[i] = std::min(0.0, Place - B.Rel[i] + MelodyShift);
				Aims[i] = Place;
				continue;
			}
			Shifts[i] = Place - B.Rel[i] + MelodyShift;
			Aims[i] = Place;
		}
		// The triangle has no volume: the DPCM level gives it its place (the noise moves with it, so the drums make up
		// for it), unless dac was given
		if (B.Triangle >= 0 && pDac == 0) {
			const double Gain = std::pow(10.0, FaderDb(S.Channel(B.Triangle)) / 20.0);
			const std::vector<int> Levels = DacLevels(S.Cells(Dpcm), S.Channel(Dpcm).EffectColumns);
			TriangleNow = First < static_cast<int>(Levels.size()) ? Levels[static_cast<size_t>(First)] : 0;
			const double Base = B.TriangleRel - MelodyShift - 20.0 * std::log10(std::max(0.01, TrianglePinShare(TriangleNow, Gain)));
			double BestMiss = 1e9;
			for (int Level = 0; Level <= (Samples ? 0x40 : 0x7F); ++Level) {
				const double Miss = std::fabs(Base + 20.0 * std::log10(std::max(0.01, TrianglePinShare(Level, Gain))) - Places.Bass);
				if (Miss < BestMiss - 1e-9) {
					BestMiss = Miss;
					TriangleDac = Level;
				}
			}
			Dac = TriangleDac;
			for (size_t i = 0; i < Spans.size(); ++i)
				if (ByEar[i] && Spans[i].Role == ROLE_DRUMS)	// never over the volumes they were written at
					Shifts[i] = std::min(0.0, Shifts[i] - 20.0 * std::log10(std::max(0.01, TriangleShare(Dac)) /
						std::max(0.01, TriangleShare(TriangleNow))));
		}
	}

	// The DPCM level where the mix starts and where the loop comes back, and on every sample there (a sample can start
	// from a level of its own: the sampled drums start from silence, and would leave the channel there). Over some bars
	// whose levels step (Zxx written on purpose), the steps move by as much as the first, rather than all becoming one
	std::string DacText, DacWarning;
	auto WriteDac = [&](Draft &Into) {
		DacText.clear();
		DacWarning.clear();
		if (Dac < 0)
			return;
		const int Columns = S.Channel(Dpcm).EffectColumns;
		const std::vector<Cell> &Old = S.Cells(Dpcm);
		std::vector<int> Rows(1, First);
		const int Loop = Flow(S).LoopRow(S.Time.PatternLength);
		if (Loop > First && Loop < End)
			Rows.push_back(Loop);
		std::vector<int> Hits;
		if (Dac > 0) {
			const std::vector<NoteInfo> Played = NotesIn(S.Notes(Dpcm), First, End);
			for (size_t i = 0; i < Played.size(); ++i)
				if (std::find(Rows.begin(), Rows.end(), Played[i].Row) == Rows.end())
					Hits.push_back(Played[i].Row);
		}
		const size_t Marks = Rows.size();
		Rows.insert(Rows.end(), Hits.begin(), Hits.end());
		// The levels the song has, row by row
		const std::vector<int> Levels = DacLevels(Old, Columns);
		auto LevelAt = [&](int Row) { return Row < static_cast<int>(Levels.size()) ? Levels[static_cast<size_t>(Row)] : 0; };
		bool Steps = false;
		const int Start = LevelAt(First);
		for (int r = First + 1; Range && r < End && !Steps; ++r)
			Steps = LevelAt(r) != Start;
		const int Move = Dac - Start;
		auto LevelFor = [&](int Row) { return Steps ? std::max(0, std::min(127, LevelAt(Row) + Move)) : Dac; };
		std::vector<Cell> &Cells = Into.Cells(Dpcm);
		int Missed = 0;
		if (Steps)
			for (int r = First + 1; r < End && r < static_cast<int>(Cells.size()); ++r)
				for (int k = 0; k < std::min(EFFECT_COLUMNS, Columns); ++k)
					if (Cells[static_cast<size_t>(r)].Effect[k] == EFF_DAC)
						Cells[static_cast<size_t>(r)].Param[k] = static_cast<unsigned char>(LevelFor(r));
		for (size_t i = 0; i < Rows.size(); ++i) {
			Cell &C = Cells[static_cast<size_t>(Rows[i])];
			const int Level = LevelFor(Rows[i]);
			bool Placed = false;
			for (int k = 0; k < EFFECT_COLUMNS && !Placed; ++k)
				if (C.Effect[k] == EFF_DAC) {
					C.Param[k] = static_cast<unsigned char>(Level);
					Placed = true;
				}
			if (!Placed && !AddEffect(C, EFF_DAC, Level, Columns)) {
				if (i >= Marks) {
					++Missed;
					continue;
				}
				throw Problem(Format("The DPCM channel has no free effect column at %s for the level (all four are full).",
					S.Time.Position(Rows[i]).c_str()));
			}
		}
		if (Missed > 0)
			DacWarning = Format("%s had no free effect column for the level (all four were full), so the level "
				"goes back to the sample's own after %s.", Plural(Missed, "sample", "samples").c_str(), Missed == 1 ? "it" : "them");
		const int Share = static_cast<int>(std::floor(100.0 * TriangleShare(Dac) + 0.5));
		DacText = Format("the DPCM level Z%02X at %s%s%s, so the triangle and the noise play at about %d%%", Dac,
			S.Time.Position(First).c_str(), Marks > 1 ? (" and where the loop starts (" + S.Time.Position(Rows[1]) + ")").c_str() : "",
			Hits.empty() ? "" : (" and with each of its " + Plural(static_cast<int>(Hits.size()), "sample", "samples") +
				" (which would reset it)").c_str(), Share);
		if (Steps)
			DacText += Format(", its later steps in these bars moved with it (%+d)", Move);
		if (Samples && Dac > 0x40)
			DacText += " (samples on the DPCM channel start from that level: at a high one they have less room and can clip; "
				"Z30-Z40 suits songs with samples)";
	};

	// Each part's volumes scaled, each as much under its loudest as it was (the VRC7 and the 5B count 3 dB a step, the
	// others in proportion), its volume slides with them; the 5B's envelope notes keep theirs
	int SlidesLost = 0;
	std::vector<double> Missed(Spans.size(), 0.0);	// as heard: how far a part fell short of its place at volume 15 or 1
	auto Scale = [&](Draft &Into, std::vector<std::string> *pDone) {
		SlidesLost = 0;
		for (size_t p = 0; p < Spans.size(); ++p) {
			const MixSpan &P = Spans[p];
			const PartPeak &Peak = Peaks[p];
			const int c = P.Channel, Want = P.Target;
			if ((Want < 1 && !ByEar[p]) || Peak.Played <= 0)
				continue;
			const ChannelInfo &Info = S.Channel(c);
			const std::string Label = LabelOf(P);
			// A level given in levels is the loudest volume as written (a pad's 8 stays 8, whatever its envelope); a
			// style's, as the part plays
			const bool Given = Leveled.count(c) > 0;
			double Shift = ByEar[p] ? Shifts[p] : Given ? LevelDb(Info, Want) - LevelDb(Info, Peak.Highest) : LevelDb(Info, Want) - Peak.Db;
			if (ByEar[p]) {
				// Its highest volume here can't pass 15 (the drums the volumes they were written at), nor its softest go under 1
				const double Room = P.Role == ROLE_DRUMS ? 0.0 : LevelDb(Info, 15) - LevelDb(Info, Own[p].Highest);
				const double Floor = LevelDb(Info, 1) - LevelDb(Info, Own[p].Highest);
				Missed[p] = Shift > Room ? Shift - Room : Shift < Floor ? Shift - Floor : 0.0;
				Shift = std::max(Floor, std::min(Room, Shift));
			}
			auto Scaled = [&](int Volume) {
				return Volume <= 0 ? 0 : VolumeForDb(Info, LevelDb(Info, Volume) + Shift);
			};
			bool Same = true;	// as heard, or for an envelope counted as it holds: every volume there stays as it is
			for (int r = P.First; r < P.End && r < static_cast<int>(S.Cells(c).size()) && Same; ++r)
				Same = S.Cells(c)[static_cast<size_t>(r)].Volume >= NO_VOLUME || Scaled(S.Cells(c)[static_cast<size_t>(r)].Volume) ==
					S.Cells(c)[static_cast<size_t>(r)].Volume;
			Same = Same && Scaled(StateAt(S.Cells(c), P.First, Info.EffectColumns).Volume) == StateAt(S.Cells(c), P.First, Info.EffectColumns).Volume;
			if (ByEar[p] || Given || Peak.Hold > 0 ? Same : Peak.Played == Want) {
				if (pDone != 0)
					pDone->push_back(Format("%s stays at %d", Label.c_str(), ByEar[p] || Given || Peak.Hold > 0 ? Own[p].Highest :
						Own[p].Played) + DrumsWhy[p]);
				continue;
			}
			// The change in words; over some bars without the part's loudest in the song, these bars' own loudest, then
			// the song's
			auto Told = [&](int From, int To) {
				if (Own[p].Highest == Peak.Highest && Own[p].Played == Peak.Played)
					return Format("%s loudest %d to %d", Label.c_str(), From, To);
				return Format("%s loudest %d to %d, as the song's %d to %d", Label.c_str(), Own[p].Highest, Scaled(Own[p].Highest), From, To);
			};
			std::vector<Cell> &Cells = Into.Cells(c);
			bool FirstNote = true;
			const int Entering = StateAt(S.Cells(c), P.First, Info.EffectColumns).Volume;	// as the song has it, before any mixing
			const std::vector<char> &Buzzing = Buzz[static_cast<size_t>(c)];
			for (int r = P.First; r < P.End && r < static_cast<int>(Cells.size()); ++r) {
				Cell &C = Cells[static_cast<size_t>(r)];
				if (r < static_cast<int>(Buzzing.size()) && Buzzing[static_cast<size_t>(r)]) {
					FirstNote = FirstNote && !C.HasNote();
					continue;
				}
				if (C.Volume < NO_VOLUME)
					C.Volume = static_cast<unsigned char>(Scaled(C.Volume));
				else if (FirstNote && C.HasNote())
					C.Volume = static_cast<unsigned char>(Scaled(Entering));
				if (C.HasNote())
					FirstNote = false;
			}
			// Volume slides keep their shape at the new level
			const SlideMix Slides = MixSlides(S.Cells(c), Cells, P.First, P.End, Info.EffectColumns, Frames,
				std::pow(10.0, Shift / 20.0), Shift / FM_STEP_DB, StepVolume(Info));
			SlidesLost += Slides.Lost;
			if (pDone == 0)
				continue;
			std::string Also;
			if (Slides.Scaled > 0)
				Also += Format(", %s with it", Plural(Slides.Scaled, "volume slide", "volume slides").c_str());
			if (Slides.Stopped > 0)
				Also += Format(" (%s stopped where %s climb past the part's level)", Plural(Slides.Stopped, "swell", "swells").c_str(),
					Slides.Stopped == 1 ? "it would" : "they would");
			if (ByEar[p] || Given) {
				pDone->push_back(Format("%s loudest %d to %d%s", Label.c_str(), Own[p].Highest, Scaled(Own[p].Highest), Also.c_str()) +
					DrumsWhy[p]);
				continue;
			}
			if (Peak.Hold > 0) {
				pDone->push_back(Format("%s (its sound holds %d; on the 5B, 3 dB a step, that counts)%s", Told(Peak.Column,
					Scaled(Peak.Column)).c_str(), Peak.Hold, Also.c_str()));
				continue;
			}
			// An envelope that peaks under 15 can keep a part under its level, its volume at 15
			if (LevelDb(Info, Peak.Column) + Shift > LevelDb(Info, 15) + 1.0)
				Also += Format(" (its instrument's envelope peaks at %d of 15, so it plays at most %d)", Peak.Envelope,
					PlayedVolume(Info, 15, Peak.Envelope));
			pDone->push_back(Told(Peak.Played, Want) + Also);
		}
		// What keeps its level
		for (size_t p = 0; p < Spans.size() && pDone != 0; ++p)
			if (Spans[p].Role == ROLE_AMBIENCE && NoteStartsIn(S, Spans[p].Channel, Spans[p].First, Spans[p].End) && !Style.empty())
				pDone->push_back(LabelOf(Spans[p]) + " stays as written");
		for (int c = 0; c < S.ChannelCount() && pDone != 0; ++c)
			if (Buzzes[static_cast<size_t>(c)] > 0)
				pDone->push_back(Format("%s's %s play the envelope at its own level whatever their volume, so they stay as written",
					S.Channel(c).FullName().c_str(), Plural(Buzzes[static_cast<size_t>(c)], "envelope note (a buzz)", "envelope notes (a buzz)").c_str()));
	};

	std::vector<std::string> Done;
	int PansLost = 0;
	std::unique_ptr<Draft> pDraft(new Draft(S));
	Scale(*pDraft, &Done);
	if (Width >= 0.0)
		ApplyPans(*pDraft, &Done, PansLost);
	WriteDac(*pDraft);

	// As heard: the balance the mix leaves. Whole steps of volume, and the envelope they multiply (FamiTracker rounds the
	// product down, so on a sound that holds 12, volumes 5 and 6 both play 4), can leave a part half a dB or more off its
	// place: such a part (a chord layer as one) tries each loudest volume around its own, and keeps the one heard nearest
	std::string Balance;
	if (Heard && Melody >= 0) {
		// The balance of a draft, or (null) of the mix as the shifts are now
		auto BalanceOf = [&](Draft *pTry) {
			std::unique_ptr<Draft> pOwn;
			if (pTry == 0) {
				pOwn.reset(new Draft(S));
				pTry = pOwn.get();
				int Lost = 0;
				Scale(*pTry, 0);
				if (Width >= 0.0)
					ApplyPans(*pTry, 0, Lost);
				WriteDac(*pTry);
			}
			Hearing Ears(S, pTry);
			return HearBalance(S, Ears, Spans, Local, Melody, Voices, First, End);
		};
		HeardBalance B = BalanceOf(pDraft.get());
		const std::vector<double> MissedFirst = Missed;
		std::vector<char> Tried(Spans.size(), 0);
		bool Searched = false, Changed = false;
		for (size_t i = 0; i < Spans.size(); ++i) {
			if (Tried[i] || !ByEar[i] || Aims[i] <= NO_LOUDNESS || B.Rel[i] <= NO_LOUDNESS || std::fabs(MissedFirst[i]) >= 0.05 ||
				std::fabs(B.Rel[i] - Aims[i]) < 0.5)
				continue;
			std::vector<size_t> Unit;
			for (size_t k = 0; k < Spans.size(); ++k)
				if (k == i || (B.Layer[i] >= 0 && B.Layer[k] == B.Layer[i]))
					Unit.push_back(k);
			for (size_t u = 0; u < Unit.size(); ++u)
				Tried[Unit[u]] = 1;
			Searched = true;
			const ChannelInfo &Info = S.Channel(Spans[i].Channel);
			const int Highest = Own[i].Highest;
			const double Was = Shifts[i];
			double Best = Was, BestMiss = std::fabs(B.Rel[i] - Aims[i]);
			const int Top = Spans[i].Role == ROLE_DRUMS ? Highest : std::min(15, Highest + 7);	// the drums never up
			for (int To = std::max(1, Highest - 7); To <= Top; ++To) {
				const double Shift = LevelDb(Info, To) - LevelDb(Info, Highest);
				if (std::fabs(Shift - Was) < 0.01)
					continue;
				for (size_t u = 0; u < Unit.size(); ++u)
					Shifts[Unit[u]] = Shift;
				const HeardBalance Tries = BalanceOf(0);
				const double Miss = Tries.Rel[i] > NO_LOUDNESS ? std::fabs(Tries.Rel[i] - Aims[i]) : 1e9;
				if (Miss < BestMiss - 0.05) {
					Best = Shift;
					BestMiss = Miss;
				}
			}
			for (size_t u = 0; u < Unit.size(); ++u)
				Shifts[Unit[u]] = Best;
			Changed = Changed || Best != Was;
		}
		if (Searched) {
			// The mix with the volumes found (and what Scale and WriteDac tell of it, which the tries changed)
			Done.clear();
			PansLost = 0;
			pDraft.reset(new Draft(S));
			Scale(*pDraft, &Done);
			if (Width >= 0.0)
				ApplyPans(*pDraft, &Done, PansLost);
			WriteDac(*pDraft);
			if (Changed)
				B = BalanceOf(pDraft.get());
		}
		double Least, Most;
		Balance = BalanceText(S, Spans, B, Melody, Least, Most);
		// What lands half a dB or more off its place (at 15 or 1, or between two volumes' steps), a chord layer as one:
		// a fader moves it the rest of the way
		std::string Off;
		std::vector<char> Named(Spans.size(), 0);
		for (size_t i = 0; i < Spans.size(); ++i) {
			if (!ByEar[i] || Named[i] || Aims[i] <= NO_LOUDNESS || B.Rel[i] <= NO_LOUDNESS)
				continue;
			const double By = B.Rel[i] - Aims[i];	// over its place (under it, negative)
			if (std::fabs(By) < 0.5)
				continue;
			std::string Names;
			for (size_t k = i; k < Spans.size(); ++k)
				if (k == i || (B.Layer[i] >= 0 && B.Layer[k] == B.Layer[i] && !Named[k])) {
					Named[k] = 1;
					Names += (Names.empty() ? "" : " and ") + S.Channel(Spans[k].Channel).FullName();
				}
			Off += (Off.empty() ? "" : ", ") + Format("%s (%s) %.1f dB too %s%s", Names.c_str(), RoleName(Spans[i].Role),
				std::fabs(By), By > 0 ? "loud" : "quiet", std::fabs(Missed[i]) >= 0.05 ? (Missed[i] > 0 ? " at 15" : " at 1") :
				" (between volume steps)");
		}
		if (!Off.empty())
			Balance += " (off their places: " + Off + "; set_mixer's faders move them the rest)";
	}

	std::vector<Change> Changes;
	std::vector<std::string> Warnings;
	if (!DacWarning.empty())
		Warnings.push_back(DacWarning);
	if (SlidesLost > 0)
		Warnings.push_back(Format("%s found no free effect column or volume column for its stop (or its slide back on), so it "
			"climbs as it did.", Plural(SlidesLost, "swell", "swells").c_str()));
	if (PansLost > 0)
		Warnings.push_back(Format("%s had a note with no free effect column for its pan, which plays where the note before it "
			"does.", Plural(PansLost, "part", "parts").c_str()));
	int Start = First;
	std::string What = Calm ? "a calm mix" : Heard ? "a lively mix" : Soft ? "a soft mix" : (Style == "full" || Style == "loud") ?
		"a full mix" : (Style.empty() && Width >= 0.0 && Arg(Args, "levels") == 0 && Dac < 0) ? "the stereo picture" : "the mix";
	What += ", " + RangeText(From, To) + (Balance.empty() ? ": " : ", as heard: " + Balance + ". Changes: ");
	for (size_t i = 0; i < Done.size(); ++i)
		What += (i == 0 ? "" : "; ") + Done[i];
	if (!DacText.empty())
		What += (Done.empty() ? "" : "; ") + DacText;
	if (!pDraft->Collect(First, true, Changes, Start, Warnings, End)) {
		std::string Drums;	// as heard: drums that keep the volumes they were written at, and why
		for (size_t i = 0; i < Spans.size(); ++i)
			if (Spans[i].Role == ROLE_DRUMS && !DrumsWhy[i].empty() && Aims[i] <= NO_LOUDNESS)
				Drums += " " + LabelOf(Spans[i]) + " keeps its volumes" + DrumsWhy[i] + ".";
		return (Chosen.Note.empty() ? std::string() : Chosen.Note + " ") + (Balance.empty() ? "The song is mixed that way already: " +
			What.substr(What.find(": ") + 2) + "." : "The song is mixed that way already, as heard: " + Balance + "." + Drums);
	}
	std::string Text = Commit(S, Changes, Start, false, "", What);
	if (Heard)
		Text += std::string(" As heard: as stems measure each part where it plays with the melody (envelopes, faders, pans and "
			"Soft counted); ") + (Calm ? "style lively puts the melody 3-4 dB over the parts instead." :
			"style calm puts it 2-3 dB over the chords instead.");
	if (Soft)
		Text += " Soft pulses leave the low end to the triangle and make the sound warmer; turn the playback volume up rather "
			"than the pulses. Volumes the tools write later start from the song's own, so mix again at the end.";
	if (Fm && !Style.empty() && !Heard)
		Text += " The VRC7 plays louder than the pulses and counts its volume in steps of 3 dB, so its parts sit nearer 15 "
			"for the same balance (9 there is 18 dB under 15).";
	if (Square && !Style.empty() && !Heard)
		Text += " The 5B counts its volume in steps of 3 dB, so its parts sit nearer 15 for the same balance (9 there is 18 dB "
			"under 15).";
	if (Quiet && !Style.empty() && !Heard)
		Text += " The N163's wave sounds play quieter than the pulses, so its parts sit nearer 15 for the same balance.";
	if (Under && !Style.empty() && !Heard)
		Text += Format(" The VRC6 Plus's soft layer sits %.0f dB under its parts' roles, under the VRC6.", SOFT_LAYER_DB);
	if (Loud && !Style.empty() && !Heard)
		Text += " The FDS plays louder than the pulses, so its parts sit lower for the same balance.";
	if (!Chosen.Note.empty())
		Text += " " + Chosen.Note;
	return WithRemarks(S, Text, Warnings);
}

int LevelArg(const Json &Args, const char *Name, int Default, const char *const *Words, const int *Values, int Count)
{
	const Json *pValue = Arg(Args, Name);
	if (pValue == 0)
		return Default;
	if (pValue->IsString()) {
		const std::string Text = Lowercase(Trim(pValue->String()));
		for (int i = 0; i < Count; ++i)
			if (Text == Words[i])
				return Values[i];
	}
	return IntArg(Args, Name, Default, 0, 15);
}

// The vibrato settings from an object (add_vibrato's arguments, or change_mood's vibrato)
struct VibratoPlan {
	int Channel, Speed, Depth, MinRows, Delay;
};

VibratoPlan VibratoArgs(Session &S, const Json &Args)
{
	static const char *const SPEEDS[] = { "slow", "medium", "fast" };
	static const int SPEED_VALUES[] = { 3, 5, 8 };
	static const char *const DEPTHS[] = { "none", "faint", "gentle", "medium", "strong" };
	static const int DEPTH_VALUES[] = { 0, 1, 2, 4, 7 };
	VibratoPlan Plan;
	Plan.Channel = ChannelArg(S, Args, "channel");
	if (!IsMelodic(S.Channel(Plan.Channel)))
		throw Problem("Vibrato is for melodic channels.");
	Plan.Speed = std::max(1, LevelArg(Args, "speed", 5, SPEEDS, SPEED_VALUES, 3));
	Plan.Depth = LevelArg(Args, "depth", 2, DEPTHS, DEPTH_VALUES, 5);
	bool Exact;
	Plan.MinRows = S.Time.BeatsToRows(NumberArg(Args, "min_beats", 1.0, 0.01, 64.0), Exact);
	Plan.Delay = S.Time.BeatsToRows(NumberArg(Args, "delay_beats", 0.25, 0.01, 16.0), Exact);
	return Plan;
}

// A calm track's vibrato comes in this many rows into a long note: nearest 27 frames (24-30, about half a beat at a
// calm tempo)
int CalmVibratoRows(const Session &S)
{
	const double RowFrames = FramesPerRow(S);
	int Rows = 1;
	for (int r = 2; r <= 8 * S.Time.RowsPerBeat; ++r)
		if (std::fabs(r * RowFrames - 27.0) < std::fabs(Rows * RowFrames - 27.0) - 1e-9)
			Rows = r;
	return Rows;
}

// Vibrato in the draft; how many notes it changed. HeardFor: only on notes whose sound is still heard that many frames
// in (0: any), so a struck sound that has faded by then gets none
int MakeVibrato(Session &S, Draft &D, const VibratoPlan &Plan, int First, int End, bool &Lost, bool SkipBuiltIn = false,
	int HeardFor = 0)
{
	const int Columns = S.Channel(Plan.Channel).EffectColumns;
	std::vector<Cell> &Cells = D.Cells(Plan.Channel);
	std::vector<NoteInfo> Notes = D.Notes(Plan.Channel);
	if (SkipBuiltIn || HeardFor > 0) {
		// Notes whose instrument has a vibrato of its own keep just that one
		std::vector<NoteInfo> Plain;
		for (size_t i = 0; i < Notes.size(); ++i) {
			const InstrumentInfo *pInfo = FindInstrument(S.Song, Notes[i].Instrument);
			if ((!SkipBuiltIn || pInfo == 0 || !pInfo->Vibrato) && (HeardFor <= 0 || HeardFrames(S.Song, Notes[i], HeardFor) >= HeardFor))
				Plain.push_back(Notes[i]);
		}
		Notes = Plain;
	}
	const int Count = ApplyVibrato(Cells, Notes, First, End, Plan.Speed, Plan.Depth, Plan.MinRows, Plan.Delay, Columns, Lost);
	if (Plan.Depth == 0 && First < static_cast<int>(Cells.size())) {
		// A vibrato still on from before the bars stops too
		const ChannelState State = StateAt(Cells, First, Columns);
		if (State.Sticky[EFF_VIBRATO] != 0 && !HasEffect(Cells[First], EFF_VIBRATO, Columns) && !AddEffect(Cells[First], EFF_VIBRATO, 0, Columns))
			Lost = true;
	}
	return Count;
}

std::string AddVibratoTool(Session &S, const Json &Args)
{
	const VibratoPlan Plan = VibratoArgs(S, Args);
	int From, To;
	BarRange(S, Args, From, To);
	const int First = S.Time.BarStart(From), End = S.Time.BarEnd(To);
	const bool AsClip = BoolArg(Args, "as_clip", false);
	bool Lost = false;
	Draft D(S);
	const int Count = MakeVibrato(S, D, Plan, First, End, Lost);
	std::vector<std::string> Warnings;
	if (Lost)
		Warnings.push_back("Some notes had no free effect column for the vibrato (all four were full).");
	std::vector<Change> Changes;
	int Start;
	if (Count == 0 || !D.Collect(First, Direct(S, AsClip), Changes, Start, Warnings))
		throw Problem(Plan.Depth == 0 ? "There's no vibrato to take off there." :
			Format("No notes there are long enough for vibrato (at least %s).", S.Time.Length(Plan.MinRows).c_str()));
	const std::string What = Plan.Depth == 0 ?
		Format("vibrato taken off %s, %s", S.Channel(Plan.Channel).FullName().c_str(), RangeText(From, To).c_str()) :
		Format("vibrato 4%X%X on the longer notes of %s, %s", Plan.Speed, Plan.Depth, S.Channel(Plan.Channel).FullName().c_str(),
			RangeText(From, To).c_str());
	return WithRemarks(S, Commit(S, Changes, Start, AsClip, StringArg(Args, "clip_name"), What) +
		Format(" (%s)", Plural(Count, "note", "notes").c_str()), Warnings);
}

// Drums, harmony, counter-melodies and finishing touches

// The bars the song's melodic parts play in, first to last; the whole song when none do
void PlayedBars(Session &S, int &From, int &To)
{
	int First = -1, Last = -1;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (!IsMelodic(S.Channel(c)))
			continue;
		const std::vector<NoteInfo> &Notes = S.Notes(c);
		for (size_t i = 0; i < Notes.size(); ++i) {
			if (First < 0 || Notes[i].Row < First)
				First = Notes[i].Row;
			Last = std::max(Last, Notes[i].Row + std::max(1, Notes[i].Rows) - 1);
		}
	}
	if (First < 0) {
		From = 1;
		To = S.Time.BarCount();
		return;
	}
	From = S.Time.BarOf(First);
	To = S.Time.BarOf(std::min(Last, S.Time.TotalRows() - 1));
}

// The bar phrases count from: where the loop comes back to when an intro
// plays once before it (a fill every 8 bars after a 4-bar intro ends bars
// 12, 20 and 28), else bar 1
int PhraseAnchor(Session &S)
{
	const int Loop = Flow(S).LoopRow(S.Time.PatternLength);
	return Loop > 0 ? S.Time.BarOf(Loop) : 1;
}

// How many bars into its phrase Bar is, in phrases of Length bars
int BarsIntoPhrase(int Bar, int Anchor, int Length)
{
	const int n = std::max(1, Length);
	return ((Bar - Anchor) % n + n) % n;
}

std::string AddDrumsTool(Session &S, const Json &Args)
{
	const bool AsClip = BoolArg(Args, "as_clip", false);
	int Channel = -1;
	if (Arg(Args, "channel") != 0) {
		Channel = ChannelArg(S, Args, "channel");
		if (S.Channel(Channel).Kind != KIND_NOISE)
			throw Problem("Drums go on the noise channel.");
	}
	for (int c = 0; c < S.ChannelCount() && Channel < 0; ++c)
		if (S.Channel(c).Kind == KIND_NOISE)
			Channel = c;
	if (Channel < 0)
		throw Problem("The song has no noise channel.");
	int From, To;
	if (RangeGiven(Args))
		BarRange(S, Args, From, To, true);
	else
		PlayedBars(S, From, To);
	const int First = S.Time.BarStart(From), End = S.Time.BarEnd(To);
	const int R = S.Time.RowsPerBeat;

	DrumOptions O;
	O.Groove = StyleArg(Args, "groove", Grooves(), S.Time.RowsPerBar == 3 * R ? GROOVE_WALTZ : GROOVE_BASIC);
	static const char *const LEVELS[] = { "light", "normal", "busy", "soft", "medium", "intense" };
	static const int LEVEL_VALUES[] = { 1, 2, 3, 1, 2, 3 };
	O.Intensity = std::max(1, std::min(3, LevelArg(Args, "intensity", 2, LEVELS, LEVEL_VALUES, 6)));
	O.FillEvery = IntArg(Args, "fill_every", 4, 0, 64);
	O.PhraseStart = O.FillEvery > 0 ? BarsIntoPhrase(From, PhraseAnchor(S), O.FillEvery) : 0;
	O.Crash = BoolArg(Args, "crash", true);
	O.Samples = SampledKitArg(Args);
	O.RowsPerBeat = R;
	const int Dpcm = O.Samples ? DpcmChannel(S) : -1;
	const std::vector<DrumHit> Hits = DrumPart(SongBarSpans(S, First, End), O);
	if (Hits.empty())
		throw Problem("There are no beats in those bars.");
	std::vector<std::string> Warnings;
	if (HasNotesIn(S, Channel, First, End))
		Warnings.push_back(S.Channel(Channel).FullName() + "'s drums in those bars were replaced.");
	std::vector<Change> Changes;
	std::string Where;
	// volume is the loudest hit's: a groove's own loudest by default (the lively groove's soft kick, 10)
	const int Designed = GrooveLoudest(O.Groove), Loudest = IntArg(Args, "volume", Designed, 1, 15);
	DrumChanges(S, Channel, Dpcm, Hits, First, End, Loudest, Direct(S, AsClip), Changes, Where, Warnings, Designed);
	static const char *const INTENSITY[] = { "", "light", "", "busy" };
	std::string What = std::string(INTENSITY[O.Intensity]) + (O.Intensity == 2 ? "" : " ") + Grooves()[static_cast<size_t>(O.Groove)].Name +
		" drums" + Where;
	if (O.Groove == GROOVE_LIVELY) {
		// What it wrote, at these volumes: the hi-hats' softest and loudest, the kick's (on the noise, or the sample)
		int HatLow = 15, HatHigh = 0, KickLow = 15, KickHigh = 0;
		for (size_t i = 0; i < Hits.size(); ++i) {
			const int Volume = std::max(1, std::min(15, (Hits[i].Volume * Loudest + Designed / 2) / Designed));
			if (Hits[i].Sound == "hi-hat" || Hits[i].Sound == "open hi-hat") {
				HatLow = std::min(HatLow, Volume);
				HatHigh = std::max(HatHigh, Volume);
			}
			else if (Hits[i].Sound == "kick" && !(Hits[i].Sampled && Dpcm >= 0)) {
				KickLow = std::min(KickLow, Volume);
				KickHigh = std::max(KickHigh, Volume);
			}
		}
		auto Volumes = [](int Low, int High) { return Low == High ? Format("%d", Low) : Format("%d-%d", Low, High); };
		if (HatHigh > 0)
			What += " (hi-hats at " + Volumes(HatLow, HatHigh) + (KickHigh > 0 ? ", a soft kick at " + Volumes(KickLow, KickHigh) :
				std::string()) + ", no snare)";
		if (Dpcm >= 0)
			Warnings.push_back("The sampled kick plays at the sample's own level: set_mixer's fader on " + S.Channel(Dpcm).FullName() +
				" (2-3 dB down) softens it for a stage that flows.");
	}
	What += O.FillEvery > 0 ? Format(", a fill every %d bars", O.FillEvery) : std::string(", no fills");
	if (O.Groove == GROOVE_LIVELY && O.FillEvery > 0)
		What += O.Crash ? " (a hi-hat roll or soft toms, in turn, and a soft splash after)" : " (a hi-hat roll or soft toms, in turn)";
	What += ", " + RangeText(From, To);
	return WithRemarks(S, Commit(S, Changes, First, AsClip, StringArg(Args, "clip_name"), What), Warnings);
}

// The melody a part goes with: as named, or the busiest channel
int MelodyArg(Session &S, const Json &Args)
{
	const int Melody = Arg(Args, "melody_channel") != 0 ? ChannelArg(S, Args, "melody_channel") : GuessMelodyChannel(S, 0, S.Time.TotalRows());
	if (Melody < 0)
		throw Problem("There's no melody yet.");
	if (!IsMelodic(S.Channel(Melody)))
		throw Problem("The melody channel needs notes, not drums or samples.");
	return Melody;
}

// The channel for a new part beside the melody: as named, or a free one like it
int PartChannel(Session &S, const Json &Args, int Melody, int First, int End, const char *What)
{
	if (Arg(Args, "channel") != 0) {
		const int Channel = ChannelArg(S, Args, "channel");
		if (Channel == Melody || !IsMelodic(S.Channel(Channel)))
			throw Problem(Format("The %s needs a melodic channel other than the melody's.", What));
		return Channel;
	}
	const int Channel = EchoTarget(S, Melody, First, End);
	if (Channel < 0)
		throw Problem(Format("No free channel for the %s in those bars; name one with channel (its notes there are replaced).", What));
	return Channel;
}

// A harmony's notes that would rub a semitone (or a semitone and octaves) against another part as the parts sound, the
// way check_song hears a clash (a held maj7 pad's seventh under the voice's note): each goes to the nearest note that
// doesn't, a chord tone first, then one of the key, on its side of the melody and no more than a fourth away; one with
// nowhere to go, or with a slide of its own, is left out (as add_echo's EchoWithoutRubs leaves an echo's out). Moved and
// Dropped count them
std::vector<PartNote> HarmonyWithoutRubs(Session &S, int Target, int Melody, const std::vector<PartNote> &Notes,
	const std::vector<ChordAt> &Chords, const Key &K, bool Above, int &Moved, int &Dropped)
{
	struct Other { int Row, End; std::vector<int> Pitches; };	// as they sound
	std::vector<Other> Others;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (c == Target || !IsMelodic(S.Channel(c)))
			continue;
		const int Lift = Written(S.Channel(c), 0);
		const std::vector<NoteInfo> &Theirs = S.Notes(c);
		const std::vector<int> Arps = StickyAt(S.Cells(c), Theirs, S.Channel(c).EffectColumns, EFF_ARPEGGIO);
		for (size_t i = 0; i < Theirs.size(); ++i) {
			if (Theirs[i].Volume <= 0)
				continue;
			Other o;
			o.Row = Theirs[i].Row;
			o.End = Theirs[i].Row + std::max(1, Theirs[i].Rows);
			o.Pitches.push_back(Theirs[i].Pitch - Lift);
			const std::vector<int> Chord = ChordAbove(S, Theirs[i], Arps[i]);
			for (size_t a = 0; a < Chord.size(); ++a)
				o.Pitches.push_back(Theirs[i].Pitch - Lift + Chord[a]);
			Others.push_back(o);
		}
	}
	auto Rubs = [&](int Sounds, int Row, int End) {
		for (size_t k = 0; k < Others.size(); ++k) {
			if (Others[k].Row >= End || Others[k].End <= Row)
				continue;
			for (size_t p = 0; p < Others[k].Pitches.size(); ++p)
				if (SemitoneRub(Sounds, Others[k].Pitches[p]))
					return true;
		}
		return false;
	};
	const int Lifted = Written(S.Channel(Target), 0), MelodyLift = Written(S.Channel(Melody), 0);
	const std::vector<NoteInfo> &Tune = S.Notes(Melody);
	Moved = Dropped = 0;
	std::vector<PartNote> Out;
	for (size_t i = 0; i < Notes.size(); ++i) {
		PartNote N = Notes[i];
		const int Sounds = N.Pitch - Lifted, End = N.Row + std::max(1, N.Rows);
		if (!Rubs(Sounds, N.Row, End)) {
			Out.push_back(N);
			continue;
		}
		bool Slides = false;
		for (size_t e = 0; e < N.Effects.size(); ++e)
			Slides = Slides || N.Effects[e].first == EFF_SLIDE_UP || N.Effects[e].first == EFF_SLIDE_DOWN || N.Effects[e].first == EFF_PORTAMENTO;
		for (size_t e = 0; e < N.LaterEffects.size(); ++e)
			Slides = Slides || N.LaterEffects[e].second.first == EFF_SLIDE_UP || N.LaterEffects[e].second.first == EFF_SLIDE_DOWN;
		// The melody's note there and the chord, as they sound
		int Over = -1000;
		for (size_t m = 0; m < Tune.size(); ++m)
			if (Tune[m].Row <= N.Row && N.Row < Tune[m].Row + std::max(1, Tune[m].Rows))
				Over = Tune[m].Pitch - MelodyLift;
		const ChordAt *pChord = 0;
		for (size_t c = 0; c < Chords.size(); ++c)
			if (Chords[c].Row <= N.Row && N.Row < Chords[c].Row + Chords[c].Rows)
				pChord = &Chords[c];
		int Best = -1;
		for (int Pass = 0; Pass < 2 && Best < 0 && !Slides; ++Pass)
			for (int d = 1; d <= 5 && Best < 0; ++d)
				for (int w = 0; w < 2 && Best < 0; ++w) {
					const int p = Sounds + ((w == 0) == Above ? d : -d);	// away from the melody first
					const bool Fits = Pass == 0 ? pChord != 0 && pChord->C.HasPitchClass(((p % 12) + 12) % 12) : InKey(p, K);
					const bool Side = Over <= -1000 || (Above ? p > Over : p < Over);
					if (Fits && Side && p + Lifted >= 0 && p + Lifted < PITCHES && !Rubs(p, N.Row, End))
						Best = p;
				}
		if (Best < 0) {
			++Dropped;
			continue;
		}
		N.Pitch = Best + Lifted;
		++Moved;
		Out.push_back(N);
	}
	return Out;
}

std::string AddHarmonyTool(Session &S, const Json &Args)
{
	const bool AsClip = BoolArg(Args, "as_clip", false);
	const int Melody = MelodyArg(S, Args);
	int From, To;
	if (RangeGiven(Args))
		BarRange(S, Args, From, To);
	else
		PlayedBars(S, From, To);
	const int First = S.Time.BarStart(From), End = S.Time.BarEnd(To);
	const std::vector<NoteInfo> Line = NotesIn(S.Notes(Melody), First, End);
	if (Line.empty())
		throw Problem(Format("%s has no notes in %s to harmonize.", S.Channel(Melody).FullName().c_str(), RangeText(From, To).c_str()));
	const int Target = PartChannel(S, Args, Melody, First, End, "harmony");
	bool Found;
	Key K = KeyArg(S, Args, "key", First, End, Found);
	if (!Found)
		K = Key(0, MODE_MAJOR);
	std::string Source;
	const std::vector<ChordAt> Chords = ChordsForMelody(S, Args, Melody, SongBarSpans(S, First, End), K, Source, Target);

	HarmonyOptions O;
	O.Interval = StyleArg(Args, "interval", HarmonyIntervals(), HARMONY_THIRD_BELOW);
	O.MinRows = BoolArg(Args, "long_notes_only", false) ? S.Time.RowsPerBeat : 0;
	O.RowsPerBeat = S.Time.RowsPerBeat;
	O.K = K;
	// In sounding pitches: the triangle sounds an octave below what's written
	const int Shift = Written(S.Channel(Target), 0) - Written(S.Channel(Melody), 0);
	O.Low = std::max(0, Written(S.Channel(Target), 12)) - Shift;
	O.High = std::min(PITCHES - 1, Written(S.Channel(Target), 84)) - Shift;
	int Loudest = 0;
	for (size_t i = 0; i < Line.size(); ++i)
		Loudest = std::max(Loudest, Line[i].Volume);
	O.VolumeDrop = Arg(Args, "volume") != 0 ? std::max(0, Loudest - IntArg(Args, "volume", 12, 1, 15)) : 3;
	std::vector<PartNote> Notes = HarmonyPart(Line, Chords, O);
	if (Notes.empty())
		throw Problem("No melody notes there are long enough to harmonize.");

	// The melody's own instruments when the channel takes them, else the one asked for or a soft lead
	const bool SameChip = InstrumentChip(S.Channel(Target)) == InstrumentChip(S.Channel(Melody));
	const int Instrument = Arg(Args, "instrument") != 0 || !SameChip ? PartInstrument(S, Args, "instrument", Target, "soft lead") : NO_INSTRUMENT;
	for (size_t i = 0; i < Notes.size(); ++i) {
		Notes[i].Pitch = std::max(0, std::min(PITCHES - 1, Notes[i].Pitch + Shift));
		// The melody's effects that its channel plays alike (an FDS modulator's Hxx would be a sweep on a pulse)
		std::vector<std::pair<int, int> > Effects;
		for (size_t e = 0; e < Notes[i].Effects.size(); ++e)
			if (CarriesEffect(S.Channel(Melody), S.Channel(Target), Notes[i].Effects[e].first, Notes[i].Effects[e].second))
				Effects.push_back(Notes[i].Effects[e]);
		Notes[i].Effects = Effects;
		std::vector<std::pair<int, std::pair<int, int> > > Later;
		for (size_t e = 0; e < Notes[i].LaterEffects.size(); ++e)
			if (CarriesEffect(S.Channel(Melody), S.Channel(Target), Notes[i].LaterEffects[e].second.first,
				Notes[i].LaterEffects[e].second.second))
				Later.push_back(Notes[i].LaterEffects[e]);
		Notes[i].LaterEffects = Later;
		for (size_t m = 0; m < Line.size(); ++m) {
			if (Line[m].Row != Notes[i].Row)
				continue;
			if (Instrument == NO_INSTRUMENT)
				Notes[i].Instrument = Line[m].Instrument;
			if (Arg(Args, "volume") == 0 && Line[m].Volume > 0)
				Notes[i].Volume = MatchVolume(S.Channel(Melody), Line[m].Volume, std::max(1, Line[m].Volume - O.VolumeDrop) /
					static_cast<double>(Line[m].Volume), S.Channel(Target));
		}
		if (Instrument != NO_INSTRUMENT)
			Notes[i].Instrument = Instrument;
	}
	TidyPart(Notes, First, End);
	// On the N163, the melody's sound (from another N163 channel) as a copy of its own
	OwnWaveSounds(S, 0, Target, First, End, Notes);
	std::vector<std::string> Warnings;
	if (O.Interval != HARMONY_OCTAVE_BELOW) {
		// Off the semitones against the other parts (a pad's maj7), which the octave below doubling the melody keeps
		int Moved = 0, Dropped = 0;
		Notes = HarmonyWithoutRubs(S, Target, Melody, Notes, Chords, K, O.Interval == HARMONY_THIRD_ABOVE, Moved, Dropped);
		if (Notes.empty())
			throw Problem("Every harmony note there would rub a semitone against another part (a chord's seventh), and none had "
				"another chord tone to go to.");
		if (Moved > 0 || Dropped > 0)
			Warnings.push_back(Format("Where the harmony would rub a semitone against another part (a chord's seventh, as check_song "
				"hears a clash), %s%s%s.", Moved > 0 ? (Plural(Moved, "note went", "notes went") + " to the nearest chord tone that "
				"doesn't").c_str() : "", Moved > 0 && Dropped > 0 ? " and " : "", Dropped > 0 ? (Plural(Dropped, "was", "were") +
				" left out").c_str() : ""));
	}
	if (HasNotesIn(S, Target, First, End))
		Warnings.push_back(S.Channel(Target).FullName() + "'s own notes in those bars were replaced.");
	Change C;
	C.Channel = Target;
	BuildPart(S.Cells(Target), First, End, Notes, OptionsFor(S, Target, Direct(S, AsClip)), C.Cells, Warnings);
	std::vector<Change> Changes(1, C);
	std::string Interval = HarmonyIntervals()[static_cast<size_t>(O.Interval)].Name;
	std::replace(Interval.begin(), Interval.end(), '_', ' ');
	const std::string What = "a harmony a " + Interval + " " + S.Channel(Melody).FullName() + " on " + S.Channel(Target).FullName() +
		", " + RangeText(From, To);
	return WithRemarks(S, Commit(S, Changes, First, AsClip, StringArg(Args, "clip_name"), What) +
		Format(" (%s, on %s in %s)", Plural(static_cast<int>(Notes.size()), "note", "notes").c_str(), Source.c_str(),
			KeyName(K).c_str()), Warnings);
}

std::string AddCounterMelodyTool(Session &S, const Json &Args)
{
	const bool AsClip = BoolArg(Args, "as_clip", false);
	const int Melody = MelodyArg(S, Args);
	int From, To;
	if (RangeGiven(Args))
		BarRange(S, Args, From, To);
	else
		PlayedBars(S, From, To);
	const int First = S.Time.BarStart(From), End = S.Time.BarEnd(To);
	const std::vector<NoteInfo> Line = NotesIn(S.Notes(Melody), First, End);
	if (Line.empty())
		throw Problem(Format("%s has no notes in %s to answer.", S.Channel(Melody).FullName().c_str(), RangeText(From, To).c_str()));
	const int Target = PartChannel(S, Args, Melody, First, End, "counter-melody");
	bool Found;
	Key K = KeyArg(S, Args, "key", First, End, Found);
	if (!Found)
		K = Key(0, MODE_MAJOR);
	const std::vector<BarSpan> Bars = SongBarSpans(S, First, End);
	std::string Source;
	const std::vector<ChordAt> Chords = ChordsForMelody(S, Args, Melody, Bars, K, Source, Target);

	CounterOptions O;
	const std::string Place = Lowercase(StringArg(Args, "position", "below"));
	if (Place != "below" && Place != "above" && Place != "under" && Place != "over" && Place != "descant")
		throw Problem("position: below or above.");
	O.Above = Place == "above" || Place == "over" || Place == "descant";
	O.RowsPerBeat = S.Time.RowsPerBeat;
	O.K = K;
	// Around a sixth to a tenth under the melody, or over it; in the melody's pitches
	const int Middle = MiddleOf(Line, 52);
	const int Shift = Written(S.Channel(Target), 0) - Written(S.Channel(Melody), 0);
	O.Low = O.Above ? Middle + 3 : Middle - 17;
	O.High = O.Above ? Middle + 15 : Middle - 4;
	O.Low = std::max(12 - Shift, O.Low);
	O.High = std::min(PITCHES - 13 - Shift, std::max(O.Low + 7, O.High));
	int Loudest = 0;
	for (size_t i = 0; i < Line.size(); ++i)
		Loudest = std::max(Loudest, Line[i].Volume);
	O.Volume = Arg(Args, "volume") != 0 ? IntArg(Args, "volume", 11, 1, 15) :
		MatchVolume(S.Channel(Melody), Loudest, std::max(4, Loudest - 4) / static_cast<double>(std::max(1, Loudest)), S.Channel(Target));
	// The melody's rests: as asked (rests), else by the style (calm: it breathes with the melody, answering only in rests of
	// two beats or more), else it moves on through them, as a busier song wants
	const std::string Style = Squeezed(StringArg(Args, "style", "any"));
	if (Style != "any" && Style != "calm" && Style != "ambient")
		throw Problem("style should be any or calm.");
	O.Rests = Style == "any" ? RESTS_FILL : RESTS_ANSWER;
	if (Arg(Args, "rests") != 0) {
		const std::string Rests = Squeezed(StringArg(Args, "rests"));
		if (Rests == "fill" || Rests == "move" || Rests == "through")
			O.Rests = RESTS_FILL;
		else if (Rests == "answer" || Rests == "answers")
			O.Rests = RESTS_ANSWER;
		else if (Rests == "leave" || Rests == "silent" || Rests == "breathe" || Rests == "none")
			O.Rests = RESTS_LEAVE;
		else
			throw Problem("rests: fill (it moves on through the melody's rests), answer (it rests with the melody, but for a short "
				"answer in rests of two beats or more) or leave (it rests with the melody).");
	}
	int Answers = 0;
	std::vector<PartNote> Notes = CounterMelody(Line, Chords, Bars, O, &Answers);
	if (Notes.empty())
		throw Problem("There are no chords there for a counter-melody to follow.");
	const int Instrument = PartInstrument(S, Args, "instrument", Target, IsBass(S.Channel(Target)) ? "bass" : "soft lead");
	for (size_t i = 0; i < Notes.size(); ++i) {
		Notes[i].Pitch = std::max(0, std::min(PITCHES - 1, Notes[i].Pitch + Shift));
		Notes[i].Instrument = Instrument;
	}
	OwnWaveSounds(S, 0, Target, First, End, Notes);	// on the N163, a sound another channel plays there as a copy of its own
	std::vector<std::string> Warnings;
	if (HasNotesIn(S, Target, First, End))
		Warnings.push_back(S.Channel(Target).FullName() + "'s own notes in those bars were replaced.");
	Change C;
	C.Channel = Target;
	BuildPart(S.Cells(Target), First, End, Notes, OptionsFor(S, Target, Direct(S, AsClip)), C.Cells, Warnings);
	std::vector<Change> Changes(1, C);
	const std::string What = std::string("a counter-melody ") + (O.Above ? "above " : "below ") + S.Channel(Melody).FullName() + " on " +
		S.Channel(Target).FullName() + ", " + RangeText(From, To);
	std::string How = "it holds where the melody moves and moves, at least every bar, where it holds";
	if (O.Rests == RESTS_FILL)
		How += " or rests";
	else if (O.Rests == RESTS_LEAVE)
		How += "; it rests where the melody does";
	else if (Answers == 0)
		How += "; it rests where the melody does (no rest of two beats or more to answer in)";
	else
		How += Format("; it rests where the melody does, but for %s in rests of two beats or more", Plural(Answers, "short answer",
			"short answers").c_str());
	return WithRemarks(S, Commit(S, Changes, First, AsClip, StringArg(Args, "clip_name"), What) +
		Format(" (%s on %s in %s; %s. Shape it further with write_notes.)", Plural(static_cast<int>(Notes.size()), "note",
			"notes").c_str(), Source.c_str(), KeyName(K).c_str(), How.c_str()), Warnings);
}

// grow_melody: a hook grown into whole phrases over the song's chords (GrowMelody.h)

bool NameSaysTense(const std::string &TrackName);	// VersionMood's tense: a battle, a boss, a chase

// The notes a melody plays on a channel, as written: from the lowest its chip plays to C-7 as it sounds, the triangle to
// C-6, the FDS to G#7, the N163 to where its channels turn a 16-sample wave grainy (check_song's range)
void MelodyRange(const Session &S, int Channel, int &Low, int &High)
{
	const ChannelInfo &Info = S.Channel(Channel);
	Low = Info.Kind == KIND_SQUARE ? 12 : Info.Chip == "FDS" ? 21 : Info.Kind == KIND_PULSE && (Info.Chip == "2A03" || Info.Chip == "MMC5") ?
		9 : 0;
	High = std::min(PITCHES - 1, 84 + Written(Info, 0));
	if (Info.Kind == KIND_TRIANGLE)
		High = std::min(High, 72);
	if (Info.Chip == "FDS")
		High = std::min(High, FDS_HIGHEST);
	if (Info.Chip == "N163") {
		int Channels = 0;
		for (int c = 0; c < S.ChannelCount(); ++c)
			Channels += S.Channel(c).Chip == "N163" ? 1 : 0;
		const double Hz = 1789773.0 / (15.0 * std::max(1, Channels) * 16.0);
		High = std::min(High, static_cast<int>(std::floor(12.0 * std::log2(Hz / 32.7032) + 0.2)));
	}
}

// The channel a melody is grown on: as named; else the melody playing in those bars (a part of single notes, not
// chords, a steady run or an echo); else a free pulse
int GrowChannel(Session &S, const Json &Args, int First, int End)
{
	if (Arg(Args, "channel") != 0) {
		const int Channel = ChannelArg(S, Args, "channel");
		if (!IsMelodic(S.Channel(Channel)))
			throw Problem("A melody needs a channel that plays notes, not the noise or the DPCM channel.");
		return Channel;
	}
	const int Melody = GuessMelodyChannel(S, First, End);
	if (Melody >= 0 && !IsBass(S.Channel(Melody))) {
		const std::vector<NoteInfo> Notes = NotesIn(S.Notes(Melody), First, End);
		int Chords = 0;
		for (size_t i = 0; i < Notes.size(); ++i)
			Chords += SoundsChord(S, Notes[i]) ? 1 : 0;
		if (!Notes.empty() && Chords * 3 < static_cast<int>(Notes.size()) && !RunsSteadily(S, Notes) &&
			!EchoesAnother(S, Melody, Notes, First, End))
			return Melody;
	}
	for (int c = 0; c < S.ChannelCount(); ++c)
		if (IsChordChannel(S.Channel(c)) && !HasNotesIn(S, c, First, End))
			return c;
	throw Problem("No channel is free for a melody in those bars: name one with channel (its notes there are replaced when a version "
		"is written).");
}

// A line of steps as write_notes takes it, a bar to a line with its number
std::string GrownLine(const ChannelInfo &Info, const std::vector<GrowNote> &Notes, int FirstBar, int Bars, int StepsPerBar)
{
	StepLine Line;
	Line.FirstBar = FirstBar;
	for (int b = 0; b < Bars; ++b) {
		StepLineBar B;
		B.First = b * StepsPerBar;
		B.Steps = StepsPerBar;
		B.Number = FirstBar + b;
		Line.Bars.push_back(B);
	}
	for (size_t i = 0; i < Notes.size(); ++i) {
		StepLineNote N;
		N.Step = Notes[i].Step;
		N.Steps = Notes[i].Steps;
		N.Pitch = StepPitch(Info, Notes[i].Pitch);
		Line.Notes.push_back(N);
	}
	return FormatStepLine(Line);
}

std::string GrowMelodyTool(Session &S, const Json &Args)
{
	const int Sixteenths = StepArg(Args);
	const StepGrid Grid = GridOf(S.Time, Sixteenths);
	if (Grid.Rows == 0 || S.Time.RowsPerBeat % Grid.Rows != 0)
		throw Problem(Format("At %s a beat, %s %s isn't a whole number of rows a beat: give step %s.", Plural(S.Time.RowsPerBeat, "row",
			"rows").c_str(), Sixteenths == 2 ? "an" : "a", StepName(Sixteenths), GridsThatFit(S.Time).c_str()));
	const int StepsPerBeat = S.Time.RowsPerBeat / Grid.Rows;

	// The motif, a line of steps of a bar or two
	const std::string MotifText = StringArg(Args, "motif");
	if (MotifText.empty())
		throw Problem("motif: the hook to grow, 4-7 notes in steps, like \"D4 G4 A4 B4 - A4 G4 -\" (a token an eighth: a pitch starts a "
			"note, - holds it, . rests).");
	StepLine Motif;
	std::string Error;
	if (!ParseStepLine(MotifText, 0, Motif, Error))
		throw Problem("motif: " + Error + STEP_HELP);
	if (Motif.Held > 0)
		throw Problem("motif: start it with a note (or . for a rest before it), not -.");
	if (Motif.Notes.size() < 4 || Motif.Notes.size() > 7)
		throw Problem(Format("motif: a hook of 4-7 notes, a bar or two (this one has %d): a short idea with a rhythm you'd recognize; "
			"grow_melody makes the phrases from it.", static_cast<int>(Motif.Notes.size())));

	// The bars: as given, else 8 from the bar the motif's line names, or from where the other parts start
	int From = 1, To = 1;
	if (RangeGiven(Args))
		BarRange(S, Args, From, To, true);
	else {
		int PlayFrom = 1, PlayTo = S.Time.BarCount();
		PlayedBars(S, PlayFrom, PlayTo);
		From = Motif.FirstBar > 0 ? Motif.FirstBar : PlayFrom;
		To = std::min(From + 7, std::max(PlayTo, From + 1));
	}
	if (To - From + 1 > 32)
		throw Problem(Format("%s is more than a call grows (32 bars): grow a section or 8-16 bars at a time.", RangeText(From, To).c_str()));
	const int Bars = To - From + 1;
	const int First = S.Time.BarStart(From), End = S.Time.BarEnd(To);
	if (End > S.MaxRows())
		throw Problem(Format("Those bars run past the longest a song can be (%d bars).", S.MaxBars()));
	const int BarRows = S.Time.BarLength(From);
	for (int Bar = From; Bar <= To; ++Bar)
		if (S.Time.BarLength(Bar) != BarRows || BarRows % Grid.Rows != 0)
			throw Problem(Format("Bar %d is %s long, unlike bar %d (the last of its frame): grow the bars before it and after it apart.",
				Bar, Plural(S.Time.BarLength(Bar), "row", "rows").c_str(), From));
	const int StepsPerBar = BarRows / Grid.Rows;
	// Each of the motif's bars holds the meter's steps; a short last one holds its last note on to the bar line (or its rest)
	std::string Padded;
	bool HoldOn = false;
	for (size_t b = 0; b < Motif.Bars.size(); ++b) {
		const bool Last = b + 1 == Motif.Bars.size();
		if (Motif.Bars[b].Steps > StepsPerBar || (!Last && Motif.Bars[b].Steps < StepsPerBar))
			throw Problem(Format("motif: its bar %d has %d steps, and a bar here holds %d (%s).", static_cast<int>(b) + 1,
				Motif.Bars[b].Steps, StepsPerBar, GridText(S, Grid, From).c_str()));
		if (Last && Motif.Bars[b].Steps < StepsPerBar) {
			HoldOn = Motif.Notes.back().Step + Motif.Notes.back().Steps == Motif.Steps();
			Padded = Format(" (its last bar had %d steps of %d: %s to the bar line)", Motif.Bars[b].Steps, StepsPerBar, HoldOn ?
				"its last note holds on" : "its rest goes on");
		}
	}
	if (Motif.Bars.size() > 2)
		throw Problem("motif: a hook is a bar or two long; grow_melody makes the phrases from it.");

	const int Channel = GrowChannel(S, Args, First, End);
	const ChannelInfo &Info = S.Channel(Channel);
	int Low = 0, High = PITCHES - 1;
	MelodyRange(S, Channel, Low, High);
	GrowRequest Q;
	for (size_t i = 0; i < Motif.Notes.size(); ++i) {
		const StepLineNote &N = Motif.Notes[i];
		int Pitch = 0;
		if (!ParsePitch(N.Pitch, Pitch))
			throw Problem(Format("motif: \"%s\" isn't a note, a hold (-) or a rest (.). Write a note like D4, C#4, Bb3 or D-4 (FamiTracker "
				"octaves: C-3 is middle C).", N.Pitch.c_str()));
		if (Pitch < Low || Pitch > High)
			throw Problem(Format("motif: %s is out of %s's range for a melody (%s to %s).", PitchText(Info, Pitch).c_str(),
				Info.FullName().c_str(), PitchText(Info, Low).c_str(), PitchText(Info, High).c_str()));
		const bool LastNote = i + 1 == Motif.Notes.size();
		const int Steps = LastNote && HoldOn ? static_cast<int>(Motif.Bars.size()) * StepsPerBar - N.Step : N.Steps;
		Q.Motif.push_back(GrowNote(N.Step, Steps, Pitch));
	}
	if (Bars < 2 * static_cast<int>(Motif.Bars.size()))
		throw Problem(Format("A %s motif grows over %d bars or more; %s is too short.", Motif.Bars.size() > 1 ? "two-bar" : "one-bar",
			2 * static_cast<int>(Motif.Bars.size()), RangeText(From, To).c_str()));

	// The key, the kind and the chords
	bool Found;
	Key K = KeyArg(S, Args, "key", First, End, Found);
	std::vector<std::string> Remarks;
	if (!Found) {
		K = Key(0, MODE_MAJOR);
		Remarks.push_back("The song has no notes or key yet: grown in C major (key gives another).");
	}
	int Kind = GROW_LIVELY;
	std::string KindWhy;
	const std::string KindText = Squeezed(StringArg(Args, "kind"));
	if (KindText == "calm" || KindText == "ambient" || KindText == "night" || KindText == "peaceful")
		Kind = GROW_CALM;
	else if (KindText == "action" || KindText == "battle" || KindText == "boss" || KindText == "fight" || KindText == "chase")
		Kind = GROW_ACTION;
	else if (KindText.empty()) {
		const TrackStyle Chosen = ChooseStyle(S, -1, "grows fewer, longer notes that move by step", "lively");
		if (Chosen.Style == STYLE_CALM)
			Kind = GROW_CALM;
		else if (NameSaysTense(S.Song.TrackName))
			Kind = GROW_ACTION;
		KindWhy = Chosen.Style == STYLE_CALM ? " (the track's name says calm)" : Kind == GROW_ACTION ? " (the track's name says so)" :
			" (the default)";
		if (Chosen.Style != STYLE_CALM && !Chosen.Note.empty()) {
			std::string Note = Chosen.Note;	// "style calm ..." is kind calm here
			const size_t At = Note.find("style calm");
			if (At != std::string::npos)
				Note.replace(At, 5, "kind");
			Remarks.push_back(Note);
		}
	}
	else if (KindText != "lively" && KindText != "stage")
		throw Problem("kind: calm (fewer, longer notes, mostly steps), lively (the default: more motion) or action (drive).");
	static const char *const KIND_NAMES[] = { "calm", "lively", "action" };
	const std::vector<BarSpan> Spans = SongBarSpans(S, First, End);
	std::string Source;
	const std::vector<ChordAt> Chords = ChordsForMelody(S, Args, Channel, Spans, K, Source);
	int Covered = 0;
	for (size_t i = 0; i < Chords.size(); ++i)
		Covered += std::max(0, std::min(End, Chords[i].Row + Chords[i].Rows) - std::max(First, Chords[i].Row));
	if (Covered * 2 < End - First || (Source == "chords fitted to the melody" && !HasNotesIn(S, Channel, First, End)))
		throw Problem(Format("There are no chords in %s to grow a melody over: start from a groove (make_groove), add chords "
			"(add_chords_and_bass), or give chords (\"| G | Em | C | D |\").", RangeText(From, To).c_str()));

	Q.Bars = Bars;
	Q.StepsPerBar = StepsPerBar;
	Q.StepsPerBeat = StepsPerBeat;
	Q.RowsPerStep = Grid.Rows;
	Q.FirstBar = From;
	for (size_t i = 0; i < Chords.size(); ++i)
		Q.Chords.push_back(Chords[i].C);
	for (int s = 0; s < Bars * StepsPerBar; ++s) {
		const ChordAt *pChord = ChordAtRow(Chords, First + s * Grid.Rows);
		Q.StepChord.push_back(pChord != 0 ? static_cast<int>(pChord - &Chords[0]) : -1);
	}
	// What the other parts sound against it, as heard on its channel (a chord's arpeggio counted), and whose
	std::vector<std::pair<int, int> > Whose;	// the channel and the pitch as written there
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (c == Channel || !IsMelodic(S.Channel(c)))
			continue;
		const int Lift = Written(Info, 0) - Written(S.Channel(c), 0);
		const std::vector<NoteInfo> &Notes = S.Notes(c);
		const std::vector<int> Arps = StickyAt(S.Cells(c), Notes, S.Channel(c).EffectColumns, EFF_ARPEGGIO);
		for (size_t i = 0; i < Notes.size(); ++i) {
			const NoteInfo &N = Notes[i];
			if (N.Row >= End || N.Row + N.Rows <= First || N.Volume <= 0)
				continue;
			GrowOther O;
			O.Row = std::max(N.Row, First) - First;
			O.End = std::min(N.Row + N.Rows, End) - First;
			O.Pitch = N.Pitch + Lift;
			Q.Others.push_back(O);
			Whose.push_back(std::make_pair(c, N.Pitch));
			const std::vector<int> Above = ChordAbove(S, N, Arps[i]);
			for (size_t a = 0; a < Above.size(); ++a) {
				O.Pitch = N.Pitch + Lift + Above[a];
				Q.Others.push_back(O);
				Whose.push_back(std::make_pair(c, N.Pitch + Above[a]));
			}
		}
	}
	Q.RubRows = std::max(1, S.Time.RowsPerBeat / 2);
	Q.K = K;
	Q.Low = Low;
	Q.High = High;
	for (size_t i = 0; i < S.Song.Sections.size(); ++i) {
		const int Bar = SectionFirstBar(S, S.Song.Sections[i]);
		if (Bar > From && Bar <= To)
			Q.Sections.push_back(Bar - From);
	}
	Q.SpanOffset = BarsIntoPhrase(From, PhraseAnchor(S), 2) == 0 ? 0 : 1;
	Q.Kind = Kind;
	Q.Variant = IntArg(Args, "variant", 1, 1, 1000);
	std::vector<GrownVersion> Versions;
	if (!GrowMelody(Q, Versions, Error))
		throw Problem(Error);

	// The hook as written over the chords where it's first stated: a note of it off the chord on a strong beat stays
	{
		std::vector<std::string> Off;
		for (size_t i = 0; i < Q.Motif.size(); ++i)
			for (int s = Q.Motif[i].Step; s < Q.Motif[i].Step + Q.Motif[i].Steps; ++s) {
				const int InBar = s % StepsPerBar, Beats = StepsPerBar / StepsPerBeat;
				if (InBar != 0 && !(Beats % 2 == 0 && InBar == StepsPerBar / 2))
					continue;
				const int Index = Q.StepChord[static_cast<size_t>(s)];
				if (Index >= 0 && !Q.Chords[static_cast<size_t>(Index)].HasPitchClass(Q.Motif[i].Pitch % 12)) {
					Off.push_back(Format("%s at %s (%s)", StepPitch(Info, Q.Motif[i].Pitch).c_str(), S.Time.Position(First +
						s * Grid.Rows).c_str(), ChordName(Q.Chords[static_cast<size_t>(Index)], K).c_str()));
					break;
				}
			}
		if (!Off.empty()) {
			std::string List;
			for (size_t i = 0; i < Off.size(); ++i)
				List += (i == 0 ? "" : i + 1 == Off.size() ? " and " : ", ") + Off[i];
			Remarks.push_back("The hook as written has " + List + " off the chord on a strong beat; it stays as you wrote it, and comes "
				"back as written where it fits as well.");
		}
		// ...and a note of it a semitone from another part's for half a beat or more (check_song's clash)
		std::vector<std::string> Rubbing;
		for (size_t i = 0; i < Q.Motif.size() && Rubbing.size() < 3; ++i) {
			const int Row = Q.Motif[i].Step * Grid.Rows, Stop = (Q.Motif[i].Step + Q.Motif[i].Steps) * Grid.Rows;
			for (size_t o = 0; o < Q.Others.size(); ++o) {
				const GrowOther &O = Q.Others[o];
				if (std::abs(Q.Motif[i].Pitch - O.Pitch) % 12 != 1 || std::min(Stop, O.End) - std::max(Row, O.Row) < Q.RubRows)
					continue;
				Rubbing.push_back(Format("%s at %s against %s on %s", StepPitch(Info, Q.Motif[i].Pitch).c_str(),
					S.Time.Position(First + std::max(Row, O.Row)).c_str(), PitchText(S.Channel(Whose[o].first), Whose[o].second).c_str(),
					S.Channel(Whose[o].first).FullName().c_str()));
				break;
			}
		}
		if (!Rubbing.empty()) {
			std::string List;
			for (size_t i = 0; i < Rubbing.size(); ++i)
				List += (i == 0 ? "" : i + 1 == Rubbing.size() ? " and " : ", ") + Rubbing[i];
			Remarks.push_back("The hook as written rubs a semitone against another part (" + List + "), which check_song counts as a "
				"clash; it stays as you wrote it: another note of the hook there, or that chord without its note, clears it.");
		}
	}

	const int Pick = IntArg(Args, "pick", 0, 0, static_cast<int>(Versions.size()));
	std::vector<std::string> Lines;
	for (size_t v = 0; v < Versions.size(); ++v)
		Lines.push_back(GrownLine(Info, Versions[v].Notes, From, Bars, StepsPerBar));
	const std::string Over = Format("%s on %s, in %s, %s%s, over %s: %s", RangeText(From, To).c_str(), Info.FullName().c_str(),
		KeyName(K).c_str(), KIND_NAMES[Kind], KindWhy.c_str(), Source.c_str(), ProgressionText(Chords, Spans, K).c_str());
	if (Pick > 0) {
		// Written as write_notes writes a line
		Json Write = Json::MakeObject();
		Write.Set("channel", Json(Channel + 1));
		Write.Set("notes", Lines[static_cast<size_t>(Pick) - 1]);
		Write.Set("from_bar", Json(From));
		if (Arg(Args, "step") != 0)
			Write.Set("step", StringArg(Args, "step"));
		if (Arg(Args, "instrument") != 0)
			Write.Set("instrument", *Arg(Args, "instrument"));
		else if (InstrumentAt(S, Channel, First) == NO_INSTRUMENT)
			Write.Set("instrument", "soft lead");
		if (Arg(Args, "as_clip") != 0)
			Write.Set("as_clip", *Arg(Args, "as_clip"));
		Write.Set("clip_name", StringArg(Args, "clip_name", Format("Grown melody %d", Pick)));
		const std::string Reply = WriteNotesInSteps(S, Write);
		std::string Text = Format("Version %d of the hook grown over %s (variant %d). %s\n%s\n", Pick, Over.c_str(), Q.Variant,
			Versions[static_cast<size_t>(Pick) - 1].Shape.c_str(), Lines[static_cast<size_t>(Pick) - 1].c_str()) + Reply +
			"\nShape it by hand from here (read_notes with format steps, write_notes), then check_song and review_arrangement.";
		for (size_t i = 0; i < Remarks.size(); ++i)
			Text += "\nNote: " + Remarks[i];
		return Text;
	}
	std::string Text = Format("The hook \"%s\"%s, grown over %s.\n%s versions, each a line write_notes takes as notes (its bars "
		"numbered); pick %s with variant %d writes one, and variant %d gives others.", MotifText.c_str(), Padded.c_str(), Over.c_str(),
		Versions.size() == 3 ? "Three" : "Two", Versions.size() == 3 ? "1, 2 or 3" : "1 or 2", Q.Variant, Q.Variant + 1);
	for (size_t v = 0; v < Versions.size(); ++v)
		Text += Format("\n\nVersion %d. %s\n", static_cast<int>(v) + 1, Versions[v].Shape.c_str()) + Lines[v];
	Text += "\n\nPick the one that sings, then shape it by hand: a note, a rhythm, a held note longer.";
	for (size_t i = 0; i < Remarks.size(); ++i)
		Text += "\nNote: " + Remarks[i];
	return WithRemarks(S, Text);
}

// Finishing touches

// Accents in the draft: notes on a bar's first row as loud as the channel
// plays, other beats a step softer, between the beats two, quarter beats
// three. Channels that already shape their volumes are left alone. How
// many notes; -1 when the channel was left alone.
int Accents(Session &S, Draft &D, int Channel, int First, int End)
{
	const int R = S.Time.RowsPerBeat;
	const std::vector<NoteInfo> Notes = D.Notes(Channel);
	std::set<int> Volumes;
	int Loudest = 0;
	for (size_t i = 0; i < Notes.size(); ++i) {
		if (Notes[i].Row < First || Notes[i].Row >= End)
			continue;
		Volumes.insert(Notes[i].Volume);
		Loudest = std::max(Loudest, Notes[i].Volume);
	}
	if (Volumes.size() >= 3)
		return -1;
	std::vector<Cell> &Cells = D.Cells(Channel);
	int Count = 0;
	for (size_t i = 0; i < Notes.size(); ++i) {
		const NoteInfo &N = Notes[i];
		if (N.Row < First || N.Row >= End || N.Row >= static_cast<int>(Cells.size()))
			continue;
		const int InBar = N.Row - S.Time.BarStart(S.Time.BarOf(N.Row));
		int Softer = InBar == 0 ? 0 : InBar % R == 0 ? 1 : (2 * InBar) % R == 0 ? 2 : 3;
		if (StepVolume(S.Channel(Channel)))
			Softer = Softer >= 2 ? 1 : 0;	// a VRC7 or 5B step is 3 dB: the notes between beats one softer
		const int Volume = std::max(1, std::min(15, N.Volume - Softer));
		Cells[N.Row].Volume = static_cast<unsigned char>(Volume);
		++Count;
	}
	// The note after the bars plays as loud as before
	for (size_t i = 0; i < Notes.size(); ++i) {
		if (Notes[i].Row >= End && Notes[i].Row < static_cast<int>(Cells.size())) {
			if (Cells[Notes[i].Row].Volume == NO_VOLUME)
				Cells[Notes[i].Row].Volume = static_cast<unsigned char>(Notes[i].Volume);
			break;
		}
	}
	(void)Loudest;
	return Count;
}

// Repeated notes that run into each other on the triangle sound as one (it
// has no attack): each gets a halt on its last row. How many.
// Fades on a channel's held notes (two beats or more): a volume slide down
// (A0y) from halfway through, to about a third of the note's loudness by its
// end, and the next note given its own volume back (A00 stops the slide).
// How many notes; Lost when an effect column was full.
int AddFades(Session &S, Draft &D, int Channel, int First, int End, bool &Lost)
{
	const int R = S.Time.RowsPerBeat;
	const int Columns = S.Channel(Channel).EffectColumns;
	std::vector<Cell> &Cells = D.Cells(Channel);
	const std::vector<NoteInfo> Notes = D.Notes(Channel);
	const int Ticks = std::max(1, S.Song.Speed);	// a row's ticks
	int Count = 0;
	for (size_t i = 0; i < Notes.size(); ++i) {
		const NoteInfo &N = Notes[i];
		if (N.Row < First || N.Row >= End || N.Rows < 2 * R || N.Volume < 3)
			continue;
		bool Shaped = false;	// a slide or tremolo of its own
		for (size_t e = 0; e < N.Effects.size(); ++e)
			Shaped = Shaped || N.Effects[e].second.first == EFF_VOLUME_SLIDE || N.Effects[e].second.first == EFF_TREMOLO;
		if (Shaped)
			continue;
		int From = N.Row + N.Rows / 2;
		const bool Fm = StepVolume(S.Channel(Channel));
		if (Fm)	// three steps of 3 dB, over the note's last frames
			From = std::max(From, N.Row + N.Rows - std::max(1, (24 + Ticks - 1) / Ticks));
		const int Rows = N.Row + N.Rows - From;
		// Two thirds of the loudness in eighths of a step, over the rows left
		const int Eighths = Fm ? 24 : N.Volume * 2 * 8 / 3;
		const int Down = std::max(1, std::min(4, (Eighths + Rows * Ticks - 1) / (Rows * Ticks)));
		if (From >= static_cast<int>(Cells.size()) || !AddEffect(Cells[static_cast<size_t>(From)], EFF_VOLUME_SLIDE, Down, Columns)) {
			Lost = true;
			continue;
		}
		// The next note, or the row after this one's end: the slide stops, the volume comes back
		const int After = N.Row + N.Rows;
		if (After < static_cast<int>(Cells.size())) {
			Cell &Next = Cells[static_cast<size_t>(After)];
			if (!HasEffect(Next, EFF_VOLUME_SLIDE, Columns) && !AddEffect(Next, EFF_VOLUME_SLIDE, 0, Columns))
				Lost = true;
			if (Next.HasNote() && Next.Volume == NO_VOLUME)
				Next.Volume = static_cast<unsigned char>(i + 1 < Notes.size() ? Notes[i + 1].Volume : N.Volume);
			// Ended by a release or halt, a rest after it: the slide stopped where it had got to, so the note after
			// the rest gets its volume back too (else it plays at the faded level, near silence)
			if (!Next.HasNote() && i + 1 < Notes.size() && Notes[i + 1].Row > After &&
				Notes[i + 1].Row < static_cast<int>(Cells.size())) {
				Cell &Later = Cells[static_cast<size_t>(Notes[i + 1].Row)];
				if (Later.Volume == NO_VOLUME)
					Later.Volume = static_cast<unsigned char>(Notes[i + 1].Volume);
			}
		}
		++Count;
	}
	return Count;
}

// Scoops into a channel's held notes that come after a leap up: the note
// written a semitone or two lower, sliding up into it at once (Q61, Q62),
// at most one every two bars. How many; Lost when an effect column was full.
int AddScoops(Session &S, Draft &D, int Channel, int First, int End, bool &Lost)
{
	const int R = S.Time.RowsPerBeat;
	const int Columns = S.Channel(Channel).EffectColumns;
	std::vector<Cell> &Cells = D.Cells(Channel);
	const std::vector<NoteInfo> Notes = D.Notes(Channel);
	int Count = 0, Last = -1000;
	for (size_t i = 1; i < Notes.size(); ++i) {
		const NoteInfo &N = Notes[i], &Before = Notes[i - 1];
		if (N.Row < First || N.Row >= End || N.Rows < R || N.Row - Last < 2 * S.Time.RowsPerBar)
			continue;
		const int Leap = N.Pitch - Before.Pitch;
		if (Leap < 3 || N.Row - (Before.Row + Before.Rows) > R || N.Pitch < 3)
			continue;
		bool Sliding = false;
		for (size_t e = 0; e < N.Effects.size(); ++e) {
			const int Effect = N.Effects[e].second.first;
			Sliding = Sliding || Effect == EFF_SLIDE_UP || Effect == EFF_SLIDE_DOWN || Effect == EFF_PORTAMENTO || Effect == EFF_PORTA_UP ||
				Effect == EFF_PORTA_DOWN || Effect == EFF_ARPEGGIO;
		}
		if (Sliding)
			continue;
		Cell &C = Cells[static_cast<size_t>(N.Row)];
		const int Below = Leap >= 5 ? 2 : 1;
		if (!AddEffect(C, EFF_SLIDE_UP, 0x60 | Below, Columns)) {
			Lost = true;
			continue;
		}
		C.SetPitch(N.Pitch - Below);
		Last = N.Row;
		++Count;
	}
	return Count;
}

// Falls where a channel's phrases end: a note of a beat or more that a rest
// of a beat or more follows drops two semitones as it ends (R42 half a beat
// before its end, quick and short, a sigh), at most one every two bars. How
// many; Lost when an effect column was full.
int AddFalls(Session &S, Draft &D, int Channel, int First, int End, bool &Lost)
{
	const int R = S.Time.RowsPerBeat;
	const int Columns = S.Channel(Channel).EffectColumns;
	std::vector<Cell> &Cells = D.Cells(Channel);
	const std::vector<NoteInfo> Notes = D.Notes(Channel);
	int Count = 0, Last = -1000;
	for (size_t i = 0; i < Notes.size(); ++i) {
		const NoteInfo &N = Notes[i];
		const int Stop = N.Row + N.Rows;	// where a halt or release ends it
		if (N.Row < First || N.Row >= End || N.Rows < R || N.Row - Last < 2 * S.Time.RowsPerBar || N.Pitch < 3 ||
			Stop >= static_cast<int>(Cells.size()) || !Cells[static_cast<size_t>(Stop)].IsEnd())
			continue;
		const int Next = i + 1 < Notes.size() ? Notes[i + 1].Row : static_cast<int>(Cells.size());
		if (Next - Stop < R)
			continue;	// a breath, not a phrase's end
		bool Sliding = false;
		for (size_t e = 0; e < N.Effects.size(); ++e) {
			const int Effect = N.Effects[e].second.first;
			Sliding = Sliding || Effect == EFF_SLIDE_UP || Effect == EFF_SLIDE_DOWN || Effect == EFF_PORTAMENTO || Effect == EFF_PORTA_UP ||
				Effect == EFF_PORTA_DOWN || Effect == EFF_ARPEGGIO;
		}
		const int At = std::max(N.Row + 1, Stop - std::max(1, R / 2));
		if (Sliding || At >= Stop)
			continue;
		if (!AddEffect(Cells[static_cast<size_t>(At)], EFF_SLIDE_DOWN, 0x42, Columns)) {
			Lost = true;
			continue;
		}
		Last = N.Row;
		++Count;
	}
	return Count;
}

int SeparateRepeats(Session &S, Draft &D, int Channel, int First, int End)
{
	const std::vector<NoteInfo> Notes = D.Notes(Channel);
	std::vector<Cell> &Cells = D.Cells(Channel);
	int Count = 0;
	for (size_t i = 0; i + 1 < Notes.size(); ++i) {
		const NoteInfo &N = Notes[i];
		if (N.Row < First || N.Row >= End || Notes[i + 1].Row != N.Row + N.Rows || Notes[i + 1].Pitch != N.Pitch || N.Rows < 2)
			continue;
		Cell &Last = Cells[static_cast<size_t>(N.Row + N.Rows - 1)];
		if (Last.Note != NOTE_NONE)
			continue;
		Last.Note = NOTE_HALT;
		++Count;
	}
	(void)S;
	return Count;
}

// A bass played short: each note of a beat or more cut after three
// quarters of a beat (a halt), so the line bounces as a triangle bass in
// atmospheric and action tracks does. How many notes.
int StaccatoBass(Session &S, Draft &D, int Channel, int First, int End)
{
	const int R = S.Time.RowsPerBeat;
	const int Keep = std::max(1, R / 2);
	const std::vector<NoteInfo> Notes = D.Notes(Channel);
	std::vector<Cell> &Cells = D.Cells(Channel);
	int Count = 0;
	for (size_t i = 0; i < Notes.size(); ++i) {
		const NoteInfo &N = Notes[i];
		if (N.Row < First || N.Row >= End || N.Rows < R || N.Row + Keep >= static_cast<int>(Cells.size()))
			continue;
		Cell &Cut = Cells[static_cast<size_t>(N.Row + Keep)];
		if (Cut.Note != NOTE_NONE)
			continue;
		Cut.Note = NOTE_HALT;
		++Count;
	}
	return Count;
}

std::string PolishTool(Session &S, const Json &Args)
{
	int From, To;
	BarRange(S, Args, From, To);
	const int First = S.Time.BarStart(From), End = S.Time.BarEnd(To);
	const bool AsClip = BoolArg(Args, "as_clip", false);
	// A calm or a lively track gets no accents unless asked (they make a melody press), and on a calm
	// one the vibrato is the shallowest, waiting about half a beat
	const TrackStyle Chosen = ChooseStyle(S, StyleArg(Args), "leaves out accents and waits longer with a shallower vibrato", "any");
	const bool Calm = Chosen.Style == STYLE_CALM;
	std::set<std::string> What;
	const Json *pWhat = Arg(Args, "touches");
	if (pWhat == 0) {
		if (Chosen.Style == STYLE_ANY)
			What.insert("accents");
		What.insert("vibrato");
		What.insert("separate");
		What.insert("clicks");
	}
	else {
		std::vector<std::string> Words;
		if (pWhat->IsArray()) {
			for (size_t i = 0; i < pWhat->Size(); ++i)
				if (pWhat->At(i).IsString())
					Words.push_back(pWhat->At(i).String());
		}
		else if (pWhat->IsString())
			Words.push_back(pWhat->String());
		for (size_t i = 0; i < Words.size(); ++i) {
			const std::string Word = Squeezed(Words[i]);
			if (Word != "accents" && Word != "vibrato" && Word != "separate" && Word != "fades" && Word != "scoops" &&
				Word != "staccato" && Word != "falls" && Word != "clicks")
				throw Problem("touches: accents, vibrato, separate, fades, scoops, falls, staccato or clicks.");
			What.insert(Word);
		}
	}
	const std::vector<int> Channels = ChannelsArg(S, Args, "channels");
	int Melody = Arg(Args, "melody_channel") != 0 ? ChannelArg(S, Args, "melody_channel") : GuessMelodyChannel(S, First, End);

	Draft D(S);
	std::vector<std::string> Done, Warnings;
	if (What.count("accents")) {
		std::string List, Fm;
		for (size_t i = 0; i < Channels.size(); ++i) {
			const int c = Channels[i];
			if (S.Channel(c).Kind == KIND_TRIANGLE || !IsMelodic(S.Channel(c)))
				continue;	// the triangle has no volume
			const int Count = Accents(S, D, c, First, End);
			std::string &Into = StepVolume(S.Channel(c)) ? Fm : List;
			if (Count > 0)
				Into += (Into.empty() ? "" : ", ") + S.Channel(c).FullName();
			else if (Count < 0)
				Warnings.push_back(S.Channel(c).FullName() + " already shapes its volumes, so it kept them.");
		}
		if (!List.empty())
			Done.push_back("accents (beats a step softer than a bar's first note, the notes between them softer still) on " + List);
		if (!Fm.empty())	// a VRC7 or 5B step is 3 dB
			Done.push_back("accents (the notes between beats a step, 3 dB, softer than the beats) on " + Fm);
	}
	if (What.count("vibrato") && Melody >= 0 && std::find(Channels.begin(), Channels.end(), Melody) != Channels.end()) {
		VibratoPlan Plan;
		Plan.Channel = Melody;
		Plan.Speed = 5;
		Plan.Depth = 2;
		Plan.MinRows = S.Time.RowsPerBeat * 3 / 2;
		Plan.Delay = std::max(1, S.Time.RowsPerBeat / 2);
		int HeardFor = 0;
		if (Calm) {
			// The shallowest (451, about 1.5 period steps), coming in nearest 27 frames in (24-30, about half a beat at a
			// calm tempo), on the long notes whose sound still sounds then
			Plan.Depth = 1;
			Plan.Delay = CalmVibratoRows(S);
			HeardFor = static_cast<int>(std::floor(Plan.Delay * FramesPerRow(S) + 0.5)) + 6;
		}
		bool Lost = false;
		const int Count = MakeVibrato(S, D, Plan, First, End, Lost, true, HeardFor);
		if (Lost)
			Warnings.push_back("Some notes had no free effect column for the vibrato (all four were full).");
		if (Count > 0 && Calm)
			Done.push_back(Format("the shallowest vibrato (4%X%X) coming in %d frames into %s of %s", Plan.Speed, Plan.Depth,
				static_cast<int>(std::floor(Plan.Delay * FramesPerRow(S) + 0.5)), Plural(Count, "long note", "long notes").c_str(),
				S.Channel(Melody).FullName().c_str()));
		else if (Count > 0)
			Done.push_back(Format("a gentle vibrato that comes in after half a beat on %s of %s", Plural(Count, "long note", "long notes").c_str(),
				S.Channel(Melody).FullName().c_str()));
	}
	if (What.count("fades")) {
		std::string List, Steps;	// Steps: the chips counting 3 dB a step that got fades ("the VRC7 and the 5B")
		int Total = 0;
		bool Lost = false;
		for (size_t i = 0; i < Channels.size(); ++i) {
			const int c = Channels[i];
			if (!IsMelodic(S.Channel(c)) || S.Channel(c).Kind == KIND_TRIANGLE)
				continue;
			const int Count = AddFades(S, D, c, First, End, Lost);
			if (Count > 0) {
				List += (List.empty() ? "" : ", ") + S.Channel(c).FullName();
				Total += Count;
				if (StepVolume(S.Channel(c)) && Steps.find("the " + S.Channel(c).Chip) == std::string::npos)
					Steps += (Steps.empty() ? "the " : " and the ") + S.Channel(c).Chip;
			}
		}
		if (Lost)
			Warnings.push_back("Some held notes had no free effect column for a fade (all four were full).");
		if (Total > 0)
			Done.push_back(Format("fades on %s (a volume slide from halfway through, A0y, the next note at its own volume%s) on %s",
				Plural(Total, "held note", "held notes").c_str(), Steps.empty() ? "" :
				("; on " + Steps + " three steps, 9 dB, over the note's end").c_str(), List.c_str()));
	}
	if (What.count("scoops") && Melody >= 0 && std::find(Channels.begin(), Channels.end(), Melody) != Channels.end()) {
		bool Lost = false;
		const int Count = AddScoops(S, D, Melody, First, End, Lost);
		if (Lost)
			Warnings.push_back("Some notes had no free effect column for a scoop (all four were full).");
		if (Count > 0)
			Done.push_back(Format("%s after leaps up on %s (written a semitone or two low, sliding up with Q6y)",
				Plural(Count, "scoop", "scoops").c_str(), S.Channel(Melody).FullName().c_str()));
	}
	if (What.count("falls") && Melody >= 0 && std::find(Channels.begin(), Channels.end(), Melody) != Channels.end()) {
		bool Lost = false;
		const int Count = AddFalls(S, D, Melody, First, End, Lost);
		if (Lost)
			Warnings.push_back("Some phrase ends had no free effect column for a fall (all four were full).");
		if (Count > 0)
			Done.push_back(Format("%s where phrases of %s end (a drop of two semitones as the last note ends, R42)",
				Plural(Count, "fall", "falls").c_str(), S.Channel(Melody).FullName().c_str()));
	}
	if (What.count("staccato")) {
		for (size_t i = 0; i < Channels.size(); ++i) {
			const int c = Channels[i];
			if (!IsBass(S.Channel(c)))
				continue;
			const int Count = StaccatoBass(S, D, c, First, End);
			if (Count > 0)
				Done.push_back(Format("%s on %s cut short after half a beat (staccato)",
					Plural(Count, "bass note", "bass notes").c_str(), S.Channel(c).FullName().c_str()));
		}
	}
	if (What.count("separate")) {
		for (size_t i = 0; i < Channels.size(); ++i) {
			const int c = Channels[i];
			if (S.Channel(c).Kind != KIND_TRIANGLE)
				continue;
			const int Count = SeparateRepeats(S, D, c, First, End);
			if (Count > 0)
				Done.push_back(Format("a short gap before %s on %s, so each is heard", Plural(Count, "repeated note", "repeated notes").c_str(),
					S.Channel(c).FullName().c_str()));
		}
	}
	if (What.count("clicks")) {
		// Last, so it hears the other touches too: notes on the 2A03's and MMC5's pulses whose vibrato clicks, nudged
		std::vector<std::vector<Cell> > All;
		std::vector<int> Columns;
		for (int c = 0; c < S.ChannelCount(); ++c) {
			All.push_back(D.View(c));
			Columns.push_back(S.Channel(c).EffectColumns);
		}
		int LoopRow = -1;
		const std::vector<std::pair<int, int> > Played = PlayedFrames(S.Song, All, Columns, LoopRow);
		bool Lost = false;
		for (size_t i = 0; i < Channels.size(); ++i) {
			const int c = Channels[i];
			if (!ClicksOnPeriods(S.Channel(c)))
				continue;
			std::vector<Cell> Work = All[static_cast<size_t>(c)];
			int Shown = Columns[static_cast<size_t>(c)];
			const std::vector<ClickFix> Fixes = SmoothClicks(S.Song, Work, Shown, First, End, Played, LoopRow, true, Lost);
			if (Fixes.empty())
				continue;
			D.Cells(c) = Work;
			std::string List;
			int Nudged = 0;
			for (size_t f = 0; f < Fixes.size(); ++f) {
				if (Fixes[f].Shift == 0 || Fixes[f].Left > 0)
					continue;
				if (++Nudged <= 4)
					List += Format("%s%s at %s (%s)", List.empty() ? "" : ", ", PitchName(Fixes[f].Pitch).c_str(),
						S.Time.Position(Fixes[f].Row).c_str(), NudgeText(S, Fixes[f]).c_str());
			}
			if (Nudged > 0)
				Done.push_back(Format("%s on %s nudged a hair so %s vibrato doesn't click (%s%s)", Plural(Nudged, "note", "notes").c_str(),
					S.Channel(c).FullName().c_str(), Nudged == 1 ? "its" : "their", List.c_str(), Nudged > 4 ? ", ..." : ""));
			if (Nudged < static_cast<int>(Fixes.size())) {
				std::vector<ClickFix> Stuck;
				for (size_t f = 0; f < Fixes.size(); ++f)
					if (Fixes[f].Shift == 0 || Fixes[f].Left > 0)
						Stuck.push_back(Fixes[f]);
				Warnings.push_back(SmoothedText(S, c, Stuck));
			}
		}
		if (Lost)
			Warnings.push_back("A note that clicks had no free effect column for its nudge (Pxx), so it still clicks.");
	}
	std::vector<Change> Changes;
	int Start;
	if (!D.Collect(First, Direct(S, AsClip), Changes, Start, Warnings))
		throw Problem(Calm ? "There was nothing to polish there: no long melody notes for vibrato (sounding when it would come "
			"in, without a vibrato of their own), no repeated triangle notes and no notes that click." : "There was nothing to "
			"polish there: no notes for accents, no long melody notes for vibrato, no repeated triangle notes and no notes that click.");
	std::string Summary;
	for (size_t i = 0; i < Done.size(); ++i)
		Summary += (i == 0 ? "" : "; ") + Done[i];
	// Asked for on a calm track, accents, scoops and falls are done, and said to work against it
	std::vector<std::string> Against;
	static const char *const PRESSING[] = { "accents", "scoops", "falls" };
	for (int k = 0; k < 3 && Calm; ++k)
		if (What.count(PRESSING[k]))
			Against.push_back(PRESSING[k]);
	if (!Against.empty()) {
		std::string List;
		for (size_t i = 0; i < Against.size(); ++i)
			List += (i == 0 ? "" : i + 1 == Against.size() ? " and " : ", ") + Against[i];
		List[0] = static_cast<char>(std::toupper(static_cast<unsigned char>(List[0])));
		Summary += ". " + List + " go against the calm style: they make a melody press, where a calm one swells in or fades by itself";
	}
	return WithRemarks(S, Commit(S, Changes, Start, AsClip, StringArg(Args, "clip_name"), "finishing touches, " + RangeText(From, To)) +
		"\nTouches: " + Summary + "." + (Chosen.Note.empty() ? "" : " " + Chosen.Note), Warnings);
}

// The chords a song's parts play in [First, End): the melody left out when
// others play too, else the chords it implies by itself
std::vector<ChordAt> SongChords(Session &S, int First, int End, const Key &K, int Melody)
{
	if (Melody == -2)
		Melody = GuessMelodyChannel(S, First, End);
	bool Backing = false;
	for (int c = 0; c < S.ChannelCount() && !Backing; ++c)
		Backing = c != Melody && IsMelodic(S.Channel(c)) && HasNotesIn(S, c, First, End);
	return HearChords(HeardNotes(S, Backing ? Melody : -1, First, End), SongBarSpans(S, First, End), S.Time.RowsPerBeat, K, true);
}

// The depth review: what a part, or the arrangement, is missing

std::string SecondsText(double Seconds);

// Bars as "3, 5-8, 12"
std::string BarList(const std::vector<int> &Bars)
{
	std::string Out;
	for (size_t i = 0; i < Bars.size(); ) {
		size_t j = i;
		while (j + 1 < Bars.size() && Bars[j + 1] == Bars[j] + 1)
			++j;
		Out += (Out.empty() ? "" : ", ") + (j == i ? Format("%d", Bars[i]) : Format("%d-%d", Bars[i], Bars[j]));
		i = j + 1;
	}
	return Out;
}

// A bar of a channel as text: its notes' rows, pitches, lengths and
// volumes, for finding bars that repeat note for note
std::string BarPrint(const std::vector<NoteInfo> &Notes, int Row, int End)
{
	std::string Out;
	for (size_t i = 0; i < Notes.size(); ++i) {
		const NoteInfo &N = Notes[i];
		if (N.Row < Row || N.Row >= End)
			continue;
		Out += Format("%d:%d:%d:%d ", N.Row - Row, N.Pitch, std::min(N.Rows, End - N.Row), N.Volume);
	}
	return Out;
}

// What a version's name says about it: calm (night), tense (battle) or neither
enum version_mood { MOOD_OTHER, MOOD_CALM, MOOD_TENSE };

int VersionMood(const std::string &Version)
{
	static const char *const CALM[] = { "night", "calm", "evening", "sleep", "sleepy", "peaceful", "quiet", "relaxed" };
	static const char *const TENSE[] = { "tense", "battle", "danger", "boss", "fight", "combat", "chase", "alarm", "panic" };
	bool Calm = false, Tense = false;
	std::string Word;
	const std::string Text = Lowercase(Version) + " ";
	for (size_t i = 0; i < Text.size(); ++i) {
		const char c = Text[i];
		if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')) {
			Word += c;
			continue;
		}
		for (size_t w = 0; w < sizeof(CALM) / sizeof(CALM[0]); ++w)
			Calm = Calm || Word == CALM[w];
		for (size_t w = 0; w < sizeof(TENSE) / sizeof(TENSE[0]); ++w)
			Tense = Tense || Word == TENSE[w];
		Word.clear();
	}
	if (Calm == Tense)
		return MOOD_OTHER;
	return Calm ? MOOD_CALM : MOOD_TENSE;
}

bool NameSaysCalm(const std::string &TrackName)
{
	return VersionMood(TrackName) == MOOD_CALM;
}

bool NameSaysTense(const std::string &TrackName)
{
	return VersionMood(TrackName) == MOOD_TENSE;
}

// How a sound shapes a long note, read from its volume sequence: one that reaches its peak in
// under 10 frames and holds 11 or more (as on a pulse's 0-15) presses, an organ key held down however soft the parts
// around it, which sounds aggressive; a swell of 10 frames or more, a strike that
// falls to 7 or under, or one that fades away doesn't. On the 5B its levels count as a pulse's would sound (3 dB a step)
struct SoundShape {
	bool Known;			// it has a volume sequence the tools can read (the VRC7's sounds have none)
	int Attack, Peak, Hold;	// frames to its peak (90% of it), its peak and the level a long note holds (0: it fades away)
	bool Presses;
	std::string Words;	// "reaches 15 in 2 frames and holds 12"
	SoundShape() : Known(false), Attack(0), Peak(15), Hold(15), Presses(false) {}
};

SoundShape ShapeOf(const InstrumentInfo *pInfo)
{
	SoundShape Out;
	if (pInfo == 0 || pInfo->Chip == "VRC7")
		return Out;
	Out.Known = true;
	std::vector<int> Values = pInfo->Volume;
	if (pInfo->Chip == "5B")
		for (size_t i = 0; i < Values.size(); ++i)
			Values[i] = Values[i] <= 0 ? 0 : static_cast<int>(std::floor(15.0 * std::pow(10.0, -3.0 * (15 - std::min(15, Values[i])) / 20.0) + 0.5));
	if (Values.empty()) {
		Out.Words = "holds 15 (no volume sequence)";
		Out.Presses = true;
		return Out;
	}
	const int Loop = pInfo->VolumeLoop, Release = pInfo->VolumeRelease, Items = static_cast<int>(Values.size());
	Out.Peak = std::max(1, *std::max_element(Values.begin(), Values.end()));
	while (Out.Attack < Items - 1 && Values[static_cast<size_t>(Out.Attack)] * 10 < Out.Peak * 9)
		++Out.Attack;
	int Run = Items;
	if (Release >= 0 && Release < Items) {
		Out.Hold = Values[static_cast<size_t>(Release)];
		Run = Release + 1;
	}
	else if (Loop >= 0 && Loop < Items)
		Out.Hold = *std::max_element(Values.begin() + Loop, Values.end());
	else
		Out.Hold = Values.back();
	if (Out.Hold == 0 || (Release < 0 && Loop < 0 && Out.Hold <= 2)) {
		int Gone = Out.Attack + 1;
		while (Gone < Run && Values[static_cast<size_t>(Gone)] > std::max(1, Out.Peak / 6))
			++Gone;
		Out.Hold = 0;
		Out.Words = Format("strikes and fades away in %d frames", Gone);
		return Out;
	}
	if (Out.Attack >= 8) {
		Out.Words = Format("swells in over %d frames, then holds %d", Out.Attack, Out.Hold);
		Out.Presses = Out.Attack < 10 && Out.Hold >= 11;
		return Out;
	}
	if (Out.Hold <= 7) {
		int Fall = Out.Attack + 1;
		while (Fall < Run && Values[static_cast<size_t>(Fall)] > Out.Hold)
			++Fall;
		Out.Words = Format("strikes and falls to %d in %d frames", Out.Hold, Fall);
		return Out;
	}
	Out.Words = Format("reaches %d in %s and holds %d", Out.Peak, Plural(Out.Attack + 1, "frame", "frames").c_str(), Out.Hold);
	Out.Presses = Out.Hold >= 11;
	return Out;
}

// The melody's sounds that hold a high, steady level from attack to release, by how many of its notes in [First, End)
// play each (two or more): the instrument, its shape and that count
struct HeldLead {
	int Instrument, Notes, Of, Row;	// Row: its first note's
	SoundShape Shape;
};

std::vector<HeldLead> HeldLeads(Session &S, int Melody, int First, int End)
{
	std::vector<HeldLead> Out;
	if (Melody < 0 || !IsMelodic(S.Channel(Melody)) || S.Channel(Melody).Kind == KIND_TRIANGLE)
		return Out;
	const std::vector<NoteInfo> Tune = NotesIn(S.Notes(Melody), First, End);
	std::map<int, std::pair<int, int> > By;	// instrument -> notes, first row
	for (size_t i = 0; i < Tune.size(); ++i) {
		std::map<int, std::pair<int, int> >::iterator it = By.find(Tune[i].Instrument);
		if (it == By.end())
			By[Tune[i].Instrument] = std::make_pair(1, Tune[i].Row);
		else
			++it->second.first;
	}
	for (std::map<int, std::pair<int, int> >::const_iterator it = By.begin(); it != By.end(); ++it) {
		const SoundShape Shape = ShapeOf(FindInstrument(S.Song, it->first));
		if (!Shape.Known || !Shape.Presses || it->second.first < 2)
			continue;
		HeldLead H;
		H.Instrument = it->first;
		H.Notes = it->second.first;
		H.Of = static_cast<int>(Tune.size());
		H.Row = it->second.second;
		H.Shape = Shape;
		Out.push_back(H);
	}
	return Out;
}

// What check_song and the review say of one, and what to do
std::string HeldLeadText(Session &S, int Melody, const HeldLead &H)
{
	return Format("%s on %s %s (%d of %d melody notes): a calm lead shouldn't hold a high, steady level from attack to "
		"release. design_instrument kind breath (swells in), falling strike (falls to 6) or music box (fades away), or a "
		"volume sequence that does.", InstrumentLabel(S.Song, H.Instrument).c_str(), S.Channel(Melody).FullName().c_str(),
		H.Shape.Words.c_str(), H.Notes, H.Of);
}

// The frames a note lasts, from the frames each row does (RowFramesOf)
int NoteFrames(const NoteInfo &N, const std::vector<int> &RowFrames)
{
	int Frames = 0;
	for (int r = std::max(0, N.Row); r < N.Row + N.Rows && r < static_cast<int>(RowFrames.size()); ++r)
		Frames += RowFrames[static_cast<size_t>(r)];
	return Frames;
}

// The channels whose notes can vanish by their envelope: not the triangle, whose envelope only starts and stops it (its
// kicks are blips by design), the drums, or the VRC7, which shapes its own sounds
bool CanVanish(const ChannelInfo &Info)
{
	return Info.Kind == KIND_PULSE || Info.Kind == KIND_SAWTOOTH || Info.Kind == KIND_OTHER || Info.Kind == KIND_SQUARE;
}

// Whether a note vanishes (Heard: the frames it's heard for), or holds. A sound struck again while the note lasts (an
// envelope that loops back up, an echo of itself at half its level or more) is heard again, so it doesn't vanish
bool Vanishes(const SongInfo &Song, const NoteInfo &N, const std::vector<int> &RowFrames, int &Heard)
{
	const int Frames = NoteFrames(N, RowFrames);
	Heard = HeardFrames(Song, N, Frames);
	if (N.Volume <= 0 || Heard > VANISH_FRAMES || Frames < Heard + 2)
		return false;
	const InstrumentInfo *pInfo = FindInstrument(Song, N.Instrument);
	const std::vector<int> Envelope = HeldEnvelope(pInfo, Frames);
	int Peak = 0;
	for (int f = 0; f < Heard; ++f)
		Peak = std::max(Peak, HeardVolume(pInfo, N.Volume, Envelope[static_cast<size_t>(f)]));
	for (int f = Heard; f < Frames; ++f)
		if (HeardVolume(pInfo, N.Volume, Envelope[static_cast<size_t>(f)]) * 2 >= Peak)
			return false;
	return true;
}

bool Holds(const SongInfo &Song, const NoteInfo &N, const std::vector<int> &RowFrames)
{
	return N.Volume > 0 && NoteFrames(N, RowFrames) >= HOLD_FRAMES && HeardFrames(Song, N, HOLD_FRAMES) >= HOLD_FRAMES;
}

// A sound's notes that vanish in the middle of a line that holds: a run of up to MAX_VANISHING_RUN of them on a channel
// with a held note of the line just before and just after (a beat apart at most, and less than an octave away: a stab an
// octave off the line, an oom-pah's, is another voice), notes gone missing from the line. A longer run, or one where a
// line starts or ends, is a figure of its own (stabs, ticks, a ratchet) and fine
struct Vanishing {
	int Instrument;
	int Heard;				// the most frames its notes are heard for
	int Held;				// the instrument of the line's notes that hold
	std::vector<int> Rows;	// its notes'
};
const int MAX_VANISHING_RUN = 4;
const int MIN_VANISHING = 2;	// notes of a sound: one alone may be meant

// A channel's notes starting in [First, End) that vanish in the middle of a line that holds, by sound (MIN_VANISHING notes
// or more)
std::vector<Vanishing> VanishingNotes(Session &S, int Channel, int First, int End, const std::vector<int> &RowFrames)
{
	std::vector<Vanishing> Out;
	if (!CanVanish(S.Channel(Channel)))
		return Out;
	const std::vector<NoteInfo> &Notes = S.Notes(Channel);
	const int Count = static_cast<int>(Notes.size());
	std::vector<int> Heard(Notes.size(), 0);
	std::vector<char> Gone(Notes.size(), 0);
	for (int i = 0; i < Count; ++i)
		Gone[static_cast<size_t>(i)] = Vanishes(S.Song, Notes[static_cast<size_t>(i)], RowFrames, Heard[static_cast<size_t>(i)]) ? 1 : 0;
	// M, a note before (or After) N, holds right beside it in its register
	auto Beside = [&](const NoteInfo &M, const NoteInfo &N, bool After) {
		const int Gap = After ? M.Row - (N.Row + N.Rows) : N.Row - (M.Row + M.Rows);
		return Gap <= S.Time.RowsPerBeat && std::abs(M.Pitch - N.Pitch) < 12 && Holds(S.Song, M, RowFrames);
	};
	std::map<int, Vanishing> By;
	for (int i = 0; i < Count; ) {
		if (!Gone[static_cast<size_t>(i)]) {
			++i;
			continue;
		}
		int j = i;
		while (j + 1 < Count && Gone[static_cast<size_t>(j + 1)])
			++j;
		if (j - i + 1 <= MAX_VANISHING_RUN && i > 0 && j + 1 < Count &&
			Beside(Notes[static_cast<size_t>(i - 1)], Notes[static_cast<size_t>(i)], false) &&
			Beside(Notes[static_cast<size_t>(j + 1)], Notes[static_cast<size_t>(j)], true)) {
			for (int k = i; k <= j; ++k) {
				const NoteInfo &N = Notes[static_cast<size_t>(k)];
				if (N.Row < First || N.Row >= End)
					continue;
				std::map<int, Vanishing>::iterator it = By.find(N.Instrument);
				if (it == By.end()) {
					Vanishing V;
					V.Instrument = N.Instrument;
					V.Heard = 0;
					V.Held = Notes[static_cast<size_t>(i - 1)].Instrument;
					it = By.insert(std::make_pair(N.Instrument, V)).first;
				}
				it->second.Heard = std::max(it->second.Heard, Heard[static_cast<size_t>(k)]);
				it->second.Rows.push_back(N.Row);
			}
		}
		i = j + 1;
	}
	for (std::map<int, Vanishing>::const_iterator it = By.begin(); it != By.end(); ++it)
		if (static_cast<int>(it->second.Rows.size()) >= MIN_VANISHING)
			Out.push_back(it->second);
	return Out;
}

std::string VanishingText(Session &S, int Channel, const Vanishing &V)
{
	return Format("%s on %s (%s) play %s, which is gone within %s, between notes of the line that hold (%s): next to "
		"those they sound like missing notes, a tick in their place. Give them a sound that lasts, a pluck that settles to a "
		"level instead of dying (design_instrument kind pluck, sustain half) or the held notes' sound; sounds that vanish this "
		"fast are for echoes, stabs and drums.", Plural(static_cast<int>(V.Rows.size()), "note", "notes").c_str(),
		S.Channel(Channel).FullName().c_str(), RangeText(S.Time.BarOf(V.Rows.front()), S.Time.BarOf(V.Rows.back())).c_str(),
		InstrumentLabel(S.Song, V.Instrument).c_str(), Plural(V.Heard, "frame", "frames").c_str(),
		InstrumentLabel(S.Song, V.Held).c_str());
}

// How loud a note plays over its rows [From, To) on average, as power against
// a pulse at 15: its volume times its instrument's envelope frame by frame (a
// pluck dies away, a pad swells), as FamiTracker plays each chip; the triangle
// a little under a pulse at 15 while its envelope lets it sound
double NotePower(Session &S, int Channel, const NoteInfo &N, int From, int To, double RowFrames)
{
	const ChannelInfo &Info = S.Channel(Channel);
	if (To <= From)
		return 0.0;
	const int First = std::max(0, static_cast<int>(std::floor((From - N.Row) * RowFrames)));
	const int Last = std::max(First + 1, static_cast<int>(std::floor((To - N.Row) * RowFrames)));
	const std::vector<int> Envelope = HeldEnvelope(Info.Kind == KIND_FM ? 0 : FindInstrument(S.Song, N.Instrument), Last);
	// A 5B note that plays the chip's envelope (a buzz) plays it at full level whatever its volume, unless that's 0
	bool Buzz = false;
	if (Info.Kind == KIND_SQUARE) {
		const InstrumentInfo *pInfo = FindInstrument(S.Song, N.Instrument);
		int Sticky = 0;	// the Vxx in effect, for an instrument without a mode sequence
		const std::vector<Cell> &Cells = S.Cells(Channel);
		for (int r = 0; (pInfo == 0 || pInfo->Mode.Items.empty()) && r <= N.Row && r < static_cast<int>(Cells.size()); ++r)
			for (int k = 0; k < std::min(EFFECT_COLUMNS, Info.EffectColumns); ++k)
				if (Cells[static_cast<size_t>(r)].Effect[k] == EFF_DUTY_CYCLE)
					Sticky = Cells[static_cast<size_t>(r)].Param[k];
		Buzz = PlaysEnvelope(S, N, Sticky);
	}
	double Sum = 0.0;
	for (int f = First; f < Last; ++f) {
		const int Level = Envelope[static_cast<size_t>(f)];
		if (Info.Kind == KIND_TRIANGLE)
			Sum += Level > 0 ? std::pow(10.0, (-2.0 + FaderDb(Info)) / 10.0) : 0.0;	// its fader in, as every channel's
		else {
			const int Volume = PlayedVolume(Info, N.Volume, Level);
			Sum += Volume > 0 ? std::pow(10.0, LevelDb(Info, Buzz ? 15 : Volume) / 10.0) : 0.0;
		}
	}
	return Sum / (Last - First);
}

// Where a melody pauses, as a listener hears its phrases end: a rest of a beat or more, or a note held two beats or more,
// as it sounds (a note on a sound that has faded away rests from there, HeardFrames; a note at volume 0 is a rest).
// Counted in the two-bar spans phrases make (from PhraseAnchor) inside bars From-To where the melody plays at all (a
// break without it is left out, not a miss); a pause is the span's where it starts (a rest where the sound stops, a held
// note where it's struck, so a phrase ending on a long note over the bar line breathes in its own span). A rest over the
// beat before a bar line, where the melody stops at the line, is a breath only where it ends a phrase of two bars or more
// (PHRASE_SLACK_BEATS short of it, for a pickup or a late start; from the phrase's first note to where the next starts):
// a melody that stops before every bar line is heard in one-bar pieces, and those rests aren't breaths (a local model's
// first stage paused in all 14 of its two-bar spans that way, with 23 rests in 28 bars; now 9, its held notes counted).
// A rest elsewhere (a phrase ending on a downbeat, a pickup after it) breathes as before, as the soundtrack's airy
// melodies do. A rest written in the notes (a beat or more from a note's end to the next) starts the next phrase, and so
// does a breath; a rest only heard (a written line on a sound that dies away) doesn't. PhraseEnds counts the spans where
// a phrase of two bars or more ends, every pause held to that (for the tip about one-bar pieces, PhrasesFinding)
const int PHRASE_SLACK_BEATS = 1;

struct MelodyBreaths {
	int Spans, Breaths, PhraseEnds;
	std::vector<int> RunOn;		// the first bars of the spans it runs through without a pause
	MelodyBreaths() : Spans(0), Breaths(0), PhraseEnds(0) {}
};

MelodyBreaths BreathsOf(Session &S, int Melody, int From, int To)
{
	MelodyBreaths Out;
	const int R = std::max(1, S.Time.RowsPerBeat), Anchor = PhraseAnchor(S), Total = S.Time.TotalRows();
	if (Total <= 0)
		return Out;
	const std::vector<int> RowFrames = RowFramesOf(S);
	auto SpanOf = [&](int Row) {
		const int Bar = S.Time.BarOf(std::max(0, std::min(Total - 1, Row)));
		return Bar - BarsIntoPhrase(Bar, Anchor, 2);
	};
	// Each note as heard: from its row to the row where its sound stops; and where it ends as written
	std::vector<std::pair<int, int> > Heard;
	std::vector<int> WrittenEnds;
	const std::vector<NoteInfo> &Notes = S.Notes(Melody);
	for (size_t i = 0; i < Notes.size(); ++i) {
		const NoteInfo &N = Notes[i];
		if (N.Volume <= 0 || N.Rows <= 0)
			continue;
		const int Frames = HeardFrames(S.Song, N, NoteFrames(N, RowFrames));
		int Stop = N.Row, Counted = 0;
		while (Stop < N.Row + N.Rows && Counted < Frames) {
			Counted += Stop < static_cast<int>(RowFrames.size()) ? RowFrames[static_cast<size_t>(Stop)] : 1;
			++Stop;
		}
		Heard.push_back(std::make_pair(N.Row, std::max(N.Row + 1, Stop)));
		WrittenEnds.push_back(N.Row + N.Rows);
	}
	std::set<int> Paused, Playing, Ended;
	const int Shortest = 2 * S.Time.RowsPerBar - PHRASE_SLACK_BEATS * R;	// a phrase's rows, its rest in, at the least
	int Phrase = Heard.empty() ? 0 : Heard[0].first, Whole = Phrase;	// where the phrase going on started (for Ended: Whole)
	for (size_t i = 0; i < Heard.size(); ++i) {
		const int Start = Heard[i].first, Stop = Heard[i].second;
		for (int Span = SpanOf(Start); Span <= SpanOf(Stop - 1); Span += 2)
			Playing.insert(Span);
		if (Stop - Start >= 2 * R) {
			Paused.insert(SpanOf(Start));
			Phrase = Stop;
			if (Stop - Whole >= Shortest) {
				Ended.insert(SpanOf(Start));
				Whole = Stop;
			}
		}
		const int Next = i + 1 < Heard.size() ? Heard[i + 1].first : Total;
		if (Next - Stop >= R) {
			const int Line = S.Time.BarStart(S.Time.BarOf(std::min(Total - 1, Stop)) + 1);
			const bool AtLine = Stop <= Line - R && Next >= Line;
			const bool Ends = !AtLine || Next - Phrase >= Shortest, EndsWhole = Next - Whole >= Shortest;
			if (Ends)
				Paused.insert(SpanOf(Stop));
			if (EndsWhole)
				Ended.insert(SpanOf(Stop));
			if (Ends || Next - WrittenEnds[i] >= R)
				Phrase = Next;
			if (EndsWhole || Next - WrittenEnds[i] >= R)
				Whole = Next;
		}
	}
	for (int Bar = From; Bar < To; ++Bar) {
		if (BarsIntoPhrase(Bar, Anchor, 2) != 0 || Playing.count(Bar) == 0)
			continue;
		++Out.Spans;
		Out.PhraseEnds += Ended.count(Bar) > 0 ? 1 : 0;
		if (Paused.count(Bar) > 0)
			++Out.Breaths;
		else
			Out.RunOn.push_back(Bar);
	}
	return Out;
}

// How few of a melody's two-bar spans may pause before the review says it hardly does (MelodyBreaths), as a share of them.
// Measured on three versions of a lively stage (bars 5-40, its break without the melody left out): 13 and 9 of 16 spans
// breathe in the two the user heard as melodies, 4 of 16 in the one heard as "all over the place, no clean melody"; a
// desert stage's draft that ran on 3 of 16, its version rewritten in phrases 15 of 16; the user's earlier stages breathe
// in 53-94% of theirs. A calm melody breathes more (the calm recipe asks for a rest of a beat
// or more every two bars; the user's night songs pause in every span)
const double BREATHING_SHARE = 0.45, CALM_BREATHING_SHARE = 0.75;
// Cues, jingles and sound effects, judged as what they are (review_arrangement, measure_mix). A cue or a jingle is short
// music that plays once and halts (a level-up, a quest done, make_jingle's): it has no loop to fill or vary, its bass
// holds a cadence's roots, and a sampled drum would thump at its halt. A sound effect plays a row a tick
// (make_sound_effect's) and has no arrangement at all.
enum track_use { TRACK_MUSIC, TRACK_CUE, TRACK_SOUND };

struct TrackUse {
	int Use;			// track_use: music that loops (a stage, a town), or plays once for longer than a cue does
	double Seconds;		// how long it plays the first time through: until the row with its halt (as export_for_game keeps it),
						// or until it loops
	bool Halts;
	TrackUse() : Use(TRACK_MUSIC), Seconds(0.0), Halts(false) {}
};

const double CUE_SECONDS = 30.0;	// the longest a cue or a jingle plays

// What the selected track is: a sound effect at speed 1 with every note on the 2A03 (the MMC5's pulses play its
// instruments too), lasting no longer than one can; a cue when it halts within CUE_SECONDS; else music
TrackUse UseOfTrack(Session &S)
{
	TrackUse Out;
	std::vector<std::vector<Cell> > Cells;
	std::vector<int> Columns;
	bool Chip2A03 = true;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		Cells.push_back(S.Cells(c));
		Columns.push_back(S.Channel(c).EffectColumns);
		Chip2A03 = Chip2A03 && (S.Notes(c).empty() || InstrumentChip(S.Channel(c)) == "2A03");
	}
	const SongFlow F = Flow(S);
	int EndTick = 0;
	const std::vector<TimedRow> Rows = TimeRows(Cells, Columns, F, S.Time.PatternLength, S.Song.Speed, S.Song.Tempo, S.Song.SplitPoint,
		S.Song.FrameRate, 1, EndTick);
	Out.Halts = F.Halts();
	Out.Seconds = (Out.Halts && !Rows.empty() ? Rows.back().Tick : EndTick) / static_cast<double>(std::max(1, S.Song.FrameRate));
	if (S.Song.Speed == 1 && Chip2A03 && EndTick <= transcribe::SFX_MAX_TICKS + SFX_SILENT_TICKS + 1)
		Out.Use = TRACK_SOUND;
	else if (Out.Halts && Out.Seconds <= CUE_SECONDS)
		Out.Use = TRACK_CUE;
	return Out;
}

// The bar a song that halts halts in (its last bar otherwise)
int HaltBar(Session &S)
{
	const SongFlow F = Flow(S);
	return F.Halts() ? S.Time.BarOf(std::max(0, F.EndRow(S.Time.PatternLength) - 1)) : S.Time.BarCount();
}

// The review's tips that still matter for a cue: notes that vanish, parts that clash with the melody (on its notes, in
// octaves with it), the balance (the melody under another part, everything loud, the sides, a bass lost low). The
// others are for looping stage tracks: the length, sections, variety and loudness swings, fills and a sampled kit, a bass
// that moves, chord colors, a beat, a melody's shape and rests, accents, a lead holding a steady level. By the tips'
// words, so a tip added for stages stays out of cues
bool CueTip(const std::string &Text)
{
	static const char *const KEPT[] = { "Melody notes vanish", "Most of the melody's notes are gone", "Parts in the melody's register",
		"A bass moving in octaves with the melody", "The melody sits about", "The chords cover the melody", "The melody plays about",
		"Everything near full volume", "plays very low, where small speakers lose it", "For width in the game's stereo", "The echo on ",
		"The bass on ", "The drums on ", "The melody plays from one side" };
	for (size_t i = 0; i < sizeof(KEPT) / sizeof(KEPT[0]); ++i)
		if (Text.find(KEPT[i]) != std::string::npos)
			return true;
	return false;
}

// review_arrangement's line for a cue: how it was judged
std::string CueText(const TrackUse &Use)
{
	return Format("Judged as a cue: it plays once and halts after %.1f s, so the tips for looping stage tracks are left out (its "
		"length and variety, fills and a sampled kit, which would thump at the halt, a bass that moves, chord colors, a beat, a lead "
		"ringing at a steady level); notes that vanish, parts that clash with the melody and the balance stay. check_song lists "
		"clashes and clicks.", Use.Seconds);
}

// review_arrangement on a sound effect: what it is and its layers, then what still matters as its file will play it: a
// sound the halt cuts while it sounds, and notes that click on the 2A03's pulses. It has no arrangement to weigh, so no
// score
std::string SoundEffectReview(Session &S, const TrackUse &Use)
{
	const double Rate = std::max(1, S.Song.FrameRate), RowFrames = FramesPerRow(S);
	const int Total = S.Time.TotalRows();
	const int Stop = static_cast<int>(std::floor(Use.Seconds * Rate + 0.5));	// the frame it halts at, or loops back from
	std::string Layers;
	std::vector<std::string> Tips;
	int Last = 0;		// the frame after the last that sounds, as the instruments' volume sequences play
	std::string Cut;	// a note the halt cuts while it's still loud
	for (int c = 0; c < S.ChannelCount(); ++c) {
		const std::vector<NoteInfo> &Notes = S.Notes(c);
		for (size_t i = 0; i < Notes.size(); ++i) {
			const NoteInfo &N = Notes[i];
			const int From = static_cast<int>(std::floor(N.Row * RowFrames + 0.5));
			if (From >= Stop)
				continue;	// after the halt: it never plays
			const int Frames = std::max(1, std::min(Stop - From, static_cast<int>(std::floor(std::max(1, N.Rows) * RowFrames + 0.5))));
			Layers += Format("%s%s with %s from %.2f s", Layers.empty() ? "" : "; ", S.Channel(c).FullName().c_str(),
				InstrumentLabel(S.Song, N.Instrument).c_str(), From / Rate);
			// Its volume a frame at a time over the note, as FamiTracker plays it (the triangle sounds at any volume)
			const InstrumentInfo *pInfo = FindInstrument(S.Song, N.Instrument);
			const std::vector<int> Envelope = HeldEnvelope(pInfo, Frames + 1);
			const int Column = S.Channel(c).Kind == KIND_TRIANGLE ? 15 : N.Volume;
			int Heard = 0;
			for (int f = 0; f < Frames; ++f)
				if (PlayedVolume(S.Channel(c), Column, Envelope[static_cast<size_t>(f)]) > 0)
					Heard = f + 1;
			Last = std::max(Last, From + Heard);
			const int Ending = PlayedVolume(S.Channel(c), Column, Envelope[static_cast<size_t>(Frames)]);
			if (Cut.empty() && Use.Halts && From + Frames >= Stop && Heard == Frames && Ending >= 2 && S.Channel(c).Kind != KIND_TRIANGLE)
				Cut = Format("%s stops at volume %d as it halts at %.2f s", S.Channel(c).FullName().c_str(), Ending, Stop / Rate);
		}
	}
	std::string Text = Format("Sound effect review: \"%s\" is a sound effect (speed 1, a row a tick, as make_sound_effect writes one), "
		"%.2f s, %s. There's no arrangement to weigh (no melody, chords, bass or drums), so no score: play it for the user and judge "
		"it by ear.\n", S.Song.TrackName.c_str(), Use.Seconds, Use.Halts ? "playing once (it halts)" : "looping, as ambience does");
	Text += "Layers: " + (Layers.empty() ? std::string("none") : Layers) + ".\n";
	const double After = Use.Seconds - Last / Rate;
	if (Use.Halts && !Cut.empty())
		Tips.push_back("It's cut while it still sounds: " + Cut + ". make_sound_effect rings its sounds out to silence; for this one, "
			"let the note run until its instrument dies away (its halt later), or its volume sequence fade sooner.");
	else if (Use.Halts && Last > 0)
		Text += After >= 0.045 ? Format("It dies away to silence %.2f s before it halts, so its file ends quiet.\n", After) :
			Format("It sounds until it halts, %.2f s before: a game's file of it ends without a moment of silence (make it again: "
			"make_sound_effect halts its sounds 0.05 s after they die away).\n", std::max(0.0, After));
	const int Clicking = static_cast<int>(SongClicks(S, 0, Total).size());
	if (Clicking > 0)
		Tips.push_back(Format("%s on the 2A03's pulses %s (a pitch that takes the period across a multiple of 256 restarts the wave): "
			"polish with touches [\"clicks\"] nudges them; check_song lists them.", Plural(Clicking, "note", "notes").c_str(),
			Clicking == 1 ? "clicks" : "click"));
	Text += "make_sound_effect with variant, semitones, length_percent or volume_percent makes other takes, and export_for_game with "
		"a loudness (like -18) sets its level in the game.";
	if (!Tips.empty()) {
		Text += "\nWhat would help:";
		for (size_t i = 0; i < Tips.size(); ++i)
			Text += Format("\n%d. ", static_cast<int>(i) + 1) + Tips[i];
	}
	return Text;
}

// What drafts miss

// What review_arrangement and check_song find in an arrangement besides their other checks, from a local model's first
// stage, which was clean on all of those and missed these: a melody in one-bar pieces, a thin or doubled bass, a sound
// its channel can't play, faders doing the mix's work, a section that repeats another note for note, a lively stage that
// loops in under 55 s. Each carries the call that fixes it, which a model can send as it is (and the calls after it)
enum arrange_kind { ARRANGE_PHRASES, ARRANGE_BASS, ARRANGE_SOUND, ARRANGE_FADERS, ARRANGE_REPEAT, ARRANGE_LOOP, ARRANGE_KINDS };

struct ArrangeFinding {
	int Kind;				// arrange_kind
	int Channel;			// -1 for none (the faders, the loop)
	int FromBar, ToBar;		// the bars it's about
	double Weight;			// what it takes off the review's score, out of 10
	std::string Text;		// what's found and what to do (the fix's call follows it)
	std::string Summary;	// a few words, for a list
	Json Details;			// its numbers, for check_song's JSON
	Json Fix;				// the call that fixes it: tool, arguments and does, and the calls after it ("then")
	ArrangeFinding() : Kind(0), Channel(-1), FromBar(1), ToBar(1), Weight(1.0), Details(Json::MakeObject()), Fix(Json::MakeObject()) {}
};

// A call a finding gives: the tool, its arguments, and what it does in words
Json ToolCall(const char *Tool, const Json &Arguments, const std::string &Does)
{
	Json Out = Json::MakeObject();
	Out.Set("tool", Tool);
	Out.Set("arguments", Arguments);
	Out.Set("does", Does);
	return Out;
}

// A call to make after a fix's own, in its "then"
void ThenCall(Json &Fix, const Json &Call)
{
	Json Then = Fix.Get("then") != 0 ? *Fix.Get("then") : Json::MakeArray();
	Then.Push(Call);
	Fix.Set("then", Then);
}

// A call as the replies write it: write_notes {"channel":"2A03 Triangle","from_bar":5,"to_bar":31,"notes":[]}
std::string CallText(const Json &Call)
{
	const Json *pTool = Call.Get("tool"), *pArguments = Call.Get("arguments");
	std::string Text = pTool != 0 && pTool->IsString() ? pTool->String() : std::string();
	if (pArguments != 0 && pArguments->IsObject())
		Text += " " + WriteJson(*pArguments);
	return Text;
}

// "Fix: read_notes {...}, then write_notes {...} (what to change)."; Whole false: the first call, then the tools after it
std::string FixText(const Json &Fix, bool Whole)
{
	std::string Text = "Fix: " + CallText(Fix);
	const Json *pThen = Fix.Get("then");
	for (size_t i = 0; pThen != 0 && i < pThen->Size(); ++i) {
		const Json &Next = pThen->At(i);
		const Json *pTool = Next.Get("tool"), *pDoes = Next.Get("does");
		Text += ", then " + (Whole ? CallText(Next) : pTool != 0 && pTool->IsString() ? pTool->String() : std::string());
		if (Whole && pDoes != 0 && pDoes->IsString())
			Text += " (" + pDoes->String() + ")";
	}
	return Text + ".";
}

// The bar lines a melody stops at, as written: of the lines inside its playing (a note of its own starting in the bars on
// both sides), those with nothing sounding over the beat before them (a rest, a note released or halted, a note at
// volume 0); a note held over the line, or ended just as the next starts on it, goes on, and a short gap (a fife's
// half-beat breath at each bar of a march) doesn't stop it
struct BarLineStops {
	int Lines, Stops;
	std::vector<int> After;		// the bars after the lines it stops at
	BarLineStops() : Lines(0), Stops(0) {}
};

BarLineStops StopsAtBarLines(Session &S, int Melody, int From, int To)
{
	BarLineStops Out;
	const int Total = S.Time.TotalRows(), Beat = std::max(1, S.Time.RowsPerBeat);
	if (Total <= 0)
		return Out;
	const std::vector<NoteInfo> &Notes = S.Notes(Melody);
	std::vector<char> Sounds(static_cast<size_t>(Total), 0);
	for (size_t i = 0; i < Notes.size(); ++i)
		if (Notes[i].Volume > 0)
			for (int r = std::max(0, Notes[i].Row); r < std::min(Total, Notes[i].Row + Notes[i].Rows); ++r)
				Sounds[static_cast<size_t>(r)] = 1;
	auto Starts = [&](int Bar) {
		const int A = S.Time.BarStart(Bar), Z = std::min(Total, S.Time.BarEnd(Bar));
		for (size_t i = 0; i < Notes.size(); ++i)
			if (Notes[i].Row >= A && Notes[i].Row < Z && Notes[i].Volume > 0)
				return true;
		return false;
	};
	for (int Bar = From; Bar < To; ++Bar) {
		const int Line = S.Time.BarStart(Bar + 1);
		if (Line >= Total || !Starts(Bar) || !Starts(Bar + 1))
			continue;
		++Out.Lines;
		bool Quiet = true;
		for (int r = std::max(0, Line - Beat); r < Line && Quiet; ++r)
			Quiet = Sounds[static_cast<size_t>(r)] == 0;
		if (Quiet) {
			++Out.Stops;
			Out.After.push_back(Bar + 1);
		}
	}
	return Out;
}

// A melody heard in one-bar pieces: it stops at PIECES_SHARE of its bar lines or more (PIECES_LINES lines at the least),
// playing PIECES_NOTES notes a bar or more (a sparse line, bells now and then, rests by nature). Measured: the local
// model's stage stopped at 23 of its 27 bar lines, where the soundtrack's melodies, phrased in two and four bars, stop at
// under half of theirs
const double PIECES_SHARE = 0.7, PIECES_NOTES = 2.0;
const int PIECES_LINES = 7;

void PhrasesFinding(Session &S, int Melody, int From, int To, std::vector<ArrangeFinding> &Out)
{
	if (Melody < 0 || !IsMelodic(S.Channel(Melody)))
		return;
	const BarLineStops B = StopsAtBarLines(S, Melody, From, To);
	const MelodyBreaths Breaths = BreathsOf(S, Melody, From, To);
	// The lines inside two-bar phrases it stops at, where a held note joins the phrase's two bars (the rest at the
	// phrase's end stays)
	const int Anchor = PhraseAnchor(S);
	std::vector<int> Ends;	// the bars whose ends hold over
	for (size_t i = 0; i < B.After.size(); ++i)
		if (BarsIntoPhrase(B.After[i], Anchor, 2) == 1)
			Ends.push_back(B.After[i] - 1);
	int FromBar = 0, ToBar = 0, Bars = 0;
	for (int Bar = From; Bar <= To; ++Bar)
		if (HasNotesIn(S, Melody, S.Time.BarStart(Bar), S.Time.BarEnd(Bar))) {
			FromBar = FromBar == 0 ? Bar : FromBar;
			ToBar = Bar;
			++Bars;
		}
	const int Notes = static_cast<int>(NotesIn(S.Notes(Melody), S.Time.BarStart(From), S.Time.BarEnd(To)).size());
	if (B.Lines < PIECES_LINES || B.Stops < PIECES_SHARE * B.Lines || Ends.empty() || Notes < PIECES_NOTES * Bars)
		return;
	ArrangeFinding F;
	F.Kind = ARRANGE_PHRASES;
	F.Channel = Melody;
	F.FromBar = FromBar;
	F.ToBar = ToBar;
	F.Weight = 1.5;
	const std::string Name = S.Channel(Melody).FullName();
	F.Text = Format("The melody on %s stops at %d of its %d bar lines (a rest or a release before the line), so it's heard in "
		"one-bar pieces, not phrases: a phrase of two bars or more ends in %d of its %d two-bar spans. Join each two bars into a "
		"phrase: hold the note before the bar line inside it (the ends of bars %s) and keep the rest at the phrase's end.",
		Name.c_str(), B.Stops, B.Lines, Breaths.PhraseEnds, Breaths.Spans, BarList(Ends).c_str());
	F.Summary = Format("the melody stops at %d of its %d bar lines: one-bar pieces, not phrases", B.Stops, B.Lines);
	F.Details.Set("bar_lines", B.Lines);
	F.Details.Set("stops", B.Stops);
	F.Details.Set("phrase_ends", Breaths.PhraseEnds);
	F.Details.Set("spans", Breaths.Spans);
	Json Held = Json::MakeArray();
	for (size_t i = 0; i < Ends.size(); ++i)
		Held.Push(Ends[i]);
	F.Details.Set("hold_bar_ends", Held);
	Json Read = Json::MakeObject();
	Read.Set("channel", Name);
	Read.Set("from_bar", FromBar);
	Read.Set("to_bar", ToBar);
	Read.Set("format", "steps");
	F.Fix = ToolCall("read_notes", Read, "reads the melody as a line of steps, a bar to a line");
	Json Write = Json::MakeObject();
	Write.Set("channel", Name);
	Write.Set("from_bar", FromBar);
	ThenCall(F.Fix, ToolCall("write_notes", Write, "notes: that line, a - in place of each . at the end of bars " + BarList(Ends) +
		", so the note before the bar line holds up to it and the phrase goes on into the next bar"));
	Out.push_back(F);
}

// A bass line as heard, over the bars it plays in (a note of its own starting there) in bars From-To: the share of
// those bars' rows it sounds, each note from its row until its sound stops (the triangle until its envelope reaches 0,
// since it plays any other level at full; the others as HeardFrames hears them), the share in silences of a beat or more
// (a bouncy bass of short notes on every beat has none), and how long its notes usually sound (the median, in rows)
struct HeardLine {
	int Channel, FromBar, ToBar, Bars, Sounding, Rows, Gaps, Usual;
	double Share, GapShare;
	HeardLine() : Channel(-1), FromBar(0), ToBar(0), Bars(0), Sounding(0), Rows(0), Gaps(0), Usual(0), Share(0.0), GapShare(0.0) {}
};

HeardLine HearLine(Session &S, int Channel, int From, int To, const std::vector<int> &RowFrames)
{
	HeardLine Out;
	Out.Channel = Channel;
	const int Total = S.Time.TotalRows();
	const int First = S.Time.BarStart(From), End = std::min(Total, S.Time.BarEnd(To));
	const bool Triangle = S.Channel(Channel).Kind == KIND_TRIANGLE;
	std::vector<char> Sounds(static_cast<size_t>(std::max(0, Total)), 0);
	std::set<int> Played;
	std::vector<int> Lengths;
	const std::vector<NoteInfo> &Notes = S.Notes(Channel);
	for (size_t i = 0; i < Notes.size(); ++i) {
		const NoteInfo &N = Notes[i];
		if (N.Row < First || N.Row >= End || N.Rows <= 0 || (!Triangle && N.Volume <= 0))
			continue;
		Played.insert(S.Time.BarOf(N.Row));
		const int Frames = NoteFrames(N, RowFrames);
		int Heard = Frames;
		if (Triangle) {
			const std::vector<int> Envelope = HeldEnvelope(FindInstrument(S.Song, N.Instrument), Frames);
			Heard = 0;
			while (Heard < Frames && Envelope[static_cast<size_t>(Heard)] > 0)
				++Heard;
		}
		else
			Heard = HeardFrames(S.Song, N, Frames);
		int Stop = N.Row, Counted = 0;
		while (Stop < N.Row + N.Rows && Counted < Heard) {
			Counted += Stop < static_cast<int>(RowFrames.size()) ? RowFrames[static_cast<size_t>(Stop)] : 1;
			++Stop;
		}
		for (int r = N.Row; r < Stop && r < Total; ++r)
			Sounds[static_cast<size_t>(r)] = 1;
		Lengths.push_back(Stop - N.Row);
	}
	// The silences of a beat or more, row by row
	std::vector<char> Gap(Sounds.size(), 0);
	for (size_t r = 0; r < Sounds.size(); ) {
		size_t Run = r;
		while (Run < Sounds.size() && Sounds[Run] == 0)
			++Run;
		if (Run - r >= static_cast<size_t>(std::max(1, S.Time.RowsPerBeat)))
			std::fill(Gap.begin() + static_cast<std::ptrdiff_t>(r), Gap.begin() + static_cast<std::ptrdiff_t>(Run), 1);
		r = Run == r ? r + 1 : Run;
	}
	for (std::set<int>::const_iterator it = Played.begin(); it != Played.end(); ++it) {
		Out.FromBar = Out.FromBar == 0 ? *it : Out.FromBar;
		Out.ToBar = *it;
		++Out.Bars;
		for (int r = S.Time.BarStart(*it); r < std::min(Total, S.Time.BarEnd(*it)); ++r) {
			++Out.Rows;
			Out.Sounding += Sounds[static_cast<size_t>(r)];
			Out.Gaps += Gap[static_cast<size_t>(r)];
		}
	}
	Out.Share = Out.Rows > 0 ? Out.Sounding / static_cast<double>(Out.Rows) : 0.0;
	Out.GapShare = Out.Rows > 0 ? Out.Gaps / static_cast<double>(Out.Rows) : 0.0;
	if (!Lengths.empty()) {
		std::sort(Lengths.begin(), Lengths.end());
		Out.Usual = Lengths[Lengths.size() / 2];
	}
	return Out;
}

// The share of a channel's notes in [First, End) that start while another channel sounds a note of their pitch class
// (as both sound: the triangle an octave under its written note)
double DoublingShare(Session &S, int Channel, int Other, int First, int End, int &Count)
{
	const std::vector<NoteInfo> Mine = NotesIn(S.Notes(Channel), First, End), &Theirs = S.Notes(Other);
	const int Apart = Written(S.Channel(Other), 0) - Written(S.Channel(Channel), 0);
	int Same = 0;
	Count = 0;
	for (size_t i = 0; i < Mine.size(); ++i) {
		if (Mine[i].Row < First || Mine[i].Row >= End)
			continue;
		++Count;
		for (size_t k = 0; k < Theirs.size(); ++k)
			if (Theirs[k].Row <= Mine[i].Row && Mine[i].Row < Theirs[k].Row + Theirs[k].Rows && Theirs[k].Volume > 0) {
				Same += ((Theirs[k].Pitch - Apart - Mine[i].Pitch) % 12 + 12) % 12 == 0 ? 1 : 0;
				break;
			}
	}
	return Count > 0 ? Same / static_cast<double>(Count) : 0.0;
}

// A thin bass: short notes (a beat or under as heard, usually) with silences of a beat or more for THIN_BASS_GAPS of the
// time in the bars it plays, so the low end comes and goes (the local model's sawtooth: an eighth on beats 1 and 3, in
// silence 75% of the time); a bouncy bass of short notes on every beat, or a held pedal now and then, carries the song.
// A second channel on the bass's roots that sounds under DOUBLE_SHARE of its bars (a lone short note now and then) and
// doubles the bass's pitch class in DOUBLED_NOTES of its notes adds a thump, not a part
const double THIN_BASS_GAPS = 0.5, DOUBLE_SHARE = 0.25, DOUBLED_NOTES = 0.75;
const int THIN_BASS_BARS = 8;

// The bass part: of the channels that play the song's bass (PlaysBassPart), the one heard longest; -1 for none
int MainBass(Session &S, int Melody, int From, int To, const std::vector<int> &RowFrames, std::vector<HeardLine> *pAll = 0)
{
	const int First = S.Time.BarStart(From), End = std::min(S.Time.TotalRows(), S.Time.BarEnd(To));
	int Best = -1, Most = 0;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		if (c == Melody || !IsMelodic(S.Channel(c)) || !HasNotesIn(S, c, First, End))
			continue;
		const bool Lone = S.Channel(c).Kind == KIND_TRIANGLE && NotesIn(S.Notes(c), First, End).size() < 3;
		if (Lone || !PlaysBassPart(S, c, First, End))
			continue;
		const HeardLine L = HearLine(S, c, From, To, RowFrames);
		if (pAll != 0)
			pAll->push_back(L);
		if (L.Sounding > Most) {
			Most = L.Sounding;
			Best = c;
		}
	}
	return Best;
}

// The chords the parts play over some bars, for a new bass line on them (add_chords_and_bass's chords): each as its triad
// on its root (a bass needs no more, and the call stays short; a chord heard without its third, as a bass's root and fifth
// alone, takes the key's), the same chord again joined to the one before
std::string ChordsOfBars(Session &S, int FromBar, int ToBar, const Key &K, int Melody)
{
	const int First = S.Time.BarStart(FromBar), End = std::min(S.Time.TotalRows(), S.Time.BarEnd(ToBar));
	const std::vector<ChordAt> Heard = SongChords(S, First, End, K, Melody);
	std::vector<ChordAt> Plain;
	for (size_t i = 0; i < Heard.size(); ++i) {
		const Chord &C = Heard[i].C;
		const int Third = C.Third() == 3 || C.Third() == 4 ? C.Third() : InKey(C.Root + 3, K) && !InKey(C.Root + 4, K) ? 3 : 4;
		std::vector<int> Tones(1, 0);
		Tones.push_back(Third);
		Tones.push_back(C.Fifth() == 6 && Third == 3 ? 6 : 7);
		ChordAt A = Heard[i];
		A.C = Chord(C.Root, Tones);
		A.C.RootSpelling = C.RootSpelling;
		if (!Plain.empty() && Plain.back().C == A.C && Plain.back().Row + Plain.back().Rows == A.Row)
			Plain.back().Rows += A.Rows;
		else
			Plain.push_back(A);
	}
	return ProgressionText(Plain, SongBarSpans(S, First, End), K, false, 64);
}

void BassFindings(Session &S, int Melody, int From, int To, bool Calm, const Key &K, std::vector<ArrangeFinding> &Out)
{
	const std::vector<int> RowFrames = RowFramesOf(S);
	std::vector<HeardLine> Lines;
	const int Bass = MainBass(S, Melody, From, To, RowFrames, &Lines);
	if (Bass < 0)
		return;
	HeardLine Main;
	for (size_t i = 0; i < Lines.size(); ++i)
		if (Lines[i].Channel == Bass)
			Main = Lines[i];
	// Another channel on the bass's roots, now and then
	for (size_t i = 0; i < Lines.size(); ++i) {
		const HeardLine &L = Lines[i];
		if (L.Channel == Bass)
			continue;
		int Count = 0;
		const double Doubled = DoublingShare(S, L.Channel, Bass, S.Time.BarStart(L.FromBar), S.Time.BarEnd(L.ToBar), Count);
		if (Count < 3 || L.Share >= DOUBLE_SHARE || Doubled < DOUBLED_NOTES || L.Sounding * 2 > Main.Sounding)
			continue;
		ArrangeFinding F;
		F.Kind = ARRANGE_BASS;
		F.Channel = L.Channel;
		F.FromBar = L.FromBar;
		F.ToBar = L.ToBar;
		F.Weight = 0.5;
		const std::string Name = S.Channel(L.Channel).FullName(), BassName = S.Channel(Bass).FullName();
		F.Text = Format("Two channels play the bass's roots: %s (%s) doubles %s, the bass, sounding %d%% of its bars (%d%% for the "
			"bass), so it adds a thump now and then rather than a part. Clear it there and let the bass carry the low end, or give "
			"it a part of its own.", Name.c_str(), Plural(Count, "note", "notes").c_str(), BassName.c_str(),
			static_cast<int>(std::floor(L.Share * 100 + 0.5)), static_cast<int>(std::floor(Main.Share * 100 + 0.5)));
		F.Summary = Format("%s doubles the bass's roots now and then (a thump, not a part)", Name.c_str());
		F.Details.Set("problem", "doubled");
		F.Details.Set("bass_channel", Bass + 1);
		F.Details.Set("bass_channel_name", BassName);
		F.Details.Set("sounding", Json::NumberText(FormatNumber(std::floor(L.Share * 100 + 0.5) / 100)));
		F.Details.Set("doubled", Json::NumberText(FormatNumber(std::floor(Doubled * 100 + 0.5) / 100)));
		F.Details.Set("note_count", Count);
		Json Clear = Json::MakeObject();
		Clear.Set("channel", Name);
		Clear.Set("from_bar", L.FromBar);
		Clear.Set("to_bar", L.ToBar);
		Clear.Set("notes", Json::MakeArray());
		F.Fix = ToolCall("write_notes", Clear, "clears " + Name + "'s notes in " + RangeText(L.FromBar, L.ToBar) + ", leaving the bass to " +
			BassName);
		Out.push_back(F);
	}
	// The bass itself: short notes with gaps, unless another part carries the low end (a 5B buzz bass or a pulse low
	// under the rest, which the tools don't take for the bass part, beside a triangle pedal now and then)
	bool Carried = false;
	for (int c = 0; c < S.ChannelCount() && !Carried; ++c) {
		if (c == Bass || c == Melody || !IsMelodic(S.Channel(c)))
			continue;
		const std::vector<NoteInfo> Low = NotesIn(S.Notes(c), S.Time.BarStart(Main.FromBar), S.Time.BarEnd(Main.ToBar));
		if (static_cast<int>(Low.size()) < Main.Bars || MiddleOf(Low, 99) - Written(S.Channel(c), 0) >= 36)
			continue;	// under C-3 as it sounds
		Carried = HearLine(S, c, Main.FromBar, Main.ToBar, RowFrames).GapShare < THIN_BASS_GAPS;
	}
	if (Main.Bars < THIN_BASS_BARS || Main.GapShare < THIN_BASS_GAPS || Main.Usual > S.Time.RowsPerBeat || Carried)
		return;
	ArrangeFinding F;
	F.Kind = ARRANGE_BASS;
	F.Channel = Bass;
	F.FromBar = Main.FromBar;
	F.ToBar = Main.ToBar;
	F.Weight = 1.0;
	const std::string Name = S.Channel(Bass).FullName();
	// Its roots alone, held on a calm track and jumping octaves on the others: a walking bass's approach notes rubbed a
	// semitone against the local model's melody five times, the roots never (a held root, or a fifth, set the review asking
	// for a bass that moves)
	const char *const Style = Calm ? "roots" : "octaves";
	F.Text = Format("The bass on %s is thin: short notes with gaps, it sounds %d%% of the time in the bars it plays and is silent for "
		"a beat or more %d%% of it, so the low end comes and goes. A line that keeps sounding carries the song: "
		"add_chords_and_bass with bass_style %s (%s) on the chords the parts play, their roots alone, so it can't rub against the "
		"melody.", Name.c_str(), static_cast<int>(std::floor(Main.Share * 100 + 0.5)), static_cast<int>(std::floor(Main.GapShare * 100 +
		0.5)), Style, Calm ? "each root held" : "each root jumping octaves every half beat");
	F.Summary = Format("the bass on %s is thin: it sounds %d%% of the time", Name.c_str(), static_cast<int>(std::floor(Main.Share *
		100 + 0.5)));
	F.Details.Set("problem", "thin");
	F.Details.Set("sounding", Json::NumberText(FormatNumber(std::floor(Main.Share * 100 + 0.5) / 100)));
	F.Details.Set("silent", Json::NumberText(FormatNumber(std::floor(Main.GapShare * 100 + 0.5) / 100)));
	F.Details.Set("usual_rows", Main.Usual);
	Json Backing = Json::MakeObject();
	Backing.Set("chord_channel", "none");
	Backing.Set("bass_channel", Name);
	Backing.Set("bass_style", Style);
	Backing.Set("chords", ChordsOfBars(S, Main.FromBar, Main.ToBar, K, Melody));
	Backing.Set("from_bar", Main.FromBar);
	Backing.Set("to_bar", Main.ToBar);
	F.Fix = ToolCall("add_chords_and_bass", Backing, std::string("writes a bass line of ") + (Calm ? "held roots" : "roots jumping octaves") +
		" on " + Name + " in " + RangeText(Main.FromBar, Main.ToBar) + ", on the chords the parts play there, in place of the old one");
	Out.push_back(F);
}

// Sounds a channel can't play as they're meant: on the triangle, which plays every level but 0 at full and has no
// duty, one meant to be soft (its envelope peaking at TRIANGLE_SOFT_PEAK or under); on the sawtooth, a VRC6 sound whose
// duty sequence plays odd values, which overdrive it (InstrumentInfo::OddDuty)
const int TRIANGLE_SOFT_PEAK = 10;

void SoundFindings(Session &S, int From, int To, std::vector<ArrangeFinding> &Out)
{
	const int First = S.Time.BarStart(From), End = std::min(S.Time.TotalRows(), S.Time.BarEnd(To));
	for (int c = 0; c < S.ChannelCount(); ++c) {
		const ChannelInfo &Info = S.Channel(c);
		if (Info.Kind != KIND_TRIANGLE && Info.Kind != KIND_SAWTOOTH)
			continue;
		const std::vector<NoteInfo> Notes = NotesIn(S.Notes(c), First, End);
		std::map<int, std::pair<int, int> > Bars;	// instrument -> its first and last bar here
		std::map<int, int> Count;
		for (size_t i = 0; i < Notes.size(); ++i) {
			const int Bar = S.Time.BarOf(Notes[i].Row);
			std::map<int, std::pair<int, int> >::iterator it = Bars.find(Notes[i].Instrument);
			if (it == Bars.end())
				Bars[Notes[i].Instrument] = std::make_pair(Bar, Bar);
			else
				it->second.second = Bar;
			++Count[Notes[i].Instrument];
		}
		for (std::map<int, std::pair<int, int> >::const_iterator it = Bars.begin(); it != Bars.end(); ++it) {
			const InstrumentInfo *pInfo = FindInstrument(S.Song, it->first);
			if (pInfo == 0)
				continue;
			const int Peak = EnvelopePeak(pInfo);
			const bool Soft = Info.Kind == KIND_TRIANGLE && Peak <= TRIANGLE_SOFT_PEAK;
			const bool Overdrives = Info.Kind == KIND_SAWTOOTH && pInfo->OddDuty;
			if (!Soft && !Overdrives)
				continue;
			ArrangeFinding F;
			F.Kind = ARRANGE_SOUND;
			F.Channel = c;
			F.FromBar = it->second.first;
			F.ToBar = it->second.second;
			F.Weight = 0.5;
			const std::string Name = Info.FullName(), Sound = InstrumentLabel(S.Song, it->first);
			F.Text = Overdrives ? Format("%s plays %s, a VRC6 pulse sound whose duty sequence plays odd values: on the sawtooth each "
				"adds 32 to the volume, so it overdrives. Give it a sawtooth sound.", Name.c_str(), Sound.c_str()) :
				Format("%s plays %s, a sound meant to be soft (its envelope peaks at %d): the triangle has no volume and no duty, so "
				"it plays it at full level until the envelope reaches 0, a hard blip. Give it a triangle sound (a bass, or a "
				"thump bass for an attack).", Name.c_str(), Sound.c_str(), Peak);
			F.Summary = Overdrives ? Format("%s overdrives the sawtooth", Sound.c_str()) : Format("%s on the triangle is a soft sound it "
				"plays at full level", Sound.c_str());
			F.Details.Set("instrument", it->first);
			F.Details.Set("instrument_name", pInfo->Name);
			F.Details.Set("envelope_peak", Peak);
			F.Details.Set("note_count", Count[it->first]);
			F.Details.Set("problem", Overdrives ? "overdrives" : "soft");
			Json Set = Json::MakeObject();
			Set.Set("channel", Name);
			Set.Set("instrument", "bass");
			Set.Set("from_bar", F.FromBar);
			Set.Set("to_bar", F.ToBar);
			F.Fix = ToolCall("set_instrument", Set, "gives " + Name + "'s notes in " + RangeText(F.FromBar, F.ToBar) + " the bass preset, "
				"made for the " + (Info.Kind == KIND_TRIANGLE ? "triangle" : "sawtooth"));
			Out.push_back(F);
		}
	}
}

// Faders doing the mix's work: the melody turned down MELODY_DOWN dB or more, or a part mix balances (one with a volume
// column) lifted FADER_LIFT dB or more over the melody's fader, while the balance as heard is off the style's places (the
// drums over them, or a part about as loud as the melody). The local model's stage had its lead at -4.5 dB and the noise
// at +6; the soundtrack's own faders trim (a pad 5.5 dB down, chords 4-6 up, a lead 3 down) and leave the balance to the
// notes. mix in the style with the faders back at 0 sets the volumes in the notes instead, which NSF files play too
const double MELODY_DOWN = 4.0, FADER_LIFT = 9.0;

void FadersFinding(Session &S, Hearing &Ears, int Melody, int From, int To, bool Calm, std::vector<ArrangeFinding> &Out)
{
	if (Melody < 0 || S.Channel(Melody).Kind == KIND_TRIANGLE)
		return;
	const int First = S.Time.BarStart(From), End = std::min(S.Time.TotalRows(), S.Time.BarEnd(To));
	std::vector<std::string> Far;
	double Lead = FaderDb(S.Channel(Melody)), Farthest = 0.0;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		const int Role = MixRole(S, c, Melody, First, End);
		if (Role == ROLE_NONE || Role == ROLE_AMBIENCE)
			continue;
		const double Db = FaderDb(S.Channel(c));
		Farthest = std::max(Farthest, std::fabs(Db));
		if ((c == Melody && Db <= -MELODY_DOWN) || (c != Melody && Db - Lead >= FADER_LIFT))
			Far.push_back(Format("%s %+.1f dB", S.Channel(c).FullName().c_str(), Db));
	}
	// The balance as heard, as the review hears it
	std::vector<MixSpan> Spans = MixSpans(S, Melody, First, End, std::set<int>());
	std::vector<int> Voiced = ChordVoicesIn(S, First, End, Melody);
	HeardRoles(S, Voiced, Spans);
	std::vector<std::vector<std::pair<int, int> > > Refs;
	for (size_t i = 0; i < Spans.size(); ++i)
		Refs.push_back(std::vector<std::pair<int, int> >(1, std::make_pair(Spans[i].First, Spans[i].End)));
	const HeardBalance B = HearBalance(S, Ears, Spans, Refs, Melody, Voiced, First, End);
	const HeardPlaces P = PlacesFor(Calm);
	double Drums = NO_LOUDNESS, Nearest = NO_LOUDNESS;
	for (size_t i = 0; i < Spans.size(); ++i) {
		if (B.Rel[i] <= NO_LOUDNESS)
			continue;
		if (Spans[i].Role == ROLE_DRUMS)
			Drums = std::max(Drums, B.Rel[i]);
		else if (Spans[i].Role == ROLE_CHORDS || Spans[i].Role == ROLE_LINE || Spans[i].Role == ROLE_BASS)
			Nearest = std::max(Nearest, B.Rel[i]);
	}
	const bool DrumsLoud = Drums > NO_LOUDNESS && Drums > P.DrumsTop;
	const bool Buried = Nearest > NO_LOUDNESS && Nearest > -1.0;
	if (Far.empty() || (!DrumsLoud && !Buried))
		return;
	ArrangeFinding F;
	F.Kind = ARRANGE_FADERS;
	F.FromBar = From;
	F.ToBar = To;
	F.Weight = 0.5;
	std::string List;
	for (size_t i = 0; i < Far.size(); ++i)
		List += (i == 0 ? "" : ", ") + Far[i];
	const char *const Style = Calm ? "calm" : "lively";
	F.Text = Format("The faders do the mix's work (%s)%s%s: mix with style %s, the faders back at 0, sets each part's volume in "
		"the notes to its place (the drums %.0f dB or more under the melody) and plays the same in NSF files.", List.c_str(),
		DrumsLoud ? Format(", and the drums play %.1f dB under the melody as heard, louder than a %s track's %.0f", -Drums,
		Style, -P.DrumsTop).c_str() : "", Buried ? ", and a part plays about as loud as the melody" : "", Style, -P.DrumsTop);
	F.Summary = "the faders do the mix's work (" + List + ")";
	F.Details.Set("faders", List);
	F.Details.Set("melody_fader", Json::NumberText(FormatNumber(Lead)));
	F.Details.Set("farthest", Json::NumberText(FormatNumber(Farthest)));
	F.Details.Set("drums", Drums > NO_LOUDNESS ? Json::NumberText(FormatNumber(std::floor(Drums * 10 + 0.5) / 10)) : Json());
	F.Details.Set("nearest", Nearest > NO_LOUDNESS ? Json::NumberText(FormatNumber(std::floor(Nearest * 10 + 0.5) / 10)) : Json());
	Json Mix = Json::MakeObject();
	Mix.Set("style", Style);
	Mix.Set("faders", "reset");
	F.Fix = ToolCall("mix", Mix, std::string("sets every fader back to 0 dB, then mixes the notes' volumes in the ") + Style + " style");
	Out.push_back(F);
}

// A section that repeats an earlier one of its length note for note, or nearly: bar by bar, its melody's bars the same in
// REPEAT_MELODY of them, every other part of the first the same in REPEAT_PART of its bars (another fill or two, a chord
// voiced higher here and there), none left out, and at most one part added, a slow one (under REPEAT_SLOW notes a bar): a
// local model's A2 was its A with one slow line added, where its refined version's A2 also had busier hi-hats in every
// bar. Busier drums, another chord part or the melody varied make it a repeat that moves on
const double REPEAT_MELODY = 0.9, REPEAT_PART = 0.7, REPEAT_SLOW = 2.0;

// How a channel's bars compare in two stretches of Bars bars from bars FromA and FromB: Same, the bars with the same notes
// starting on the same rows of the bar (by pitch; the volumes aside), of Playing, the bars either has a note starting in;
// InA and InB the bars each has notes in, and Notes how many start in B
void BarsAlike(Session &S, int Channel, int FromA, int FromB, int Bars, int &Same, int &Playing, int &InA, int &InB, int &Notes)
{
	Same = Playing = InA = InB = Notes = 0;
	const std::vector<NoteInfo> &All = S.Notes(Channel);
	const bool Triangle = S.Channel(Channel).Kind == KIND_TRIANGLE;
	auto Starts = [&](int Bar) {
		std::set<std::pair<int, int> > Out;
		const int First = S.Time.BarStart(Bar), End = S.Time.BarEnd(Bar);
		for (size_t i = 0; i < All.size(); ++i)
			if (All[i].Row >= First && All[i].Row < End && (Triangle || All[i].Volume > 0))
				Out.insert(std::make_pair(All[i].Row - First, All[i].Pitch));
		return Out;
	};
	for (int b = 0; b < Bars; ++b) {
		const std::set<std::pair<int, int> > A = Starts(FromA + b), B = Starts(FromB + b);
		Notes += static_cast<int>(B.size());
		if (A.empty() && B.empty())
			continue;
		++Playing;
		InA += A.empty() ? 0 : 1;
		InB += B.empty() ? 0 : 1;
		Same += A == B ? 1 : 0;
	}
}

void RepeatFindings(Session &S, int Melody, int From, int To, std::vector<ArrangeFinding> &Out)
{
	const SectionList &List = S.Song.Sections;
	if (Melody < 0)
		return;
	std::set<size_t> Found;
	for (size_t y = 0; y < List.size(); ++y) {
		const int YFrom = SectionFirstBar(S, List[y]), YTo = SectionLastBar(S, List[y]);
		if (YFrom < From || YTo > To || Found.count(y) > 0)
			continue;
		for (size_t x = 0; x < y; ++x) {
			const int XFrom = SectionFirstBar(S, List[x]), XTo = SectionLastBar(S, List[x]);
			if (XTo - XFrom != YTo - YFrom || XFrom < From)
				continue;
			const int Bars = XTo - XFrom + 1;
			int TuneSame = 0, TunePlaying = 0, TuneX = 0, TuneY = 0, TuneNotes = 0;
			BarsAlike(S, Melody, XFrom, YFrom, Bars, TuneSame, TunePlaying, TuneX, TuneY, TuneNotes);
			const double Tune = TunePlaying > 0 ? TuneSame / static_cast<double>(TunePlaying) : 0.0;
			double Least = 1.0;
			int Added = 0, AddedNotes = 0, Changed = -1, Dropped = 0;
			std::string AddedName;
			for (int c = 0; c < S.ChannelCount(); ++c) {
				if (c == Melody)
					continue;
				int Same = 0, Playing = 0, InX = 0, InY = 0, Notes = 0;
				BarsAlike(S, c, XFrom, YFrom, Bars, Same, Playing, InX, InY, Notes);
				if (Playing == 0)
					continue;
				if (InX == 0) {
					++Added;
					AddedNotes = std::max(AddedNotes, Notes);
					AddedName = S.Channel(c).FullName();
				}
				else if (InY == 0)
					++Dropped;
				else if (Same / static_cast<double>(Playing) < Least) {
					Least = Same / static_cast<double>(Playing);
					Changed = c;
				}
			}
			if (TuneX < Bars / 2 || TuneX < 2 || Tune < REPEAT_MELODY || Least < REPEAT_PART || Dropped > 0 || Added > 1 ||
				AddedNotes >= REPEAT_SLOW * Bars)
				continue;
			ArrangeFinding F;
			F.Kind = ARRANGE_REPEAT;
			F.Channel = Melody;
			F.FromBar = YFrom;
			F.ToBar = YTo;
			F.Weight = 1.0;
			F.Text = Format("\"%s\" (%s) repeats \"%s\" (%s) %s%s: a repeat with nothing new is where a loop starts to sound like a "
				"loop. Vary it: the melody embellished (vary_part), a counter-melody or a harmony only there (add_counter_melody, "
				"add_harmony on its bars), or busier drums.", List[y].Name.c_str(), RangeText(YFrom, YTo).c_str(), List[x].Name.c_str(),
				RangeText(XFrom, XTo).c_str(), Tune >= 0.999 && Least >= 0.999 ? "note for note" : "nearly note for note",
				Added == 1 ? (" with one slow line added on " + AddedName).c_str() : "");
			F.Summary = Format("\"%s\" repeats \"%s\" %s", List[y].Name.c_str(), List[x].Name.c_str(), Tune >= 0.999 && Least >= 0.999 ?
				"note for note" : "nearly note for note");
			F.Details.Set("section", List[y].Name);
			F.Details.Set("repeats", List[x].Name);
			F.Details.Set("repeats_from_bar", XFrom);
			F.Details.Set("melody_alike", Json::NumberText(FormatNumber(std::floor(Tune * 100 + 0.5) / 100)));
			F.Details.Set("parts_alike", Json::NumberText(FormatNumber(std::floor(Least * 100 + 0.5) / 100)));
			F.Details.Set("parts_added", Added);
			F.Details.Set("least_alike", Changed >= 0 ? Json(S.Channel(Changed).FullName()) : Json());
			Json Vary = Json::MakeObject();
			Vary.Set("channel", S.Channel(Melody).FullName());
			Vary.Set("variation", "embellish");
			Vary.Set("section", List[y].Name);
			F.Fix = ToolCall("vary_part", Vary, "embellishes the melody in \"" + List[y].Name + "\" (passing and neighbour notes, at most two "
				"a bar), so the repeat isn't pasted");
			Out.push_back(F);
			Found.insert(y);
			break;
		}
	}
}

// A lively stage (style lively) that loops in under SHORT_LOOP_SECONDS repeats too soon: heard for minutes, the lively
// recipe's stages loop in 60-70 s (the local model's looped in 52 s, the soundtrack's lively stages in 57.6-67.2). Other
// music isn't held to it: the soundtrack's battles loop in 47-51 s, a mine cart chase in 40, a fair in 45, by design, and
// a sketch of a few bars is a song still growing. Not a cue or a sound effect
const double SHORT_LOOP_SECONDS = 55.0;

void LoopFinding(Session &S, int Style, const TrackUse &Use, std::vector<ArrangeFinding> &Out)
{
	if (Use.Use != TRACK_MUSIC || Use.Halts || Style != STYLE_LIVELY)
		return;
	const double Shortest = SHORT_LOOP_SECONDS;
	std::vector<std::vector<Cell> > Cells;
	std::vector<int> Columns;
	for (int c = 0; c < S.ChannelCount(); ++c) {
		Cells.push_back(S.Cells(c));
		Columns.push_back(S.Channel(c).EffectColumns);
	}
	const SongFlow Flowing = Flow(S);
	int EndTick = 0;
	const std::vector<TimedRow> Rows = TimeRows(Cells, Columns, Flowing, S.Time.PatternLength, S.Song.Speed, S.Song.Tempo,
		S.Song.SplitPoint, S.Song.FrameRate, 1, EndTick);
	int LoopTick = -1;
	for (size_t i = 0; i < Rows.size() && LoopTick < 0; ++i)
		if (Rows[i].LoopStart)
			LoopTick = Rows[i].Tick;
	const int LoopRow = Flowing.LoopRow(S.Time.PatternLength), EndRow = Flowing.EndRow(S.Time.PatternLength);
	if (LoopTick < 0 || LoopRow < 0 || EndRow <= LoopRow)
		return;
	const double Seconds = (EndTick - LoopTick) / static_cast<double>(std::max(1, S.Song.FrameRate));
	if (Seconds >= Shortest)
		return;
	const int LoopBar = S.Time.BarOf(LoopRow), LastBar = S.Time.BarOf(EndRow - 1);
	const double BarSeconds = Seconds / std::max(1, LastBar - LoopBar + 1);
	// More of the loop's music after its end: its first section after the one it starts with (B, after A), else its bars
	// from the start, as many times as it takes to reach Shortest; then the loop taken to the copy's end
	std::string Source;
	int SourceFrom = LoopBar, SourceTo = LoopBar;
	const int Wanted = std::max(4, static_cast<int>(std::ceil((Shortest - Seconds) / std::max(0.1, BarSeconds) / 4.0)) * 4);
	for (size_t i = 0; i < S.Song.Sections.size() && Source.empty(); ++i) {
		const Section &P = S.Song.Sections[i];
		const int A = SectionFirstBar(S, P), Z = SectionLastBar(S, P);
		if (A > LoopBar && Z <= LastBar && Z - A + 1 >= 4) {
			Source = P.Name;
			SourceFrom = A;
			SourceTo = Z;
		}
	}
	if (Source.empty())
		SourceTo = std::min(LastBar, LoopBar + Wanted - 1);
	const int Copied = SourceTo - SourceFrom + 1, Times = std::max(1, std::min(4, (Wanted + Copied - 1) / Copied));
	ArrangeFinding F;
	F.Kind = ARRANGE_LOOP;
	F.FromBar = LoopBar;
	F.ToBar = LastBar;
	F.Weight = 0.5;
	F.Text = Format("The loop (%s) plays %.0f s before it repeats: a stage is heard for minutes, and one that loops in under %.0f s "
		"repeats too soon (stages loop in 60-90 s). Give it more music: %s again after its end, varied, or a new section.",
		RangeText(LoopBar, LastBar).c_str(), Seconds, Shortest, Source.empty() ? RangeText(SourceFrom, SourceTo).c_str() :
		("\"" + Source + "\"").c_str());
	F.Summary = Format("the loop plays %.0f s, under %.0f", Seconds, Shortest);
	F.Details.Set("loop_seconds", Json::NumberText(FormatNumber(std::floor(Seconds * 10 + 0.5) / 10)));
	F.Details.Set("loop_from_bar", LoopBar);
	F.Details.Set("loop_to_bar", LastBar);
	Json Copy = Json::MakeObject();
	if (!Source.empty())
		Copy.Set("section", Source);
	else {
		Copy.Set("from_bar", SourceFrom);
		Copy.Set("to_bar", SourceTo);
	}
	Copy.Set("at_bar", LastBar + 1);
	if (Times > 1)
		Copy.Set("times", Times);
	F.Fix = ToolCall("copy_bars", Copy, Format("copies %s again after the loop's end (bars %d-%d)", Source.empty() ? RangeText(SourceFrom,
		SourceTo).c_str() : ("\"" + Source + "\"").c_str(), LastBar + 1, LastBar + Copied * Times));
	Json Loop = Json::MakeObject();
	Loop.Set("from_bar", LoopBar);
	Loop.Set("to_bar", LastBar + Copied * Times);
	ThenCall(F.Fix, ToolCall("set_loop", Loop, "takes the loop to the copy's end"));
	Out.push_back(F);
}

// Every finding of the arrangement in bars From-To: the melody's phrases, the bass, sounds, faders, repeats and the loop
std::vector<ArrangeFinding> ArrangeFindings(Session &S, Hearing &Ears, int Melody, int From, int To, int Style, const TrackUse &Use,
	const Key &K)
{
	std::vector<ArrangeFinding> Out;
	if (Use.Use != TRACK_MUSIC || S.Song.Speed == 1)
		return Out;	// a cue, a sound effect, or ambience written a row a tick
	const bool Calm = Style == STYLE_CALM;
	PhrasesFinding(S, Melody, From, To, Out);
	BassFindings(S, Melody, From, To, Calm, K, Out);
	SoundFindings(S, From, To, Out);
	FadersFinding(S, Ears, Melody, From, To, Calm, Out);
	RepeatFindings(S, Melody, From, To, Out);
	LoopFinding(S, Style, Use, Out);
	return Out;
}

// A tip of review_arrangement's: what it takes off the score, its text, and for one of ArrangeFindings its summary and call
struct ReviewTip {
	double Weight;
	std::string Text, Summary;
	Json Fix;
	ReviewTip() : Weight(0.0) {}
};

// A tip as the short forms give it: its summary and call, or else its first clause (up to a colon or a full stop) and
// the tool its text names first
std::string ShortTip(const std::string &Text, const std::string &Summary, const Json &Fix)
{
	if (!Summary.empty() && Fix.IsObject() && Fix.Get("tool") != 0) {
		std::string Line = Summary;
		if (!Line.empty())
			Line[0] = static_cast<char>(std::toupper(static_cast<unsigned char>(Line[0])));
		return Line + ". " + FixText(Fix, false);
	}
	size_t Cut = std::min(Text.find(": "), Text.find(". "));
	if (Cut == std::string::npos || Cut > 160)
		Cut = std::min<size_t>(Text.size(), 160);
	std::string Line = Text.substr(0, Cut);
	static const char *const TOOLS[] = { "add_chords_and_bass", "add_counter_melody", "add_harmony", "add_drums", "add_echo",
		"add_sample_drums", "add_vibrato", "polish", "mix", "write_notes", "transpose", "vary_part", "set_pan", "design_instrument",
		"set_instrument", "insert_bars", "copy_bars", "set_loop", "set_mixer", "set_tempo", "change_mood" };
	size_t Where = std::string::npos;
	std::string Tool;
	auto Word = [&](size_t At) { return At < Text.size() && (std::isalnum(static_cast<unsigned char>(Text[At])) || Text[At] == '_'); };
	for (size_t t = 0; t < sizeof(TOOLS) / sizeof(TOOLS[0]); ++t) {
		const size_t Length = std::strlen(TOOLS[t]);
		size_t At = Text.find(TOOLS[t]);
		while (At != std::string::npos && ((At > 0 && Word(At - 1)) || Word(At + Length)))	// a whole word: not "mix" in "mixes"
			At = Text.find(TOOLS[t], At + 1);
		if (At < Where) {
			Where = At;
			Tool = TOOLS[t];
		}
	}
	return Line + (Tool.empty() ? "." : " (" + Tool + ").");
}

// review_arrangement's short form: the score, the parts, the numbers that matter, and the three tips that matter most
std::string ShortReview(const std::string &Head, const std::string &Cue, const std::string &Parts,
	const std::vector<std::string> &Numbers, const std::vector<ReviewTip> &Tips)
{
	std::string Text = Head;
	if (!Cue.empty())
		Text += " " + Cue;
	Text += "\n" + Parts;
	if (!Numbers.empty()) {
		Text += "\nNumbers: ";
		for (size_t i = 0; i < Numbers.size(); ++i)
			Text += (i == 0 ? "" : "; ") + Numbers[i];
		Text += ".";
	}
	if (Tips.empty())
		return Text + "\nNothing obvious is missing. Listen with the user (play) and ask what they'd change.";
	const size_t Shown = std::min<size_t>(3, Tips.size());
	Text += Tips.size() > Shown ? Format("\nMost of all (%d of %d tips; format text gives them all):", static_cast<int>(Shown),
		static_cast<int>(Tips.size())) : std::string("\nWhat would help, most first:");
	for (size_t i = 0; i < Shown; ++i)
		Text += Format("\n%d. ", static_cast<int>(i) + 1) + ShortTip(Tips[i].Text, Tips[i].Summary, Tips[i].Fix);
	return Text;
}

std::string ReviewTool(Session &S, const Json &Args)
{
	// A sound effect has no arrangement; a cue isn't judged as a looping stage
	const TrackUse Use = UseOfTrack(S);
	if (Use.Use == TRACK_SOUND)
		return SoundEffectReview(S, Use);
	int From, To;
	if (RangeGiven(Args))
		BarRange(S, Args, From, To);
	else
		PlayedBars(S, From, To);
	const int First = S.Time.BarStart(From), End = std::min(S.Time.BarEnd(To), S.Time.TotalRows());
	const int R = S.Time.RowsPerBeat;
	const int BarCount = To - From + 1;
	bool Found;
	Key K = KeyArg(S, Args, "key", First, End, Found);
	if (!Found)
		K = Key(0, MODE_MAJOR);
	const std::vector<BarSpan> Bars = SongBarSpans(S, First, End);
	// A calm track (a night version, an ambient one) floats: no drums, fills or accents are asked of it, nor a melody that
	// stands out, more notes or shorter ones, and its balance and its lead's sound are heard as calm tracks want them; a
	// lively stage's are heard as stages that bounce without pressing want them. Calm when asked, or when the track's
	// name says so
	const TrackStyle Chosen = ChooseStyle(S, StyleArg(Args), "reviews it as a calm track", "any");
	const bool Calm = Chosen.Style == STYLE_CALM, Lively = Chosen.Style == STYLE_LIVELY;
	const std::string Form = Squeezed(StringArg(Args, "format", "text"));
	if (Form != "text" && Form != "short")
		throw Problem("format: text (the default: every line and tip) or short (the score, the three tips that matter most with "
			"their calls, and the numbers).");
	std::vector<std::string> Lines, Numbers;	// Numbers: the ones that matter, for the short form
	std::vector<ReviewTip> Tips;
	double Missing = 0.0;	// what the tips take off the score, out of 10
	auto TipCall = [&](double Weight, const std::string &Text, const std::string &Summary, const Json &Fix) {
		if (Use.Use == TRACK_CUE && !CueTip(Text))
			return;	// for looping stage tracks
		ReviewTip T;
		T.Weight = Weight;
		T.Text = Text;
		T.Summary = Summary;
		T.Fix = Fix;
		Tips.push_back(T);
		Missing += Weight;
	};
	auto Tip = [&](double Weight, const std::string &Text) { TipCall(Weight, Text, std::string(), Json()); };

	// The parts and what each does
	const int Melody = Arg(Args, "melody_channel") != 0 ? ChannelArg(S, Args, "melody_channel") : GuessMelodyChannel(S, First, End);
	if (Melody < 0)
		throw Problem(Format("Nothing plays a melody in %s yet. Write one with write_notes (or ask for a backing with "
			"add_chords_and_bass and chords) first.", RangeText(From, To).c_str()));
	const std::vector<NoteInfo> Tune = NotesIn(S.Notes(Melody), First, End);
	int Bass = -1, Drums = -1, Samples = -1;
	std::vector<int> Chords, Voices, Echoes, Doubles, Playing, BassDoubles;
	std::vector<std::string> Free;
	// The bass: of the channels that play it, the one heard longest (a triangle with a lone note every other bar beside a
	// sawtooth line doubles that line's roots, it doesn't carry the bass)
	const int MainBassChannel = MainBass(S, Melody, From, To, RowFramesOf(S));
	for (int c = 0; c < S.ChannelCount(); ++c) {
		const ChannelInfo &Info = S.Channel(c);
		const std::vector<NoteInfo> Notes = NotesIn(S.Notes(c), First, End);
		if (Notes.empty()) {
			if (Info.Kind != KIND_DPCM)
				Free.push_back(Info.FullName());
			continue;
		}
		Playing.push_back(c);
		if (c == Melody)
			continue;
		if (Info.Kind == KIND_NOISE) {
			Drums = c;
			continue;
		}
		if (Info.Kind == KIND_DPCM) {
			Samples = c;
			continue;
		}
		// A lone deep note or two on the triangle (the loudest thing in a quiet bar) isn't a bass part, nor any part
		if (Info.Kind == KIND_TRIANGLE && Notes.size() < 3)
			continue;
		if (c == MainBassChannel || (MainBassChannel < 0 && Bass < 0 && PlaysBassPart(S, c, First, End))) {
			Bass = c;
			continue;
		}
		if (MainBassChannel >= 0 && PlaysBassPart(S, c, First, End)) {
			int Count = 0;
			if (DoublingShare(S, c, MainBassChannel, First, End, Count) >= DOUBLED_NOTES && Count >= 3) {
				BassDoubles.push_back(c);	// on the bass's roots
				continue;
			}
		}
		int Arpeggios = 0;	// notes that sound chords (0xy, or arpeggio instruments)
		for (size_t i = 0; i < Notes.size(); ++i)
			if (SoundsChord(S, Notes[i]))
				++Arpeggios;
		// An echo: the melody's notes again, a little later
		int Delayed = 0;
		for (size_t i = 0; i < Notes.size(); ++i) {
			for (size_t m = 0; m < Tune.size(); ++m) {
				if (Notes[i].Row > Tune[m].Row && Notes[i].Row - Tune[m].Row <= 2 * R && Notes[i].Pitch == Tune[m].Pitch) {
					++Delayed;
					break;
				}
			}
		}
		// A double: the melody's notes at the same time, in unison or an octave away (a chorus, a musette's two reeds)
		int Doubled = 0;
		for (size_t i = 0; i < Notes.size(); ++i) {
			const int Sounds = Notes[i].Pitch - Written(Info, 0);
			for (size_t m = 0; m < Tune.size(); ++m) {
				const int Interval = std::abs(Sounds - (Tune[m].Pitch - Written(S.Channel(Melody), 0)));
				if (Notes[i].Row == Tune[m].Row && (Interval == 0 || Interval == 12)) {
					++Doubled;
					break;
				}
			}
		}
		if (Arpeggios * 3 >= static_cast<int>(Notes.size()))
			(IsSparkle(S, c, Melody, First, End) ? Voices : Chords).push_back(c);	// a sparkle over the melody is a line of its own
		else if (Delayed * 2 >= static_cast<int>(Notes.size()) && FollowDelay(S, c, Melody, First, End) > 0)
			Echoes.push_back(c);
		else if (Doubled * 10 >= static_cast<int>(Notes.size()) * 6)
			Doubles.push_back(c);
		else
			Voices.push_back(c);
	}
	auto Names = [&](const std::vector<int> &List) {
		std::string Out;
		for (size_t i = 0; i < List.size(); ++i)
			Out += (i == 0 ? "" : ", ") + S.Channel(List[i]).FullName();
		return Out;
	};
	std::string Parts = "Parts: melody on " + S.Channel(Melody).FullName();
	if (!Chords.empty())
		Parts += "; chords on " + Names(Chords);
	if (Bass >= 0)
		Parts += "; bass on " + S.Channel(Bass).FullName() + (BassDoubles.empty() ? std::string() : " (its roots doubled on " +
			Names(BassDoubles) + ")");
	if (Drums >= 0)
		Parts += "; drums on " + S.Channel(Drums).FullName() + (Samples >= 0 ? " with samples on " + S.Channel(Samples).FullName() : "");
	else if (Samples >= 0)
		Parts += "; samples on " + S.Channel(Samples).FullName();
	if (!Voices.empty())
		Parts += "; another line on " + Names(Voices);
	if (!Echoes.empty())
		Parts += "; an echo on " + Names(Echoes);
	if (!Doubles.empty())
		Parts += "; the melody doubled on " + Names(Doubles);
	Parts += ".";
	if (!Free.empty()) {
		Parts += " Free: ";
		for (size_t i = 0; i < Free.size(); ++i)
			Parts += (i == 0 ? "" : ", ") + Free[i];
		Parts += ".";
	}
	Lines.push_back(Parts);
	const int Layers = static_cast<int>(Playing.size());
	if (Chords.empty() && Voices.empty())
		Tip(2.0, "Nothing harmonizes the melody: add_chords_and_bass fits chords to it (choose a chord_style and color).");
	if (Bass < 0)
		Tip(2.0, "No bass line: add_chords_and_bass with chord_channel \"none\" and a bass_style.");
	if (Drums < 0 && !Calm)
		Tip(1.0, "No drums: add_drums (groove calm for a quiet track, driving for action), unless the track should float without a beat.");
	if (Voices.empty() && Echoes.empty())
		Tip(1.0, "The melody has no company: add_counter_melody (a line of its own) or add_harmony (thirds under it) on " +
			(Free.empty() ? std::string("a channel") : Free[0]) + " adds depth; add_echo makes it spacious.");

	// Thin bars: two parts or fewer; and how much the number of parts changes
	std::vector<int> Thin;
	int Most = 0;
	for (size_t b = 0; b < Bars.size(); ++b) {
		int Sounding = 0;
		for (size_t p = 0; p < Playing.size(); ++p)
			if (HasNotesIn(S, Playing[p], Bars[b].Row, Bars[b].Row + Bars[b].Rows))
				++Sounding;
		if (Sounding <= 2 && Layers > 2)
			Thin.push_back(S.Time.BarOf(Bars[b].Row));
		Most = std::max(Most, Sounding);
	}
	if (!Thin.empty() && static_cast<int>(Thin.size()) < BarCount)
		Lines.push_back("Thin: only two parts or fewer play in bars " + BarList(Thin) + ".");

	// Loudness bar by bar, from the parts that sound in it at their levels (as FamiTracker plays each chip; the
	// triangle a little under a pulse at 15, drums at a steady share), two bars at a time: how far the song swings
	double Swing = 0.0;
	int Quietest = -1, Loudest = -1;
	{
		// The DPCM level softens the triangle and the noise (0.4.6's mixer: to about 70% at Z30, 57% at Z50 and 44% at
		// Z7F), bar by bar as the song sets it
		std::vector<double> Softened(Bars.size(), 1.0);
		for (int c = 0; c < S.ChannelCount(); ++c) {
			if (S.Channel(c).Kind != KIND_DPCM)
				continue;
			const std::vector<Cell> &Cells = S.Cells(c);
			const int Columns = std::max(1, std::min(EFFECT_COLUMNS, S.Channel(c).EffectColumns));
			std::vector<int> LevelAt(static_cast<size_t>(std::max(0, End)), 0);
			int Level = 0;
			for (int r = 0; r < End; ++r) {
				if (r < static_cast<int>(Cells.size()))
					for (int k = 0; k < Columns; ++k)
						if (Cells[static_cast<size_t>(r)].Effect[k] == EFF_DAC)
							Level = Cells[static_cast<size_t>(r)].Param[k] & 0x7F;
				LevelAt[static_cast<size_t>(r)] = Level;
			}
			for (size_t b = 0; b < Bars.size(); ++b) {
				double Sum = 0.0;
				int Rows = 0;
				for (int r = Bars[b].Row; r < Bars[b].Row + Bars[b].Rows && r < End; ++r, ++Rows) {
					const double F = 1.091 / (1.091 + 100.0 * LevelAt[static_cast<size_t>(r)] / 22638.0);
					Sum += F * F * F * F;	// the amplitude's factor is F squared; its power, that squared
				}
				Softened[b] = Rows > 0 ? Sum / Rows : 1.0;
			}
			break;
		}
		std::vector<double> Power(Bars.size(), 0.0);
		const double RowFrames = FramesPerRow(S);
		for (size_t p = 0; p < Playing.size(); ++p) {
			const int c = Playing[p];
			const ChannelInfo &Info = S.Channel(c);
			const std::vector<NoteInfo> Notes = NotesIn(S.Notes(c), First, End);
			for (size_t b = 0; b < Bars.size(); ++b) {
				const int Begin = Bars[b].Row, Stop = Bars[b].Row + Bars[b].Rows;
				const double Beats = std::max(1.0, Bars[b].Rows / static_cast<double>(std::max(1, S.Time.RowsPerBeat)));
				if (Info.Kind == KIND_NOISE || Info.Kind == KIND_DPCM) {
					// Drums at a steady share (-6 dB) when they play on every beat (hi-hats on every half beat), less for a
					// few hits, quiet ticks or a lone tom
					double Hits = 0.0;
					for (size_t i = 0; i < Notes.size(); ++i) {
						if (Notes[i].Row < Begin || Notes[i].Row >= Stop)
							continue;
						const double Share = Info.Kind == KIND_NOISE ? Notes[i].Volume / 15.0 : 1.0;
						Hits += Share * Share;
					}
					const double Full = Info.Kind == KIND_NOISE ? 2.0 * Beats : Beats;
					Power[b] += 0.25 * std::min(1.0, Hits / Full) * (Info.Kind == KIND_NOISE ? Softened[b] : 1.0);
					continue;
				}
				for (size_t i = 0; i < Notes.size(); ++i) {
					const int A = std::max(Begin, Notes[i].Row), Z = std::min(Stop, Notes[i].Row + Notes[i].Rows);
					if (Z <= A || (Info.Kind != KIND_TRIANGLE && Notes[i].Volume <= 0))
						continue;
					Power[b] += NotePower(S, c, Notes[i], A, Z, RowFrames) * (Z - A) / static_cast<double>(std::max(1, Bars[b].Rows)) *
						(Info.Kind == KIND_TRIANGLE ? Softened[b] : 1.0);
				}
			}
		}
		double Low = 0.0, High = 0.0;
		for (size_t b = 0; b + 1 < Power.size() || (b == 0 && Power.size() == 1); b += 2) {
			const double Mean = b + 1 < Power.size() ? (Power[b] + Power[b + 1]) / 2 : Power[b];
			if (Mean <= 0.0)
				continue;
			const double Db = 10.0 * std::log10(Mean);
			if (Quietest < 0 || Db < Low) {
				Low = Db;
				Quietest = static_cast<int>(b);
			}
			if (Loudest < 0 || Db > High) {
				High = Db;
				Loudest = static_cast<int>(b);
			}
		}
		Swing = Quietest >= 0 ? High - Low : 0.0;
	}
	if (Quietest >= 0 && Bars.size() >= 4) {
		auto Pair = [&](int b) {
			const int Bar = S.Time.BarOf(Bars[static_cast<size_t>(b)].Row);
			return static_cast<size_t>(b) + 1 < Bars.size() ? Format("bars %d-%d", Bar, Bar + 1) : Format("bar %d", Bar);
		};
		Lines.push_back(Format("Loudness: about %d dB between the quietest bars (%s) and the loudest (%s).",
			static_cast<int>(std::floor(Swing + 0.5)), Pair(Quietest).c_str(), Pair(Loudest).c_str()));
	}
	if (BarCount >= 16 && Most >= 3 && Swing < 3.0)
		Tip(0.5, Format("The song keeps about one loudness all the way through (%d dB between its quietest and loudest bars), "
			"so it never breathes: let it build and fall back, a few bars with fewer and quieter parts (an intro on the chords "
			"alone, the bass joining later; a break without the drums and the melody) and the full sound where it matters. "
			"Well-arranged tracks swing 8-12 dB in loudness between sections; the triangle is loud, so bars with it stay "
			"loud. write_notes with an empty list of notes clears a part from bars.", static_cast<int>(std::floor(Swing + 0.5))));

	// The intro (the bars before the loop starts, or a section named Intro at the start), as the stems measure it: more
	// than 10 dB under the rest it reads as silence in a game (6-10 dB under is the soundtrack's target)
	Hearing Ears(S);
	{
		int IntroEnd = Flow(S).LoopRow(S.Time.PatternLength);
		for (size_t i = 0; IntroEnd <= 0 && i < S.Song.Sections.size(); ++i)
			if (Lowercase(S.Song.Sections[i].Name) == "intro" && S.Song.Sections[i].First == 0)
				IntroEnd = (S.Song.Sections[i].Last + 1) * S.Time.PatternLength;
		if (IntroEnd > First && IntroEnd < End) {
			std::vector<int> All;
			for (int c = 0; c < S.ChannelCount(); ++c)
				if (S.Channel(c).Kind != KIND_DPCM)
					All.push_back(c);
			const double Intro = Ears.Loudness(All, std::vector<std::pair<int, int> >(1, std::make_pair(First, IntroEnd)));
			const double Rest = Ears.Loudness(All, std::vector<std::pair<int, int> >(1, std::make_pair(IntroEnd, End)));
			if (Intro > NO_LOUDNESS && Rest > NO_LOUDNESS && Rest - Intro > 10.0)
				Tip(0.5, Format("The intro (%s) plays about %d dB under the rest: more than 10 dB under reads as silence in a game "
					"(6-10 dB under is the target), so bring a part in sooner or play it louder.", RangeText(S.Time.BarOf(First),
					S.Time.BarOf(IntroEnd - 1)).c_str(), static_cast<int>(std::floor(Rest - Intro + 0.5))));
		}
	}

	// What drafts miss (ArrangeFindings), each a tip with its call; the older tips they say better are left out
	const std::vector<ArrangeFinding> Arranged = ArrangeFindings(S, Ears, Melody, From, To, Chosen.Style, Use, K);
	bool PiecesFound = false, ThinFound = false, LoopFound = false;
	for (size_t i = 0; i < Arranged.size(); ++i) {
		PiecesFound = PiecesFound || Arranged[i].Kind == ARRANGE_PHRASES;
		ThinFound = ThinFound || (Arranged[i].Kind == ARRANGE_BASS && Arranged[i].Channel == Bass);
		LoopFound = LoopFound || Arranged[i].Kind == ARRANGE_LOOP;
	}

	// Harmony: the chords the parts play (with the melody when nothing else does)
	const bool Backing = !Chords.empty() || Bass >= 0 || !Voices.empty();
	const std::vector<ChordAt> Heard = SongChords(S, First, End, K, Melody);
	if (!Heard.empty()) {
		std::set<std::string> Vocabulary;
		bool Colored = false;
		for (size_t i = 0; i < Heard.size(); ++i) {
			Chord Plain = Heard[i].C;	// an inversion (Fmaj7/C) is the same chord
			Plain.Bass = Plain.Root;
			Vocabulary.insert(ChordName(Plain, K));
			Colored = Colored || !Heard[i].C.IsTriad();
		}
		std::string Line = "Harmony" + std::string(Backing ? "" : " (implied by the melody alone)") + ": " +
			ProgressionText(Heard, Bars, K, false, 16) + Format(" — %d different chords%s.", static_cast<int>(Vocabulary.size()),
			Colored ? "" : ", all plain triads");
		// The same chords every four bars, all the way
		if (BarCount >= 12) {
			std::vector<std::string> Blocks;
			for (int b = 0; b + 4 <= static_cast<int>(Bars.size()); b += 4) {
				const std::vector<BarSpan> Four(Bars.begin() + b, Bars.begin() + b + 4);
				Blocks.push_back(ProgressionText(Heard, Four, K));
			}
			bool Same = Blocks.size() >= 3;
			for (size_t i = 1; i < Blocks.size(); ++i)
				Same = Same && Blocks[i] == Blocks[0];
			if (Same) {
				Line += Format(" The same four-bar progression plays %d times.", static_cast<int>(Blocks.size()));
				Tip(1.0, "The chords loop unchanged: a contrasting section (a B part on IV, V or vi, or the relative "
					"minor or major) for a few bars gives the song somewhere to go. add_chords_and_bass takes chords by name.");
			}
		}
		Lines.push_back(Line);
		if (!Colored && (!Chords.empty() || !Voices.empty()))
			Tip(1.0, "Every chord is a plain triad: add_chords_and_bass with color \"sevenths\" or \"rich\" (add9, maj7, "
				"m9, V7sus4) sounds less bare.");
	}

	// Bass: how it moves
	if (Bass >= 0) {
		const std::vector<NoteInfo> Notes = NotesIn(S.Notes(Bass), First, End);
		const double PerBar = Notes.size() / static_cast<double>(BarCount);
		std::set<int> Pitches;
		for (size_t i = 0; i < Notes.size(); ++i)
			Pitches.insert(Notes[i].Pitch);
		const std::string Rounded = FormatNumber(std::floor(PerBar * 10 + 0.5) / 10);
		std::string Line = "Bass: " + Rounded + (Rounded == "1" ? " note" : " notes") + Format(" a bar on average, %d different notes",
			static_cast<int>(Pitches.size()));
		const int Middle = MiddleOf(Notes, 30) - Written(S.Channel(Bass), 0);	// as it sounds
		Line += ", around " + PitchName(Written(S.Channel(Bass), Middle)) + " as written.";
		Lines.push_back(Line);
		Numbers.push_back("the bass " + Rounded + (Rounded == "1" ? " note" : " notes") + " a bar");
		if (PerBar <= 2.0 && !Calm && !ThinFound)
			Tip(1.0, "The bass mostly holds roots: bass_style walking (towns, jazz), octaves (action), syncopated (pop) "
				"or arpeggio (adventure) in add_chords_and_bass gives it a pulse.");
		if (Middle < 8)
			Tip(0.5, S.Channel(Bass).FullName() + " plays very low, where small speakers lose it: an octave up (transpose).");
	}

	// Drums: variety, fills
	if (Drums >= 0) {
		const std::vector<NoteInfo> &Notes = S.Notes(Drums);
		std::map<std::string, int> Prints;
		int Fills = 0, PhraseEnds = 0;
		std::string Before;
		const int Anchor = PhraseAnchor(S);
		for (size_t b = 0; b < Bars.size(); ++b) {
			const std::string Print = BarPrint(Notes, Bars[b].Row, Bars[b].Row + Bars[b].Rows);
			++Prints[Print];
			const int Bar = S.Time.BarOf(Bars[b].Row);
			if (BarsIntoPhrase(Bar, Anchor, 4) == 3) {
				++PhraseEnds;
				if (b > 0 && Print != Before)
					++Fills;
			}
			Before = Print;
		}
		int Most = 0;
		for (std::map<std::string, int>::const_iterator it = Prints.begin(); it != Prints.end(); ++it)
			Most = std::max(Most, it->second);
		Lines.push_back(Format("Drums: %d different bars in %d; %s.", static_cast<int>(Prints.size()), BarCount,
			Fills > 0 ? Plural(Fills, "phrase ends with a change (a fill)", "phrase ends change (fills)").c_str() : "no fills where phrases end"));
		if (Fills == 0 && BarCount >= 8 && !Calm)
			Tip(1.0, "The drums never change where a phrase ends: add_drums with fill_every 4 (or 8) adds fills and crashes.");
		else if (Most * 10 >= BarCount * 9 && BarCount >= 8 && !Calm)
			Tip(1.0, "The drums repeat one bar almost all the way: add_drums varies every other bar and fills phrase ends.");
		// Every drum on the noise, one at a time
		int Struck = 0;
		for (size_t i = 0; i < Notes.size() && Samples < 0; ++i) {
			const InstrumentInfo *pInfo = Notes[i].Row >= First && Notes[i].Row < End ? FindInstrument(S.Song, Notes[i].Instrument) : 0;
			const std::string Name = pInfo == 0 ? std::string() : Lowercase(pInfo->Name);
			if (Name.find("kick") != std::string::npos || Name.find("snare") != std::string::npos)
				++Struck;
		}
		if (Samples < 0 && Struck >= 2 * BarCount && !Calm)
			Tip(0.5, "Every drum plays on the noise channel, one at a time, so the hi-hats drop out under the kicks and snares: "
				"add_drums with kit samples puts a sampled kick and snare on the DPCM channel, punchier, and leaves the noise to "
				"the hi-hats.");
	}

	// The melody
	{
		int Low = 1000, High = -1, Rests = 0, LongBare = 0;
		std::set<int> Lengths;
		// Vibrato from a 4xy still on from before, or built into the instrument
		const std::vector<int> Sticky = StickyAt(S.Cells(Melody), Tune, S.Channel(Melody).EffectColumns, EFF_VIBRATO);
		std::set<int> Wobbly;
		for (size_t i = 0; i < S.Song.Instruments.size(); ++i)
			if (S.Song.Instruments[i].Vibrato)
				Wobbly.insert(S.Song.Instruments[i].Index);
		// On a calm track a vibrato waits about half a beat: a struck sound gone by then (a pluck) wants none
		const int Waits = Calm ? static_cast<int>(std::floor(CalmVibratoRows(S) * FramesPerRow(S) + 0.5)) + 6 : 0;
		for (size_t i = 0; i < Tune.size(); ++i) {
			const NoteInfo &N = Tune[i];
			Low = std::min(Low, N.Pitch);
			High = std::max(High, N.Pitch);
			Lengths.insert(N.Rows);
			if (i + 1 < Tune.size()) {
				if (Tune[i + 1].Row - (N.Row + N.Rows) >= R || (N.EndNote != NOTE_NONE && Tune[i + 1].Row - N.Row - N.Rows >= R / 2))
					++Rests;
			}
			bool Expression = (Sticky[i] & 0x0F) != 0 || Wobbly.count(N.Instrument) > 0;
			for (size_t e = 0; e < N.Effects.size(); ++e)
				Expression = Expression || N.Effects[e].second.first == EFF_VIBRATO;
			if (N.Rows >= 2 * R && !Expression && (Waits <= 0 || HeardFrames(S.Song, N, Waits) >= Waits))
				++LongBare;
		}
		std::string Line = "Melody: " + PitchName(Low) + " to " + PitchName(High) + Format(" (%d semitones), %s, %s", High - Low,
			Plural(static_cast<int>(Lengths.size()), "note length", "note lengths").c_str(),
			Rests == 0 ? "no rests" : Plural(Rests, "rest", "rests").c_str());
		// Phrases that come back note for note
		std::vector<int> Repeats;
		const std::vector<NoteInfo> &All = S.Notes(Melody);
		for (size_t b = 4; b < Bars.size(); ++b) {
			const std::string Print = BarPrint(All, Bars[b].Row, Bars[b].Row + Bars[b].Rows);
			if (!Print.empty() && Print == BarPrint(All, Bars[b - 4].Row, Bars[b - 4].Row + Bars[b - 4].Rows))
				Repeats.push_back(S.Time.BarOf(Bars[b].Row));
		}
		if (Repeats.size() == 1)
			Line += Format("; bar %d repeats the bar four before it", Repeats[0]);
		else if (!Repeats.empty())
			Line += "; bars " + BarList(Repeats) + " repeat the bars four before them";
		// Phrases: the two-bar spans where it pauses, as it sounds. A busy part taken for the melody (a run of broken
		// chords, arpeggios) isn't one; melody_channel names the melody
		int Chordal = 0;
		for (size_t i = 0; i < Tune.size(); ++i)
			Chordal += SoundsChord(S, Tune[i]) ? 1 : 0;
		const MelodyBreaths Breaths = BreathsOf(S, Melody, From, To);
		const bool Phrases = Breaths.Spans >= 4 && !RunsSteadily(S, Tune) && Chordal * 3 < static_cast<int>(Tune.size());
		if (Phrases)
			Line += Format("; it pauses (a rest of a beat or more, or a note held two beats) in %d of %d two-bar spans", Breaths.Breaths,
				Breaths.Spans);
		Lines.push_back(Line + ".");
		if (Phrases)
			Numbers.push_back(Format("the melody breathes in %d of %d two-bar spans", Breaths.Breaths, Breaths.Spans));
		if (Lengths.size() <= 2 && Tune.size() >= 8 && !Calm)
			Tip(1.0, "The melody keeps one or two note lengths: mix long and short notes (a dotted rhythm, a held note "
				"at each phrase end, a run of quick notes) with write_notes.");
		if (Rests == 0 && BarCount >= 8)
			Tip(1.0, "The melody never rests: a breath of a beat or two between phrases (every 2 or 4 bars) helps it "
				"sound sung, and leaves room for a counter-melody to answer.");
		else if (Phrases && Breaths.Breaths < (Calm ? CALM_BREATHING_SHARE : BREATHING_SHARE) * Breaths.Spans && !PiecesFound) {
			// The bars it runs on through, spans next to each other as one
			std::vector<std::string> Runs;
			for (size_t i = 0; i < Breaths.RunOn.size(); ) {
				size_t j = i;
				while (j + 1 < Breaths.RunOn.size() && Breaths.RunOn[j + 1] == Breaths.RunOn[j] + 2)
					++j;
				Runs.push_back(Format("%d-%d", Breaths.RunOn[i], Breaths.RunOn[j] + 1));
				i = j + 1;
			}
			std::string Bars;
			for (size_t i = 0; i < Runs.size(); ++i)
				Bars += (i == 0 ? "" : i + 1 == Runs.size() ? " and " : ", ") + Runs[i];
			Tip(1.0, Format("The melody hardly pauses: %d of %d two-bar spans have a rest of a beat or more or a note held two beats, "
				"and it runs on through bars %s. ", Breaths.Breaths, Breaths.Spans, Bars.c_str()) + (Calm ? "A calm melody breathes "
				"every two bars: end each phrase with a rest of a beat or more, so it's heard as phrases." : "End each 2- or 4-bar "
				"phrase with a rest of a beat or a held note, so it's heard as phrases."));
		}
		if (High - Low < 7 && Tune.size() >= 8)
			Tip(1.0, "The melody stays within a few notes: let a phrase climb to a high point (a climax) and fall back.");
		if (!Repeats.empty() && Repeats.size() * 4 >= static_cast<size_t>(BarCount))
			Tip(1.0, "Phrases come back unchanged: vary the repeat (another ending, an octave up, a counter-melody "
				"only the second time, busier drums).");
		if (LongBare > 0)
			Tip(0.5, Plural(LongBare, "long melody note has", "long melody notes have") + std::string(Calm ? " no vibrato: polish "
				"with style calm adds the shallowest one, coming in about half a second into each." : " no vibrato: polish adds a "
				"gentle one that comes in after half a beat."));
		// A lead whose sound holds a high, steady level from attack to release presses, however soft the parts around it:
		// what makes a melody sound aggressive
		if (Calm || Lively) {
			const std::vector<HeldLead> Held = HeldLeads(S, Melody, First, End);
			for (size_t i = 0; i < Held.size(); ++i) {
				if (Calm)
					Tip(1.5, "The lead presses: " + HeldLeadText(S, Melody, Held[i]));
				else if (Held[i].Notes * 4 >= Held[i].Of)
					Tip(0.5, Format("%s %s from attack to release; a lively stage's lead wants notes that fade (a stepped decay, or "
						"design_instrument kind falling strike).", InstrumentLabel(S.Song, Held[i].Instrument).c_str(),
						Held[i].Shape.Words.c_str()));
			}
		}
		// Notes that vanish: a tune on a sound that's gone within a few frames, or some of its notes beside ones that hold.
		// The user hears them as missing notes, so they cost the most
		if (CanVanish(S.Channel(Melody))) {
			const std::vector<int> RowFrames = RowFramesOf(S);
			int Long = 0, Gone = 0, GoneFor = 0, GoneSound = NO_INSTRUMENT;
			for (size_t i = 0; i < Tune.size(); ++i) {
				int HeardFor;
				if (Tune[i].Volume <= 0 || NoteFrames(Tune[i], RowFrames) < 6)
					continue;
				++Long;
				if (Vanishes(S.Song, Tune[i], RowFrames, HeardFor)) {
					++Gone;
					GoneFor = std::max(GoneFor, HeardFor);
					GoneSound = Tune[i].Instrument;
				}
			}
			if (Long >= 8 && Gone * 2 >= Long)
				Tip(2.5, Format("Most of the melody's notes are gone within %s (%s): a tune of blips sounds like ticks, not a "
					"melody. Give it a sound that lasts, a lead or a pluck that settles to a level (design_instrument kind pluck, "
					"sustain half); sounds that vanish this fast are for echoes, stabs and drums.", Plural(GoneFor, "frame",
					"frames").c_str(), InstrumentLabel(S.Song, GoneSound).c_str()));
			else {
				const std::vector<Vanishing> Found = VanishingNotes(S, Melody, First, End, RowFrames);
				for (size_t i = 0; i < Found.size(); ++i)
					Tip(2.5, "Melody notes vanish: " + VanishingText(S, Melody, Found[i]));
			}
		}
	}

	// Dynamics: parts at one volume throughout
	std::vector<int> Flat;
	for (size_t p = 0; p < Playing.size(); ++p) {
		const int c = Playing[p];
		if (S.Channel(c).Kind == KIND_TRIANGLE || S.Channel(c).Kind == KIND_DPCM ||
			std::find(Chords.begin(), Chords.end(), c) != Chords.end())
			continue;	// chord stabs keep a level on purpose
		const std::vector<NoteInfo> Notes = NotesIn(S.Notes(c), First, End);
		std::set<int> Volumes;
		for (size_t i = 0; i < Notes.size(); ++i)
			Volumes.insert(Notes[i].Volume);
		if (Notes.size() >= 8 && Volumes.size() == 1)
			Flat.push_back(c);
	}
	if (!Flat.empty()) {
		Lines.push_back("Dynamics: every note at one volume on " + Names(Flat) + ".");
		if (!Calm)
			Tip(1.0, "Flat dynamics sound typed: polish adds accents (the bar's first note loudest, the notes between beats "
				"softer).");
	}

	// The mix: every part near full volume buries the triangle and sounds harsh
	{
		int Parts = 0, Loud = 0;
		for (size_t p = 0; p < Playing.size(); ++p) {
			const int Kind = S.Channel(Playing[p]).Kind;
			if (Kind == KIND_TRIANGLE || Kind == KIND_DPCM || Kind == KIND_NOISE)
				continue;
			const std::vector<NoteInfo> Notes = NotesIn(S.Notes(Playing[p]), First, End);
			int Loudest = 0;	// as it plays: an envelope that peaks under 15 keeps it softer
			for (size_t i = 0; i < Notes.size(); ++i)
				Loudest = std::max(Loudest, PlayedVolume(S.Channel(Playing[p]), Notes[i].Volume, Kind == KIND_FM ? 15 :
					EnvelopePeak(FindInstrument(S.Song, Notes[i].Instrument))));
			++Parts;
			if (Loudest >= (Kind == KIND_SQUARE ? 15 : 13))	// the 5B's 13 is 6 dB under its 15
				++Loud;
		}
		if (Parts >= 2 && Loud == Parts && !Calm && !Lively) {
			Lines.push_back(Format("Mix: %s near full volume.", Parts == 2 ? "both parts with a volume play" :
				"every part with a volume plays"));
			Tip(0.5, "Everything near full volume buries the triangle and sounds harsh: mix (style soft) brings the melody to 9, "
				"an echo to 4 and the rest to 6-7, and softens the triangle and the noise a little with the DPCM level.");
		}
	}

	// Levels: the melody well under another part, counted as FamiTracker plays each chip (the VRC7
	// louder and 3 dB a step, the N163 quieter, every channel's fader in); a soft mix keeps the triangle a little over the
	// melody. Calm and lively tracks are heard as the stems measure them instead (below)
	if (S.Channel(Melody).Kind != KIND_TRIANGLE && !Calm && !Lively) {
		const double RowFrames = FramesPerRow(S);
		auto Typical = [&](int c) {
			// Each note over its first beat as it plays (its envelope in), the louder ones
			const std::vector<NoteInfo> Notes = NotesIn(S.Notes(c), First, End);
			std::vector<double> Levels;
			for (size_t i = 0; i < Notes.size(); ++i) {
				const int Rows = std::max(1, std::min(Notes[i].Rows, S.Time.RowsPerBeat));
				const double Power = NotePower(S, c, Notes[i], Notes[i].Row, Notes[i].Row + Rows, RowFrames);
				Levels.push_back(Power > 0.0 ? 10.0 * std::log10(Power) : -60.0);
			}
			if (Levels.empty())
				return -60.0;
			std::sort(Levels.begin(), Levels.end());
			return Levels[Levels.size() * 3 / 4];
		};
		const double Lead = Typical(Melody);
		int Over = -1;
		double Most = 0.0;
		for (size_t p = 0; p < Playing.size(); ++p) {
			const int c = Playing[p];
			const int Kind = S.Channel(c).Kind;
			if (c == Melody || Kind == KIND_NOISE || Kind == KIND_DPCM || std::find(Echoes.begin(), Echoes.end(), c) != Echoes.end())
				continue;
			const double Above = (Kind == KIND_TRIANGLE ? -1.0 + FaderDb(S.Channel(c)) : Typical(c)) - Lead - (Kind == KIND_TRIANGLE ? 8.0 : 3.0);
			if (Above > Most) {
				Most = Above;
				Over = c;
			}
		}
		if (Over >= 0) {
			const double Under = Most + (S.Channel(Over).Kind == KIND_TRIANGLE ? 8.0 : 3.0);
			// A 5B buzz plays the envelope at its own full level, whatever the volume column: mix leaves it
			bool Buzzing = false;
			if (S.Channel(Over).Kind == KIND_SQUARE) {
				const std::vector<NoteInfo> Notes = NotesIn(S.Notes(Over), First, End);
				const std::vector<int> Sticky = StickyAt(S.Cells(Over), Notes, S.Channel(Over).EffectColumns, EFF_DUTY_CYCLE);
				for (size_t i = 0; i < Notes.size() && !Buzzing; ++i)
					Buzzing = PlaysEnvelope(S, Notes[i], Sticky[i]);
			}
			Lines.push_back(Format("Levels: the melody plays about %d dB under %s%s.", static_cast<int>(std::floor(Under + 0.5)),
				S.Channel(Over).FullName().c_str(), Buzzing ? " (its buzz plays at full level whatever its volume)" : ""));
			if (Buzzing)
				Tip(1.0, Format("The melody plays about %d dB under %s, whose buzz plays the envelope at full level whatever its "
					"volume, so mix leaves it: a softer sound there (a square bass), or the melody on a louder channel.",
					static_cast<int>(std::floor(Under + 0.5)), S.Channel(Over).FullName().c_str()));
			else
				Tip(1.0, Format("The melody plays about %d dB under %s, so it hardly comes through: mix (style soft) sets each part's "
					"level for its chip%s.", static_cast<int>(std::floor(Under + 0.5)), S.Channel(Over).FullName().c_str(),
					StepVolume(S.Channel(Melody)) ? (" (the " + S.Channel(Melody).Chip + " counts its volume in steps of 3 dB: 9 is 18 dB "
					"under 15)").c_str() : ""));
		}
	}

	// As heard (calm and lively): the melody against the chords, an echo, a second line and the bass, as the stems measure
	// them where they play together, the way mix sets them in those styles
	if ((Calm || Lively) && S.Channel(Melody).Kind != KIND_TRIANGLE) {
		std::vector<MixSpan> Spans = MixSpans(S, Melody, First, End, std::set<int>());
		std::vector<int> Voiced = ChordVoicesIn(S, First, End, Melody);
		HeardRoles(S, Voiced, Spans);
		std::vector<std::vector<std::pair<int, int> > > Refs;
		for (size_t i = 0; i < Spans.size(); ++i)
			Refs.push_back(std::vector<std::pair<int, int> >(1, std::make_pair(Spans[i].First, Spans[i].End)));
		const HeardBalance B = HearBalance(S, Ears, Spans, Refs, Melody, Voiced, First, End);
		double Least = NO_LOUDNESS, Most = NO_LOUDNESS;
		const std::string Text = BalanceText(S, Spans, B, Melody, Least, Most);
		Lines.push_back("Balance as heard: " + Text + ".");
		double DrumsRel = NO_LOUDNESS;
		for (size_t i = 0; i < Spans.size(); ++i)
			if (Spans[i].Role == ROLE_DRUMS)
				DrumsRel = std::max(DrumsRel, B.Rel[i]);
		Numbers.push_back("as heard: " + (Most > NO_LOUDNESS ? "the melody " + GapText(Least, Most, true) + " the chords" :
			std::string("no chords")) + (DrumsRel > NO_LOUDNESS ? ", the drums " + GapText(-DrumsRel, -DrumsRel, false) : std::string()));
		const double Want = Calm ? 2.5 : 3.5, Top = Calm ? 4.0 : 5.0, Bottom = Calm ? 1.0 : 2.0;
		const char *const Word = Calm ? "a calm track wants 2-3, or it presses" : "a lively stage wants 3-4, or it presses";
		if (Most > NO_LOUDNESS && Most > Top)
			Tip(1.0, Format("The melody sits about %.1f dB over the chords as heard (%s): mix with style %s puts it at %.1f.", Most, Word,
				Calm ? "calm" : "lively", Want));
		else if (Least > NO_LOUDNESS && Least < Bottom)
			Tip(1.0, Format("The chords cover the melody as heard (it sits %s them; %s): mix with style %s puts it at %.1f.",
				GapText(Least, Least, true).c_str(), Calm ? "a calm track wants 2-3" : "a lively stage wants 3-4", Calm ? "calm" : "lively", Want));
	}

	// Stereo (this FamiTracker's own; the game's OGG files have it): where the parts play between the speakers, the
	// mixer's starting pans counted. An echo on the melody's side blurs it; the bass and the drums carry the song from
	// the middle
	{
		std::map<int, std::vector<NoteInfo> > Panned;
		for (size_t p = 0; p < Playing.size(); ++p)
			Panned[Playing[p]] = NotesIn(PannedNotes(S, Playing[p]), First, End);
		const std::vector<NoteInfo> PannedTune = Panned[Melody];
		bool Pans = false;
		for (size_t p = 0; p < Playing.size() && !Pans; ++p) {
			const std::vector<NoteInfo> &Notes = Panned[Playing[p]];
			for (size_t i = 0; i < Notes.size() && !Pans; ++i)
				Pans = Notes[i].Pan != PAN_CENTER;
		}
		if (!Pans) {
			Lines.push_back("Stereo: every part plays in the middle.");
			if (!Echoes.empty() || Chords.size() + Voices.size() >= 2)
				Tip(0.0, "For width in the game's stereo OGG files: an echo on the other side of the melody (add_echo with pan "
					"\"opposite\", or set_pan), chord voices or a second line apart (mix with width wide does it all); the melody, "
					"the bass and the drums stay in the middle.");
		}
		else {
			std::string Line = "Stereo:";
			for (size_t p = 0; p < Playing.size(); ++p)
				Line += (p == 0 ? " " : "; ") + S.Channel(Playing[p]).FullName() + " " + PanText(Panned[Playing[p]]);
			Lines.push_back(Line + ".");
			const double Lead = PanPositionOf(PannedTune);
			for (size_t i = 0; i < Echoes.size(); ++i) {
				const double Echo = PanPositionOf(Panned[Echoes[i]]);
				if ((std::fabs(Echo) < 0.15 && std::fabs(Lead) < 0.15) || Echo * Lead > 0.0)
					Tip(0.5, Format("The echo on %s plays on the melody's side (%s, the melody %s): on the other side (set_pan, or "
						"add_echo again with pan \"opposite\") it stops blurring the melody and the song widens.",
						S.Channel(Echoes[i]).FullName().c_str(), PanText(Panned[Echoes[i]]).c_str(), PanText(PannedTune).c_str()));
			}
			if (Bass >= 0 && std::fabs(PanPositionOf(Panned[Bass])) >= 0.25)
				Tip(0.5, "The bass on " + S.Channel(Bass).FullName() + " plays from one side: keep it in the middle (set_pan with pan "
					"center), as the low end anchors the song and some players hear only one speaker.");
			const int Kit[2] = { Drums, Samples };
			for (int k = 0; k < 2; ++k)
				if (Kit[k] >= 0 && std::fabs(PanPositionOf(Panned[Kit[k]])) >= 0.25)
					Tip(0.5, "The drums on " + S.Channel(Kit[k]).FullName() + " play from one side: the kick and the snare belong in "
						"the middle (set_pan with pan center).");
			if (std::fabs(Lead) >= 0.5)
				Tip(0.5, "The melody plays from one side (" + PanText(PannedTune) + "): it belongs in the middle, with its echo or a "
					"second line to the sides.");
		}
	}

	// Register: another part sitting on the melody while it sounds. A double thickens it rather than blurring it, and a
	// part that plays in the melody's gaps (a hocket, answers) trades notes with it
	const int TuneMiddle = MiddleOf(Tune, 52) - Written(S.Channel(Melody), 0);	// as they sound
	std::vector<char> TuneSounds(static_cast<size_t>(std::max(0, End - First)), 0);
	for (size_t i = 0; i < Tune.size(); ++i)
		for (int r = std::max(First, Tune[i].Row); r < std::min(End, Tune[i].Row + std::max(1, Tune[i].Rows)); ++r)
			TuneSounds[static_cast<size_t>(r - First)] = 1;
	std::vector<int> Crowding, Trading;
	for (size_t p = 0; p < Playing.size(); ++p) {
		const int c = Playing[p];
		if (c == Melody || c == Bass || !IsMelodic(S.Channel(c)))
			continue;
		const std::vector<NoteInfo> Notes = NotesIn(S.Notes(c), First, End);
		const int Middle = MiddleOf(Notes, 0) - Written(S.Channel(c), 0);
		if (std::abs(Middle - TuneMiddle) > 3 || std::find(Echoes.begin(), Echoes.end(), c) != Echoes.end() ||
			std::find(Doubles.begin(), Doubles.end(), c) != Doubles.end())
			continue;
		int Sounding = 0, Together = 0;
		for (size_t i = 0; i < Notes.size(); ++i) {
			for (int r = std::max(First, Notes[i].Row); r < std::min(End, Notes[i].Row + std::max(1, Notes[i].Rows)); ++r) {
				++Sounding;
				Together += TuneSounds[static_cast<size_t>(r - First)];
			}
		}
		if (Sounding > 0 && Together * 4 < Sounding)
			Trading.push_back(c);
		else
			Crowding.push_back(c);
	}
	if (!Trading.empty())
		Lines.push_back("Register: " + Names(Trading) + " plays in the melody's gaps, around its notes (a hocket, or answers).");
	if (!Crowding.empty()) {
		Lines.push_back("Register: " + Names(Crowding) + " plays around the melody's own notes (" +
			PitchName(Written(S.Channel(Melody), TuneMiddle)) + ").");
		Tip(1.0, "Parts in the melody's register blur it: move them an octave down (transpose with semitones -12) or "
			"the melody up.");
	}

	// Parallel octaves with the bass
	if (Bass >= 0) {
		const std::vector<NoteInfo> Low = NotesIn(S.Notes(Bass), First, End);
		int Parallel = 0;
		for (size_t i = 0; i + 1 < Tune.size(); ++i) {
			const NoteInfo *pA = 0, *pB = 0;
			for (size_t k = 0; k < Low.size(); ++k) {
				if (Low[k].Row == Tune[i].Row)
					pA = &Low[k];
				if (Low[k].Row == Tune[i + 1].Row)
					pB = &Low[k];
			}
			if (pA != 0 && pB != 0 && (Tune[i].Pitch - pA->Pitch) % 12 == 0 && (Tune[i + 1].Pitch - pB->Pitch) % 12 == 0 &&
				Tune[i].Pitch != Tune[i + 1].Pitch)
				++Parallel;
		}
		if (Parallel >= 3) {
			Lines.push_back(Format("The bass doubles the melody in octaves %d times as both move.", Parallel));
			Tip(0.5, "A bass moving in octaves with the melody sounds hollow: let it move the other way, or hold.");
		}
	}

	// Everything repeating: the whole arrangement four bars on
	std::vector<int> Copies;
	for (size_t b = 4; b < Bars.size(); ++b) {
		bool Same = true;
		for (size_t p = 0; p < Playing.size() && Same; ++p) {
			const std::vector<NoteInfo> &Notes = S.Notes(Playing[p]);
			Same = BarPrint(Notes, Bars[b].Row, Bars[b].Row + Bars[b].Rows) == BarPrint(Notes, Bars[b - 4].Row, Bars[b - 4].Row + Bars[b - 4].Rows);
		}
		if (Same)
			Copies.push_back(S.Time.BarOf(Bars[b].Row));
	}
	if (!Copies.empty()) {
		Lines.push_back(Copies.size() == 1 ? Format("Bar %d repeats the bar four before it in every part.", Copies[0]) :
			"Bars " + BarList(Copies) + " repeat the bars four before them in every part.");
		Tip(1.0, "A repeat with nothing new is where a loop starts to sound like a loop: change one or two layers the "
			"second time (a counter-melody, drums one step busier, chords in another style, the melody an octave up).");
	}

	// Length
	const double Bpm = BeatsPerMinute(S.Song.Speed, S.Song.Tempo, S.Song.FrameRate, R);
	const double Seconds = Bpm > 0 ? BarCount * (S.Time.RowsPerBar / static_cast<double>(R)) * 60.0 / Bpm : 0.0;
	Lines.push_back(Format("Length: %d bars, %s at %s BPM.", BarCount, SecondsText(Seconds).c_str(), FormatNumber(std::floor(Bpm + 0.5)).c_str()));
	Numbers.insert(Numbers.begin(), Format("%d bars, %s at %s BPM", BarCount, SecondsText(Seconds).c_str(),
		FormatNumber(std::floor(Bpm + 0.5)).c_str()));
	if (Seconds > 0 && Seconds < 30 && BarCount <= 16 && !LoopFound)
		Tip(0.0, "Under half a minute before it loops: game music heard for minutes wants more material, an A part and "
			"a B part (16 to 32 bars or more).");

	for (size_t i = 0; i < Arranged.size(); ++i)
		TipCall(Arranged[i].Weight, Arranged[i].Text + " " + FixText(Arranged[i].Fix, true), Arranged[i].Summary, Arranged[i].Fix);
	// Most first: the tips that take the most off the score (in the order found where they take as much)
	std::stable_sort(Tips.begin(), Tips.end(), [](const ReviewTip &a, const ReviewTip &b) { return a.Weight > b.Weight; });
	const int Score = std::max(1, std::min(10, static_cast<int>(std::floor(10.0 - Missing + 0.5))));
	if (Form == "short")
		return ShortReview(Format("Review (%s), %s in %s: %d/10.", Calm ? "calm" : Lively ? "lively" : "any style",
			RangeText(From, To).c_str(), KeyName(K).c_str(), Score), Use.Use == TRACK_CUE ? Format("Judged as a cue: it plays once and halts "
			"after %.1f s.", Use.Seconds) : std::string(), Parts, Numbers, Tips);
	std::string Text = "Depth review, " + RangeText(From, To) + " in " + KeyName(K) + Format(": %d/10.\n", Score);
	if (!Chosen.Note.empty())
		Text += Chosen.Note + "\n";
	if (Use.Use == TRACK_CUE)
		Text += CueText(Use) + "\n";
	for (size_t i = 0; i < Lines.size(); ++i)
		Text += Lines[i] + "\n";
	if (Tips.empty())
		Text += "Nothing obvious is missing. Listen with the user (play) and ask what they'd change.";
	else {
		Text += "What would help, most first:\n";
		for (size_t i = 0; i < Tips.size(); ++i)
			Text += Format("%d. ", static_cast<int>(i) + 1) + Tips[i].Text + "\n";
	}
	return Text;
}

// Grooves to start from, sections repeated and varied, the soundtrack's notes

struct Mood {
	const char *Name;
	const char *Aliases;	// separated by "|"
	const char *Use;
	bool Minor;
	const char *Chords;		// as degrees, four bars
	const char *Color;
	int Style, Rhythm, Pattern, Bass, Groove, Intensity, Bpm;
	const char *ChordSound;
};

